-- Merit and Flaw descriptions, the [en] half (SPEC I102e, I21, V210 / T751).
--
-- One entry per item of PICKER_LIST["merit"] and ["flaw"], keyed in ENGLISH because that is
-- what the sheet saves (SPEC V24). Three blocks, exactly as the eight description modules
-- already do: "<Book>, p. <n>" - blank - blank - <Name> - blank - blank - <text>. The book
-- title does not translate; only p./pag. does (SPEC I100e).
--
-- One module PER LANGUAGE and never both halves in one file (SPEC V210): half of every
-- module was the language the session never opens, and require pulled both in to read one.
-- The renderer builds the name by concatenation - require("descMerit_" .. half .. ".lua")
-- and never a constant name (SPEC V210b).
--
-- Data only: no function, no state, no require of gui/ndb/locale (SPEC I24).
-- Generated by research/gen_merit_data.ps1 from research/merit_flaw.tsv and the bodies
-- research/extract_merit_flaw.ps1 pulls out of the books. Do not hand-edit.

return {
				-- >>> MERIT_DESC_BEGIN (generated - SPEC T751)
				["Ability Deficit"] = {
					en = [==[Book of Secrets, p. 53


Ability Deficit


For whatever reason, you have fallen short of your potential. Maybe you're too young to have learned a lot about life (an excellent reason for a child-mage to have this Flaw); or you've led a sheltered existence, honing your Knowledges but lacking in Talents. You could be a construct who only recently left the lab, or too physically frail to have mastered much in the way of Talents or Skills. There's certainly some story-based reason for your deficient Traits, and that cause will have other effects on the chronicle as well.

In game terms, this Flaw subtracts five points from one of your Ability categories (Talents, Skills, or Knowledges), and limits your starting Traits in that category to three dots or fewer even if /when you spend freebie points to raise them. (You may, of course, raise them after the chronicle has begun.) As noted above, this makes a good Flaw for Awakened kids, constructs, and other folks who haven't been able to “be all that you can be” just yet.

For details about young mages, see Child-Mages in Chapter Two, pp. 115-116.]==],
				},
				["Absent-Minded"] = {
					en = [==[Book of Secrets, p. 50


Absent-Minded


Um… what was that thing you were trying to remember, again? Damn… This Flaw reflects a scatterbrained sense of memory and connection – nothing quite as dangerous as full Derangement (Mage 20, pp. 648-650), but a distressing and occasionally hazardous disconnection nonetheless.

System-wise, your Storyteller will often have you make Intelligence rolls to recall things like names, faces, mission details, and so forth. Story-wise, you're forever drawing blanks, mistaking people for other folks, scrambling data, leaving projects half-finished (or totally abandoned), forgetting to feed your familiar, and making potentially hazardous errors in judgment. Although you won't forget vital things like your name, the elements of your magickal focus, or vital character Traits (Talents, Abilities, and Knowledges), other stuff slips your mind with frustrating regularity. And when that mind commands the powers of True Magick, such slips can have fatal consequences.]==],
				},
				["Addicted to Vampire Blood"] = {
					en = [==[The Hunters Hunted II, p. 42


Addicted to Vampire Blood


Your character constantly needs the rush that only vampire blood can provide her. She feels empty and listless otherwise. This habit is a very dangerous one and can only be overcome via complete abstention (and likely no small amount of therapy). Anytime your character has access to Kindred vitae and wishes to resist the urge to drink, the Storyteller may require a Self-Control roll. If your character has not tasted vampire blood in over a week, you suffer a progressive +1 difficulty to these rolls until she quenches her thirst. Physical Flaw]==],
				},
				["Addiction"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Addiction


You suffer from an addiction to a substance, which must now be present in the blood you drink (or you automatically frenzy, as per the Prey Exclusion Flaw). This can be alcohol, nicotine, hard drugs, or simply adrenaline. This substance always impairs you in some fashion (see “Poisons and Drugs,” p. 301, for particu- lars).]==],
				},
				["Aging"] = {
					en = [==[The Hunters Hunted II, p. 141


Aging


You are not as spry as you used to be. Lower one Physical Attribute score (your choice) by one point. An Attribute cannot go below one with this Flaw. You may take this Flaw at 40 years old and once again per decade after. Mental]==],
				},
				["Albino"] = {
					en = [==[Ghouls & Revenants, p. 134


Albino


Albinism occurs when a group of normally recessive genes become prominent, leading to a lack of pigmentation of the skin. While generally harmless, the appearance of an albino individual can be startling, particularly to others who are unfamiliar with the condition. The condition is marked by extremely pale skin and red irises.

Albinism was viewed with great suspicion in most early cultures, such that even today people with albinism are shunned and ostracized, and considered to be an ill- omen in many parts of the world. While this condition is harmless from a physiological standpoint, it does cause afflicted individuals to stand out. This may reduce a ghoul's capacity to blend into a crowd, without the help of a disguise. However, those who suffer from the Albino Flaw can also turn other people's fear into a source of intimidation, particularly if your ghoul or revenant has a reputation that cannot be ignored.

When you take the Albino Flaw, keep in mind that your skin is highly susceptible to sunburn, having little or no pigmentation to reflect the sun's harmful UV rays.

Used by: All ghouls and revenants Vicissitude Modifications]==],
				},
				["Amnesia"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Amnesia


You are unable to remember anything about your past, yourself, or your family (whether mortal or vam- piric), though your past might well come back to haunt you. Your origins and the circumstances behind your amnesia are for the Storyteller to determine, and she is encouraged to make it as interesting as possible.]==],
				},
				["Anachronism (1)"] = {
					en = [==[Book of Secrets, p. 81


Anachronism (1)


Time has passed you by… or maybe it simply hasn't caught up with you yet. Your beliefs, personality, mannerisms, fashion, and expectations are radically out of step with your surroundings. This could be a deliberate affection on your part (“The Old Days were better than today” /“Why wait for the future to arrive when you can become the future?”), a Time Sphere-related temporal hiccup or Paradox Flaw, the result of paranormal longevity or back-tracking time travel, the manifestation of an especially assertive past (or future) life… hell, even you might not know quite why you're like this, but you are, and the rest of the world can't help but notice.

The value of this Flaw depends upon the amount of trouble you get into as a result of your anachronisms: (1 point) You seem a little weird, and potentially offen-

sive (“Why are they not sitting in the back of the bus? Aren't

there laws about that sort of thing?”), displaying quirks

from a recognizably different past or future that isn't

radically behind or ahead of the current age. Add +1 to

the difficulty of understanding current technology and

modes of behavior. (2 points) You're a relic of a distinctly earlier age, or the

harbinger of a seriously advanced one. The things you

say, wear, expect, and believe are disturbingly out of touch

with your surroundings, and can present significant

problems… especially if and when you hold forth on silly

little things like politics, social mores, sexuality, and the

law. Current technology puzzles you, either because it's

inexplicably advanced or staggeringly primitive. Add +2

to the difficulty of all efforts to understand your current

era, including social rolls based upon getting along with

people in this age. (3 points) You hail from a time so distant that the current

era seems as alien to you as you seem to people of this

era. Hell, you might not even speak English (a common

trait of folks who existed before the expansion of British

and American influence in the 1800s), or speak your

language with an accent and idioms that essentially turn

it into another language entirely (think Shakespeare,

or Anthony Burgess' novel A Clockwork Orange). Your

expectations regarding technology and social mores are

wildly divergent, and you could easily get yourself into

serious trouble. Add +3 to the appropriate rolls, and

you may be unable to process certain things (driving,

politics, current computer tech, etc.) at all.

Assuming you have a chance to acclimate to your surround- ings, this Flaw can be bought down with experience points. Until that time, your companions will have a lot of explaining to do on your behalf!]==],
