				},
				["Arcane Curse (1)"] = {
					en = [==[Lore of the Clans, p. 219


Arcane Curse (1)


Because of either your studies or someone else's, you suffer from a magical curse. It might be an aversion or allergy, or even a strange magical effect. The level of the flaw depends on how debilitating the curse is. Curing the affliction may be impossible, or require some sort of quest or advanced research. Flaw Value Example Curse 1 point 2 point A minor oddity, such as an animal feature

or strange eye color 3 point

A noticeable problem, such as your magic

having a strange taint or pattern that makes

it instantly recognizable, or that plants

wither in your presence.

Something problematic, such as people

sickening in your presence or animals

attacking you.

LORE OF THE CLANS 4 point Concerning handicap, such as developing 5 points another Clan's weakness.

Potentially deadly, such as moonlight being

as dangerous to you as sunlight.]==],
