				},
				["Artificially Aged"] = {
					en = [==[Ghouls & Revenants, p. 138


Artificially Aged


You are an underage ghoul or revenant that has been fleshcrafted to look like an older, mature adult. Your true maturity is still far off in your future, but you appear to be a decade or two older than your actual age. As long as you remain a ghoul, your body will not age.

Due to the terrors inflicted on your young body and mind, your character may never reconcile what has happened to you. Physically, you might pass for a much older person, but mentally and emotionally you are still a child. Thus, you will likely encounter challenges in most social situations, and your Storyteller may require you to subtract one or more dice from rolls involving your Social dice pools.

Used by: Like the Vicissitude Modification Merit, this Flaw may only be added at your Storyteller's discretion.]==],
				},
				["Aura of the Typhon"] = {
					en = [==[Lore of the Clans, p. 67


Aura of the Typhon


Something slithers beneath your skin, coiled in your very essence — something that causes the Lupines to stalk you for some dread purpose you do not understand. Their howls follow in your wake. You catch glimpses of blurred motion and the gleam of eyes and teeth in the dark. They get closer every night. What do they want from you?]==],
				},
				["Bad Sight (1)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Bad Sight (1)


Your sight is defective. The difficulties of any die rolls involving the use of your eyesight are increased by two. As a one-point Flaw, this condition can be cor- rected with glasses or contacts; as a three-point Flaw, the condition is too severe to be corrected.]==],
				},
				["Bad Sight (3)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Bad Sight (3)


Your sight is defective. The difficulties of any die rolls involving the use of your eyesight are increased by two. As a one-point Flaw, this condition can be cor- rected with glasses or contacts; as a three-point Flaw, the condition is too severe to be corrected.]==],
				},
				["Banshee-in-Waiting"] = {
					en = [==[Lore of the Bloodlines, p. 3


Banshee-in-Waiting


The Fugue is gradually driving you towards madness. If your temporary Willpower ever reaches 0, you automatically gain a derangement which can never be removed. You may remove other derangements you gain in other ways as usual. You may gain a maximum of three of these permanent derangements from losing your Willpower before being consumed by it. Should it happen a fourth time, you immediately lose yourself to the Fugue and become a character under the control of the Storyteller, walking in whatever direction the music takes you and killing anything you come across.]==],
				},
				["Beacon of the Unholy"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Beacon of the Unholy


You radiate palpable evil. Clergy and devout mor- tals know instinctively that there is something horribly wrong with you, and react accordingly.]==],
				},
				["Beast Within"] = {
					en = [==[Book of Secrets, p. 92


Beast Within


You've got a truly infernal temper: one so violent it feels like a volcano in your soul. As with a werewolf or vampire, you're subject to the dreaded frenzy that turns you into an engine of hot rage. Under intense stress, you risk losing every shred of enlightenment you possess. Driven to such extremity, you let loose with the most immediately destructive powers at your command, and “vulgarity” be damned! Everyone in your vicinity becomes a target, and the consequences matter to you only when this inner storm has passed.

System-wise, this Flaw sends you into deadly rages as per the Berserker /Stress Atavism Trait featured in Mage 20, p. 644. Instead of rolling your Willpower to avoid the frenzy, however, you roll your Avatar rating plus one die, with your Willpower as the difficulty of that roll. If, as an example, young Vyper Trabia suffers from the Beast Within Flaw, with an Avatar of 4 and a Willpower of 5, Vyper's player rolls five dice against a difficulty of 5 when that Akashic hothead is under ferocious stress. A failure on that roll sends Vyper into a berserk rage. Yeah, this probably happens pretty often. Vyper's friends don't stick around for long when things go poorly.

(If you employ the optional Resonance Trait described in Chapter Two, you could substitute your highest Resonance, plus one die, as the dice pool for your rage. The roll's difficulty is still your Willpower Trait, and your Resonance plus that extra die should at least equal, if not exceed, your Avatar Trait. In this case, the Resonance in question must be something capri- ciously unstable – Wild, Primal, Ferocious, and so forth – instead of calm and centered energy. For details, see Four Flavors of Resonance, pp. 136-138.)

Considering that the Avatar could be seen as your inner Beast, a character with the Pattern Essence cannot take this Flaw. It's best suited for Dynamic Essences, although a Quest- ing or Primordial Avatar could attain frightening rages too. A berserk mage cannot employ rituals or employ complicated tools; only the most direct methods of attack – magickal or otherwise – will do. Although mages rarely suffer from such grotesque lapses of self-control, an Awakened Ghoul (as in that Merit), a cyborg, a Victor, a Shapechanger Kin (again, as per the Merit), or an animalistic shape-changer could possess such inhuman monstrousness.

For similarly bestial character traits, see the Mental Flaw: Feral Mind (p. 52) and the Expanded Practice of Animalism in Chapter Three, pp. 197-199.]==],
				},
				["Bedeviled"] = {
					en = [==[Book of Secrets, p. 94


Bedeviled


Oh, you poor bastard! A mysterious power has decided to fuck with you, and it's perfectly capable of making your life a chronicle of woe. Misery and setbacks are your bread and butter; should things start looking up for you, you begin looking up as well to spot the inevitable anvil dropping toward your head. This sort of thing goes way beyond simple misfortune or even a paltry little curse. Your enigmatic foe is a dedicated cuss, and whatever it might be (it's not necessarily an actual devil, though it certainly seems like one to you!), that force has apparently unlimited resources and a very sick sense of humor; in short, then, it's your typical Storyteller.

A story-based Flaw, this wretched Trait essentially grants the Storyteller a license to give your character the starring role in a twenty-first-century Book of Job. (And again, check out Tragedy.) There ought to be a certain rhyme and reason behind this metaphysical fuckery, of course, but the source of your agonies, and the way you could potentially end them, are for your Storyteller to know and you to find out… should you be fortunate enough to live so long.]==],
				},
				["Bestial"] = {
					en = [==[Lore of the Clans, p. 163


Bestial


You are closer to animals than humans, and it shows. In addition to the Nosferatu Clan weakness, you have an additional weakness: whenever you frenzy, you gain an animal feature, similar to the Gangrel Clan weakness (V20, p. 55).

With Storyteller permission, permanently acquired animal features may be justification to acquire certain Merits after character creation, such as Lizard Limbs (p. 160) or Monstrous Maw (pp. 160-161). If so, the Storyteller can simply award them, or require an experience point expenditure (such as two times the Merit point value). Similar Flaws can also be taken, but cannot grant additional freebie or experience points.]==],
				},
				["Betrayer's Mark"] = {
					en = [==[Lore of the Clans, p. 219


Betrayer's Mark


Even though you are loyal to House and Clan Tremere, for some reason you are branded with the mark of the antitribu (see the sidebar on p. 216). It might be that you have returned to the Clan after leaving the Sabbat or that you unwittingly or as part of an undercover operation took part in the Vaulderie. Whatever the reason, the mark makes other Tremere wary of you. You will have to go that extra mile to prove yourself, and few among the Clan will trust you with positions of power and responsibility.]==],
				},
				["Bigot"] = {
					en = [==[Book of Secrets, p. 50


Bigot


You really fucking hate those people, whoever “those people” happen to be. Those people probably don't like you either. Okay, maybe you don't make your feelings obvious, but your conviction that those people are inferior troublemakers who are Everything Wrong with the World Goddammit comes through in your actions and decisions even if you say nothing of the kind out loud. Such prejudices determine your choice of friends and enemies, guide your beliefs, influence your politics, and tend to spill out at inconvenient times if you lose your temper. (See Short Fuse, above.) You might end up changing your mind someday, but for the moment, bigotry is the lens through which you view your world… and especially for mages, that sort of thing means quite a bit to the world at large.

Despite the conventional (and not inaccurate) view of bigots as raging racists, sexists, and homophobes, supposedly liberal people can be bigots too; the worst kinds of bigots, in fact, are often self-righteous folks whose claims of open-mindedness get undercut by a quiet yet implacable prejudice against those people. Older versions of this Flaw rated it at only two points; in the twenty-first century, however, bigotry is more likely to get you in trouble if and when it's revealed, especially on the Internet or in mass media… unless, of course, you're running for president, or otherwise speaking up for folks who share your views, in which case you become a saint to some people and a demon to others.

It's worth noting that bigots tend to have understandable reasons for their prejudices. Those reasons could stem from personal grievances, cultural bias, racial anxieties, scriptural proclamations, psychic trauma, gender clashes, philosophical paradigms, and – especially within Mage's world – physical and metaphysical distinctions between “us” and “them.” Those reasons probably seem like bullshit to most people, but remain perfectly justified to the bigot in question.

It's also worth noting that this Flaw should not in any way be taken as a license to abuse your fellow players. As with other ma- ture-audience subjects, a character's prejudices might become a trigger for real-life tensions within the group, and should thus be handled carefully, as described under the Problems and Triggers sections of Mage 20, pp. 344-345.]==],
				},
				["Bizarre Hunger (2)"] = {
					en = [==[Book of Secrets, p. 87


Bizarre Hunger (2)


You prefer – maybe even need – to eat weird shit… quite possibly in a literal sense of that expression. Perhaps you've sworn a vow, suffered a curse, been treated (or created) with unhallowed rituals or arcane hyperscience, or initiated into an occult fellowship with… interesting admission demands. In any case, you must consume substances that may be degrading, unpleasant, expensive, or downright illegal.

The more inconvenient the substance, the more this Flaw is worth: (2 points) Easy to procure, though not as easy to devour

(paper, fresh eggs, poop, etc.). (3 points) Unpleasant, hazardous, and perhaps illegal

to consume (rotten meat, swamp water, raw cannabis,

and so forth). (4 points) Specialized, foul, criminal, and /or expensive

chow (human blood, custom-brewed potions or meals,

and the like). (5 points) You really shouldn't eat such things… but

you must (live humans, toxic sludge, gold dust, highly

specialized food-like concoctions, and other similar

forms of sustenance).

For each dot in your Stamina Trait, you can go one day without satisfying your special dietary requirements. After that, you lose one health level per day until you either consume your particular substance, or else die of hunger or thirst, suf- fer the punishment of a vow unfulfilled, or otherwise endure whichever other consequences might result from denying your bizarre hunger.

For a related (and probably essential) companion Trait, see the physical Merit: Cast-Iron Stomach, p. 36. And for a potentially related focus-instrument, see the Chapter Three Expanded Instruments entry for Cannibalism, pp. 206-207.]==],
				},
