				["Black and White"] = {
					en = [==[The Hunters Hunted II, p. 42


Black and White


The world is really a collection of shades of gray, but your character doesn't see it that way. To her, everything is clear as black and white. She thinks in terms of people being either for or against her, hot or cold, good or evil, easy or impossible, stupid or genius. This closed mindset can cost your character dearly in missed opportunities, misunderstandings, and under- or overestimation of others. In social situations where your character's judgmental perspective comes to bear, the difficulties of associated rolls increase by one.]==],
				},
				["Black Sheep"] = {
					en = [==[Anarchs Unbound, p. 102


Black Sheep


You belong to a prestigious lineage that is considered to be paragon of another sect, or at least it did before you joined the Anarch Movement. You have embarrassed your sire, grandsire, and perhaps even farther back up the line; now the time has come to pay. Your erstwhile broodmates want to bring you back into the fold, if only to clean the stain from your reputation, and are unwilling to recognize your independence. Your sire and grandsire spare no effort to make things uncomfortable for you and any Anarchs who shelter you. This flaw combines the effects of Sire's Resentment and Hunted Like a Dog, so those flaws may not be taken in conjunction with Black Sheep. (For more information on those Flaws, see p. 490 and 492 of V20, respectively.)

In addition, many members of the Anarch Movement actively distrust you solely based on your lineage, believing that you are a double-agent. All social rolls involving your fellow Anarchs incur a +2 difficulty.]==],
				},
				["Blacklisted (1)"] = {
					en = [==[Book of Secrets, p. 59


Blacklisted (1)


Having crossed some Powers That Be, you've now been pariah-fied among some segment of the Masses. The results impact your employment potential, social standing, legal status, credit rating, background checks, rental possibilities, and other significant elements of existing in the everyday world.

Originally presented as an Adversarial Background for Cer- tification, this Flaw affects your regional, national, and perhaps international official status. The degree to which you've been professionally shunned depends upon the value of this Flaw: (1 point) Trivial – poor driving record, suspected shop-

lifter, banned from a local union. (2 points) Minor – misdemeanor criminal record, sus-

pended license. (3 points) Significant – disbarred lawyer, defrocked clergy,

unpopular political affiliation, dishonorable military

discharge. (4 points) Major – convicted felon, registered sex offender,

government watch-list, revoked medical license. (5 points) Pariah – FBI's most-wanted, suspected terrorist,

convicted pedophile, declared legally incompetent or insane.

A four- or five-point Blacklisting will also wind up in the Technocracy's supervision database – a very dangerous place for a mage to be! And although the Awakened don't typically check in with mundane authorities before recruiting or making alliances with their own kind, a mage who's had major problems with such authorities is likely to have problems with mages too… especially if such problems include offenses like terrorism or pedophilia, which certain mages take very, very poorly.]==],
