				},
				["Blind"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Blind


You cannot see. Characters can compensate for the loss of vision by becoming more attuned to other sen- sory input, but visual cues and images are lost to them. Difficulties of all Dexterity-based rolls are increased by two. Oddly, vampires with Aura Perception (Auspex 2) are still able to use this ability, thought the informa- tion is interpreted via the other senses. On the other hand, vampires who need make eye contact to enact powers like Dominate against you are only at a penalty to do so (see the sidebar on p. 152). Mental]==],
				},
				["Blood Feud"] = {
					en = [==[Ghouls & Revenants, p. 132


Blood Feud


The hostility between revenant families such as the Grimaldi and Zantosa is well known throughout the Sabbat. Rivalries between the Brujah and the Ventrue occasionally bleed into the behavior of their ghouls throughout Camarilla-held cities. Fights between revenant families are all too common, and these feuds have been going on for so long that some family members may have forgotten how an argument first started. A Blood Feud might be a recent development, but more than likely a deadly rivalry has probably been smoldering for decades, if not centuries.

Not all disagreements and rivalries between families or factions, however, are considered to be Blood Feuds. A Blood Feud is what occurs after a slight or injury has been escalated to impossible heights, and the initial cause of the argument can now only be rectified when both debts are settled, often violently. Other family members will even go so far as to swear a revenge-filled oath to harm the rival family at the first opportunity. Like the nature of the feud, the violence both families cause may range from slashing tires to slitting throats.

While Blood Feud is particularly applicable to members of certain revenant families, this Flaw may also apply to rival Clans in a given city. Loyal ghouls might take offense at a misstep or take up vengeance for a slight against their Domitor, and their feelings could escalate into hatred and a desire to kill. A Gangrel ghoul might be involved in a bitter dispute over territory or domain with the servants of a Toreador Primogen. Enough betrayal and insults could be hurled over the course of the conflict that tense discussions erupt into bitter arguments. Usually, however, for a Blood Feud to exist there must be more than a simple rivalry between the two parties. In a Blood Feud, several members of each side should be willing to battle over the insult or slight. The hatred between the two sides has escalated over time, and calls for vengeance carry weight.

When confronted with the possibility that your rival is nearby, your character must make a Frenzy check at a -2 difficulty. If successful, your character is able to control the blind fury caused by your thirst for revenge.

If your character fails the check, you will feel compelled to act on your obsession for vengeance. You might seek out and confront your rival. You might attack someone who looks like her, or sabotage her car or attack her girlfriend. You might even rile up the other people around you to join the fight, too. How you act on your hatred is up to you, but a failure will guarantee that the Blood Feud is renewed.

You may choose to spend a Willpower point to delay your moment of frenzy for one round. However, the longer you delay acting on your thirst for revenge, the greater the chances are that your rival will act upon hers.

Used by: Revenants who have a clear rivalry with another family, or by ghouls from warring Clans, bloodlines, or Sects.

To take this Flaw, you must work with the Storyteller to name which family (or Clan) the Blood Feud is with, and how much the player character knows about its cause. You must also select a specific rival from the opposing side who is heavily involved with the feud or its cause.]==],
				},
				["Blood Hunted (4)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Blood Hunted (4)


You have been made the target of a blood hunt, and for you to return to your home city is death. For four points, this Flaw means that only your home city is off- limits to you. For six, it means that the entire Cama- rilla is howling for your vitae. This Flaw can only be taken by Camarilla vampires.]==],
				},
				["Blood Hunted (6)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Blood Hunted (6)


You have been made the target of a blood hunt, and for you to return to your home city is death. For four points, this Flaw means that only your home city is off- limits to you. For six, it means that the entire Cama- rilla is howling for your vitae. This Flaw can only be taken by Camarilla vampires.]==],
				},
				["Blood Magick"] = {
					en = [==[Book of Secrets, p. 92


Blood Magick


Your Arts demand blood… specifically, your own blood. And while many practices employ small amounts of ritual cutting or bloodletting, this degree of sacrifice demands an injurious amount of vital fluid each time you cast a spell.

With this Flaw (mislabeled as a Merit in the sourcebook Sorcerer, Revised Edition), you must suffer one unsoakable health level in bashing damage whenever you employ an Ef- fect. Story-wise, you cut yourself, slash designs in your skin, or otherwise hurt yourself enough to shed the required amount of blood. This sort of thing can, of course, add up quickly if you're throwing lots of magick around without giving yourself a chance to heal, as bashing damage soon leads to lethal damage (see Types of Injury in Mage 20, p. 406). Meanwhile, your bloodletting looks pretty gross and obvious (often vulgarly so), and tends to make a mess as well. Your companions might appreciate the results of your magick, but may well object to the methods you employ… especially since blood magick has a rather unsavory rep among all but the most primal of practices.]==],
				},
				["Blood Weakness (4)"] = {
					en = [==[Lore of the Bloodlines, p. 4


Blood Weakness (4)


The bloodline began as an experiment in manufacturing a Kindred from diverse bloodlines. They perfected the alchemical process, but somewhere along the way, a weakness in an ancestor caught hold. It manifested in your Embrace. In addition to the weaknesses you possess, you also possess either the Gangrel (V20, p. 55) or the Tzimisce weakness (V20, p. 71). For four points, choose one of the two weaknesses. For seven points, you possess both. Warrior Gargoyles with the Gangrel weakness version of Blood Weakness may gain both animal features and stone features from one frenzy.

Additionally, choose one of the four Disciplines available to the Gargoyles. For you, this Discipline is considered out of Clan and costs the higher amount of experience points to advance.]==],
				},
				["Blood Weakness (7)"] = {
					en = [==[Lore of the Bloodlines, p. 4


Blood Weakness (7)


The bloodline began as an experiment in manufacturing a Kindred from diverse bloodlines. They perfected the alchemical process, but somewhere along the way, a weakness in an ancestor caught hold. It manifested in your Embrace. In addition to the weaknesses you possess, you also possess either the Gangrel (V20, p. 55) or the Tzimisce weakness (V20, p. 71). For four points, choose one of the two weaknesses. For seven points, you possess both. Warrior Gargoyles with the Gangrel weakness version of Blood Weakness may gain both animal features and stone features from one frenzy.

Additionally, choose one of the four Disciplines available to the Gargoyles. For you, this Discipline is considered out of Clan and costs the higher amount of experience points to advance.]==],
				},
				["Blood-Hungry Soul (2)"] = {
					en = [==[Book of Secrets, p. 87


Blood-Hungry Soul (2)


In a previous incarnation, you had been a ghoul in thrall to an unholy addiction to vampiric blood. Now, you must resist the call of that ravenous past life and its fixation on intoxicating Kindred vitae.

The deeper your thirst for this damning fulfillment, the more this Flaw is worth: (2 points) You recall the glorious temptations of the

blood, but remember it like a poor choice from long

ago. If the opportunity presents itself to you, however,

you'll need to make a Willpower roll (difficulty 5) in

order to resist the urge to pursue that addiction again. If

you succumb to that temptation again in this life, your

difficulty to resist further temptations rises to 6 every

time the chance to consume such blood arises again. (3 points) That temptation is stronger. Now the roll to

resist that first taste is 6, and the roll to resist further

crimson snacks becomes 8. (5 points) You've got it bad. Really bad! Obsessed with

the memories of glorious mystic blood, you must beat

difficulty 8 in order to resist your old habits, and diffi-

culty 10 each time you try to deny that thirst after you've

fallen back to that damned addiction again.

This is so not going to end well… See the sidebar Mages, the Blood Bond, and the Effects of Vitae, p. 76, for the long- term effects of such fatal addictions.]==],
				},
				["Blood-Hungry Soul (3)"] = {
