				},
				["Body Trail"] = {
					en = [==[Lore of the Bloodlines, p. 5


Body Trail


Whether the Nagaraja is just too sloppy and prone to overlooking details during her kills or she is especially fond of leaving a signature for every kill to send a message to others, others can use this to track her down. Each time there are items at a scene of a crime that could link directly back the Nagaraja, causing her to always look over her shoulder. The police are always one step away from busting her, or the Camarilla's assassins have her in their sights. In any case, leaving a trail is a terrible thing. For every person they kill during a single story, the difficulty to Survival checks for tracking are reduced by 1. This penalty resets at the beginning of a new story… if they survive to the next story, that is.]==],
				},
				["Botched Presentation"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Botched Presentation


When your sire presented you to the Prince of the city, you flubbed it. Now you're convinced His Majesty hates you (whether he does or not). You need to suc- ceed on a Willpower roll (difficulty 7) just to stand in front of the Prince or one of his duly authorized rep- resentatives without running, blubbering, or otherwise making a fool of yourself. This Flaw can only be taken by Camarilla vampires.]==],
				},
				["Bound (Mage)"] = {
					en = [==[Book of Secrets, p. 92


Bound (Mage)


Mentor always told you not to make bargains with strange entities. But did you listen? Nope. Now you're in deep to someone whose power dwarfs your own, and your prospects for getting out of bondage are laughable at best. Haunted by thoughts of the payment to come, you live on borrowed time and realize that the worst is yet to come…

Sometimes known, with minor variations, as Faust's Bargain, Bound puts your character in the Faust-like position of getting something interesting in return for something sig- nificant – her life, her soul, a thousand years of servitude, or a similarly awful fate that no one in their right mind would want to risk. Still, occultists are infamous for short-term thinking, and literal devil's deals are common currency in the magickal world. The specifics of that deal are for you and your Story- teller to arrange; you might have received some Merit(s) and / or Abilities in return for the debt (purchased with the points from this Flaw), escaped an awful situation (“You want out of this death-trap, dear wizard? Very well – what do you have to offer me?”), saved someone who was important to you (“Sure, I'll bring your mother back from the brink of death – let us discuss the terms of this favor…”), or otherwise blew a standoff with an Otherworldly entity (see the Summoning, Binding, Bargaining, and Warding section of How Do You DO That? pp. 91-95).

Like the Flaw: Dark Fate (below), this debt throws a fore- boding air over your character's part of the chronicle. In this case, though, your doom may be averted if you can wrangle a way out of this pact. In the meantime, your creditor will call in occasional favors – nothing large enough to pay off the debt (unless that entity needs a significant service and agrees to write off the larger obligation), but deeds that can spark new stories or complicate existing ones. Despite tradition, this debt doesn't have to be a soul-pact owed to a devil – a promise to your god(s) or their immediate emissaries can be just as terrible as one owed to Old Scratch!]==],
				},
				["Bound (Vampire)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Bound (Vampire)


You are blood bound to another vampire. Your reg- nant may not necessarily treat you badly, but the fact remains that your will is not entirely your own. The knowledge gnaws at you, even as you find yourself lost in devotion to your vampiric master. Sabbat vampires cannot take this Flaw.]==],
				},
				["Bound to the Clan"] = {
					en = [==[Lore of the Clans, p. 219


Bound to the Clan


You have done more than just drink from the blood of the elders. Whether as punishment or by choice, you have become fully blood bound to Clan Tremere. You cannot act against the Clan, and find everything you do works in the service of the Tremere. You might not like it, but you can't help yourself doing it. Of course, now you are bound to the Clan, you cannot be bound to another individual. Many older Tremere have this Flaw, as it has been common in the past to completely blood bind new Tremere.]==],
				},
				["Branded (3)"] = {
					en = [==[Book of Secrets, p. 89


Branded (3)


You've been found guilty by a Traditions Tribunal, who Branded your Avatar with a sigil that indicates your crime. Folks who can see that sigil recognize that you're a criminal of some sort, and the worse the Brand, the more severe your crime and the more appropriate their reaction will be. Those reactions won't always be negative; considering the sort of people who'd be favorably inclined toward a known criminal, though, do you really want the goodwill of such people? (3 points) A temporary Brand for a Low Crime (see

below), which fades after one to three months. At the

end of that period, this Flaw goes away. This Brand raises

the difficulty of your social rolls by +1 for “average”

Tradition mages and +2 for especially law-biding ones. (4 points) A lasting Brand for a Low Crime. This Brand

lasts for a year or more, and marks you as a rather

notorious offender. The difficulty of your social rolls

rises by +2 among most mages who can recognize the

Brand's significance, and +3 among mages who take

such offenses and punishments seriously. (5 points) A lasting Brand for a High Crime, which will

not fade for at least nine years and may be essentially

permanent. The Brand raises the difficulty of your so-

cial rolls by +3 for any character who cares at all about

Tradition justice and the people who incur its pun-

ishment. Certain parties will target you for additional

punishment, and others will consider you to be prime

meat for their recruiting efforts.

For details about Tradition crimes and punishments, see Chapter Four's entries regarding Crimes and Punishments in the section Among the Traditions, pp. 213-219.]==],
				},
