				},
				["Brittle Body (2)"] = {
					en = [==[Lore of the Bloodlines, p. 91


Brittle Body (2)


Your already disfigured corpse doesn't handle the physical demands of being a Kindred as well as it should. Your bones break at inopportune times, your skin tears if you move too quickly, and you have to be careful on a nightly basis. The 2-point version of this flaw gives you a +2 difficulty to all Physical rolls because of the delicate nature of your body. The 4-point version means that you also hang onto physical damage longer than other Kindred. You may still heal health levels as normal, but any dice penalties remain until the next evening when you awaken. This is in addition to the penalty to Physical rolls.]==],
				},
				["Brittle Body (4)"] = {
					en = [==[Lore of the Bloodlines, p. 91


Brittle Body (4)


Your already disfigured corpse doesn't handle the physical demands of being a Kindred as well as it should. Your bones break at inopportune times, your skin tears if you move too quickly, and you have to be careful on a nightly basis. The 2-point version of this flaw gives you a +2 difficulty to all Physical rolls because of the delicate nature of your body. The 4-point version means that you also hang onto physical damage longer than other Kindred. You may still heal health levels as normal, but any dice penalties remain until the next evening when you awaken. This is in addition to the penalty to Physical rolls.]==],
				},
				["Broken Antitribu"] = {
					en = [==[Lore of the Clans, p. 26


Broken Antitribu


You are one of those most pitiful things — an Assamite antitribu who still labors under the Tremere Curse. You have pledged yourself to the Sabbat, but you cannot perform diablerie and can only partake of Kindred vitae already transubstantiated through the Vaulderie. As a result, the difficulty of all Social rolls against other Sabbat members is at +2.]==],
				},
				["Bulimia"] = {
					en = [==[Lore of the Clans, p. 270


Bulimia


You hunger for blood, and like all vampires, you will

eventually feed, but the thought of it still makes you

sick. Maybe you're just not cut out for an eternity of

bloodsucking, or you had an eating disorder in life that

has followed you to the other side of mortality. Whatever

the reason, you can't hold your blood. Whenever you

feed, make a Stamina roll with a difficulty 8. If you fail,

you vomit out the fresh blood before it can be absorbed

into your body, spraying it everywhere (embarrassing at

best, a breach of the Masquerade at worst). Note that

blood taken in frenzy is absorbed normally, though

this carries its own risks.]==],
				},
				["flaw|Cannibal"] = {
					en = [==[Ghouls & Revenants, p. 136


Cannibal


Though the Bratovich family of revenants is known for their depravity, the desire to consume human flesh is not limited to them alone. Historically, mortals have resorted to acts of cannibalism during times of war or starvation, but they have also eaten the flesh of the dead as part of a religious ceremony to honor the fallen, too. The vast majority of cultures, however, consider the practice barbaric and unnatural.

To become a Cannibal, is to put your character at risk of ostracization and death. There are several physical disorders that can be transmitted through the consumption of infected flesh or organs. For the most part, such an infection is undetectable through normal, non-medical means. Should you eat human flesh as a ghoul, the vitae you've already ingested is likely strong enough to negate the effects in most cases. Should your ghoul be denied future feedings, however, the infection will take hold as your body returns to its natural state and age.

A character with the Cannibal Flaw will generally only feed on the flesh of the living or the dead in privacy. Most cannibals are not rabid animals, and are cunning and highly intelligent. They are aware that modern society frowns on cannibalism, but they feel compelled to do it anyway. Thus, they are often careful to act on their Flaw in places and at times where they and their victims cannot be easily discovered. Missing corpses or well-loved people, for example, are likely to be searched for. If there are witnesses who spotted the cannibal and victim together, it might lead to further complications a Cannibal is not prepared to deal with. A Willpower roll may be called for to determine if the cannibal can exercise sufficient control and discretion to avoid leaving clues behind.

The Cannibal Flaw may be selected by any ghoul, or may be bestowed upon a character by the Storyteller as a result of acquiring a Derangement. Though this Flaw is far more common among revenant families, it is not exclusively available to them. Because of the dramatic impact the Cannibal Flaw has on ghouls in modern society, Camarilla ghouls are discouraged from taking this Flaw.

Used by: Revenants, some Sabbat and independent ghouls]==],
				},
				["Cannot Embrace"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Cannot Embrace


Through some curse, weakness, or defect in your vampirism, you are unable to create progeny. You may not be aware of this until it is too late and a victim lays bleeding out in your arms.]==],
				},
				["Can't Cross Running Water"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 495


Can't Cross Running Water


You believe in the old folklore, and cannot cross run- ning water unless you are at least 50 feet (15 meters) above it. Running water is considered to be any body of water at least two feet (half a meter) wide in any direc- tion and not completely stagnant.]==],
				},
				["Carrion Presence"] = {
					en = [==[Lore of the Bloodlines, p. 16


Carrion Presence


This affliction represents the Baali's true connection to the decrepitude their bloodline commands. Pestilence is attracted to the Baali; flies leave their delicious carcasses to circle around the vampire, rats crawl along their limbs and squeak their praises, and vultures can be seen circling them at almost all times. The degree to which they are afflicted differs from character to character, but there is no getting rid of their swarm. Swatting their flies simply calls others to take their place. While quite disgusting to most, these vampires wear such a thing with pride. It does, however, make dealing in non-Baali circles quite difficult.]==],
				},
				["Cast No Reflection"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Cast No Reflection


You actually cast no reflection, just like the vampires of legend. This can have a detrimental effect when try- ing to pass as a human. Vampires of Clan Lasombra au- tomatically have this Flaw (and you may be mistaken for one of them if you possess this).]==],
				},
				["Cast No Shadow or Reflection (1)"] = {
					en = [==[Book of Secrets, p. 82


Cast No Shadow or Reflection (1)


According to certain legends, witches cast no shadow. And while that isn't true of most mages, it's somehow true for you. Maybe you suffer from a lingering Paradox Flaw, manifest your own cultural fears, or made a bargain that cost you your shadow or reflection. In any case, your shadow and /or reflection are absent from your presence. For one point, you're missing one of those things, for two points you lack them both, and although most folks won't notice this consciously, they do tend to feel uneasy in your presence even if they're not sure why. (Techno- logical machines record this phenomenon, too.) Add +1 to the difficulty of all your Social-Trait rolls under most circumstances, and +2 to the difficulty if a witness makes a perception-based roll (difficulty 7) and figures out why you seem so weird.]==],
				},
				["Cast No Shadow or Reflection (2)"] = {
					en = [==[Book of Secrets, p. 82


Cast No Shadow or Reflection (2)


According to certain legends, witches cast no shadow. And while that isn't true of most mages, it's somehow true for you. Maybe you suffer from a lingering Paradox Flaw, manifest your own cultural fears, or made a bargain that cost you your shadow or reflection. In any case, your shadow and /or reflection are absent from your presence. For one point, you're missing one of those things, for two points you lack them both, and although most folks won't notice this consciously, they do tend to feel uneasy in your presence even if they're not sure why. (Techno- logical machines record this phenomenon, too.) Add +1 to the difficulty of all your Social-Trait rolls under most circumstances, and +2 to the difficulty if a witness makes a perception-based roll (difficulty 7) and figures out why you seem so weird.]==],
				},
				["Catspaw"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Catspaw


You've done dirty work for someone high up in the city's hierarchy in the past — the Sheriff, the Bishop, or even someone higher. However, instead of granting you favor, your deeds have made you an embarrassment or a liability. For the moment, your former employer's concern is to keep you quiet. In the long term, it's to get rid of you.]==],
				},
				["Chandala"] = {
					en = [==[Lore of the Clans, p. 182


Chandala


Being a member of the the Chandala jati is a mixed bag. You are responsible for the disposal of corpses, as well as many other foul tasks, but at the same time, you are often ignored. Your Social rolls against other Ravnos are made at a +2 difficulty.

You do not have to take this Flaw to be a member of the Chandala jati, but only members of the Chandala jati may have this Flaw.]==],
				},
				["Child"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Child


You were a small child (between five and 10 years old) at the time of your Embrace, leaving your Physical Attributes underdeveloped and making it difficult to interact with some aspects of mortal society. You may not have more than two dots in Strength or Stamina at character creation, except when raising Physical At- tributes with blood points, and the difficulties of all die rolls when attempting to direct or lead mortal adults are increased by two. Characters with this Flaw should also take the Short Flaw.]==],
				},
				["Chronic Depression"] = {
					en = [==[Book of Secrets, p. 51


Chronic Depression


Regardless of your external circumstances, you often feel drawn toward despair. Everything seems overwhelming, point- less, and at best a fucking joke at the world's expense. That feeling pervades each aspect of your existence: your attitude, your physical health, your relationships, and even – especially! – your approach to magick and all its manifestations. (See the Mage 20 sections about Focus and the Arts, Resonance, Quiet, and the Vidare perceptions of the Otherworlds.) TL/DR: It really sucks to be you.

Often viewed as a purely psychological issue (“It's all in your pretty little head…”), chronic depression tends to be linked to physiological Impediments, as in the Physical Flaw of that name. This Flaw can also reflect the psychic aftermath of Paradox backlashes, Quiet episodes, Things Man Was Not Meant to Know, Mind-Sphere attacks, and other forms of trauma (break- ups, violation, disaster, and the like), although trauma-induced depression is most often a manifestation of the Flaw: PTSD, referenced above. Regardless of its origins, the psychological element of depression is inescapable. The emotional weight of constant despair tends to sap physical vitality, which comes back around and inspires more depression. No wonder chronically depressed people have a hard time “living life to the fullest.” On some days, just getting out of bed without falling into a crying heap is a challenge.

Story-wise, this Flaw influences roleplaying and character descriptions as suggested above. System-wise, it often requires you to make a Willpower roll when your depressed character needs to push himself beyond the depression. A successful roll means that he acts without hindrance. A failed one adds +2 to the difficulty of the primary task at hand, which could involve Attributes from the Physical (depression drains vitality), Social (undercuts relationships with other folks), or Mental (mental fuzz) categories, depending upon the situation. A botched roll means that the depression takes over and drops him into a deep black pit of despair in which he'll be stuck for hours or even days at a time.

You can spend a Willpower point to shove depression aside, avoiding this roll entirely. However, as anyone who understands the analogy of spoons can attest, sooner or later you run out of Willpower points. (For those who are not familiar with the analogy, it's the idea that you have a limited number of spoons to use each day; every task demands that you give up one spoon, and so you soon run out of spoons). The fact that people tend to get frustrated with your Black Cloud of Doom™ doesn't exactly help matters much; hell, you're more frustrated with that shit than anybody else is! So seriously – in all aspects of one's life, Chronic Depres- siontown is not a fun place to be… not even for fans of the World of Darkness.]==],
				},
				["Clan Enmity"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Clan Enmity


One Clan in particular wants you dead. You have of- fended the entire Clan, from elders to neonates, and as a result every member of that bloodline wants your head on a plate. The effects of the Flaw may manifest as anything from very public snubs and insults to actual attempts on your unlife. You are also at +2 difficulty on all Social rolls relating to members of the Clan in question.]==],
				},
				["Clan Weakness"] = {
					en = [==[Lore of the Clans, p. 270


Clan Weakness


Despite your failure to adopt your original Clan's

other abilities, you did inherit their weakness. While

this can be deadly to the unprepared vampire, a canny

Caitiff might turn this to their advantage to better blend

among the parent Clan. Some Nosferatu, for example,

would likely never notice, and might even stand up

for the Caitiff even amidst accusations from outsiders.]==],
				},
				["Cloaked in Shadow"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Cloaked in Shadow


Shadows cling to you constantly. These are not the ordinary shadows cast simply by existing; the darkness around you is thick and heavy, making it impossible for you to pass as anything other than something supernatural. In addition to this complication, the difficulty for Social rolls with other vampires (especially the Lasombra) increases by one.]==],
				},
				["Cloistered"] = {
					en = [==[Lore of the Clans, p. 219


Cloistered


You have spent almost all of your undead existence in the halls of the chantry, making Kindred society rather new and confusing for you. You suffer a -2 dice penalty to any social interactions with those outside the Tremere.]==],
				},
				["Cold Breeze"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Cold Breeze


A chill wind follows you everywhere you go. While it may make for dramatic entrances, this effect also dis- comfits mortals (+1 difficulty on all appropriate Social rolls) and marks you as obviously supernatural. Cold winds sweeping through executive offices or crowded nightclubs can raise all sorts of questions.]==],
				},
				["Combat Novice"] = {
					en = [==[The Hunters Hunted II, p. 42


Combat Novice


Your character might talk a good game, but he's never been around real violence, and when it happens, he's not likely to respond well. When confronted with gunfire; obvious, brutal combat (blood drawn, stab wounds, bones breaking); or any kind of supernatural violence, roll Willpower (difficulty 7). If this roll fails, the character either freezes in place (if his Courage is higher than his Self-Control) or flees the area (if his Self-Control is higher than his Courage).

You must make this roll for every scene in which he witnesses a violent occurrence, but if you accumulate five successes, no further rolls need be made for that night of game time. An especially gory show of violence can reset the character's total, however, at the Storyteller's discretion.]==],
				},
				["Compulsion"] = {
					en = [==[Book of Secrets, p. 46


Compulsion


An almost reflexive mental tic drives you toward compul- sive, often subconscious, behaviors. In some cases, especially among mages, these behaviors manifest as ritualized activities: hand-washing, obsessive grooming, doing a task exactly the same way every time, and so forth. Other compulsions inspire annoying habits (humming, making farty noises with your mouth, speaking out loud even when you don't mean to, etc.), or potentially harmful activities like shoplifting, gambling, or hitting on everything that moves, which manifest when you're under stress. (A seriously harmful compulsion could be considered a Derangement Flaw instead, as referenced below.)

Minor compulsions tend to get chalked up to the ra- tionalization, “That's just what she's like.” If you want your character to avoid a serious compulsion, however, you must spend a Willpower point in order to put off that behavior for a little while. However, once that little while is up (Storyteller's discretion), your character is again compelled to perform that activity… unless you spend another Willpower point… to put it off again for a little while longer…]==],
				},
				["Compulsive Speech (1)"] = {
					en = [==[Book of Secrets, p. 59


Compulsive Speech (1)


Dude, please just shut up! But no, you just keep talking… and talking… and talking some more. This compulsion could come from a nervous social habit, a know-it-all personality, a sense of awkwardness in silence, or some other (potentially metaphysical) urge to fill up space with words. Worse still, those words often feature rude observations, sensitive information, and other stuff that's best left unsaid. Day-um – did you just say what I think you just said? Yep. You did. Arg…

As far as this Flaw is concerned, the one-point version means you run at the mouth too much, while the two-point one (also known as Big Mouth) means you say the wrong things to the wrong people on a fairly regular basis, often to people who sit higher than you do on the proverbial totem pole, or who do not exactly have your best interests at heart. You can spend a Willpower point to keep your mouth shut for a scene or two; sooner or later, though, the words start flowing again…]==],
				},
				["Compulsive Speech (2)"] = {
					en = [==[Book of Secrets, p. 59


Compulsive Speech (2)


Dude, please just shut up! But no, you just keep talking… and talking… and talking some more. This compulsion could come from a nervous social habit, a know-it-all personality, a sense of awkwardness in silence, or some other (potentially metaphysical) urge to fill up space with words. Worse still, those words often feature rude observations, sensitive information, and other stuff that's best left unsaid. Day-um – did you just say what I think you just said? Yep. You did. Arg…

As far as this Flaw is concerned, the one-point version means you run at the mouth too much, while the two-point one (also known as Big Mouth) means you say the wrong things to the wrong people on a fairly regular basis, often to people who sit higher than you do on the proverbial totem pole, or who do not exactly have your best interests at heart. You can spend a Willpower point to keep your mouth shut for a scene or two; sooner or later, though, the words start flowing again…]==],
				},
				["Conflicting Loyalties (1)"] = {
					en = [==[Book of Secrets, p. 59


Conflicting Loyalties (1)


Though deeply loyal (probably to the point of having the Merit: Loyalty – see p. 53), you're facing a crisis of commit- ments: two or more of the parties you feel loyal to are at odds with one another, and you're caught in the middle trying to support them all. Your best friend could be in trouble with the police force your father worked for; your lover may have betrayed the trust of your Convention; your Allies may have decided that your Mentor has to go. And so there you are – poised in an impossible situation, attempting to do the right thing for everyone involved.

The value of this Flaw, as always, depends upon the in- tensity of the conflict: (1 point) A minor crisis forces you to shuttle between

loyalties while remaining true to all parties. (2 points) A significant clash leads you to mediate un-

tenable situations with frustrating frequency. (3 points) Irreconcilable differences will eventually

compel you to choose between loyalties, and that's not a

choice you're sure you can make. Until that time, you're

fighting an apparently doomed campaign to support all

sides without betraying anyone.

The nature of your loyalties, relationships, and disputes should, of course, be worked out when you take this Flaw. Your Storyteller will make sure to bring them into play often enough to keep you scrambling for the best solution to an apparently impossible dilemma.]==],
				},
				["Conflicting Loyalties (2)"] = {
					en = [==[Book of Secrets, p. 59


Conflicting Loyalties (2)


Though deeply loyal (probably to the point of having the Merit: Loyalty – see p. 53), you're facing a crisis of commit- ments: two or more of the parties you feel loyal to are at odds with one another, and you're caught in the middle trying to support them all. Your best friend could be in trouble with the police force your father worked for; your lover may have betrayed the trust of your Convention; your Allies may have decided that your Mentor has to go. And so there you are – poised in an impossible situation, attempting to do the right thing for everyone involved.

The value of this Flaw, as always, depends upon the in- tensity of the conflict: (1 point) A minor crisis forces you to shuttle between

loyalties while remaining true to all parties. (2 points) A significant clash leads you to mediate un-

tenable situations with frustrating frequency. (3 points) Irreconcilable differences will eventually

compel you to choose between loyalties, and that's not a

choice you're sure you can make. Until that time, you're

fighting an apparently doomed campaign to support all

sides without betraying anyone.

The nature of your loyalties, relationships, and disputes should, of course, be worked out when you take this Flaw. Your Storyteller will make sure to bring them into play often enough to keep you scrambling for the best solution to an apparently impossible dilemma.]==],
				},
				["Conflicting Loyalties (3)"] = {
					en = [==[Book of Secrets, p. 59


Conflicting Loyalties (3)


Though deeply loyal (probably to the point of having the Merit: Loyalty – see p. 53), you're facing a crisis of commit- ments: two or more of the parties you feel loyal to are at odds with one another, and you're caught in the middle trying to support them all. Your best friend could be in trouble with the police force your father worked for; your lover may have betrayed the trust of your Convention; your Allies may have decided that your Mentor has to go. And so there you are – poised in an impossible situation, attempting to do the right thing for everyone involved.

The value of this Flaw, as always, depends upon the in- tensity of the conflict: (1 point) A minor crisis forces you to shuttle between

loyalties while remaining true to all parties. (2 points) A significant clash leads you to mediate un-

tenable situations with frustrating frequency. (3 points) Irreconcilable differences will eventually

compel you to choose between loyalties, and that's not a

choice you're sure you can make. Until that time, you're

fighting an apparently doomed campaign to support all

sides without betraying anyone.

The nature of your loyalties, relationships, and disputes should, of course, be worked out when you take this Flaw. Your Storyteller will make sure to bring them into play often enough to keep you scrambling for the best solution to an apparently impossible dilemma.]==],
				},
				["Conniver"] = {
					en = [==[Book of Secrets, p. 60


Conniver


As far as most folks who know you are concerned, you're a perpetual knife in someone else's back. That rep might not be accurate (see the Flaws: Cultural Other, Infamy, Troublemaker, and Profiled Appearance), but people expect treachery from you even if they're wrong to think so. Subtract one die from any non-magickal dice pool you employ when you're trying to get other characters to trust you. This penalty does not extend to Arete dice pools when you're casting Mind-Sphere magick (or any other Sphere's magick, for that matter), but if you're having to cast spells in order to be believed, then you've kinda just lived up to that reputation.]==],
				},
				["Conspicuous Consumption"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Conspicuous Consumption


It is not enough for you to draw nourishment from the blood of mortals — you believe you must also con- sume your victim's heart, liver, and other blood-rich tissue. Of course, this will necessitate the deaths of all of your victims (unless you are extremely creative), which might lead to numerous problems with main- taining Humanity (and a low profile). Characters with this Flaw should additionally purchase the Eat Food Merit.]==],
				},
				["Construct"] = {
					en = [==[M20 Victorian Age, p. 122


Construct


As the Order of Reason has

not yet advanced technology to genetic engineering or

cloning, players selecting this Flaw to create artificial

“people” such as clockwork automatons or other tech-

nological creations should discuss the implications with

their Storyteller. Permanent entanglement with the

Straits likely accompanies this Flaw. Awakened golems,

reanimated corpses, and other mystical creations risk

the same danger.]==],
				},
				["Consumption"] = {
					en = [==[Lore of the Clans, p. 239


Consumption


There is something hungry inside of you. But what is it? Portions of the Antediluvian? Your Vicissitude gone horribly wrong? Whatever it is, it is active, acting like a cancer, devouring you from the inside out. Your very blood is wrought with corrosive, flesh-eating bacteria. At the beginning of each evening, you suffer one health level of lethal damage that cannot be soaked nor healed with blood. The only way to counteract the effect is by ingesting one-tenth of your body-weight in flesh to supplement your depleted carcass. Whether you kill and devour the skin from humans or raid the biohazard containers of liposuction clinics for siphoned fat, you need your ration of human flesh in order to survive. If you try and ingest this macabre meal before damage is done, you'll simply vomit it out like any other food — this does not impart the benefits of the Eat Food Merit. 239]==],
				},
				["Contagious"] = {
					en = [==[Lore of the Clans, p. 163


Contagious


Your body is still dying on the inside, your rotting entrails providing nutrition for noxious bacteria, spores, and even fungi. Mortals that touch you or on whom you feed must make a Stamina roll (difficulty 9) not to fall ill. The illness puts them in bed with fever and sickness, and each week they may attempt the Stamina roll again. The Storyteller might reduce the difficulty if the target is receiving proper medical LORE OF THE CLANS attention. On a success they recover, but if they fail, they remain feverish. At the end of each month the victim remains ill, they lose a point of Stamina; if they are reduced to zero Stamina they die. If the Nosferatu knows of their contagion and infects someone maliciously, the Storyteller might call for a Humanity (or appropriate Path of Enlightenment) degeneration roll if they die. Supernatural creatures generally have the ability to heal or cure such sickness in themselves, and vampires are immune to these germs of the dead.]==],
				},
				["Credulous (3)"] = {
					en = [==[The Hunters Hunted II, p. 133


Credulous (3)


You believe in monsters and conspiracies, and your fellow agents know it. This credulous reputation makes you a liability — no matter how much of the truth you actually know. With the three-point version of this Flaw you're still a field agent, but your fellow agents either ignore you or openly mock you. Subtract one die from all Empathy, Investigation, or Leadership rolls when dealing with members of the intelligence community. If a supernatural creature is looking for a scapegoat, your name is top of the list.

With the five-point version of this Flaw, you're on your way out. You've got a make-work assignment — maybe a feasibility study for building a wall along the Canadian border, or listening for intelligence coming out of the New Zealand field office. You won't get any backup, and if you continue to make trouble (by, say, investigating supernatural creatures), people high up in your agency's food chain will arrange an accident to shut you up permanently. Asset]==],
				},
				["Credulous (5)"] = {
					en = [==[The Hunters Hunted II, p. 133


Credulous (5)


You believe in monsters and conspiracies, and your fellow agents know it. This credulous reputation makes you a liability — no matter how much of the truth you actually know. With the three-point version of this Flaw you're still a field agent, but your fellow agents either ignore you or openly mock you. Subtract one die from all Empathy, Investigation, or Leadership rolls when dealing with members of the intelligence community. If a supernatural creature is looking for a scapegoat, your name is top of the list.

With the five-point version of this Flaw, you're on your way out. You've got a make-work assignment — maybe a feasibility study for building a wall along the Canadian border, or listening for intelligence coming out of the New Zealand field office. You won't get any backup, and if you continue to make trouble (by, say, investigating supernatural creatures), people high up in your agency's food chain will arrange an accident to shut you up permanently. Asset]==],
				},
				["Crucial Component (2)"] = {
					en = [==[Book of Secrets, p. 87


Crucial Component (2)


Your metaphysical practice demands specialized instru- ments. It's not simply that you need fuel for your hypermodded Porsche 911 Turbo S – you need your own specially prepared blend of fuels, or the car won't go. A simple rowan wand will not suffice – your spells demand a hand-carved branch cut from an unscarred rowan tree at high midnight on Samhain Eve. In game terms, at least one of the instruments in your magickal focus must be specifically created, harvested or modified to work with your magicks. No lesser tool will suffice.

How hard is it to procure or employ this specialized com- ponent? That depends on the value of the Flaw: (2 points) Easy to procure and /or employ (sunlight,

yoga postures, motor oil, strong emotions, a book

commonly found in the New Age section at your local

bookstore, etc.). (3 points) Challenging to procure, employ, or replace

(open flames, the Kurmasana posture, professional

racing oil, genuine sorrow, an out-of-print occult text,

and so on). (4 points) Pretty damned hard to obtain, employ, and

replace (liquid fire, the Vrschikasana pose, alchemically

formulated oil, deep-core grief, a genuine Roman text

of De Daemonum Socrates by Apuleius, and other rare

and precious instruments). (5 points) Unique, obscure, forbidden, cumbersome, or

some combination of those four (a bottle of alchemically

distilled sunfire, an impossibly complex yoga posture

invented by the practitioner, personally formulated and

distilled hypertech lubricating oil, the heartfelt scream

of a grieving mother, a woodcut-illustrated Renaissance

Grimoire of Honorius inscribed on flayed human skin,

and similarly rarified instruments).

When used, the chosen instrument functions as a Person- alized Instrument (Mage 20, pp. 503 and 587) – possibly a Unique Personalized one in the case of a five-point component. In your case, however, you cannot employ the magick that's connected to that instrument at all unless you're also able to employ that particular instrument. If Lee Ann Milner depends upon a unique vengeful centipede yoga posture in order to employ certain Forces Effects through her yoga practice, then Lee Ann is SOL unless she can assume that posture in time to deploy the necessary Effects.

In the original version of this Flaw, the material was bound to a specific Sphere Effect. This revised version ties the Crucial Component to a tool you employ. This change makes it easier to keep track of the component and its uses, employing the new focus rules presented in Mage 20, Chapter Ten, so that the Flaw becomes an integral part of the way your mage per- forms magickal Effects. For details about Assigning Practices and Instruments to Effects, see the section of that name in Chapter Three, p. 169.]==],
				},
				["Crucial Component (3)"] = {
					en = [==[Book of Secrets, p. 87


Crucial Component (3)


Your metaphysical practice demands specialized instru- ments. It's not simply that you need fuel for your hypermodded Porsche 911 Turbo S – you need your own specially prepared blend of fuels, or the car won't go. A simple rowan wand will not suffice – your spells demand a hand-carved branch cut from an unscarred rowan tree at high midnight on Samhain Eve. In game terms, at least one of the instruments in your magickal focus must be specifically created, harvested or modified to work with your magicks. No lesser tool will suffice.

How hard is it to procure or employ this specialized com- ponent? That depends on the value of the Flaw: (2 points) Easy to procure and /or employ (sunlight,

yoga postures, motor oil, strong emotions, a book

commonly found in the New Age section at your local

bookstore, etc.). (3 points) Challenging to procure, employ, or replace

(open flames, the Kurmasana posture, professional

racing oil, genuine sorrow, an out-of-print occult text,

and so on). (4 points) Pretty damned hard to obtain, employ, and

replace (liquid fire, the Vrschikasana pose, alchemically

formulated oil, deep-core grief, a genuine Roman text

of De Daemonum Socrates by Apuleius, and other rare

and precious instruments). (5 points) Unique, obscure, forbidden, cumbersome, or

some combination of those four (a bottle of alchemically

distilled sunfire, an impossibly complex yoga posture

invented by the practitioner, personally formulated and

distilled hypertech lubricating oil, the heartfelt scream

of a grieving mother, a woodcut-illustrated Renaissance

Grimoire of Honorius inscribed on flayed human skin,

and similarly rarified instruments).

When used, the chosen instrument functions as a Person- alized Instrument (Mage 20, pp. 503 and 587) – possibly a Unique Personalized one in the case of a five-point component. In your case, however, you cannot employ the magick that's connected to that instrument at all unless you're also able to employ that particular instrument. If Lee Ann Milner depends upon a unique vengeful centipede yoga posture in order to employ certain Forces Effects through her yoga practice, then Lee Ann is SOL unless she can assume that posture in time to deploy the necessary Effects.

In the original version of this Flaw, the material was bound to a specific Sphere Effect. This revised version ties the Crucial Component to a tool you employ. This change makes it easier to keep track of the component and its uses, employing the new focus rules presented in Mage 20, Chapter Ten, so that the Flaw becomes an integral part of the way your mage per- forms magickal Effects. For details about Assigning Practices and Instruments to Effects, see the section of that name in Chapter Three, p. 169.]==],
