				},
				["Curiosity"] = {
					en = [==[Book of Secrets, p. 48


Curiosity


You simply can't resist a good mystery! A nagging sense of curiosity drags you into all kinds of sticky situations. Given your abilities, you've got a decent chance at finding things out, too… which is not, especially in the World of Darkness, an especially healthy thing to do. Isn't that just like a damn mage, anyway?

When confronted with an enticing clue or enigmatic cir- cumstance, make a Wits roll to avoid giving in to temptation. The difficulty for that roll depends upon the situation: a casual mystery (like, say, the identity of that intriguing girl behind the counter at Starbucks) would be difficulty 5, while resisting a more compelling sort of mystery (like the identity of the person who dropped off a dozen roses at your Chantry house) would be difficulty 9. Once you're on the trail, few things short of a deadly threat will make you stop… and said deadly threat might simply encourage you to dig even deeper.]==],
				},
				["Cursed (1)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Cursed (1)


You are the recipient of a supernatural curse. The strength and pervasiveness of the curse depend upon how many points you wish to incur. Examples follow:

If you pass on a secret you were entrusted with, your betrayal will come back to harm you in some way. (1 pt.)

You stutter uncontrollably when you try to describe what you have seen or heard. (2 pts.)

Tools break or malfunction when you try to use them. (3 pts.)

You are doomed to make enemies of those whom you most love or admire. (4 pts.)

Every one of your accomplishments or triumphs will eventually become soiled or fail in some way. (5 pts.)]==],
				},
				["Cursed (2)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Cursed (2)


You are the recipient of a supernatural curse. The strength and pervasiveness of the curse depend upon how many points you wish to incur. Examples follow:

If you pass on a secret you were entrusted with, your betrayal will come back to harm you in some way. (1 pt.)

You stutter uncontrollably when you try to describe what you have seen or heard. (2 pts.)

Tools break or malfunction when you try to use them. (3 pts.)

You are doomed to make enemies of those whom you most love or admire. (4 pts.)

Every one of your accomplishments or triumphs will eventually become soiled or fail in some way. (5 pts.)]==],
