				["Dangerous Secret (1)"] = {
					en = [==[Lore of the Clans, p. 161


Dangerous Secret (1)


You have come to know something you really wish you hadn't discovered. Worse yet, the people you have the 161

Buying and Selling

Information

It's hard to give an abstract system for

information. Secrets are each unique and special,

and such things often lend themselves better to

plot and story rather than dots and dice. As such,

we don't offer a specific system for selling and

knowing secrets. However, the Storyteller may

wish to allow Nosferatu a Background similar

to Anarch Information Exchange (Anarchs

Unbound p. 98) to represent their network and

control of the city's information. dirt on know that you know. It might be that you have discovered the Prince's haven, or that there are infernalists hiding in the diocese. Whatever it is, you are not sure whom you can tell, and if you do, you will only make the subjects of the secret more enthusiastic about getting rid of you. You may even be implicated in the secret and risk going down with them. The more potent the Flaw, the more powerful the people in question are, and the more they want it silenced.]==],
