				},
				["Dark Aura"] = {
					en = [==[Lore of the Bloodlines, p. 3


Dark Aura


Even without the use of Auspex, the Baali seems somehow wrong to anyone they interact with, emitting a terrifying aura of sickness and power. The character is always at a slight disadvantage when dealing with other vampires or those touched by the divine, as they sense the depravity of the Baali's soul. Baali with this Flaw suffer a +2 difficulty to all Social rolls, unless they are using Intimidation. To those who use Auspex to view the Baali's aura, it appears as a thin, red mist surrounding the character with the occasional watchful eyes appearing within.]==],
				},
				["Dark Fate"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 495


Dark Fate


You are doomed to experience Final Death or, worse, suffer eternal agony. No matter what you do, you can- not avoid this terrible fate. At some point during the chronicle, your Dark Fate will come upon you. Even more ghastly is the fact that you occasionally have vi- sions of this fate, and the malaise these images inspire requires an expenditure of a temporary Willpower point to avoid, or else you lose a die from all of your ac- tions for the remainder of the night. It is up to the Sto- ryteller to determine the exact nature of this fate, and when it will occur. This is a difficult Flaw to roleplay; ironically, though it may seem as though it removes all free will, the knowledge of one's death can be quite liberating.]==],
				},
				["Dark Secret"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Dark Secret


You have some sort of secret that, if uncovered, would be of immense embarrassment to you and would make you a pariah in the local Kindred community. This could be anything from having murdered an elder to being a member of the Anarchs.]==],
				},
				["Dead Inside"] = {
					en = [==[Lore of the Clans, p. 142


Dead Inside


You feel nothing but pain and numbness. While others find ways to make their lives worth living, you sometimes don't get that thrill. Once per session, the Storyteller may cancel any gain of Willpower points.]==],
				},
				["Deaf"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 483


Deaf


You cannot hear. While you may be more resistant to some applications of Dominate, you also may not listen to electronic or vocal media, and the difficulties of many Perception rolls are increased by three.]==],
				},
				["Deathsight"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Deathsight


Everything appears rotted and decayed to you. The world appears to you as a corpse; mortals look diseased or skeletal, buildings seem decrepit, and your fellow Kindred seem to be walking, moldering cadavers. You are at -2 difficulty to resist all rolls based on Appear- ance, but by the same token you are at +2 difficulty on all Perception-based rolls. In addition, you find so- cial interaction difficult and are at +1 difficulty on all Social-based rolls.]==],
				},
				["Debts (1)"] = {
					en = [==[Book of Secrets, p. 61


Debts (1)


Mages still need money in order to function in the human realm. And in your case, you're kinda fucked financially. Student loans, credit-card debts, child-support payments, gambling losses, legal judgments, medical bills, car and /or mortgage payments… the ways in which a modern mage can get in over her head financially are as numerous as the parties who prosper from such debts. And then there's the possibility of financial manipulation from Awakened sources – mages or Night-Folk who, intentionally or otherwise, are keeping you broke in order to assert their hold over you (see Technocracy: Syndicate, p. 28). Maybe you just suck at the whole paying-your-bills thing. For whatever reason, your income keeps going back out. You might indeed have the Background: Resources, but the money just doesn't stay in your bank account for long.

As a Flaw, these Debts represent a minimum amount of money you owe your creditors. The more you owe, the more this Flaw is worth: (1 point) Minimal debt (less than $10,000). (2 points) Moderate debt (less than $50,000). (3 points) Significant debt (over $50,000). (4 points) Crushing debt (over $100,000). (5 points) Overwhelming debt (over $500,000).

From the three-point level onward, your creditors will expend a fair amount (perhaps a great deal) of effort to collect those funds from you. Certain creditors, like loan sharks, will start far lower than that. Tactics could range from round- the-clock phone calls and red-envelope letters to lawsuits, repossessions, threats, eviction, and physical violence. For folks with small and /or irregular incomes, the pressure from debt and debt-collection harassment can cause intense emotional and psychological distress… which, in turn, affects one's ability to make money… which deepens the debt… which deepens the stress… in a desperate cycle that can lead to desperate acts.]==],
				},
				["Debts (2)"] = {
					en = [==[Book of Secrets, p. 61


