At the nine-point level, that Health loss is essentially ag- gravated damage, and cannot be healed except through vulgar Life-Sphere Effects.

Obviously, this Flaw is meaningless in one-shots or short-duration games. It should be taken only by characters (and players) involved in long-term chronicles.]==],
				},
				["Degeneration (9)"] = {
					en = [==[Book of Secrets, p. 41


Degeneration (9)


Your body is falling apart. A curse, disease, flawed biotech, corrupting magicks, or some other affliction is rotting your physical form, and although Life magick can repair the damage to some degree, this degeneration remains permanent unless the Flaw is somehow removed.

In its three-point variation, this Flaw reflects an inability to heal injuries without the aid of magick or medical technology. Until treated by Life Sphere Effects or medical intervention, the character cannot recover heath levels lost to injury, disease or other factors.

At the six-point level, the character suffers a constant stream of injuries even without outside trauma. Whenever he's at full Health, that character loses one health level every two weeks until he is either healed or he dies. As described above, he cannot heal on his own.

At the nine-point level, that Health loss is essentially ag- gravated damage, and cannot be healed except through vulgar Life-Sphere Effects.

Obviously, this Flaw is meaningless in one-shots or short-duration games. It should be taken only by characters (and players) involved in long-term chronicles.]==],
				},
				["Demented Eidolon"] = {
					en = [==[Book of Secrets, p. 89


Demented Eidolon


There's someone in your head, and it's not you. Despite your commitment to logic and reason, a mad heretic rants through the inside of your skull, insisting that what you do is magick, not science. This rough voice drives you toward Su- perstitionism and Reality Deviance. Not that you would ever consider such insanity. No, really – seriously, never.

A Flaw for Technocratic operatives and other techno- mancers who refuse to view what they do as “magic,” this Trait pits your conscious-self against an Avatar hell-bent on reclaiming the identity of mage. The Eidolon (Technocrat-ese for Essence) invested within your Genius (Avatar) whips that paragon of Enlightenment into Deviant directions. While most Technocratic Geniuses behave themselves for the most part, this one assumes a flagrantly supernatural mien and batters at the fortress of Reason (and Social Processing) that protects you from Deviant thoughts. It may even be entertaining to have a different player assume the role of your Genius, especially during a Seek… I mean, during one of those meditative interludes which allow you to process the enigmas of Enlightenment. Ideally, this Flaw compliments a Genius (Avatar) Trait rated at 3 or higher, and it goes well (from a “dramatic roleplaying” standpoint, anyway!) with Backgrounds like Past Lives, Destiny, and Legend, Merits like Twin Soul and Avatar Companion, and Flaws like Throwback, and – as one may imagine – Dark Fate.]==],
				},
				["Demon-Hounded (1)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Demon-Hounded (1)


A demon has taken a shine to you. It comes at odd and inconvenient hours and offers you bribes of wealth and power. Some days, it asks for favors; on others, it offers them. What black schemes does hell have in mind for you that one of its servants would bother you so? What fell powers have you toyed with that you should not? At 1 point, the demon is little more than an imp, asking for minor favors or stealing small objects. At 3 points, the demon is your physical or magical equal, or is a smaller threat that is willing to also drag your close friends into this affair. At 5 points, the demon is significantly powerful, able to threaten your coterie, or a lesser demon willing to torment your friends, family, and acquaintances.]==],
				},
