				["Deranged (3)"] = {
					en = [==[Book of Secrets, p. 51


Deranged (3)


See Mage 20, p. 648-650.]==],
				},
				["Deranged (5)"] = {
					en = [==[Book of Secrets, p. 51


Deranged (5)


See Mage 20, p. 648-650.]==],
				},
				["Devil's Mark"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 179


Devil's Mark


Whether product of your Embrace or gained through exposure to infernal or other unholy power, you've been branded with the “Devil's Mark,” an anatomical aber- ration that manifests the taint of the demonic. Possible deformities include, but are not limited to: bestial or inhuman eyes, hooves, horns, unnaturally colored or scaly skin, a birthmark in the form of a sigil, parasitic in- festation, claws, misshapen teeth. or ineffectual (perhaps additional) limbs. You may never remove or “improve” these disfigurements, although magic or Disciplines can hide them from plain sight.

A Devil's Mark confers the following mechanical effects: Lower the maximum rating in one Attribute by one (if the maximum rating is 5, it becomes 4), while the cost to raise said Attribute increases by one (1 + the current rating x 4). If the mark becomes visible or is known to a mortal, it confers a -1 difficulty on Intimidation rolls when dealing with her, but in turn increases the difficulties for all other Social die rolls by one. Players should work with a Storyteller to determine an appropriate Devil's Mark, and the Physical Attribute best suited to their mark.]==],
				},
				["Diabolical Mentor"] = {
					en = [==[Book of Secrets, p. 64


Diabolical Mentor


Your mentor wasn't merely bad at his job – he turned out to be actively malevolent. That person could be an actual Nephandus, a demented Marauder, a ruthless wizard, a diehard “black hats and mirrorshades” type of Technocrat, an Infernalist sellsoul… maybe you don't even know what your mentor really is, but it's just plain bad. Obviously, this personage has fucked you up. Additionally, if you've uncovered things he would rath- er keep secret, that could lead to other Flaws as well: Enemy, Cursed, and worse…]==],
				},
				["Discredited"] = {
					en = [==[Book of Secrets, p. 62


Discredited


In your chosen field, your name is mud. Perhaps you're a scientist whose bizarre theories have cost him the respect of his peers… or an academic who wound up on the wrong side of departmental politics… or a journalist who stepped too far over the line of credibility. Whatever it is you did (or are reputed to have done), your professional associates look down on you. Add +2 to the difficulty of your social and Background-based rolls when you're trying to get those associates to take you seriously. Although this is a common Flaw among the feud-happy Etherites, anyone who depends upon a professional reputation can be discredited in this fashion – professorial Hermetics, corporate-ladder Syndicate ops, White Tower agents, and other competitive-field mages can fall afoul of a bad rep too.]==],
				},
				["Disease Carrier"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 483


Disease Carrier


Your blood carries a lethal and highly contagious dis- ease. The disease can be anything from rabies to HIV, and Kindred who drink your blood have a 10% chance of becoming a carrier as well. You must spend an extra blood point each night on awakening, or you will begin manifesting symptoms of the disease (increased chance to frenzy for rabies, reduced soak rolls for HIV, etc.).]==],
				},
				["Disfigured"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Disfigured


A hideous disfigurement makes your appearance dis- turbing and memorable. The difficulties of all die rolls relating to social interaction are increased by two. You may not have an Appearance rating greater than 2.]==],
				},
				["Disgrace to the Blood"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Disgrace to the Blood


Your sire regards the fact that he Embraced you to be a titanic mistake, and has let everyone know it. You are mocked at gatherings, taunted by your peers, and actively despised by the one who should be giving you guidance. Any request or petition you make is likely to be looked down upon by friends of your sire, and your achievements are likely to be discounted.]==],
				},
				["Dogmatic"] = {
					en = [==[Book of Secrets, p. 64


Dogmatic


Look, it's great that you've got such strong spiritual con- victions… but do you have to be such a dick about them? This Flaw represents a religious, spiritual, and /or philosophical approach that defines your moral and magickal beliefs. Trouble is, your beliefs don't play well with others; rules-wise, you add +2 to the difficulty of all social rolls which involve dealing with people of differing beliefs. Even when you're trying, dammit, to get along with those misguided heretics, folks can tell that you don't approve. You sneer, you argue, you try to convert everyone around you to your way of thinking… you can't help it, really – your convictions are just that formidable! After all, you do use them to change the world, so how could they possibly be wrong?]==],
				},
				["Domitor Pariah"] = {
					en = [==[Ghouls & Revenants, p. 130


Domitor Pariah


Your master is a vampire who, for whatever reason, is unwelcome among or even hated by other members of his Clan, bloodline, or Sect. Without allies, your domitor may struggle to retain her status and will likely rely on ghouls, like yourself, to fulfill her basic needs. You may be given additional responsibilities, or you might be manipulated into spying, attacking, defending, or stealing for your domitor.

Should you take the Domitor Pariah as a Flaw, keep in mind that should other vampires discover whom you serve, your life might well be in danger. The events that led to your domitor's downfall may be kept hidden from you, at your Storyteller's discretion, or you might stumble upon your master's secrets accidentally.

Once a ghoul understands how challenging life may be with a Domitor Pariah, you might sow the seeds of rebellion despite the strength of your blood bond.

Used by: Camarilla ghouls, some Sabbat ghouls Under Surveillance (2, 4, or 6pt. Flaw)

Your ghoul's activities are being monitored by members of law enforcement or government agencies. You might be Under Surveillance because you are suspect in a crime, or because you've been spotted associating with other criminals or suspects.

The points you take in this Flaw represent the level of scrutiny your character is under. At two points, only local authorities are watching your ghoul's activities. At four points, both city officials and state authorities are involved. At six points, local, state, and national law enforcement agents are coordinating efforts to analyze your movements, and they may share their concerns with foreign agencies should you travel outside the country.

The effects of this Flaw vary, depending upon your circumstances, and you may not always be aware of them. For example, among Camarilla ghouls, any ghoul Under Surveillance will risk a Masquerade breach. Some vampires might decide that your character is too dangerous to live, and may take an opportunity to end your life at the hands of your associates or domitor. Other Kindred might take a different, more devious approach. They might use you as bait, create a body double, or plant false information.

Generally speaking, Under Surveillance is less dangerous than the Fugitive Flaw, because your character is a person of interest as opposed to a wanted criminal. Thus, this GHOULS & REVENANTS Flaw, at your Storyteller's discretion, may be reduced in points or regulated to a cold file with time and effort. Ghouls and revenants, however, might be given a limited number of opportunities to correct the situation before their domitors or families lose patience and turn on them.

Independent ghouls might have a much harder time ditching nosy officers. Though their first instinct might be to run to the cops and confess, keep in mind that no agency is immune from the reach of a Clan, bloodline, or Sect. Thus, some independent ghouls who take this Flaw might suspect that their former domitor has engineered their situation, and they are now Under Surveillance as punishment for abandoning them.

Used by: All ghouls and revenants]==],
				},
				["Double Agent"] = {
					en = [==[Book of Secrets, p. 65


Double Agent


You work both sides of a very spiky fence; one of these days, you're gonna get stuck on it. Perhaps you're a Syndicate spy in the Ecstatic Cult, or an Etherite working with Iteration X. In the days of the Disparate Alliance, you might belong to a Tradition while ferreting data to your true Craft. Eventually, this dangerous game will catch up with you. Make plans, establish contingencies, and try not to get yourself perished!

Obviously, this Flaw must be kept secret from the other characters in your group. For extra drama, try to keep it hidden from the other players, too…]==],
				},
				["Dreadful Mara"] = {
					en = [==[Lore of the Bloodlines, p. 60


Dreadful Mara


You drank something that still lives within you and hates you, exerting alarming control over your thoughts and actions. Each night, the Storyteller may convert a single rolled success into a 1, potentially leading to a botch. At the Storyteller's discretion, the entity may also whisper advice or insults, which can lead to increased difficulty during attempts to concentrate.]==],
				},
				["Driving Goal"] = {
					en = [==[Book of Secrets, p. 51


Driving Goal


Even by Awakened standards, you possess (or are possessed by) a cause so intense that it drives every aspect of your life, up to and including your beliefs about, and approach to, magick and Ascension. This goal, sadly, is almost impossible to achieve on an individual basis: the collapse of the Technocracy, the return of the Old Ways, the fall of the industrialized era, and so forth. As a mage, you actually could gather enough influence to lead a larger movement that shifts Reality toward your goal. More likely, you will break yourself against that goal, as so many other mages have done before you… but hey, if a cause is as worth fighting for as yours is, then it's worth whatever cost you must pay.

As a Flaw, this Driving Goal inspires roleplaying choic- es and informs your character's focus, allegiance, magick, Path, Resonance, Seekings, Paradox backlashes, and pretty much everything else you can imagine. You can take short breaks from your crusade (usually by spending a Willpow- er point in order to take a different road for a while), but eventually this obsession brings you back to the goal you must pursue at all costs until you finally accomplish it or destroy yourself trying.]==],
				},
				["Dulled Bite"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Dulled Bite


For some reason your fangs never developed fully, or they may not have manifested at all. When feed- ing, you need to find some other method of making the blood flow. Failing that, you must achieve double the normal number of successes in order to make your bite penetrate properly. A number of Caitiff and high- Generation vampires often manifest this Flaw.]==],
				},
				["Duplicitous"] = {
					en = [==[Ghouls & Revenants, p. 128


Duplicitous


Ghouls and revenants with this Flaw have an underhanded

reputation based on their previous actions. In the past,

you've probably lied, cheated, or played both sides against

the middle during a deal that went south. The nature of your

underhanded actions, as well as your intended target, has

not been the same every time. A ghoul might, for example,

go to her domitor and inform him of a transgression, real

or imagined, and then suggest an appropriate punishment

for her target. That same ghoul might turn around and

fabricate stories that show how well-meaning she was to

stand up for her fellow ghoul in front of her master.

While you can be duplicitous as a character, when you

take this Flaw, it impacts your relationships and dealings

with other characters. You probably don't seek to take

the upper hand in every situation, but other characters

expect you to. Your allies and enemies are on edge around

you, because they're not sure when and if you'll ever treat

them fairly. They may even backstab or try to undercut

you, too, because they expect you to.

The influence of the blood bond does impact most

ghouls with this Flaw in subtle ways. While your domitor would know you are Duplicitous, you would not act out in a direct way against your master. Instead, you might backstab or double-cross your allies to curry favor and obtain rewards from him. Your domitor may also point you at a dangerous target, too, to use you as bait or to draw out his enemies, to taking advantage of your reputation.

Used by: All ghouls and revenants Social]==],
				},
				["Easily Intoxicated"] = {
					en = [==[Book of Secrets, p. 40


Easily Intoxicated


Shit really fucks you up fast. The flipside of Alcohol /Drug Tolerance, above, this Flaw renders you especially susceptible to intoxication. Your Stamina rolls to resist the effects of drugs or poisons (though not disease), as described in the Drugs, Poisons, and Disease section of Mage 20, suffer a +3 modifier to the usual difficulty involved. Contrary to popular conception, this does not make you a good candidate for the Cult of Ecstasy because you don't control the drugs – the drugs control you.]==],
				},
				["Echo Chamber"] = {
					en = [==[Book of Secrets, p. 66


Echo Chamber


You surround yourself with groupthink. All opinions on important topics (politics, religion, magick, and so forth) must remain unified. No disagreements on such matters are permitted within this echo chamber, and anyone who bucks that decree is shown the door – often with great force – and shunned, probably vilified, afterward. Loyalty to the group is measured by the devotion each member shares with regards to the “truth” as your group understands it. As a result, that “truth” soon gets distorted. Like an echo reverberating within a closed space, it verges into a distortion of the original source, growing wilder and more extreme until something has to give. Will that breaking point be you? Gods forbid…

Essentially a story-based Trait, this Flaw cuts your char- acter off from information that runs contrary to the group's determined “truth.” Characters and data that disagree with that “truth” must be pushed aside, ignored, silenced, possibly attacked, maybe even destroyed “for the good of the group.” Because isolation breeds distortion, the Storyteller should gradually make “the truth” seem more extreme than it once had been. Anyone – especially a player character – who disagrees with “the truth” should be punished by the group; the more extreme the distortions become, the harsher the punishment becomes as well. Eventually, the distorted “truth” will require distorted acts as well: assault, torture, murder, terrorism. At that point, any character who tries to step away will become the enemy too (possibly receiving the Flaw of that name) – shunned by former friends at the very least, probably disgraced socially, and potentially even attacked physically for being a traitor to the cause.

This Flaw reflects a social phenomenon that's increasingly common in the twenty-first century, though it's certainly not exclusive to our era: a social group committed to enforced orthodoxy and the removal of dissent. The group in question could be a religious or military order, a socio-political activist tribe, a corporate office, a think-tank, an art collective, a fan- nish subculture, a media outlet, mystic sect, or Political Action Committee – any social clique that holds “certain truths to be self-evident” and vital to that group's existence could become an echo chamber. “Us” and “them” is a ruling principle, and if you're not one of Us, then you're one of Them.]==],
				},
				["Echoes (1)"] = {
					en = [==[Book of Secrets, p. 83


Echoes (1)


See Mage 20, pp. 646-647. Paranormal Prohibition or Imperative]==],
