				},
				["Eerie Presence"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 495


Eerie Presence


Mortals have an unconscious awareness of your un- dead nature, which makes then anxious and ill at ease in your presence. Because of this, difficulties of all rolls relating to social interaction with mortals are increased by two.]==],
				},
				["Enemy (1)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Enemy (1)


You have an enemy, or perhaps a group of enemies, who seek to harm you. The power of the enemy de- pends upon how many points the player wishes to spend (five points indicate the wrath of a Methuselah or other potent supernatural foe).]==],
