Enemy (4)


You have an enemy, or perhaps a group of enemies, who seek to harm you. The power of the enemy de- pends upon how many points the player wishes to spend (five points indicate the wrath of a Methuselah or other potent supernatural foe).]==],
				},
				["Enemy (5)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Enemy (5)


You have an enemy, or perhaps a group of enemies, who seek to harm you. The power of the enemy de- pends upon how many points the player wishes to spend (five points indicate the wrath of a Methuselah or other potent supernatural foe).]==],
				},
				["Enemy Brood"] = {
					en = [==[Lore of the Clans, p. 163


Enemy Brood


You have made an enemy of another group of Nosferatu. Unlike your usual enemies, they know the places you like to go and aren't too squeamish about following you there. They keep you on the move, hunting you from sanctuary to sanctuary. The sewers themselves might not even be safe for you anymore. If you move to a new city, they use their contacts to pass on the word to their allies to keep hounding you. Sooner or later, you are going to have to take them down to rid yourself of them.]==],
				},
				["Escaped Target"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 491


Escaped Target


You had targeted a mortal for the Embrace, but someone else got there first. You cannot stand the hu- miliation of being cheated of your prize, and fly into a rage (+2 difficulty to avoid frenzy) whenever you see the one who got away. This hatred may lead you into other irrational behaviors, like Embracing enemies of the neonate, creating unauthorized childer, or even trying to kill your rival. Furthermore, your petty and irrational behavior is well-known and quite noticeable, and as a result you are at + 1 difficulty on all Charisma rolls until the situation is resolved.]==],
				},
				["Esoteric Discourse / Technobabbler"] = {
					en = [==[Book of Secrets, p. 62


Esoteric Discourse / Technobabbler


Your obsessive love of a specialized field inspires you to fill every waking hour with obscure jargon and obtuse metaphrase- ology. Most folks can't understand half of what you say, and their incomprehension of such elementary terminology impels you to facilitate obligatory (if remedial) pedagogy. Oh, for fuck's sake – just talk normal for a change!

In game terms, this Flaw imposes difficulty modifiers (+1 or +2) on social rolls, thanks to the character's compulsive jar- gonization, hyperinitiated nomenclature, and condescending pedanticism. The Flaw's first variation reflects arcane special- ization, the second reflects tech-based terminology, and other variations (Specious Legalese, Obtuse Academia, and so forth) could reflect similar fascinations with other fields. For people who actually understand you, however, the usual penalty might become a social bonus instead… at which point everyone else probably leaves the room and lets the experts talk amongst themselves.]==],
				},
				["Ethical Prohibition (2)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 422


Ethical Prohibition (2)


The necessity of feeding is at odds with your moral compass. You cannot reconcile what you have become with what you believe in. At 2 points, you refuse to feed on humans, instead preying upon the blood of animals. At 4 points, you can- not come to terms with yourself at all and refuse to feed except when utterly necessary.]==],
				},
				["Ethical Prohibition (4)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 422


Ethical Prohibition (4)


The necessity of feeding is at odds with your moral compass. You cannot reconcile what you have become with what you believe in. At 2 points, you refuse to feed on humans, instead preying upon the blood of animals. At 4 points, you can- not come to terms with yourself at all and refuse to feed except when utterly necessary.]==],
				},
				["Expendable"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Expendable


Someone in power doesn't want you around. Maybe she wants territory you possess, or is jealous of the at- tention you're getting from a prize mortal retainer — the details are irrelevant. What does matter is that she has the power to maneuver you into dangerous situa- tions “for the good of the Sect,” and has no compunc- tions about doing so. 489]==],
				},
				["Expiration Date"] = {
					en = [==[Anarchs Unbound, p. 102


Expiration Date


Your personal motto is simple: I do what I want. This has, as might be expected, caused you trouble more than once. You are wanted in several domains for various minor crimes, such as exsanguinating the Seneschal's favorite ghoul. You haven't been bloodhunted just yet, but the writing is on the wall. You've just about run out of time and no one wants you to take them with you when everything turns sideways. One more mistake and you sign your Final Death warrant. All social-based rolls to acquire help are at +2 difficulty, except those involving Intimidation.]==],
				},
				["Extreme Kink (3)"] = {
					en = [==[Book of Secrets, p. 52


Extreme Kink (3)


Everyone's a little kinky; your needs are more, shall we say, exotic than a run-of-the-mill fetish. You might still adhere to the third part of the BDSM mantra safe, sane, and consensual, but your kink is neither safe nor sane by most people's definition of those words. We're not talking about tame bondage-and-spanking stuff – more like Fifty Shades of What the Fuck is Wrong with You? Unlike the old Flaw: Sadism /Masochism (which it replaces), this Flaw isn't about the nature and specifics of your kink – it's about how much trouble you can get into trying to satisfy your needs. A three-point kink can damage your health, reputation, and play partners; a four-point kink can seriously harm you (and whoever's unfortunate enough to hook up with you), and a five-point kink can get you prison time or worse. (Gods help the people you choose to help you satisfy that kink…)

Certain mages are more prone to this Flaw than others, especially if they favor Left-Hand Path-type practices. For what ought to be obvious reasons, this is not an appropriate Flaw for all chronicles or players, and may well invoke safewords and blackouts from your Storyteller or companions. (See Mage 20, p. 345.) Although this Flaw, like others of its kind, does not bear a judgment on our part, this sort of thing can offend and trigger other players, so don't be a dick about it.]==],
				},
				["Extreme Kink (4)"] = {
					en = [==[Book of Secrets, p. 52


Extreme Kink (4)


Everyone's a little kinky; your needs are more, shall we say, exotic than a run-of-the-mill fetish. You might still adhere to the third part of the BDSM mantra safe, sane, and consensual, but your kink is neither safe nor sane by most people's definition of those words. We're not talking about tame bondage-and-spanking stuff – more like Fifty Shades of What the Fuck is Wrong with You? Unlike the old Flaw: Sadism /Masochism (which it replaces), this Flaw isn't about the nature and specifics of your kink – it's about how much trouble you can get into trying to satisfy your needs. A three-point kink can damage your health, reputation, and play partners; a four-point kink can seriously harm you (and whoever's unfortunate enough to hook up with you), and a five-point kink can get you prison time or worse. (Gods help the people you choose to help you satisfy that kink…)

Certain mages are more prone to this Flaw than others, especially if they favor Left-Hand Path-type practices. For what ought to be obvious reasons, this is not an appropriate Flaw for all chronicles or players, and may well invoke safewords and blackouts from your Storyteller or companions. (See Mage 20, p. 345.) Although this Flaw, like others of its kind, does not bear a judgment on our part, this sort of thing can offend and trigger other players, so don't be a dick about it.]==],
				},
				["Extreme Kink (5)"] = {
					en = [==[Book of Secrets, p. 52


Extreme Kink (5)


Everyone's a little kinky; your needs are more, shall we say, exotic than a run-of-the-mill fetish. You might still adhere to the third part of the BDSM mantra safe, sane, and consensual, but your kink is neither safe nor sane by most people's definition of those words. We're not talking about tame bondage-and-spanking stuff – more like Fifty Shades of What the Fuck is Wrong with You? Unlike the old Flaw: Sadism /Masochism (which it replaces), this Flaw isn't about the nature and specifics of your kink – it's about how much trouble you can get into trying to satisfy your needs. A three-point kink can damage your health, reputation, and play partners; a four-point kink can seriously harm you (and whoever's unfortunate enough to hook up with you), and a five-point kink can get you prison time or worse. (Gods help the people you choose to help you satisfy that kink…)

Certain mages are more prone to this Flaw than others, especially if they favor Left-Hand Path-type practices. For what ought to be obvious reasons, this is not an appropriate Flaw for all chronicles or players, and may well invoke safewords and blackouts from your Storyteller or companions. (See Mage 20, p. 345.) Although this Flaw, like others of its kind, does not bear a judgment on our part, this sort of thing can offend and trigger other players, so don't be a dick about it.]==],
				},
				["Faceless"] = {
					en = [==[Lore of the Clans, p. 239


Faceless


You have escaped the tyranny of physical self-identity. You call no face your own. Every sunset, you awaken to a new visage, an amalgam pieced together from memory and dream. Your features, ethnicity, even gender become fluid things while you sleep. While this Flaw exemplifies the extreme ideals of Azi Dahaka (and should impress most Metamorphosists), it can cause complications for vampire concerned with maintaining recognition, reputation, or a mortal alias.

Every sundown, the player rolls one die and is subject to the results on the following table: Roll Result 1 No change. 2-3 Minor changes, somewhat recognizable. 4-8 Unrecognizable by even those closest to the

character (such as her packmates or sire).

Ethnicity and gender may change. 9-10 Total metamorphosis. Tentacles, bone spikes,

or other inhuman features may appear.

LORE OF THE CLANS

This Flaw affects some Backgrounds (V20, p. 110). Without a stable face, Alternate Identity and Fame cannot be maintained. Backgrounds like Allies, Contacts, Influence, and Status might be complicated by the lack of a solid identity as well. The vampire can use Malleable Visage and a mirror to reconstruct her true face from memory, but this requires at least three successes at difficulty 8 to make her recognizable, and five successes for a flawless copy.

The Mistaken Identity Flaw (V20, p. 450) cannot be taken. Other Merits/Flaws may be affected, at the Storyteller's discretion. Characters must have at least one dot of Vicissitude to take this Flaw.]==],
				},
				["Failure"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 491


Failure


You once held a title in the city, but failed catastroph- ically in your duties. Now you are branded incompe- tent, excluded from circles of power and responsibility, and generally ostracized by those on their way up. Your exclusion may make you a target for recruitment by the Sect's enemies (or so the whispers run, making you even more distrusted). Conversely, the consequences of your error might come back to haunt you.]==],
				},
				["Faithless"] = {
					en = [==[Book of Secrets, p. 93


Faithless


Magick, according to your beliefs, does not come from you – it comes from your god, and you've broken faith with him. Until you can shake this crisis of faith, perhaps atoning for your perceived misdeeds, your Spheres remain stuck at Rank 1 – potent enough to perceive the presence of Divinity around you, limited enough to remind you that you have failed.

This Flaw (which is more likely to be “awarded” to you through the course of the game than it is to be something you purchased during character creation, though of course you can start off a new character in such a crisis) represents the power of faith in your character's life – a power so strong that it can interfere with your abilities as a mage. Ironically, the strength of that faith denies you the ability to use magick when you feel that your faith is lacking. From a game-system standpoint, you are denying yourself the ability to access your magick because you believe that your magick comes from a source you have betrayed. Your mage believes that his god is cutting him off from magick, though… and, considering that the player is pretty much the “god” of a gaming character, in a meta sort of way, that's true.

Although a character with this Flaw can pursue any sort of spiri- tual focus, his paradigm and practice must be oriented toward religious devotion. You could be a shaman or a priest, a Goddess-bound witch, a spiritual scientist, even an Infernalist whose hell-spawned powers flow from a damnation pact. Obviously, this Flaw means nothing to an atheist, or to someone with nebulously casual beliefs. Only a mage who believes deeply in some greater power can believe that she has so much to lose from a sudden lack of faith.

In order to discard this Flaw, the player must pay a five- point “fine” in order to buy off the Trait itself, and roleplay out a “dark night of the soul” sort of Seeking in which he faces his sins and rededicates himself to his divine Path. The character, meanwhile, must first undergo an atonement that suits his belief system and the “sin” that invoked this punishment. Maybe he needs to take strict vows within a re- ligious order… or take on even stricter ones if he had already broken his previous set of vows. Did he violate a taboo? Then he must undergo ritual purification, often by way of fasting, marathons of prayer, and some traditionally torturous ordeals. A mage who has sworn never to kill, and yet who has killed someone, may be forced to make significant restitutions to the murdered person's family. Traditional atonements in- clude pilgrimages, vision quests, oaths of poverty, appalling mortifications (self-torture, radical fasting, mutilation, and so forth), and other difficult paths back to the favor of one's god. Regardless of the creed and specific atonements, however, the mage must spend endless hours in intensive prayer. A faithless soul, after all, must find his way back to the presence of his god… typically on his knees.]==],
				},
				["Family Issues (1)"] = {
					en = [==[Book of Secrets, p. 62


Family Issues (1)


Many mages leave their families behind. You didn't do that, although you may often wish you could. A flipside of the Merit: Family Support (pp. 53-54), this Flaw saddles you with a basket of goodies from Dysfunction Junction, family-style. You might have a meddling uncle, an abusive sibling, an alcoholic parent, or “simply” the leftovers from dealing with such peo- ple. You might have tried to escape them, but if so, someone in your family is still looking for you. (See the Werewolf 20 Flaw: Persistent Parents, and the story “We Are the Shadows Cast by the Memory of Giants” in Truth Beyond Paradox.) The family doesn't have to still be part of your physical reality, but the mess they left behind if you managed to get away from them remains a part of your existence today.

As with Supportive Family, the clan in question could be blood relatives, an adopted family, or a family-of-choice you kinda wish you hadn't chosen. The more points you have in this Flaw, the more your family issues interfere with your Awak- ened life. They could be mages themselves, though that's not often the case. More likely, they're folks who still look for you even in your Newlife, hangers-on who won't leave you alone, sickly relations who need tending (see also the Flaw: Ward, p. 66), kids or siblings (or even parents) who have constant troubles with the law… the possibilities are as endless as the real-life complications that a troubled family can bring. And no, you can't just ditch out on 'em even if you've already tried to do so. If you could, they wouldn't still be your problem, now would they?]==],
				},
