				},
				["Feral Mind"] = {
					en = [==[Book of Secrets, p. 52


Feral Mind


More animal than human being, you lack the social graces and mental conditioning that most folks consider essential. Perhaps you're a throwback, or wild-raised since childhood; or maybe you lost a part of yourself to animalistic shapechanging, suffer from a mental or psychological quirk, or simply renounce your humanity in favor of a more honest primal truth.

Regardless of its origins, this feral-mindedness limits your ability to function in human society. You prefer non-linguistic vocalizations and body language over cultured speech, and may lack the ability to “speak” in human terms at all. Your actions and reactions are animalistic too; you mark territory, snarl when annoyed, cower or lash out when threatened, feel no sense of so-called “modesty,” detest clothing, and smell musky even when you've just had a bath (which you rarely do under your own power). Such behaviors usually raise the difficulty of your social-interaction rolls by +3, although certain situations – like intimidation or seduction – may lower the difficulty by the same amount (-3).

This Flaw, however, isn't simply a social drawback; you may not have more than three separate Language Merits, and you speak very little (and very simply) when you choose to speak at all. Your human developmental skills (speech, reading, math, socialization, etc.) hover at a child-like level despite your sharp instincts and innate primal cunning. Although your Mental Attributes (especially Perception and Wits) may be high, you probably won't ever reach an adult level of human development; even if you do, the animal in you remains very close to the skin.]==],
				},
				["Fifteenth Generation"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Fifteenth Generation


Your vitae is so weak that only six of your 10 blood points can be used for Disciplines, healing or raising VAMPIRE THE MASQUERADE 20th ANNIVERSARY EDITION Attributes. For these functions, you must expend two blood points to obtain the effect a normal vampire would achieve with one. (The cost for nightly rising remains a single blood point.) What's more, you can- not create or sustain ghouls, create a blood bond, or sire a vampiric childe. You can use the remaining four blood points to survive through the day and wake up each night, nothing more.

You cannot raise any Discipline above three dots.

The weakening of the Curse of Caine has compen- sations, though (which distinguish this Flaw from the Thin Blood Flaw itself). Sunlight does lethal damage to you, instead of aggravated damage as it does to other vampires. You can hold down mortal food and drink for an hour or so; other vampires vomit immediately if they try (unless they have the Eat Food Merit). Strang- est of all, once in a while you might actually have a child the normal, human way... though it will hardly be a normal, human child.]==],
				},
				["Fifth Degree"] = {
					en = [==[Book of Secrets, p. 68


Fifth Degree


Whether you know it or not, you have outlived your use- fulness to the Technocratic Union. Your superiors have set you up to fall, and your date with Room 101 or a suicide mission waits right around the corner. Combine all the deficits of the Flaw: Rogue (above) with the assurance that you're only alive because someone would rather have you take out the bad guys when you go down in a blaze of glory than spend the resources necessary to take you down themselves. You have one more chance to make good and stay alive. Step out of line again, and your fate will be the sort of thing that makes cyborgs cringe.]==],
				},
				["Finicky Palate"] = {
					en = [==[Ghouls & Revenants, p. 138


Finicky Palate


Your ghoul must choose a Clan or bloodline, other than your domitor's, whose blood causes you an allergic reaction when present in your bloodstream. Any time your ghoul ingests blood from a vampire of that selected Clan, either intentionally or forcibly, you must make a Stamina check to avoid vomiting it up. If you are successful, the blood remains in your system and all rolls involving Disciplines will be at +1 difficulty until either the offensive blood is burned off, or you consume new blood from a different Clan, whichever comes first.

For most Camarilla ghouls, this Flaw represents little threat. In the unlikely event that a ghoul consumes the blood of a Kindred other than his domitor, it won't take long for that ghoul to find the blood he does need. For an independent ghoul or a Clan-sponsored revenant family, on the other hand, this Flaw could represent a dire problem.

Used by: All ghouls and revenants]==],
				},
				["Flashbacks"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 487


Flashbacks


You managed to make it through the Creation Rites or other similarly traumatic experience, but not wholly in- tact. The most insignificant thing can throw you into a different mood or state of mind, and as such your behav- ior is extremely unpredictable. Because of your precarious emotional state, your Willpower fluctuates. At the begin- ning of each story, make a Willpower roll (you may not spend Willpower for an automatic success). If you succeed, you may participate in the story as normal. If you fail, how- ever, your Willpower score is considered to be 1 for the duration of that session, and you only have one Willpower point to spend. You may roll again at the beginning of the next session to see if you regain your Willpower. Social]==],
				},
				["Flawed Reality"] = {
					en = [==[Lore of the Clans, p. 182


Flawed Reality


Your illusions always contain a notable flaw, and as such, are easier to disbelieve. The difficulties of all rolls to disbelieve your illusions are reduced by two.]==],
				},
				["Flesh Eater"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 422


Flesh Eater


You cling to the misguided belief that you must also consume the blood-rich flesh of your victim (such as the heart or liver). This has obvious impact on the size of your herd as well as the mortal pop- ulation eventually linking mysterious, gruesome deaths to you. To keep down blood consumed without a murderous amount of flesh, you must succeed in a Willpower roll (difficulty 8) or vomit up the blood.]==],
				},
				["Flesh of the Corpse"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 483


Flesh of the Corpse


Your flesh does not fully regenerate itself once it is damaged. While you are able to heal yourself to the point of regaining full functionality, your skin still retains the cuts, tears, bullet holes, and other visible damage that you have incurred. Depending on the na- ture of the damage, this Flaw will make social dealings exceedingly difficult, and may decrease your Appear- ance dots over time (even to 0). VAMPIRE THE MASQUERADE 20th ANNIVERSARY EDITION 483]==],
				},
				["Forked Tongue"] = {
					en = [==[Lore of the Clans, p. 67


Forked Tongue


Your tongue is forked, flickering, and inhumanly reptilian. Upholding the Masquerade becomes difficult for you. Note that this tongue does not inflict aggravated damage, nor draw blood.]==],
				},
				["Former Prince"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Former Prince


Once, you held near-absolute power in a city, but those nights are gone now. Perhaps you stepped down, perhaps you were deposed, or perhaps your city fell to the Sabbat; it matters little in your reduced state. What does matter is that the Prince in the city where you now dwell is aware of your prior employment, and has concerns that you might be trying to make a come- back. The machinery of the Camarilla in the city where you now make your home is subtly stacked against you, and if the Prince sees an opportunity to get rid of you he just might take it. This Flaw can only be taken by Camarilla vampires.]==],
				},
				["Fourteenth Generation"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Fourteenth Generation


You were created five or fewer years ago by a mem- ber of the Thirteenth Generation. Though you have 10 blood points in your body, only eight of them may be used to heal wounds, power Disciplines, raise Attri- butes, etc. You can still use the final two blood points for other purposes, though. The blood point costs of nightly rising, creating and sustaining ghouls, and cre- ating blood bonds remains the same as for other vam- pires. You cannot raise any Discipline above four dots.

Taking this Flaw precludes you from taking the Gen- eration Background, and you may not start with Status, either. You are likely a Clanless Caitiff, for your blood is probably too thin to pass down the distinguishing characteristics of a Clan. Most Fourteenth-Genera- tion vampires should also take the Thin Blood Flaw (p. 483).]==],
				},
				["Fugitive"] = {
					en = [==[Ghouls & Revenants, p. 133


Fugitive


You are wanted by the authorities. You may be a suspect in a case, or might have been charged and convicted with a serious crime. Your ghoul or revenant may have even gone so far as to escape a high security prison or mental health facility. You may have, on the other hand, run afoul of a Sect and are now being hunted by its members, whether they be Kindred, Cainite, Anarchs, etc.

When you take the Fugitive Flaw, you are admitting that you have either committed (or have been framed 133 for) a transgression that is so severe, agents who uphold the law, be they vampire or mortal, have ordered your capture. Any and all persons found in your company may immediately become suspect as well, and could be charged with additional crimes.

A Fugitive is rarely hunted without good cause, and often those who seek to bring you in will have a personal reason for doing so. An officer might track you down because her negligence allowed you to escape. A rival ghoul, who managed to uncover how you were attempting to thwart your domitor, might want to prove his worth to your former domitor. A Sabbat pack may be hard on your heels, because they feel your escape is an embarrassment to them. These are all examples of characters who would probably pursue you at great personal cost in an attempt to recapture or even murder you.

To the Camarilla, a ghoul or revenant Fugitive represents a serious threat to the Masquerade, regardless of who may be after you. While it is possible you may have been carrying out orders under the influence of the Blood Bond or Disciplines like Dominate, Kindred authorities cannot turn a blind eye to a desperate ghoul or revenant who's on the run. To the Sabbat, on the other hand, a Fugitive may be hunted for other reasons, ranging from a sense of pride to a fear that you'll run to the Camarilla and divulge secrets that must be kept buried.

Though you are a Fugitive, you may have Allies, Contacts, or have clearly identified a place to hide for a time. Your domitor or revenant family, for example, might often you a place to stay for a few nights, but doing so puts them at risk. Safe houses may be arranged to ensure your survival, with the understanding that you are expected to curry favors or perform services that will help your benefactors. You may even be asked to follow a strict code of conduct to avoid exposing your accomplices.

Used by: All ghouls and some revenants. This Flaw is particularly appropriate for independent ghouls who are on the run from their domitors. Physical]==],
				},
				["Glowing Eyes"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Glowing Eyes


You have the stereotypical glowing eyes of vampire legend, which gives you a -1 difficulty on Intimidation rolls when you're dealing with mortals. However, the tradeoffs are many; you must constantly disguise your condition (no, contacts don't cut it); the glow impairs your vision and puts you at +1 difficulty on all sight- based rolls (including the use of ranged weapons); and the radiance emanating from your eye sockets makes it difficult to hide (+2 difficulty to Stealth rolls) in the dark.]==],
				},
				["Gremlin (1)"] = {
					en = [==[Book of Secrets, p. 84


Gremlin (1)


There's a perverse imp running around your home. Okay, maybe it's not an actual imp – it could be a malfunctioning robot companion, a vain and selfish bioconstruct, a trouble- some spirit, an obnoxious beast, that talking winged tarantula we mentioned a few entries ago… the form of the creature is unimportant. Like the above Flaw: Apprentice, this Trait reflects a companion character who, despite being supposedly on your side, remains a constant pain in your ass.

Originally presented as the adversarial Background for Familiar, this Flaw becomes more significant as the power of the creature, and its attendant nuisance, grows: (1 point) A creature of unusual, but minor, ability, which

busies itself with trivial annoyances. (2 points) An entity whose power and intellect (or at least

its cunning) make your life frustrating but not actively

hazardous. (3 points) A being of notable power whose mischief has

begun to shade into actual damage to your property,

health, status, and relationships. (4 points) A metaphysical pain in the tuchus whose

powers cause lasting harm to you and to the things you

consider precious. (5 points) A walking plague of significant power and

malignancy. Said critter might not actually mean to be

bad, but its effects on your life are inescapably destructive.

As with an Apprentice Flaw, above, you bear a certain amount of responsibility to this creature – it's not simply your enemy, or even a nemesis, but a being with whom you share a vital bond. Also as per the Apprentice Flaw, your treatment of this “gremlin” (a legendary being that sabotaged airplanes for fun) may reduce or intensify the value of this Flaw. A formerly malignant entity could be tamed and eventually become a Fa- miliar (as in that Background), while a poorly-treated familiar might become a gremlin, and a previously annoying gremlin could be annoyed into becoming a serious threat to the mage and his surroundings. As an optional rule, you might even – with Storyteller approval – be able to purchase the Gremlin Flaw in addition to the Familiar Background, to reflect a helpful yet perpetually troublesome companion.

A gremlin, as with all other Trait-based characters, is an entity in its own right. Chances are good that the trouble it causes for your mage has an understandable foundation – a reason that seems inexplicable to the mage yet remains perfectly reasonable to the gremlin. A mage who explores the reasons behind this misbehavior may calm her temperamental com- panion; then again, an attempt to understand the gremlin's grudge might only piss it off further…]==],
				},
				["Gremlin (2)"] = {
					en = [==[Book of Secrets, p. 84


