				},
				["Grip of the Damned"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 495


Grip of the Damned


There is no ecstasy in your Embrace — only terror and pain. Mortals upon whom you feed struggle and shriek while you attempt to feed, requiring you to grapple with them for as long as you wish to take their blood. For vampires with high Humanity, this experi- ence may require a Humanity roll, at the discretion of the Storyteller. Giovanni cannot take this Flaw.]==],
				},
				["Guilt-Wracked"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Guilt-Wracked


You simply cannot come to grips with the fact that you must drink blood to survive. You suffer horrible guilt over each time you feed (roll Conscience, diffi- culty 7, or else frenzy every time you feed — characters with the Conviction Virtue cannot take this Flaw) and try to avoid doing so as much as possible. This means that you rarely have much blood in your system, leav- ing you vulnerable to both attacks and hunger-based frenzies.]==],
				},
				["Gullible"] = {
					en = [==[Book of Secrets, p. 65


Gullible


You believe everything folks tell you. You repost memes without checking their accuracy or source. You fall for cons and pranksters every single time. Seriously? How can a mage be so goddamned gullible? Beats me, but yeah – subtract three dice from every dice pool you roll (down to a minimum of one die) when you're trying to penetrate falsehoods (lies, not stealth), or to fool people with your own bumbling attempts at deception.]==],
				},
				["Harbinger of the Abyss"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 428


Harbinger of the Abyss


You have become the void: the endless black of night, an empty pool of darkness. Where you pass, shadows leap to join you and flames gutter and perish. When you are in the presence of mundane fire, you must make a reflexive Obtenebra- tion roll against the soak difficulty of any nearby flame. A success extinguishes the fire instantly, casting the area into darkness. This Flaw also includes the effects of Touch of Frost (page 426) and Eerie Presence (page 427) and is therefore mutually exclusive with them. However, the clinging darkness around you provides one benefit (besides being an unusual way to extinguish unwanted fires): reduce the difficulty of all Intimidation rolls by two, to a minimum of 4. You must have at least one dot of Obtenebration to purchase this Flaw.]==],
				},
				["Hard of Hearing"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Hard of Hearing


Your hearing is defective. The difficulties of any rolls involving the use of hearing are increased by two.]==],
				},
				["Hatred"] = {
					en = [==[Book of Secrets, p. 52


Hatred


As with Bigot, above, you utterly despise some source of hatred. Maybe you loathe vampires, werebeasts, rich or homeless people, fae folk, spirits, dogs, trucks, machines, TV, lawyers, witches, cops, politicians… whatever it is that you hate, you hate it a lot, and will take advantage of any opportunity to hinder or harm the object of your hostility.

Like a bigot, you have what you consider to be a perfectly rational reason for hating whatever it is you despise. Other folks probably consider you crackers unless they share your point of view – in which case, they might become disciples instead. (See the Backgrounds: Allies, Backup, Cult, Influence and Retainers.) As with a Driving Goal, this Flaw guides roleplaying choices, determines targets, and makes you seem rather obses- sive whenever the object of aversion comes into play. Because fear and hatred are so closely intertwined, chances are good that you've got a Short Fuse and /or a Phobia related to this Flaw. And if you also have Berserker /Stress Atavism or Beast Within, then you need to make a Willpower roll (difficulty 8) when confronted head-on with the thing you abhor, or else lose your proverbial shit in its general direction.

Obviously, this Flaw must be chosen carefully. If your char- acter tends to go thermonuclear at, say, the police on an ongoing basis, he is in for a very rough (and probably short) life indeed.]==],
				},
				["Haunted"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 495


Haunted


You are haunted by an angry and tormented spirit, most likely one of your first victims. This spirit actively attempts to hinder you, especially when feeding, and does its utmost to vent its anguish upon you and any- one in your presence. The Storyteller determines the exact nature of the spirit, its powers, and whether or not it can eventually be laid to rest.]==],
				},
				["Heartless"] = {
					en = [==[Lore of the Clans, p. 67


Heartless


You have lost your heart. Either you removed it via The Heart of Darkness (see V20, p. 210), or an elder did it to you, but either way you no longer have easy access to it. The heart might be in the possession of a foe, or simply missing. If it turns out that a Cainite possesses the heart (say a Setite elder, or your sire) you must obey their every command. If it's merely missing, the anxiety and obsession to find it interferes with your nightly existence, and may increase the difficulty of Willpower rolls by +1 at Storyteller discretion.]==],
				},
				["Hemophiliac"] = {
					en = [==[The Hunters Hunted II, p. 43


Hemophiliac


Your character suffers from hemophilia. If she is cut, she will not stop bleeding without medical help. If your hunter suffers lethal or aggravated damage, she suffers an additional level of bashing damage every five minutes until her wound has been dressed to stop the bleeding. Any vampire who bites her may “dress” such wounds and end the ongoing bashing damage by licking the injury after he bites her. Asset Merits Occult Library (2- or 4-pt. Merit)

Your character owns an estimable collection of works on arcane lore. If he has access to his library, you can lower the difficulty of Intelligence-, Occult-, or research-related rolls by 1 when he's attempting to solve an occult mystery or THE HUNTERS HUNTED II generally learn more about the occult. Having this library doesn't automatically mean the hunter's an occult expert, it just means he has convenient access to some knowledge. If you have purchased the four-point version of this Merit, your character also has an Occult Laboratory stocked with strange and rare ingredients he might need for his Numina rituals.]==],
				},
				["Hero Worship"] = {
					en = [==[Book of Secrets, p. 46


Hero Worship


You adore another character, to the point where that person can do no wrong as far as you're concerned. Attempts to sway your opinion will just piss you off, shut you down, or drive you to heights (or depths) of absurd justification for whatever someone says about him. A common trait among folks in an Echo Chamber (see the Social Flaw of that name, pp. 66-67), this psychological blind spot can become annoying, even haz- ardous, if centered on the wrong person… like, say, a Syndicate Manager, a Nephandus, or certain presidential candidates!

If your hero tells you to do something, you're inclined to obey, and must make a Willpower roll in order to refuse their desires. The difficulty for this roll depends upon the extremity of those desires; “Gimme a kiss,” would probably be difficulty 5, while “Go stab your best friend in the back for me” would be 9 or 10. If and when you're confronted with proof of your hero's weak- nesses, you are capable of seeing reason eventually – it's just not easy to get you to think so clearly. Any social roll that's aimed at getting you to discard your hero worship adds +2 to its difficulty unless the hero has recently done something very wrong… like, say, telling you to stab your best friend in the back for him!]==],
				},
				["Hit List"] = {
					en = [==[Book of Secrets, p. 67


Hit List


A rival group wants you dead. You might be a Templar who's made enemies among the Etherites, an Etherite who crossed the line with the New World Order, and so forth. Whatever happened, it's personal and extends to the entire group. As with the Vampire 20 Flaw: Clan Enmity, this is a deadly business, far worse than the one-point Sect Enmity, above. Social rolls when dealing with members of this group add +2 to their difficulty – if you get a chance to make such rolls at all. Whether or not the enemy group actively attacks you on sight, its members will go out of their way to make your life solitary, unpleasant, nasty, brutish, and short.]==],
				},
				["Horrific"] = {
					en = [==[Book of Secrets, p. 41


Horrific


Well past Monstrous, you're hideous to the point of inspiring nightmares. Unless you mask your true form with serious magick, people and animals run screaming from your presence. Physically, you're not merely misshapen but repulsive on a primal level – the sort of terror that sent Lovecraft's heroes over the edge. You might not actually be a Nephandus or Marauder, but folks who know what those words mean will assume that you are one. A normal life is, for you, impossible. Whether due to Paradox disfigurement, malignant disease, extreme body modifications (cybernetic, artistic, At the five-point level of this Flaw, your character ages one or otherwise), severe scarring, or similar acts of malevolent fate, year for every two months of earthly time (six years of age for you look like John Cobb threw up on you, then ran. each passing year). At the 10-point level, he ages one year per

week (or 52 years of age in a single 12-month period). Such a

System-wise, this Flaw inflicts a +3 difficulty modifier to any character had best watch out for Time-savvy mages; the Acceler- social roll that involves not scaring the shit out of people, and lowers ated Youth or Decay feat described in How Do You DO That? the difficulty by -3 if you are. Your Appearance Trait is stuck below ( pp. 111-112) has horrific effects on a mayfly, who suffers six zero, and faint-hearted or weak-willed Storyteller characters may be to 52 years of aging for each year of time inflicted upon him. faced with Things Man Was Not Meant to Know (as per Mage 20, p. 407) if they wind up spending time with you. As the years rush in, other Flaws like Aging, Impediment,

Absent-Minded, and so forth may pile up on this character as]==],
				},
				["Hunted"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 491


Hunted


You are pursued by a fanatical witch-hunter who believes (perhaps correctly) that you are a danger to humanity. All those with whom you associate, be they mortal or Kindred, may be hunted as well.]==],
				},
				["Hunted by the Hierophants"] = {
					en = [==[Dark Ages Tome of Secrets, p. 4


Hunted by the Hierophants


Setites claim their religion is one of freedom from in- doctrination and conditioning. The Hierophants openly agree, and then crush those who seek to subvert Sutekh's faith. Whether as a result of being a Witch of Echidna, one of their postulants, or simply a Setite who throws off the yoke of Sutekh — the Hierophants are displeased by your decision and seek you out, actively sending Setite warriors to bring you to heel. Depending on the depth of your sins, they will either aim to capture you and bring you back to the Courts of Egypt, or destroy you on the spot. The Hierophants brook no profanation, and will not remove you from their lists until they're convinced of repentance or Final Death. Storytellers are encouraged to make this vampire's existence one of paranoia and near-constant threat. Postulant of Echidna]==],
				},
				["Hunted Like a Dog"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Hunted Like a Dog


Another Sect or group of vampires has decided that you're a target for extermination, and pursues you re- lentlessly. On the bright side, the enemies of your en- emy may well wish to help you out, potentially garner- ing you allies.]==],
				},
				["Icy"] = {
					en = [==[Book of Secrets, p. 49


Icy


You are one ice-cold bastard – an assassin, gangbanger, so- ciopath, or sadist who can commit atrocities without the slightest twitch. Although you're not necessarily insane (see the Derange- ments in Mage 20, pp. 649-650), your callousness marks you as a creepy motherfucker. People avoid you unless they've got killing that needs doing… and then they step back and let you do your thing. Room 101 has positions for people like you (and so, despite their good-guy façade, do the Traditions and Disparate groups), but no one truly trusts you, and your soul is definitely in peril, with the Fallen only a step or two away from owning your cold ass.]==],
				},
				["Ignorance"] = {
					en = [==[Lore of the Clans, p. 270


Ignorance


Many sires abandon their Caitiff progeny without a

word of instruction or warning about their new nature.

For most Princes, ignorance is no excuse for a breach of

the Masquerade, and Sabbat packs are quick to notice

weakness. The character starts with no knowledge of

the abilities, customs, or politics of the undead, and

must learn from their mistakes or find a mentor. Of

course, any vampire willing to take on a Caitiff will

most likely blood bond the poor wretch, leading to a

completely new set of problems. Ignorance is deadly

for a vampire, and doubly so for the Clanless.]==],
				},
				["Illiterate (1)"] = {
					en = [==[Lore of the Bloodlines, p. 4


Illiterate (1)


Perhaps you communicate best through illustration, dance, or impassioned speech; but you can't read or write. This is either a temporary Flaw (1pt.) that can be rectified with a patient teacher, or permanent (2pt.) due to a disability inhibiting your understanding. This Flaw is enough to get you ostracized by others of your bloodline if you do not conceal it.]==],
				},
				["Illiterate (2)"] = {
					en = [==[Lore of the Bloodlines, p. 4


Illiterate (2)


Perhaps you communicate best through illustration, dance, or impassioned speech; but you can't read or write. This is either a temporary Flaw (1pt.) that can be rectified with a patient teacher, or permanent (2pt.) due to a disability inhibiting your understanding. This Flaw is enough to get you ostracized by others of your bloodline if you do not conceal it.]==],
				},
				["Immortal Enemy (5)"] = {
					en = [==[Book of Secrets, p. 93


Immortal Enemy (5)


Oh, dear. You've pissed off someone whose concept of “eternal grudge” could be taken literally. Essentially, you've got the Enemy Flaw with a powerful and more or less immortal entity: a vampire elder, a demon, a demigod, totem spirit, Loa, dragon, or other being who measures its existence in centuries or millennia, with resources and abilities to match. Foolish wizard, what will you do now?

For the relative power of this enemy (or perhaps for the number of your enemies), see the Merit: Powerful Ally, p. 77.]==],
