				},
				["Incoherent"] = {
					en = [==[Lore of the Clans, p. 163


Incoherent


Human speech is impossible for you. It might be that your mouth is too misshapen after the Embrace, or that years of living in the sewers have made you forget how to communicate. While you can understand what is being said to you, you cannot respond. Telepathy works on you as normal, and you have no problem communicating with animals, but human speech is barred to you.]==],
				},
				["Incomplete Understanding"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Incomplete Understanding


The whole matter has been explained to you, but you're still not quite sure how things in your Sect work. Your imperfect understanding of the rules and regula- tions of your new existence means that sooner or later, you're going to make a mistake. It's only a matter of time….]==],
				},
				["Infamous Sire"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Infamous Sire


Your sire was, and perhaps still is, distrusted and dis- liked by many of the city's Kindred. As a result, you are distrusted and disliked as well.]==],
				},
				["Infamy (1)"] = {
					en = [==[Book of Secrets, p. 62


Infamy (1)


You've made a bad name for yourself among the Masses. Like the Background: Fame, this Flaw represents a degree of recognition; in your case, though, that's not a good thing… especially not when you want to keep your life as a mage a secret from the Sleepers.

Once again, the weight of the Flaw determines its value: (1 point) Certain people within a region or subculture

recognize and dislike you. (Examples: the local drunk,

Vox Day.) (2 points) Your notoriety was wide once, but has faded

to occasional recognition and disdain (H.R. Clinton,

M.C. Hammer). (3 points) You're famous, but many people do not like

you (Kanye West, Nickelback). (4 points) The authorities don't like you either (Roosh

V, Jared Fogle). (5 points) You're a household name, and that name is

shit (O.J. Simpson, Charles Manson).

Especially in the age of social media and intelligence net- works, this sort of infamy can be a very bad thing. Obviously, some folks adore you, if only because the rest of the world hates you. On the whole, however, your reputation among the Masses is more bad than good, and folks go out of their way to give you a hard time. As with other bad reputations, you may not have actually done anything wrong; then again, there might be reasons that folks hate your guts.]==],
				},
				["Infamy (2)"] = {
					en = [==[Book of Secrets, p. 62


