				},
				["Infectious"] = {
					en = [==[Lore of the Clans, p. 142


Infectious


Madness flows within your blood, but your bite carries a taint as well. Mortals take a temporary derangement for every three points of blood you take from them. The derangements stay until the mortal restores the lost blood.]==],
				},
				["Infectious Bite"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Infectious Bite


You may not automatically lick the wounds of your feeding closed. In fact, your bites have a one in five chance of becoming infected and causing mortal vic- tims to become seriously ill. The precise nature of the infection is determined by the Storyteller.]==],
				},
				["Infertile Vitae"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Infertile Vitae


During your Embrace, something went horribly wrong, causing your blood to mutate under the stress of dying and rising again. All those you try to Embrace die. No matter what you do, you may not create any childer. However, your blood can still be used in blood rituals like Thaumaturgy and the Vaulderie, or for any other vampiric needs like making ghouls.]==],
				},
				["Initiate of the Road"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 426


Initiate of the Road


Your life on the road to enlightenment has just begun. Though you fully grasp the tenets and precepts of your chosen Road, you have not yet put them to the test. This may be because you were recently Embraced or because you previously abandoned a former Road (in which case you may also consider taking the Apostate Flaw on page 425). With this comes a +1 difficulty in resisting frenzy and Rötschreck, and you lack an aura tied to your Road. However, you have an easier time changing Roads, if you wish to do so.]==],
				},
				["Insane /Infamous Mentor"] = {
					en = [==[Book of Secrets, p. 63


Insane /Infamous Mentor


The mage who taught you the ropes is dangerously tangled up in them. Maybe she's out of her head (though probably not a Marauder… yet); or he's got an awful rep that has splattered all over you. That person could be angry at you for some reason (good or otherwise), or live downstream on Shit Creek, with a nasty habit of dragging you along for the ride. This Flaw makes an excellent addition to the Background: Mentor, and has a way of fouling up your relationships with other mages as well as your bond with the mentor herself.]==],
				},
				["Insubordinate"] = {
					en = [==[Lore of the Clans, p. 123


Insubordinate


You like to be in charge so much you have a hard time following anyone else's orders. When given a plan or told to do something, you tend to do the opposite on principle. Whenever you are ordered to do something, you must make a Willpower roll with a difficulty depending on the importance of the superior and the danger of the task (difficulty 7 is typical for someone directly above the vampire assigning them a moderately dangerous task). If you fail, you will do anything except what you've been told to do.]==],
				},
				["Intemperate"] = {
					en = [==[Book of Secrets, p. 49


Intemperate


Everything you do, you do to excess. Oh, sure, you can (usually) resist the urge to be terminally stupid, but moderation isn't part of your vocabulary. Having a drink? Why not have six? A hand of cards? Why not bet your next paycheck on the outcome? From expressing opinions to risking body and soul, you play chicken with life and expect the other guy to swerve. Folks expect this sort of thing from Ecstasy Cultists, but most Ecstatics actually have a better sense of their limits than you do.

Whenever you happen to be doing something that probably won't result in criminal charges or immediate death, make a Willpower roll to resist the urge to go whole-hog. The difficulty for the roll depends on the likely consequences of excess; taking little risks means difficulty 8 or 9, while risks with life-threatening potential are easier to resist (difficulty 5 or 6)… though you've been known to go too far in that department, too!]==],
				},
				["Isolated Upbringing"] = {
					en = [==[The Hunters Hunted II, p. 123


Isolated Upbringing


You were raised by the Society of Leopold, either born to an Inquisitor or adopted by the Society at an early age. The Inquisition is all you know. The sanctity of your holy work is honed by a purity of skill, unclouded by distraction. Unfortunately, you have a limited understanding of the outside world. When in a non-Society setting, subtract one die from all Social dice pools. When field work takes you beyond the Inquisition's walls, how will you react to all the new people, stimuli, and fellow hunters who are not so cloistered?]==],
				},
				["Jinx /Infernal Contraption (10)"] = {
					en = [==[Book of Secrets, p. 88


Jinx /Infernal Contraption (10)


Stormbringer. The One Ring. The Monkey's Paw. Sure, that paranormal doohickey may possess amazing powers, but it's also a sack of miseries the likes of which few humans can imagine. And you've got one. Lucky you…

As with the Background: Wonder (a Trait for which this Flaw was once an adversarial Background), this Trait reflects an uncanny item or device. In this case, however, the “treasure” is more trouble than it's worth. Perhaps it's cursed with mis- fortunes, poorly made, haunted by malignant spirits, seething with Paradox emanations, or too experimental for its own good. It could be the earthly form of an unpleasant entity (“I was a thousand times eviler than thou…”), an alien artifact, or the remnant of a culture that passed into dust millennia ago – and good riddance to them! Or maybe it's simply a truly wondrous treasure that dislikes you personally, like the Sword of Fighting in JourneyQuest. For whatever the reason might be, you own this mystic /hypertech millstone, and can't easily get rid of it.

Like all variable-point Flaws, the value of this Trait depends upon its ability to screw up your life. In this case, however, the value of the Flaw is deducted from the Background cost of a Wonder. In order to avoid nightmarish catastrophes of math, every two points in the Flaw are worth one dot in the Wonder Background's cost. That cost, however, cannot drop below one dot (two points), and so any points that get “left over” between the value of the Flaw and the two points in that Wonder are added to the owner's character sheet, reflecting the proverbial dead albatross around the character's neck: a mighty burden he can't just toss away.

For expanded rules regarding Wonders, see the section of that name in Chapter Two, pp. 139-165. (2 points) Your Jinxed item features an annoying

drawback that, while not deadly, makes life

difficult for the person who owns it. Examples:

it attracts ghosts, smells bad, makes irritating

sounds at inconvenient times, or radiates a

pervasive aura of discomfort. (4 points) The Jinxed item has several annoying

drawbacks (as above), or perhaps one or two

problematic ones. Examples: It must shed blood

each time it's employed, has a contentious

and unpleasant personality, attracts malignant

spirits, or tempts the owner to violate her moral

code. (6 points) Your item features a host of annoying

drawbacks (at least six of them), three or four

problematic ones, and /or a major flaw. Exam-

ples: The item belongs a powerful paranormal

entity that wants it back, it inflicts constant

pain on whomever uses it (three bashing health

levels per turn of operation), the object radiates

an aura of corruption and decay, or it steadily

drives its owner toward atrocities. (8 points) In addition to at least six annoying

drawbacks and /or five problematic ones, plus

two or more major flaws, the item also backfires

if you fail a roll of Wits + Esoterica (or Wits

+ Hypertech, if the item employs advanced

technology), against difficulty 7. The Storyteller

is encouraged to get creative when deciding

how that backfire manifests; for suggestions,

see the Mucking About with Wonders chart,

Chapter Two, p. 141. (10 points) In addition to the previous level of

difficulty, the Storyteller essentially has an open

license to make your life difficult in unexpected,

creative, and often mysterious ways. Examples:

A bloodthirsty cult that's after the treasure, a

demonic entity imprisoned within the item, a

cross-dimensional vortex of probability fluxes

and quirks of physics that manifest in the

object's vicinity, and so forth.

These flaws, of course, should be based in the nature of the Jinxed item and its relationship to the owner. That said, there's no reason that a robot can't be possessed by evil spirits or a primeval artifact can't be a technological hazard using unknown technology. Stranger things, in Mage, happen all the time. Permanent Paradox Flaw]==],
