These flaws, of course, should be based in the nature of the Jinxed item and its relationship to the owner. That said, there's no reason that a robot can't be possessed by evil spirits or a primeval artifact can't be a technological hazard using unknown technology. Stranger things, in Mage, happen all the time. Permanent Paradox Flaw]==],
				},
				["Jinx /Infernal Contraption (9)"] = {
					en = [==[Book of Secrets, p. 88


Jinx /Infernal Contraption (9)


Stormbringer. The One Ring. The Monkey's Paw. Sure, that paranormal doohickey may possess amazing powers, but it's also a sack of miseries the likes of which few humans can imagine. And you've got one. Lucky you…

As with the Background: Wonder (a Trait for which this Flaw was once an adversarial Background), this Trait reflects an uncanny item or device. In this case, however, the “treasure” is more trouble than it's worth. Perhaps it's cursed with mis- fortunes, poorly made, haunted by malignant spirits, seething with Paradox emanations, or too experimental for its own good. It could be the earthly form of an unpleasant entity (“I was a thousand times eviler than thou…”), an alien artifact, or the remnant of a culture that passed into dust millennia ago – and good riddance to them! Or maybe it's simply a truly wondrous treasure that dislikes you personally, like the Sword of Fighting in JourneyQuest. For whatever the reason might be, you own this mystic /hypertech millstone, and can't easily get rid of it.

Like all variable-point Flaws, the value of this Trait depends upon its ability to screw up your life. In this case, however, the value of the Flaw is deducted from the Background cost of a Wonder. In order to avoid nightmarish catastrophes of math, every two points in the Flaw are worth one dot in the Wonder Background's cost. That cost, however, cannot drop below one dot (two points), and so any points that get “left over” between the value of the Flaw and the two points in that Wonder are added to the owner's character sheet, reflecting the proverbial dead albatross around the character's neck: a mighty burden he can't just toss away.

For expanded rules regarding Wonders, see the section of that name in Chapter Two, pp. 139-165. (2 points) Your Jinxed item features an annoying

drawback that, while not deadly, makes life

difficult for the person who owns it. Examples:

it attracts ghosts, smells bad, makes irritating

sounds at inconvenient times, or radiates a

pervasive aura of discomfort. (4 points) The Jinxed item has several annoying

drawbacks (as above), or perhaps one or two

problematic ones. Examples: It must shed blood

each time it's employed, has a contentious

and unpleasant personality, attracts malignant

spirits, or tempts the owner to violate her moral

code. (6 points) Your item features a host of annoying

drawbacks (at least six of them), three or four

problematic ones, and /or a major flaw. Exam-

ples: The item belongs a powerful paranormal

entity that wants it back, it inflicts constant

pain on whomever uses it (three bashing health

levels per turn of operation), the object radiates

an aura of corruption and decay, or it steadily

drives its owner toward atrocities. (8 points) In addition to at least six annoying

drawbacks and /or five problematic ones, plus

two or more major flaws, the item also backfires

if you fail a roll of Wits + Esoterica (or Wits

+ Hypertech, if the item employs advanced

technology), against difficulty 7. The Storyteller

is encouraged to get creative when deciding

how that backfire manifests; for suggestions,

see the Mucking About with Wonders chart,

Chapter Two, p. 141. (10 points) In addition to the previous level of

difficulty, the Storyteller essentially has an open

license to make your life difficult in unexpected,

creative, and often mysterious ways. Examples:

A bloodthirsty cult that's after the treasure, a

demonic entity imprisoned within the item, a

cross-dimensional vortex of probability fluxes

and quirks of physics that manifest in the

object's vicinity, and so forth.

These flaws, of course, should be based in the nature of the Jinxed item and its relationship to the owner. That said, there's no reason that a robot can't be possessed by evil spirits or a primeval artifact can't be a technological hazard using unknown technology. Stranger things, in Mage, happen all the time. Permanent Paradox Flaw]==],
				},
				["Kiss of Death"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 179


Kiss of Death


Should you drain a mortal vessel of all blood minutes after their heart stops beating, the corpse rises as a zombie (using the statistics for zombies on p. 164 of V20). These zombies are free-willed, hostile toward you, and cannot be directed without some sorcerous or necromantic means to command them. THE BLACK HAND: A GUIDE TO THE TAL'MAHE'RA]==],
				},
				["Lame"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Lame


Your legs are damaged, which prevents you from run- ning or walking easily. You are forced to walk with a cane or possibly leg braces, and you have a pronounced limp to your stride. Your walking speed is one-quarter that of a normal human, and running is impossible.]==],
				},
				["Laughingstock"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Laughingstock


Somehow you've drawn the scorn of the local Har- pies, who make you their favorite target. You are at a +2 difficulty on all Social rolls in Elysium and a +1 anywhere else in the city. In addition, you are at +2 difficulty to use Intimidation or any Dominate pow- ers on anyone who has heard the stories mocking you. This Flaw can only be taken by Camarilla vampires.]==],
				},
				["Lazy"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Lazy


You are simply lazy, avoiding anything that requires effort on your part. Preferring to let others do the hard work, you lounge around. For any action that requires preparation, there's a good chance you didn't properly prepare. Difficulty rolls for spontaneous Physical ac- tions (including combat, unless it's part of a planned offensive) increase by one.]==],
				},
				["Lifesaver"] = {
					en = [==[Book of Secrets, p. 53


Lifesaver


Life, to you, is a gift and miracle worth saving. As far as you're concerned, even the most wretched people are worth another chance at redemption, and so you go out of your way to save lives and improve the lot of people (human and otherwise) who need a leg up in this world. More than a simple “code verses killing,” this Trait gives you a moral imperative to salvage lives, not just a reason to not end them. In short, it makes you a big-hearted, generous person who deeply believes in the sanctity (whether you would use that religious term or not) of life. And that, in the World of Darkness, is a magnificent burden to bear.]==],
				},
				["Light-Sensitive"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 495


Light-Sensitive


You are even more sensitive to sunlight than other vampires are. Sunlight causes double normal damage, and the light of the moon can cause lethal damage in a manner similar to the sun, though it must shine direct- ly upon you. Even bright lights hurt your eyes, requir- ing the use of sunglasses. Followers of Set and related bloodlines cannot take this Flaw, as they already have a worse version of it. 495]==],
				},
				["Lightweight"] = {
					en = [==[Lore of the Bloodlines, p. 60


Lightweight


Shamefully, you cannot imbibe the blood of any creatures other than mortals, ghouls, and vampires. Whenever you attempt to drink from another entity, you're forced to purge the contents immediately after and gain no sustenance from it.]==],
				},
				["Loathsome Regnant"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Loathsome Regnant


Not only are you blood bound, but you are also in thrall to a vampire who mistreats you hideously. Per- haps you are publicly abused or humiliated; perhaps your master forces you to commit unspeakable acts for him. In any case, existence under the bond is a never- ending nightmare, with your regnant serving to con- duct the symphony of malice. Sabbat vampires cannot take this Flaw.]==],
				},
				["Locked Vidare"] = {
					en = [==[Book of Secrets, p. 85


Locked Vidare


Mages view the Otherworldly Penumbra through a meta- physical perspective called the Vidare. Most of them can alter that perspective by changing their point of view. Not you. For you, the Periphery remains “locked” into a single perspective: the glittering clarity of the Vidare Astral, the primal luminosity of the Vidare Spiritus, or the rotting deathscape of the Vidare Mortem. Essentially, your metaphysical perspective is frozen in place. This is literally the way you view the world around you, and that view never really changes. (For details about the Vidare and the impressions they present, see Mage 20, pp. 82, 89, 94-95, 98-99, and 474.)

In addition to shaping the way your Storyteller describes the Vidare to you, and guiding your reaction to what you perceive, this Flaw also influences your personality, your sense of fashion, your philosophical and metaphysical paradigms, your magickal focus, and so on. When you perceive things in a certain way, after all, that perspective tends to color most aspects of your life.]==],
				},
				["Loose Lips"] = {
					en = [==[Ghouls & Revenants, p. 131


Loose Lips


Ghouls are often privy to a great deal of sensitive information in the night-to-night dealings with their domitors, and some cannot resist the urge to divulge (or sell) these secrets. In general, ghouls and revenants who cannot keep secrets tend not to live very long.

When you take the Loose Lips Flaw, you might be known as a gossip. In fact, this weakness may be the reason why 131 any ghoul might become independent. It's possible that the ghoul's master felt that withholding feedings for the rest of his vassal's pitiful life would be suitable punishment, and might still be keeping tabs on his former ghoul.

Ghouls with this Flaw tend to not be trusted with jobs involving secrets, so their usefulness to higher-ranking vampires is limited. On the other hand, they make perfect tools for spreading false information, which can often be far more useful. Unfortunately, you may not know whether you're spewing fact or fiction until it's too late.

Used by: All ghouls and revenants]==],
				},
				["Lord of the Flies"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 495


Lord of the Flies


Buzzing harbingers of decay swirl around you every- where. Their constant presence makes it difficult for you to interact socially (+1 difficulty when appropri- ate) and nearly impossible to sneak up on someone or hide effectively. The buzzing of the flies inevitably gives you away — all Stealth rolls are at +2 difficulty. Can't Cross Running Water]==],
				},
				["Lord of the Night"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 179


Lord of the Night


In your presence lights dim, tiny flames extinguish, and shadows cling to you or languidly move about with a surreal unlife, making it impossible to pass as anything other than inhuman. The particular shadow you cast is a malicious entity with a will of its own. It lashes out at friends and enemies alike, tearing at the scenery, and snarling at passers-by. These effects can be suppressed for a scene by spending a point of Willpower.]==],
				},
				["Lost Svadharma"] = {
					en = [==[Lore of the Clans, p. 183


Lost Svadharma


You once knew your svadharma, but when the time came to fulfill it, you failed. Now that destiny has passed you by, and there may never be another chance to make it right. Other Ravnos know the tale, and hold your failure against you. You are scorned, and your confidence has been thrown into doubt. Your total Willpower score is permanently reduced by one and you may not spend Willpower when performing actions where other Ravnos are directly involved.]==],
				},
				["Lunacy"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Lunacy


You are affected by the phases of the moon, increas- ing your chances to frenzy. Under the crescent moon, difficulties to avoid frenzy increase by one. Under the half or gibbous moon, difficulties rise by two. When the moon is full, difficulties increase by three.]==],
				},
				["Mage Blood"] = {
					en = [==[Lore of the Clans, p. 219


Mage Blood


Your blood is so tied to magic that you find you are unable to use any Discipline apart from Thaumaturgy (and for Kindred who are not Tremere, it is still paid for at out-of-Clan rates). While no path or ritual is barred to you, you may not gain any dots in any other Discipline.]==],
				},
				["Manchurian Candidate"] = {
					en = [==[The Hunters Hunted II, p. 132


Manchurian Candidate


You're the worst kind of double agent: one who doesn't know he's compromised. Some power unknown to you gave you a task, and you can't help but carry it out. Your controller has programmed you to react to a specific signal — it could be a trigger word, a pattern of flashing lights, or a specific image. When you encounter your trigger, you'll do whatever your master asked of you. Afterwards, you'll remember up to the point where you encountered the signal — the rest is a blank. Common duties include spying on your own organization, destroying sensitive documents, assassinating a target named at the same time as the trigger, or stealing valuable equipment.

Work with the Storyteller to come up with a signal and a duty. Optionally, you can let the Storyteller work out the details of what you're up to. At some point she will describe your trigger, and you have no knowledge of what happens between that point and when you come around. The Storyteller may leave what happens when you're triggered a mystery — or might have the other characters encounter you when you're programmed. Work with her to portray your character in his brainwashed state. The brainwashing is strong enough that even supernatural powers may not sway your character from his task. Social]==],
				},
				["Marked for Death"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 425


Marked for Death


The Court of Blood has found fault with you and placed a price upon your head. You are earmarked for death, and one by one your peers will come to bring it to you. While you may be more than capable of taking your equals in a fight, you know not when or where they will strike. The festering paranoia claws at the edges of your thoughts; in addition to attackers of varying capabilities appearing at random, at Storyteller's discretion you may also lose one die to Mental rolls due to distraction.]==],
				},
				["Masquerade Breaker"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 491


Masquerade Breaker


In your first nights as a vampire, you accidentally broke the Masquerade — and were spotted doing so. Someone else covered for your mistake, but holds the favor over you. Now you exist in fear that your error will be revealed. In the meantime, your “savior” takes pitiless advantage of you. This Flaw can only be taken by vampires in Sects or Clans that respect the Mas- querade.]==],
				},
				["Mayfly Curse (10)"] = {
					en = [==[Book of Secrets, p. 42


Mayfly Curse (10)


well. Life-Sphere magick cannot negate this Flaw, which could be

interpreted as a manifestation of the Unbelief form of Paradox,

Your lifespan burns bright and fast. Due, perhaps, to unless the player buys off the Flaw… and perhaps not even then. biotech, cloning, or some other inhuman heritage or modifi- cation, you age far more quickly than normal human beings Mental Merits do. While this means that you reach(ed) maturity in record time, it ushers in premature decrepitude. When you live this Mages depend upon their mental faculties. Although vam- fast, kid, one way or another, you're dying young! pires, werefolk, and the like prize certain mental aptitudes, most

Neurodiversity and Mental Traits

Minds aren't machines. For all the talk of “normal brains” and “average functionality,” medical research and social

activism have shown that such ideas are absurd. In older days, people slapped labels on folks whose mental capabilities

seemed to be “different”: slow, moron, diminished capacity, retarded. (Also, brilliant, genius, egghead, and savant.)

Some people cling to those definitions even now. In the twenty-first century, however, two terms have gained preference

over those old labels: neurodivergence and neurodiversity.

Essentially, neurodivergence means “someone whose brain-functions diverge from the human norm,” while neurodiversity

means “all of our brains work differently, so let's respect our differences.” Some folks argue that the latter term is too

broad-ranging and “politically correct” to be useful, while others assert that neurodivergent is an insult which holds

human minds to an unrealistic standard. Both arguments have merit; severe mental conditions do interfere with a

person's ability to function in the everyday world, and it is insulting to call folks “divergent” when their minds work

along different lines than other people's minds do. (Maybe less insulting than moron, but you get the idea.) As of this

writing, neurodiversity is the preferred term among people who want to be inclusive, not divisive, with regards to the

vast range of human minds.

What does this have to do with Mage? For starters, both Merits and Flaws in the Mental category reflect “divergence”

from supposedly normal mental functions. If these traits didn't diverge from the norm, they would not be “merits” or

“flaws.” Secondly, both the benefits and the drawbacks originate with the same source: mental capacity that ranges

beyond the apparent human norm. People whose minds work differently than other people's minds work have pluses

in some regards and minuses in others. And so, a character who has, say, Lightning Calculator might also behave

in ways that are Inappropriate to many situations. This works the opposite way too – witness the ways in which

autistic people often Hyperfocus with uncanny acuity. Mental conditions, pro and con, tend to be intertwined. The

conditions that nurture the Merit often nurture the Flaw as well, and so characters with Mental Merits or Flaws really

ought to have both.

Because neurological conditions like dyslexia and the autistic spectrum have physical causes which affect mental

processing, such conditions are considered, in game terms, to be Impediments, as in the Physical Flaw of that name.

(See pp. 39-40.) The ways in which they manifest, though, can come through as Mental Merits and /or Flaws too.

Other, more nebulous conditions, like Chronic Depression, may have physical sources with predominantly mental

results for one character, and completely psychological sources for another. Such distinctions, of course, fall into the

rather Technocratic mind /body Cartesian duality thing, which doesn't really suit the spirit of Mage. To be honest, all

these distinctions are arbitrary anyhow. Minds aren't lists of game traits, either. It really doesn't matter whether a given

Merit or Flaw is Physical, Mental, Social, or even Supernatural – only that it guides roleplaying and affects gameplay.

Technically, all mages are neurodivergent. Awakened consciousness is functionally different than a Sleeping mind,

and can perform tasks (like, say, magick) that a “normal” mind cannot manage. Even so, mental Merits and Flaws

represent significant departures from what the “average” mage can do, and so a character who has such Traits is

functioning on a different mental plane – for better and worse – than the characters who do not. When choosing such

Traits, and roleplaying them out, we recommend keeping that fact literally in mind. Awakened characters favor those abilities over all else. And so, it's likely that your mage will have at least one Mental Merit… and, all things being related, may well suffer from Mental Flaws as well, as described in the sidebar nearby.

Like Physical Flaws, Mental Flaws make excellent Genetic Flaws for Enhanced and biomodded characters, especially for ones whose “modifications” and /or origins remain essentially invisible to the naked eye. Constructs (Technocratic and other- wise) are especially subject to such conditions. See the heading Physical Flaws for details.]==],
				},
				["Mayfly Curse (5)"] = {
					en = [==[Book of Secrets, p. 42


