Like Physical Flaws, Mental Flaws make excellent Genetic Flaws for Enhanced and biomodded characters, especially for ones whose “modifications” and /or origins remain essentially invisible to the naked eye. Constructs (Technocratic and other- wise) are especially subject to such conditions. See the heading Physical Flaws for details.]==],
				},
				["Member of the Pack"] = {
					en = [==[Lore of the Clans, p. 87


Member of the Pack


You can only summon, speak to, and command a specific type of animal — ravens, rats, and so forth — with Animalism. Your Storyteller is the best adjudicator of what types of animal are appropriate for this Flaw, but the choice should be fairly limiting. Other animals do not respond to your uses of Animalism at all.]==],
				},
				["Mental Lock"] = {
					en = [==[Book of Secrets, p. 47


Mental Lock


Somewhere in between impulse and action, things get stuck inside your head. Thoughts or images wind up caught in mental loops, and you occasionally find yourself tripping over words, getting stuck in patterns of speech, or repeating apparently uncontrollable activities (flapping your hands, shaking your head, rubbing your wrists, and so forth) which, under most circumstances, would be easy to stop or manage. Sometimes known as perseveration or stimming (see the Merit: Hyperfocus), these mental tics often manifest from brain damage, emotional trauma, intense stress, and /or autism and other sensory-processing conditions. Conventionally and incorrectly called “nervous habits,” these mental quirks may be attempts to control your apparently chaotic surroundings by giving your brain something that feels like you can control it. Problem is, you essentially have to shake yourself out of the locked pattern, concentrate on a new sensation in order to break the loop, invoke a sort of “ritualized” word or action that triggers a break in that loop, or employ some other method to break free of the mental lock. Until that point, you could find yourself stuttering even though you don't have a speech impediment, feel “frozen” on words or thoughts you can't easily articulate, lock into near-obsessive ruminations on nonsense phrases or perilous thoughts, get stuck doing the same thing over and over again, or otherwise wind up focused on an internal feedback cycle.

System-wise, the Storyteller will occasionally drop small but annoying quirks into your character's ability to speak, suggest small, repetitious actions for your character to perform, and otherwise screw with your character's capacity to move beyond a single nagging thought. To break those mental locks, you'll need to roll your character's Willpower against difficulty 7, spend a temporary point of Willpower, or else stand around “locked up” in mid-thought or action until you can break that irritating mental block through force of will or (after five turns) the simple passage of time.]==],
				},
				["Methuselah's Thirst"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 177


Methuselah's Thirst


You can no longer sustain yourself on mortal blood and must feed on the blood of Kindred or other supernatural creatures with potent reserves, such as lupines or fairies. Mental Grand Library (2, 4, 6, or 7 pt. Merit)

Throughout the years, you've managed to amass an exquisite collection of books, both common and rare. Choose 3 Knowledge dots for every 2 points taken in this Merit, or 10 Knowledge dots for 7 points. While working in your library, the difficulty rating for any rolls involving those Knowledges is reduced by 2.]==],
				},
				["Mistaken Identity"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Mistaken Identity


You look similar to descriptions of another Kin- dred, which cause cases of mistaken identity. This can prompt numerous awkward or even dangerous situa- tions, especially if your “twin” has a terrible reputation or is wanted for some crime.]==],
				},
				["Monstrous"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Monstrous


Your physical form was twisted during the Embrace, and now reflects the Beast that rages inside you. Char- acters with this Flaw appear to be savage monsters and have Appearance ratings of zero. Nosferatu and other bloodlines whose weaknesses cause them to start off with Appearance zero cannot take this Flaw.]==],
				},
				["Mortal Flashbacks"] = {
					en = [==[Lore of the Bloodlines, p. 91


Mortal Flashbacks


Your body remembers your death. Every night when you awaken, you vividly remember the pain of your death wound. The wound reopens during the night and closes itself shortly before you rise. This traumatic reminder of your mortality starts your night off in a bad way. You lose a point of Willpower each night when you awaken, because of the trauma of dying again. 91]==],
				},
				["Mr. Red Tape"] = {
					en = [==[Book of Secrets, p. 67


Mr. Red Tape


Bureaucracy hates you. Any official complication that could go wrong will go wrong if you're the one who's dealing with the authorities. Essentially the opposite of the Merit: Master of Red Tape (p. 58), this Flaw adds + 2 to the difficulty of any roll you make when trying to get something done through an established system, and throws stupid mistakes and delays into the works whenever you've got to work with any sort of bureaucracy.]==],
				},
				["Multiple Curses"] = {
					en = [==[Lore of the Clans, p. 26


Multiple Curses


In addition to the normal curse imposed upon you by your caste or sect, you suffer one additional one associated with the Assamite Clan. Most likely, you are a rare vizier or sorcerer within the Sabbat who suffers the Baali Curse in addition to your normal caste-imposed curse, but at the Storyteller's discretion, other combinations may be possible.]==],
				},
				["Mute"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 483


Mute


You cannot speak. You may communicate with the Storyteller and describe your actions, but cannot talk to player or Storyteller characters unless everyone concerned purchases a commonly understood sign language (via the Language Merit) or you write down what you wish to say.]==],
				},
				["Nameless"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 425


Nameless


You do not exist. Certainly, you still walk the earth and your friends and kin can still see and touch you, but all records of your existence have been destroyed. Not even your vampiric progeny can lay claim to your name. As far as anyone can prove, you never were. If you take this Flaw, you may not take any Social Merits that grant benefits based on reputation. At Storyteller's discretion, you may also be barred from taking Backgrounds that require a social presence. Who or what have you made so angry that they have erased your existence from the face of this earth?]==],
				},
				["Narc"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Narc


You are known to be a snitch, an informer firmly planted in the pocket of the vampires in charge. Those on whom you might yet inform loathe you as a result, feeding you misinformation when they can in an attempt to discredit you. Given the opportunity, they might do you mischief. Regardless, your reputation as a weasel pre- cedes you, putting you at +1 difficulty on all Social rolls against those who don't agree with your politics.]==],
				},
				["New Arrival"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


New Arrival


You've just arrived in your new city of residence, and don't know anyone in the place. Existing factions may try to recruit or eliminate you, while vampires in posi- tions of authority size you up and take your measure. Meanwhile, your ignorance of the city's current events, history, and politics (not to mention the personality quirks of the vampires already in place) may cause you to make a serious blunder.]==],
				},
				["New Kid"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


New Kid


You're the latest in the city to be Embraced or have yet to prove yourself to your Sect, and everyone knows it. That automatically puts you at the bottom of the social totem pole. Other neonates take every oppor- tunity to demonstrate your inferiority, or rival packs constantly test your worthiness to the Sabbat. Even if someone else is added to the ranks of the unliving, you're still regarded as something as a bit of a geek by your peers — a distinction that can have dangerous consequences if bullets start flying. All Social-related rolls are at +1 difficulty when you are dealing with oth- er neonates. (Ancillae and elders lump you in with all the other neonates under their general disdain.)]==],
				},
				["Nightmares"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Nightmares


You experience horrendous nightmares every time you sleep, and memories of them haunt you during your waking hours. Upon awakening, you must make a Willpower roll (difficulty 7) or lose a die on all ac- tions for that night. A botched Willpower roll indi- cates that, even when awake, you still believe that you are locked in a nightmare.]==],
				},
				["Notoriety"] = {
					en = [==[Book of Secrets, p. 65


Notoriety


Thanks to this inverse of the Merit: Prestige, you're saddled with a bad reputation among your fellow mages. System-wise, this Flaw adds +2 to the difficulties of all social rolls within your faction (Traditions, Crafts, Technocracy, etc.), and pre- disposes pretty much everyone outside your closest friends to think the worst of you. Rumors dog your steps, and whispers precede your appearance. Whether or not the stories are true, you've been linked to some disgrace, and will be shunned and probably punished accordingly if you haven't been punished already. (See the Supernatural Flaw: Branded, p. 89, for a potential punishment, or for an alternative to this Flaw that could be taken by a Tradition mage character.) You might be able to shuck this bad rep eventually, but it's gonna be a pretty rough road until you do.]==],
				},
				["Oathbreaker"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 178


Oathbreaker


Once you swore fealty to a lord or organization, or made a binding contract. You've broken that promise and everyone knows about it. Now it's near impossible to earn the trust of others. The difficulty of Social rolls to convince someone of your trustworthiness is increased by three, and even members of your coterie may have reservations about you. Supernatural]==],
				},
				["Oathbreaker (Ravnos)"] = {
					en = [==[Lore of the Clans, p. 182


Oathbreaker (Ravnos)


Making an oath ties one person's svadharma to another, linking the two spirits until the oath can be fulfilled. With this in mind, a Ravnos never breaks her word once given in good faith, and so long as it was done with proper ceremony. If the Ravnos spits into her palm and shakes on her word, then the oath cannot be broken without negatively impacting the vampire's svadharma (or so Ravnos superstition dictates).

The oathbreaker will lose her way, falling into vice and worthlessness, until the broken oath can be redeemed. Anyone who looks at your aura can see a sickly red slash indicating the broken oath. You may not spend Willpower to ignore your Ravnos vice, and you do not gain Willpower from fulfilling your Nature.]==],
				},
				["Obsession"] = {
					en = [==[Book of Secrets, p. 49


Obsession


An all-consuming interest of yours tends to overshadow whatever passes, in your mind, for common sense. If you love Star Wars, then you've seen all the movies many times over, own tons of merchandise, and spend inordinate amounts of time arguing about SW trivia. Is Tarot your obsession? Then you've got dozens (if not hundreds) of decks, research every potential element of Tarot significance, and drive your friends crazy with constant offers of readings and advice. You can't have just one or two cats – you're the local Crazy Cat Person who drops half a paycheck on food, litter, and veterinary bills. This obsession probably won't get you killed or anything (unless you're crazy enough to get obsessive about werecritters or similarly fatal topics), but it consumes vast amounts of time, attention, and cash. When faced with an opportunity to pursue your obsession down unexplored avenues, or if that obsession interferes with important things like relationships, work or both, you may need to make a Willpower roll (difficulty 6) to suppress the urge. And if the obsession involves something that's compulsive by nature – gambling, for example – the Willpower roll could involve a difficulty of 8 or maybe higher before you can shake off your compulsion and focus on something else.]==],
				},
				["Obvious Predator"] = {
					en = [==[Lore of the Clans, p. 48


Obvious Predator


Your innate Brujah rage always percolates below the surface no matter how hard you try to project an image of calm. Mortals find you intrinsically menacing, and instinctively fear you for the violence you promise to unleash.

System: The difficulty of all Social rolls made against mortals other than Intimidation rolls increases by 2.]==],
				},
				["OCPD"] = {
					en = [==[Book of Secrets, p. 53


OCPD


Mages tend to be kinda obsessive by nature. You, however, feel compelled to follow stringent personal rituals, maintain an obsessive sense of order, work yourself to the point of exhaustion (and beyond), organize every possible element of your life and space, employ compulsive behaviors without realizing that you're doing so, and otherwise lose track of time, things, and people unless they fall into the sphere of your obsessive-compulsive personality disorder.

An especially common Flaw among technomancers, sci- entists, ritual magi, religious devotees, autistic people, military personnel, artists, executives, and other folks whose philosophies and pursuits demand continual attention, OCPD could also result from various forms of psychic trauma, brain damage, spiritual epiphanies, cultural or professional perfectionism, and metaphysical dedication. As a rule, a person's behaviors grow more compulsive when he's under stress. After all, when it seems like your world's spinning out of control, it becomes all the more important to establish control over whatever elements you can control.

When this Flaw is chosen, you'll need to define which compulsions your character has, and figure out the triggers that make those compulsions more obvious. System-wise, you'll often have to make Willpower rolls in order to shake off the need to organize and obsess over the object of your attentions. The difficulty, of course, depends upon the situation and the character's level of stress at the time; the more challenging the circumstances, the more obsessive the compulsions.]==],
				},
				["Odd Gait"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 421


Odd Gait


Moving swiftly does not come

easily for you; perhaps walking is painful or perhaps you are

simply never in a hurry. Whatever the reason, you move at

half your normal movement speed. Storyteller characters

may also come to recognize you by your uncommon walk.]==],
				},
				["Offensive to Animals"] = {
					en = [==[Ghouls & Revenants, p. 138


Offensive to Animals


Ghouls and revenants who take the Offensive to Animals Flaw will have difficulty in their encounters with animals. Dogs, wolves, bats, birds, and other creatures will act hostile toward the character whenever she's around, and will likely attack the closer the character gets. Much like the vampiric Flaw of the same name, a ghoul or revenant who is Offensive to Animals may find it challenging to walk freely in certain areas.

Animals will bark, howl, whine, and make noise when the character approaches them. They may not directly attack the ghoul unless provoked, but they will clearly be aggressive or, alternatively, might flee from the area.

This Flaw is not recommended for ghouls or revenants who either plan on using the Animalism Discipline or come into contact with characters that do.

Used by: All ghouls and revenants]==],
				},
				["Offline (1)"] = {
					en = [==[Book of Secrets, p. 63


Offline (1)


You hate the goddamned Internet. As far as you're con- cerned, it's a complicated waste of time. You loathe social networking, lack a webpage, refuse to Twitter, and don't really even know (or care) how to Google stuff. Anyone who wants to contact you can damned well write a letter, use a telephone, or just leave you the hell alone! (Damn kids, get off my digital lawn…)

While this Flaw is worth only one point in cultures where the Internet is an occasional (and often privileged) indulgence, it's a three-point Flaw in cultures where Internet access and participation are major elements of most people's social lives. Those cultural divides are more tied to generational and eco- nomic divides than they are to ethnic or geographical ones. A poor, elderly, or simply old-fashioned New Yorker might not really care about net access, so long as she can still stay in contact with her friends and family; a college student in Rio, however, would be at a pretty significant disadvantage if he chose to avoid the Internet. And yeah – twenty-first-century mages use the Internet too, even if they don't visit the Digital Web. Online presence isn't just for Virtual Adepts anymore!]==],
				},
				["Offline (3)"] = {
					en = [==[Book of Secrets, p. 63


Offline (3)


You hate the goddamned Internet. As far as you're con- cerned, it's a complicated waste of time. You loathe social networking, lack a webpage, refuse to Twitter, and don't really even know (or care) how to Google stuff. Anyone who wants to contact you can damned well write a letter, use a telephone, or just leave you the hell alone! (Damn kids, get off my digital lawn…)

While this Flaw is worth only one point in cultures where the Internet is an occasional (and often privileged) indulgence, it's a three-point Flaw in cultures where Internet access and participation are major elements of most people's social lives. Those cultural divides are more tied to generational and eco- nomic divides than they are to ethnic or geographical ones. A poor, elderly, or simply old-fashioned New Yorker might not really care about net access, so long as she can still stay in contact with her friends and family; a college student in Rio, however, would be at a pretty significant disadvantage if he chose to avoid the Internet. And yeah – twenty-first-century mages use the Internet too, even if they don't visit the Digital Web. Online presence isn't just for Virtual Adepts anymore!]==],
				},
				["Old Flame"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 491


Old Flame


Someone you once cared deeply for is now with the enemy. He still attempts to play on your sympathies “for old times' sake” while working against you. Unless you succeed on a contested Manipulation + Expression roll against your former friend, you cannot act against him unless the situation becomes life-threatening.]==],
				},
				["One Eye"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


One Eye


You have only one eye — which eye is missing is up to you. The difficulties of all Perception rolls involving eyesight are increased by two, and the difficulties of all die rolls requiring depth perception are increased by one (this includes ranged combat). 481]==],
				},
				["Open Wound (2)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Open Wound (2)


You have one or more wounds that refuse to heal, and which constantly drip blood. This slow leakage costs you an extra blood point per evening (marked off just before dawn), in addition to drawing attention to you. If the wound is visible, you are at + 1 difficulty for all Social-based rolls. For two points, the Flaw is simply unsightly and has the basic effect mentioned above; for four points the seeping wound is serious or disfiguring and includes the effects of the Flaw Permanent Wound (below).]==],
				},
				["Open Wound (4)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Open Wound (4)


You have one or more wounds that refuse to heal, and which constantly drip blood. This slow leakage costs you an extra blood point per evening (marked off just before dawn), in addition to drawing attention to you. If the wound is visible, you are at + 1 difficulty for all Social-based rolls. For two points, the Flaw is simply unsightly and has the basic effect mentioned above; for four points the seeping wound is serious or disfiguring and includes the effects of the Flaw Permanent Wound (below).]==],
				},
				["Out of Phase"] = {
					en = [==[Lore of the Bloodlines, p. 99


Out of Phase


The character is a little too aware of time and the possibilities surrounding them. People often seem to be in slightly different places, and speech frequently echoes in their ears. They see layers of alternate timelines in too 99

much detail. Any perception rolls they make are at +2

difficulty, as they try to see past the unreal.]==],
				},
				["Outcast"] = {
					en = [==[Lore of the Clans, p. 26


Outcast


Your have rejected the ethos of the caste into which you were Embraced. Perhaps you are one of the few viziers or sorcerers to support the Web of Knives or pursue the Path of Blood. Perhaps you are a warrior who has little stomach for combat, preferring instead to be a diplomat or a student of the occult. Perhaps you made some kind of public spectacle that revealed your disdain for your fellow caste members. Your sire now rejects you, as do the other members of your caste. The difficulty of all Social rolls against members of your caste is at +2.]==],
				},
				["Outsider"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 423


Outsider


This is not your native land; this is not your mother tongue. You are not from around here. Everything is strange and different, from the customs to the food. You struggle with the area's native language (though you can get by with a purchase of the Lingua Franca Merit) and the difficulty to applicable Social rolls increases by one.]==],
				},
				["Outspoken Heretic"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 425


Outspoken Heretic


You hold a belief con- sidered to be heretical by a major religious power, such as the Catholic Church. Unlike others who practice their heresies in secret, you are open about your beliefs. You must constantly face false accusations, harassment from others who fancy themselves true believers, and the denial of hospitality from steadfastly faithful stranger, or those who fear the religious authority. At the Storyteller's discretion, this can impose a difficulty increase of up to 3 to applicable Social rolls.]==],
				},
				["Overconfident"] = {
					en = [==[Book of Secrets, p. 48


Overconfident


You're the best there is at what you do. If other folks disagree, then that's their problem, not yours! Nothing is beyond your reach, and so you almost never back down from a challenge, no matter how absurdly outmatched you appear to be at the time. If things go poorly, of course, you can always blame someone else. After all, it's clearly not your fault!]==],
				},
				["Overextended"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Overextended


You've got your fingers in too many pies, and people are starting to notice. You have too many ghouls, too many retainers, or too much influence, which means that a lot of people have a vested interest in trimming back your operations. These enemies take every oppor- tunity to reduce your power and influence, and if that means lying, cheating, or killing, so be it. Furthermore, your enemies block every attempt you make to move into new areas of control. You're boxed in, and the box is getting smaller.]==],
				},
				["Overstimulated"] = {
					en = [==[Lore of the Clans, p. 142


Overstimulated


Malkavians notice things that many others do not. That means keeping their eyes and ears open far longer than anyone else does. That makes you easily distracted when trying to focus. Take a +2 penalty to all rolls involving Perception.]==],
				},
				["Pacifist"] = {
					en = [==[M20 Sorcerer, p. 107


Pacifist


You've chosen to cause no intentional harm to anyone, be it a religious restriction or a moral decision you made. You may defend yourself with magic, and this may be something that you have specialized in for that purpose. If you take this Flaw, you should be prepared to play with these restrictions sincerely.]==],
				},
				["Paper Trail"] = {
					en = [==[Lore of the Clans, p. 142


Paper Trail


You've spent some time in state institutions like prisons or asylums, likely before your Embrace. Most people have some sort of information that relays date of birth and other bits of fact. This information is hard to eliminate, and may endanger the Masquerade. Enemies with the right influence may be able to track down the information and use it against you. It may lead to vulnerable targets or clue hunters to where your haven is located.]==],
				},
				["Paradise Lost"] = {
					en = [==[The Hunters Hunted II, p. 125


Paradise Lost


You once had the True Faith that could light the night. It is now extinguished. This is not the simple loss of an advantage, but a gaping wound of the soul. You know what it was like to be seen in the light of the divine, but now stumble outside the sight of God and drown in the corpse-cold murk of doubts, an ever-flowing river with no end in sight.

Whenever you are confronted with this loss (holding a holy symbol, asked to perform a miracle, entering a church, etc.), make a Willpower roll (difficulty 7) or lose one die on all actions for the scene, as sorrow seizes you. A botched Willpower roll consumes a Willpower point and opens you to despair. Indulging a vice (alcohol, drugs, pornography, etc.) can replenish Willpower points lost in this way.

This Flaw can be earned mid-chronicle with a loss of True Faith, or it can be taken at character creation as part of a tragic backstory, possibly initiating a redemption tale of faith regained.]==],
				},
				["Paranoid"] = {
					en = [==[The Hunters Hunted II, p. 132


Paranoid


Too many years in the intelligence business means that you know that it's only paranoia if they're not out to get you. You're suspicious of everything and everyone — you'd call for backup, but how can you be sure that they're not in on it too? You pick up on innocuous details, each one providing more evidence for the conspiracy against you. Add one to the difficulty of all social interaction rolls.]==],
				},
				["Paranormal Prohibition or Imperative (2)"] = {
					en = [==[Book of Secrets, p. 83


Paranormal Prohibition or Imperative (2)


Also known as Geasa and Magical Prohibition or Imper- ative, this Flaw represents a thing you either must do, or are forbidden from doing, on pain of awful consequences. Generally, this imperative comes from an oath you swore, a curse that was inflicted upon you, or a legacy that follows your family lineage. Faerie grudges, infernal pacts, godly inheritances, ancient proph- ecies, Fortean quirks of physics… any one of them can inflict such a burden upon you. So long as you never cross that line, you should be okay – and may, in fact, possess some blessing (a Merit or Background Trait) that's linked to this Flaw. Ah, but life has a way of pushing us to do things we don't want to do, and that's especially true in the case of people who have a curse or geas upon their heads!

The value of this Flaw is based on your chances of vio- lating the prohibition, and the consequences that occur if / when you do: (1 point) You break the prohibition only with an easily

avoided circumstance (never kill a cat, go to London, or

have sex with a married person), or find it easy to fulfill

your imperative (you must shave all your hair off, walk

outside every day, or wear blue clothing). (2 points) Your prohibition is easy to break (never tell

a lie, leave your home town, or have sex with anyone),

or your imperative is challenging to fulfill (you must

always cover your head, walk at least three miles every

day, or go barefoot at all times). (3 points) It's very hard to not break your prohibition

(never speak, have a home of your own, or fall in love

or lust with anyone), or to honor your imperative (you

must blindfold yourself every day even though you

can see, walk everywhere you go, or remain naked at

all times). (+1 point) Inconvenient consequences – you botch your

next three rolls, suffer a migraine, develop a rash for

several days, etc. (+2 points) Annoying consequences – you lose your

voice for a day, lose a die from all your pools for a week

due to constant pain, add +2 to all your social rolls

with members of your faction until you can atone from

breaking your oath, and so forth. (+3 points) Painful consequences – until you can atone,

you go blind or mute, lose one dot from an Attribute,

lose an Ally, Mentor, or Familiar, take the Flaw:

Oathbreaker (below), or suffer a similarly awful fate. (+4 points) Crippling consequences – until you atone,

your Avatar abandons you, you lose a total of three dots

from various Attributes, you take the Flaws: Oathbreaker,

Deranged or both, or else endure a related punishment. (+5 points) Fatal consequences – either you're gonna

die soon, you'll be whisked off to an Otherworldly

punishment Realm, or both. Atonement, if it's even

possible, will be very harsh, so do NOT break this oath

or forsake this imperative!

This Flaw makes an excellent companion to numerous Backgrounds (Familiar, Legend, Past Life, Totem, Wonder, and potentially others at the Storyteller's discretion) and Merits (pretty much anything, really, depending on how you define the source of that Merit). Although this does not reduce the cost of that Trait (despite the description of this Flaw in Mage Revised, which employed a complex and potentially abusive rule system that's not found in other World of Darkness games), a Prohibition /Imperative can represent vows, obligations, and /or legacies associated with the beneficial Trait. If, for exam- ple, Riordan Manseragh were to have sworn a mystic oath in order to win his tiger-spirit familiar, that oath would represent a Paranormal Imperative, with painful consequences (the loss of his Familiar Background) if he breaks his promise.

Your Prohibition /Imperative must be tied in with your character's backstory, and probably has a connection to all three elements of her magickal focus (paradigm, practice, and instruments). The conditions must be something that could conceivably present an obstacle for your character (no prohibitions, for example, against having sex with Voormas, or imperatives to get out of bed in the morning), and your Story- teller will, of course, make a point of throwing said obstacles in your path at various points during the chronicle. That said, we also urge Storytellers not to abuse this Flaw, or to apply it out of proportion with the points the Flaw is worth.

Although it's rather unusual, a technomancer could have a metaphysical pact or prohibition too. She may, for instance, need to work on a Mac, employ only steamtech, or invent all of her own technology to avoid suffering some paranormal malaise. Thus, this Flaw is not always “mystical” in nature, even if the line separating mysticism from paranormal phenomena is more a matter of semantics than of metaphysical principles.]==],
				},
				["Paranormal Prohibition or Imperative (3)"] = {
					en = [==[Book of Secrets, p. 83


