breaking your oath, and so forth. (+3 points) Painful consequences – until you can atone,

you go blind or mute, lose one dot from an Attribute,

lose an Ally, Mentor, or Familiar, take the Flaw:

Oathbreaker (below), or suffer a similarly awful fate. (+4 points) Crippling consequences – until you atone,

your Avatar abandons you, you lose a total of three dots

from various Attributes, you take the Flaws: Oathbreaker,

Deranged or both, or else endure a related punishment. (+5 points) Fatal consequences – either you're gonna

die soon, you'll be whisked off to an Otherworldly

punishment Realm, or both. Atonement, if it's even

possible, will be very harsh, so do NOT break this oath

or forsake this imperative!

This Flaw makes an excellent companion to numerous Backgrounds (Familiar, Legend, Past Life, Totem, Wonder, and potentially others at the Storyteller's discretion) and Merits (pretty much anything, really, depending on how you define the source of that Merit). Although this does not reduce the cost of that Trait (despite the description of this Flaw in Mage Revised, which employed a complex and potentially abusive rule system that's not found in other World of Darkness games), a Prohibition /Imperative can represent vows, obligations, and /or legacies associated with the beneficial Trait. If, for exam- ple, Riordan Manseragh were to have sworn a mystic oath in order to win his tiger-spirit familiar, that oath would represent a Paranormal Imperative, with painful consequences (the loss of his Familiar Background) if he breaks his promise.

Your Prohibition /Imperative must be tied in with your character's backstory, and probably has a connection to all three elements of her magickal focus (paradigm, practice, and instruments). The conditions must be something that could conceivably present an obstacle for your character (no prohibitions, for example, against having sex with Voormas, or imperatives to get out of bed in the morning), and your Story- teller will, of course, make a point of throwing said obstacles in your path at various points during the chronicle. That said, we also urge Storytellers not to abuse this Flaw, or to apply it out of proportion with the points the Flaw is worth.

Although it's rather unusual, a technomancer could have a metaphysical pact or prohibition too. She may, for instance, need to work on a Mac, employ only steamtech, or invent all of her own technology to avoid suffering some paranormal malaise. Thus, this Flaw is not always “mystical” in nature, even if the line separating mysticism from paranormal phenomena is more a matter of semantics than of metaphysical principles.]==],
