				["Parasitic Infestation"] = {
					en = [==[Lore of the Clans, p. 162


Parasitic Infestation


Living in the dark has made you a home to all manner of creepy crawlies and bloodsuckers. Your skin is crawling with ticks, lice, and leeches of all descriptions. They constantly bite and burrow, and having fed on your vitae, they have become very hard to kill. Not only can you not command them, you have tried everything to get rid of them and still they persist. Whatever the reason, they find you so succulent they reduce your blood pool by the result of one die divided by 3 (round down) each time you rise. The constant itch also keeps you on edge, increasing the difficulty of any Self-Control or Instinct rolls by 1.]==],
				},
				["Path Inept"] = {
					en = [==[M20 Sorcerer, p. 108


Path Inept


You have a Path that you just do not understand. This could be due to a curse, lack of training, or a mental block. You must choose a Path from those that are available to your Affiliation. When improving the chosen Path, you must spend one quarter more experience points to increase Path levels or rituals. This must be a Path your character desires and plans to study.]==],
				},
				["Permanent Fangs"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Permanent Fangs


Your fangs do not retract, making it impossible for you to hide your true nature. While some mortals may think you've had your teeth filed or are wearing pros- thetics, sooner or later you're going to run into some- one who knows what you truly are. You are also limited to a maximum Appearance rating of 3.]==],
				},
				["Permanent Paradox Flaw (2)"] = {
					en = [==[Book of Secrets, p. 89


Permanent Paradox Flaw (2)


Following a nasty brush with Paradox, you're got a Flaw that just won't go away. System-wise, select a trivial (two points), minor (four points), or significant (six points) Paradox Flaw as described on Mage 20, p. 551. That Flaw is now part of your character's life until you buy off this Flaw, preferably with ex- perience earned through some extraordinary adventure that's related to the Paradox Flaw in question and the mishap that created that Flaw in the first place.]==],
				},
