					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Permanent Wound


You suffered injuries during your Embrace which your transformation somehow failed to repair. At the begin- ning of each night, you rise from sleep at the Wounded health level, though this may be healed by spending blood points.]==],
				},
				["Phobia"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Phobia


You have an overpowering fear of something. Spi- ders, snakes, crowds, and heights are examples of com- mon phobias. You must make a Courage roll every time you encounter the object of your fear. The difficulty of the roll is determined by the Storyteller. If you fail the roll, you must retreat from the object.]==],
				},
				["Phylactery"] = {
					en = [==[Book of Secrets, p. 94


Phylactery


Your magick, perhaps your very soul, resides outside of your physical self. Maybe you've placed your soul within a ring, a jar, or a wooden doll in order to protect yourself from possession and control. Or perhaps you believe that your wand, not your Will, is the source of your mystic powers. You could have built a robot as an extension of your Genius, or crafted a jacket into which you've instilled the very essence of who you are. The receptacle itself is not important except with regards to its portability. This Flaw reflects the fact that you must have the receptacle before you can employ your Arts. Without it, you're just another Sleeper.

Linguistically, phylactery comes from a Greek root meaning “to guard.” In many forms of classical magick, practitioners would place their souls or life-force within amulets, either as protection for their souls or as portable vessels for spellwork. Orthodox Jews sometimes employ tefillin – often referred to as phylacteries – as reminders of their covenant with God. As a Mage Trait, your Phylactery serves as a container for the “inner god” that allows a mage to change reality: the Awakened Avatar.

How your character views this relationship between the container, his Awakened self, and the ability to perform magick depends on the character's paradigm. A Slavic witch could believe that she has taken her heart and placed it into a hardboiled egg; a mad scientist may use consciousness-transposing co-location theory in order to secure his brilliance in a vat-held brain. The shapechanging shaman invests her soul into a wolf-skin, while a Hermetic magus employs Roman rituals to lock his immortal essence into a golden staff. Your phylactery is probably an item, but it could conceivably be a location (a grove, a garden, a house, etc.) or living being (a child, a bird, a tree, a manufactured in- telligence housed within a mainframe, and so forth). The key is this: Your mage must be able to physically access the phylactery in order to employ Sphere magick. And therein lays the Flaw.

All told, a phylactery offers a few powerful benefits in ex- change for some pretty significant drawbacks. On the plus side: A phylactery allows you to preserve a part of your con-

sciousness outside your mortal body. That body may

be destroyed, but your soul and consciousness live on

until or unless the phylactery is destroyed. With Mind

4, you can project that consciousness into another body

or an astral form, while a character with Mind 5 /Spirit

5 can place your Awakened consciousness into a new

body for you. If the phylactery is taken from you, or you're taken away

from it, you can retrieve it, or return to it, with a successful

application of the Correspondence Sphere. The difficulty

for this return Effect is 4 if the return would seem coinci-

dental to a witness, 5 if it's vulgar without witnesses, and 6

if it's vulgar with witnesses. (Yes, the usual Paradox applies.) A living phylactery retains a psychic bond with you, as if

you're in constant empathic and telepathic contact with

that character. (No roll necessary.) If the phylactery is a

place, then you retain an awareness of that place, and

can check in with it by using Perception + Awareness,

difficulty 6. (For very large areas, the check-in difficulty

may range from 7 to 10.) With the addition of the Merit: “Immortal” at the

seven-point level, your physical body may continue

to survive until the phylactery is destroyed… which, if

you don't mind going without your magick for a while,

could render you more or less immune to death if

you then hide your phylactery away in a safe location.

Traditionally speaking, that's why many mages make

phylacteries in the first place: to preserve their mortal

lives indefinitely. So long as your phylactery remains safe and undamaged,

you remain immune to Gilgul and other soul-trapping

attacks. Your body may be possessed, but your soul

cannot be stolen or destroyed unless someone attacks

your phylactery instead… in which case you're screwed,

as described below. For details about Gilgul, see that

entry in Chapter Four, pp. 218-220. And if you invest your soul into a place, you literally carry

the essence of that place within yourself, while a part of

you always remains there. For practitioners of certain an-

cestral forms of magic (or simply for hardcore romantics),

that's a very powerful reason to do such a thing.

Those are the good points. The downsides are as follows: If the phylactery gets destroyed, your ability to use magick

in this life gets destroyed along with it. You cannot perform magick or recharge your Avatar

unless you have some form of physical connection to

your phylactery. That form could involve a physical

gateway to virtual contact, as with a computer that

accesses a mainframe, but you still need that gateway

in order to reach a distant phylactery. (Yes, you may use

Correspondence Sphere magick to reach the phylactery,

and you are always counted as being one success away

from your phylactery when you use Correspondence to

reach out to it.) If your phylactery is a place, you must be in that place

in order to employ the Spheres. If it's a living thing,

then that character has got to be within touching range

before you can use the Spheres. (Explains a lot about

Blofeld and his cat, doesn't it?) If you're using your phylactery to cast magick, you need

to be rather obvious about it – shouting commands to

your hypertech robot pal, holding your mystic crown aloft,

hewing your demonic sword through enemies as you shout

invocations to your patron god, that sort of thing. If your Avatar communicates to you through an embod-

ied phylactery character, then you need to purchase the

Merit: Manifest Avatar (p. 71) to represent the Avatar's

physical form.]==],
				},
				["Plague of Demons"] = {
					en = [==[Lore of the Bloodlines, p. 16


Plague of Demons


No matter what, demons are constantly drawn to the Baali. Once in a while, this can be a benefit (Baali with this Flaw are at -1 difficult to summon a particular demon), but most of the time these nefarious spirits are distractions. They scream in the Baali's ear, tug at her clothes, or screw with her possessions… and always at the worst possible moment. The character is at +1 difficulty for any rolls involving Perception. Further, once per session, the Storyteller can convert one of the Baali's dice rolls into a botch.]==],
				},
				["Prey Exclusion"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Prey Exclusion


You refuse to hunt a certain class of prey. You might refuse to feed on drug dealers, policemen, accountants, or rich people — if you accidentally feed upon such an individual, you automatically frenzy and must make a roll to prevent Humanity or Path loss (difficulty 7). Witnessing other Kindred feeding on the object of your exclusion might also provoke a frenzy, at the Sto- ryteller's discretion. Ventrue, owing to the limitations already imposed on their feeding by their Clan weak- ness, may not take this Flaw.]==],
				},
				["Primal Marks"] = {
					en = [==[Book of Secrets, p. 90


Primal Marks


You've been marked by some god, spirit, myth, or other metaphysical entity… and the mark is not a pleasant one. Maybe you share Papa Ghede's nasal voice and crude sense of humor, or Coyote's grotesquely huge cock, or Christ's bleeding stigmata. Essentially, this Flaw is the flipside of the Merit: Mark of Favor; in your case, though, the mark complicates your life, twists your body, and alerts people who understand the significance of that mark. In certain circles – say, being marked by Satan while living in a deeply religious region – a Primal Mark can be a life-threatening affair. Such marks can also indicate the profound displeasure of the entity in question, like the Mark of Cain (in a non-vampiric sense, anyway) which set the First Murderer apart while sparing his life for a long-enduring punishment. But even if the entity in question likes you, this particular mark is more of a burden than a blessing. If, for instance, you stink like a goat and have 90 The Book of Secrets the heavy, hairy features of Pan, that's not going to make you terribly popular with the ladies… especially not if you're female to begin with!

This disconcerting legacy might come through as animal- istic features that reveal your connection to a totem spirit, as described in the Totem Background entry and the appropriate section of Mage 20's Appendix I. (See pp. 326-328 and 633- 636.) Or the “mark” might involve some physical manifestation of your inner Avatar. You could share the archetypal “look” of a notorious family, like the Borgias or Romanovs, even if you're not actually related to that bloodline; or bear an uncanny resem- blance to some sinister beast even if you're not a shapechanger or totem-friend. Maybe you just look like what people think of when they say wizard, shaman, or witch – which, in many cultures, can be rather unhealthy for people so identified. In short, you look weird in the literal, uncanny meaning of that phrase, and people notice.

Obviously, you should define the appearance of this feature, and decide the sort of reaction people have when they notice it. Because this is a Flaw, of course, that reaction should be negative in some way – the “primal mark of the Jolie-Pitt Clan” is not exactly a Flaw unless you're dealing with paparazzi. The “mark” could also be a tone of voice, a distinct way of moving (birdlike, catlike, Papa Legba-like), or a certain vibe that nearly anyone can sense. Whatever their source and manifestation, these Primal Marks are obvious, and they tend to carry over even when a mage changes shape. People recognize you even when you'd rather not be recognized, and that sort of distinction can be rather unhealthy too.

This Flaw goes well with Backgrounds like Blessing, Destiny, Legend, Past Lives, and, as suggested earlier, Totem. It could be taken as a genetic Flaw for Enhancements, or as a reflection of an especially potent Avatar. For extra fun, you might not even know why you've been so marked, who marked you, or what may come as a result of the mark. As with so many elements of a mage's life, these Primal Marks could be mysteries whose answers lay at the end of a long and winding Path… if, indeed, those answers ever reveal themselves at all.]==],
				},
				["Privacy Obsession"] = {
					en = [==[Lore of the Clans, p. 239


Privacy Obsession


Perhaps it is a trait carried in the blood. Perhaps your strict sire carved this lesson into your mind and flesh. Either way, you carry the Tzimisce respect for privacy to extremes. You must make a Willpower roll (difficulty 6) to enter another being's dwelling without being invited, though you can go to fiendishly clever lengths to garner an unwitting invitation. When disturbed in your haven by an uninvited guest, you must make a Self-Control or Instincts roll (difficulty 7) to avoid frenzy.]==],
				},
				["Private Life"] = {
					en = [==[Lore of the Clans, p. 200


Private Life


You have a completely separate life that no other Kindred know about. It may be your mortal family that you have turned into ghouls, or a YouTube channel that you use to talk in metaphor about your frustrations with Kindred society. If discovered, this could risk other vampires accusing you of breaching the Masquerade (if Camarilla), consorting with humanity instead of being a superior vampire (if Sabbat), or just overall paranoia and suspicion on why you're keeping such deep secrets.]==],
				},
				["Probationary Member"] = {
					en = [==[Book of Secrets, p. 68


Probationary Member


Having recently defected from a rival group or faction, you're on probation with the current group. Peers expect you to turn on them, and certain folks have probably decided to throw you under the bus on general principle. Your continued membership (possibly even your survival) depends upon doing everything right and nothing wrong… and just how often do things really go that well in the real world, anyway?]==],
				},
				["Probationary Sect Member"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Probationary Sect Member


You are a defector. You turned traitor to the Cama- rilla, Sabbat, or other Sect, and you still have much to prove before you are accepted by the Kindred you have defected to. Other vampires treat you with distrust and even hostility, and your reputation might even sully those whom you regularly associate with.]==],
				},
				["Problem with Authority"] = {
					en = [==[Ghouls & Revenants, p. 133


Problem with Authority


Problem with Authority is unhealthy for ghouls or revenants who are expected to serve without question. It is especially problematic for ghouls who have violent or unpredictable masters, and may spur a ghoul to leave her domitor's side. Many independent ghouls suffer from this Flaw, and continue to feel the effects of their disobedience.

When taken to its extreme, your ghoul will become argumentative and unruly, and may take an issue with the simplest instructions. While you might argue with lesser authority figures in your ghoul's life, like the police, your combative words are less likely to get you killed, but may result in being arrested or fired.

Used by: All ghouls and revenants]==],
				},
				["Profiled Appearance"] = {
					en = [==[Book of Secrets, p. 41


Profiled Appearance


You look like one of those people… y'know, the people that “respectable citizens” expect bad things from. Depending on the setting of your chronicle, this could involve physical mannerisms, body art, gender distinctions, individual features, ethnic heritage, cybernetic modifications, or other elements of your physical body that you cannot remove and probably don't want to “fix” anyhow. Problem is, the people around you are constantly watching your every move, making trouble for you when they can get away with it, and otherwise causing you grief. The authorities shake you down on principle, and most folks won't object to whatever they choose to do to you.

Although it's related to the Social Flaw: Cultural Other (below), Profiled Appearance is based on your character's physical features, not on their social behavior. Although it can be concealed to some degree, your Profiled Appearance is not something that can be removed without magick, and it reflects an essential part of your identity. Like Impediment, it does not carry a value judgment in the game even though it represents the way other characters will view you. If this feels unfair in the game, imagine how it must feel in real life.]==],
				},
				["Prone to Quiet (4)"] = {
					en = [==[Book of Secrets, p. 91


Prone to Quiet (4)


In an effort to avert the inevitable stresses of Awakened life, you tend to drop into metaphysical Quiets (as per Mage 20, pp. 554-561) more easily than most other mages do. The easier you fall into them, the more this Flaw is worth: (4 points) Quiet is your default Paradox backlash, and

so a backlash of five points or more automatically sends

you into Quiet. (5 points) Quiet is your default backlash, and you

can fall into it even without a Paradox discharge.

Roll your Intelligence + Enigmas dice pool when

you're faced with an unusually stressful situation;

if you succeed, then you're able to puzzle your way

out of the fall – and if not, well, then, welcome back

to Quietville… (The roll's difficulty ranges from 6

to 10, depending upon the severity of the stress and

whether or not you've dealt with this particular kind

of stress before.)

Although it's most often noticed in Virtual Adepts and other Netizens, who tend to set off into the Digital Web in order to escape physical unpleasantness, any mage can suffer from this Flaw.]==],
				},
				["Prone to Quiet (5)"] = {
					en = [==[Book of Secrets, p. 91


Prone to Quiet (5)


In an effort to avert the inevitable stresses of Awakened life, you tend to drop into metaphysical Quiets (as per Mage 20, pp. 554-561) more easily than most other mages do. The easier you fall into them, the more this Flaw is worth: (4 points) Quiet is your default Paradox backlash, and

so a backlash of five points or more automatically sends

you into Quiet. (5 points) Quiet is your default backlash, and you

can fall into it even without a Paradox discharge.

Roll your Intelligence + Enigmas dice pool when

you're faced with an unusually stressful situation;

if you succeed, then you're able to puzzle your way

out of the fall – and if not, well, then, welcome back

to Quietville… (The roll's difficulty ranges from 6

to 10, depending upon the severity of the stress and

whether or not you've dealt with this particular kind

of stress before.)

Although it's most often noticed in Virtual Adepts and other Netizens, who tend to set off into the Digital Web in order to escape physical unpleasantness, any mage can suffer from this Flaw.]==],
				},
				["Psi Focus (3)"] = {
					en = [==[M20 Sorcerer, p. 108


Psi Focus (3)


Your psychic power requires something beyond your own mental powers to manifest, whether you need your lucky feather, to ask pretty please, or just pantomime the action you need to happen. For a 3-point Flaw, you have to gesture or speak an incantation for the power to work. For a 4-point Flaw, you require a physical focus to work such as crystals, tarot cards, or candles. For a 5-point Flaw, the power only works with a specific focus, akin to a mage's unique instrument (Mage 20 p. 588). The 5-point version of this Flaw is also available to hedge wizards.]==],
				},
				["Psi Focus (4)"] = {
					en = [==[M20 Sorcerer, p. 108


Psi Focus (4)


Your psychic power requires something beyond your own mental powers to manifest, whether you need your lucky feather, to ask pretty please, or just pantomime the action you need to happen. For a 3-point Flaw, you have to gesture or speak an incantation for the power to work. For a 4-point Flaw, you require a physical focus to work such as crystals, tarot cards, or candles. For a 5-point Flaw, the power only works with a specific focus, akin to a mage's unique instrument (Mage 20 p. 588). The 5-point version of this Flaw is also available to hedge wizards.]==],
				},
				["Psi Focus (5)"] = {
					en = [==[M20 Sorcerer, p. 108


Psi Focus (5)


Your psychic power requires something beyond your own mental powers to manifest, whether you need your lucky feather, to ask pretty please, or just pantomime the action you need to happen. For a 3-point Flaw, you have to gesture or speak an incantation for the power to work. For a 4-point Flaw, you require a physical focus to work such as crystals, tarot cards, or candles. For a 5-point Flaw, the power only works with a specific focus, akin to a mage's unique instrument (Mage 20 p. 588). The 5-point version of this Flaw is also available to hedge wizards.]==],
				},
				["Psychic Vampire"] = {
					en = [==[Book of Secrets, p. 93


Psychic Vampire


Also known as the Reaper's Touch, this dreadful curse makes you a life-force siphon. Your presence consumes vitality from your surroundings and the living things who happen to get too close to you. Unless you do so, however, your own life- force withers. Despite your best intentions, you're essentially a walking void into which life itself pours in order to sustain your own existence.

Story-wise, you're a drain on the energy of your compan- ions. Insects and small plants perish in your presence, while children and animals smaller than a horse feel ill when you stand near them. System-wise, any character who's in physical contact with you for an hour or more loses one health level per hour to bashing damage. If you're unable to soak up someone else's life-force, though, then your own vitality drains away. In system terms, you lose health levels in the reverse order that you would heal lethal damage, dropping to Bruised after one day, to Hurt after three days, to Injured after one week, and so on. (For details, see Mage 20, p. 406.)

If you employ Life Sphere magicks, your difficulties for healing or improvement-type Effects are raised by +2, while your difficulties with corrupting, damage, or illness-related Effects are lowered by -2. (In both cases, the usual maximums and minimums still apply.) Each health level you inflict on someone else with Life Sphere magick heals you of one health level if you're injured, or else forestalls the “starvation” loss of your own health levels by one day per health level inflicted.

An inversion of the Merit: Spark of Life (p. 78), this Flaw darkens your aura, makes your blood taste awful as far as vampires are concerned, and keeps your close associates constantly sick with low-level ailments. Life-affirming mages consider this to be a mark of profound misfortune or outright evil, while folks who love corruption (Nephandi and the like) see you as a ripe candidate for recruitment. Mundane science can't do a damn thing about this metaphysical malady, and dismisses such fluffy concepts as “life-force energies.” The Technocratic Union, on the other hand, takes this sort of thing seriously, and tends to view psychic vampires as Reality Deviants of the most unfortunate kind.

For a potentially related metaphysical application of this Flaw, see the Chapter Three Expanded Instruments entry Cannibalism, pp. 206-207.]==],
				},
				["PTSD (2)"] = {
					en = [==[Book of Secrets, p. 50


PTSD (2)


See Mage 20, p. 647-648.]==],
				},
				["PTSD (3)"] = {
					en = [==[Book of Secrets, p. 50


PTSD (3)


See Mage 20, p. 647-648.]==],
				},
