				},
				["PTSD (5)"] = {
					en = [==[Book of Secrets, p. 50


PTSD (5)


See Mage 20, p. 647-648.]==],
				},
				["Putrescent"] = {
					en = [==[Lore of the Clans, p. 163


Putrescent


The supernatural process that usually keeps a vampire's form from rotting after death has failed to work on you. Your body has become putrescent and fragile as it gradually decays. All soak rolls you make have their dice pool reduced by 1. You may even lose body parts if you suffer a solid enough blow. Should this happen, make a Stamina roll (difficulty 6) and lose a part of your body (Storyteller's choice) if you fail. Should you botch, you also receive a level of aggravated damage. These missing parts may regrow, but your body continues to rot.]==],
				},
				["Ragged Bite"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 421


Ragged Bite


Unlike your Cainite peers,

you lack the ability to neatly seal up the wound caused

by feeding. Instead, you leave torn, bleeding marks which

have a chance of becoming infected. Your target must

make a Stamina roll (difficulty the number of damage

caused + 5) to resist infection. The impact of such a no-

table wound in conjunction with a diseased target is left

to the discretion of the Storyteller. At the very least, this

poses complications in hiding your identity as anything

other than a monster.]==],
				},
				["Rat in a Cage"] = {
					en = [==[Lore of the Clans, p. 87


Rat in a Cage


Anytime you are penned in or physically restrained (such as by a cage, or with handcuffs), you suffer acute anxiety. The difficulties of any rolls made under such circumstances are increased by two.]==],
				},
				["Rebel (1)"] = {
					en = [==[The Hunters Hunted II, p. 123


Rebel (1)


You have acquired some infamy in the Society of Leopold. At the one-point version of this Flaw, you might simply be scorned by your betters, who wait for you to slip up. At the two-point version, you are actively loathed and can expect little help. At the three-point version, there are Inquisitors who hate you as much as the supernaturals. You should work with the Storyteller to come up with the specific reason for this ill repute. Bear in mind, your reputation is relative among the divisions within the Inquisition. Some sects may embrace you just to spite their rivals. For example, while you might earn the ire of the Society at large by studying the sorcerous arts too closely, you might find acceptance, and even encouragement, from the Brethren of Albertus. Supernatural]==],
				},
				["Rebel (2)"] = {
					en = [==[The Hunters Hunted II, p. 123


Rebel (2)


You have acquired some infamy in the Society of Leopold. At the one-point version of this Flaw, you might simply be scorned by your betters, who wait for you to slip up. At the two-point version, you are actively loathed and can expect little help. At the three-point version, there are Inquisitors who hate you as much as the supernaturals. You should work with the Storyteller to come up with the specific reason for this ill repute. Bear in mind, your reputation is relative among the divisions within the Inquisition. Some sects may embrace you just to spite their rivals. For example, while you might earn the ire of the Society at large by studying the sorcerous arts too closely, you might find acceptance, and even encouragement, from the Brethren of Albertus. Supernatural]==],
				},
				["Rebel (3)"] = {
					en = [==[The Hunters Hunted II, p. 123


Rebel (3)


You have acquired some infamy in the Society of Leopold. At the one-point version of this Flaw, you might simply be scorned by your betters, who wait for you to slip up. At the two-point version, you are actively loathed and can expect little help. At the three-point version, there are Inquisitors who hate you as much as the supernaturals. You should work with the Storyteller to come up with the specific reason for this ill repute. Bear in mind, your reputation is relative among the divisions within the Inquisition. Some sects may embrace you just to spite their rivals. For example, while you might earn the ire of the Society at large by studying the sorcerous arts too closely, you might find acceptance, and even encouragement, from the Brethren of Albertus. Supernatural]==],
				},
				["Recruitment Target"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Recruitment Target


Someone in one of your Sect's enemy organizations wants you, and they want you bad. Every effort is being made to recruit you, willing or no, and the press gangs usually show up at the worst possible time.]==],
				},
				["Red List"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Red List


You are either being considered for or are already on the dreaded Red List, the registry of those vampires the Camarilla most wants extinguished. Any Camarilla vampire will either attack you on sight or, more likely, call in for a great deal of help. Supernatural]==],
				},
				["Refined Palate (1)"] = {
					en = [==[Lore of the Bloodlines, p. 60


Refined Palate (1)


Many Kiasyd self-impose feeding restrictions: refusing to feed from the poor and diseased, or even those still wearing skin, or over a certain age. This manifests akin to the Ventrue Clan weakness (V20, p. 73), due to conditioning making any blood outside of the Kiasyd's preference unpalatable. The severity of the Flaw depends on how narrow the restriction is.]==],
				},
				["Refined Palate (2)"] = {
					en = [==[Lore of the Bloodlines, p. 60


Refined Palate (2)


Many Kiasyd self-impose feeding restrictions: refusing to feed from the poor and diseased, or even those still wearing skin, or over a certain age. This manifests akin to the Ventrue Clan weakness (V20, p. 73), due to conditioning making any blood outside of the Kiasyd's preference unpalatable. The severity of the Flaw depends on how narrow the restriction is.]==],
				},
				["Refined Palate (3)"] = {
					en = [==[Lore of the Bloodlines, p. 60


Refined Palate (3)


Many Kiasyd self-impose feeding restrictions: refusing to feed from the poor and diseased, or even those still wearing skin, or over a certain age. This manifests akin to the Ventrue Clan weakness (V20, p. 73), due to conditioning making any blood outside of the Kiasyd's preference unpalatable. The severity of the Flaw depends on how narrow the restriction is.]==],
				},
				["Religious Hysteria"] = {
					en = [==[The Hunters Hunted II, p. 123


Religious Hysteria


Angels and demons are everywhere! You see them. You note the signs of the Divine plan in every nuance of life. The entire world's an omen! The Holy Ghost whispers in your ear constantly. Why do others not understand? Even your brothers and sisters in the faith shake their heads as you breathlessly elucidate your latest holy vision. The difference between this Flaw and the Ecstatic Merit (see below) is that people do not take you seriously. Your visions occur a bit too often, are a bit too untenable. Subtract one die from all Social dice pools. Social]==],
				},
				["Repelled by Crosses"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 495


Repelled by Crosses


You are repelled by the sight of ordinary crosses, believing them to be symbols of holy might. When confronted by a cross, you must make a Willpower roll VAMPIRE THE MASQUERADE 20th ANNIVERSARY EDITION (difficulty 9) or flee from the symbol for the duration of the scene. If you botch the roll, not only must you attempt to flee, but the touch of the cross can cause ag- gravated damage (one health level of damage per turn that the cross touches your skin). This damage cannot be soaked, even if the vampire possesses Fortitude.]==],
				},
				["Repulsed by Garlic"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Repulsed by Garlic


You cannot abide garlic, and the smallest whiff of its scent will drive you from a room unless you make a suc- cessful Willpower roll (difficulty based on the strength of the odor).]==],
				},
				["Repulsive Feature"] = {
					en = [==[Book of Secrets, p. 40


Repulsive Feature


Some physical feature of yours turns people away. Maybe you smell bad regardless of your state of hygiene, possess the proverbial “evil eye,” have an especially grating voice, suffer from a pervasive skin condition, or have a similarly repugnant physical characteristic. Perhaps the mere presence of you makes people's skins crawl even though there's nothing discernibly ugly about you. In any case, this feature discourages folks from sticking around much.

Essentially the inverse of the Merit: Enchanting Feature, this Flaw represents a concealable yet disconcerting element of your physical presence. Unlike Impediment, this Feature affects the way people regard you, not the way your body functions. That said, you could take both Flaws together, in order to reflect a physically debilitating condition that has socially awkward effects as well. The feature in question doesn't represent overall ugliness, as per Monstrous and Horrific, below; instead, it manifests as a single unpleasant physical distinction.

System-wise, this Flaw adds a +2 difficulty modifier to Social-Trait rolls whenever this feature comes into play. Sto- ry-wise, this Flaw renders you physically distinctive unless you make an effort to hide the Repulsive Feature. If you change shape, that feature carries over into your other forms, which interferes with disguise attempts. If the feature transcends visual senses (like, for example, an unpleasant odor or grating voice), it might betray your presence even if you can't be seen. In both cases, this Flaw penalizes your rolls for physical concealment the same way it penalizes your social interactions.

As some consolation, the feature could be used to deliber- ately frighten or irritate people; in that case, the usual penalty becomes a -2 to your difficulty instead. A Repulsive Feature that has been integrated into your magickal focus (again, for instance, the “evil eye”) offers the same instrumental benefits described under Enchanting Feature, with the same potential for mutilation and a greater incentive for someone to mess you up!]==],
				},
				["Repulsive to Animals"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Repulsive to Animals


When you are near, natural animals startle and panic. Unlike the normal dis- turbance caused by the presence of Cainites, animals near you either bolt in terror or become aggressive and violent, depending on their temperament. This makes riding a horse (or any other riding beast) nearly impossible, as you are un- able to calm any creature down with a normal Animal Ken roll. You must use the abilities of the Animalism Discipline or feed the animal some of your blood, which transforms it into a ghoul.

Permanent Third Eye (2 or 4 points; Salubri and Tremere only): While others descended from the blood of Saulot are able to conceal their third eye, yours remains permanently open on your forehead. For 2 points, it is mechanically treated as any normal third eye, though narratively may draw strange looks and unwanted atten- tion. For 4 points, the eye is permanently open and may only be closed for a scene on a successful Willpower roll.]==],
				},
				["Revenant Weakness"] = {
					en = [==[Lore of the Clans, p. 239


Revenant Weakness


You were once part of a revenant family. Following the Embrace, you suffered both your Clan's weakness and your revenant family's limitation (V20, pp. 503-506). The Storyteller might let you manifest a weakness from a lost or destroyed revenant line. This could add mystery to your background and allow for a bit of genealogical detective work, certainly making you a curiosity to the Romanian Legacy Foundation.]==],
				},
				["Ritual Sleeper"] = {
					en = [==[M20 Sorcerer, p. 108


Ritual Sleeper


Magic doesn't happen at the snap of a finger. You are unable to manifest any instant magical effects, and you are limited to performing rituals. If the rules of your Affiliation already require magic through only ritual, you may not take this Flaw. You're considered a Sleeper if you witness an instant magical effect.]==],
				},
				["Rival House (1)"] = {
					en = [==[Book of Secrets, p. 63


Rival House (1)


You belong to a Chantry (or Construct, or whatever) that has a longstanding animosity with another such organization. This could be a rival Hermetic Chantry, a temple whose members consider you to be heretics, a hostile street gang, an opposing martial arts order, a coven that has declared a witch- war against your group, a Construct that has marked you all for death, and so on. This antagonism is mutual, too, and you're expected to act accordingly. Mediation remains unlikely, and things could get worse before they get better… if improved relations are even possible.

Obviously, such hostility is personal, with deep roots in the backstory of your chronicle and its characters. Groups of mages don't generally pursue mass grudges without serious reasons to do so! The Flaw's value depends upon the power of that other stronghold and the level to which they hate members of your own. (1 point) A minor rivalry with an associated Chantry of

equal or lesser power in relation to your own. For the

most part, the antagonism involves pranks, competition,

minor sabotage, and occasional “friendly” brawls. (2 points) A significant rivalry (serious fights and slanders,

major sabotage) with a Chantry of similar power, or a

minor rivalry with a Chantry so powerful they don't

consider yours to be a true threat. (3 points) Deadly antagonism between roughly equal

Chantries. (4 points) A significant rivalry between your Chantry

and one that's powerful enough to inflict serious damage

upon your own. (5 points) Deadly hatred from a Chantry that could level

yours if they really wanted to… and they probably do.

From the three-point version onward, it's pretty unlikely that the rivalry can be resolved without a shared enemy or some significant interference from an even more powerful third party. It might not be resolvable even then. This Flaw requires the Background: Chantry /Construct, but any character with such associations can take it – the Flaw is not restricted to mages from the Traditions and Technocracy. Your rivalry might cross factions, too; a Hermetic House might hold a longstanding enmity with a Progenitor lab. It can also exist within a single group (two rival Etherite collectives), or between two related groups that do not belong to the same faction; alchemist sects, for example, have been arguing over the name Solificati for centuries, with no end in sight!]==],
				},
				["Rival House (2)"] = {
					en = [==[Book of Secrets, p. 63


Rival House (2)


You belong to a Chantry (or Construct, or whatever) that has a longstanding animosity with another such organization. This could be a rival Hermetic Chantry, a temple whose members consider you to be heretics, a hostile street gang, an opposing martial arts order, a coven that has declared a witch- war against your group, a Construct that has marked you all for death, and so on. This antagonism is mutual, too, and you're expected to act accordingly. Mediation remains unlikely, and things could get worse before they get better… if improved relations are even possible.

Obviously, such hostility is personal, with deep roots in the backstory of your chronicle and its characters. Groups of mages don't generally pursue mass grudges without serious reasons to do so! The Flaw's value depends upon the power of that other stronghold and the level to which they hate members of your own. (1 point) A minor rivalry with an associated Chantry of

equal or lesser power in relation to your own. For the

most part, the antagonism involves pranks, competition,

minor sabotage, and occasional “friendly” brawls. (2 points) A significant rivalry (serious fights and slanders,

major sabotage) with a Chantry of similar power, or a

minor rivalry with a Chantry so powerful they don't

consider yours to be a true threat. (3 points) Deadly antagonism between roughly equal

Chantries. (4 points) A significant rivalry between your Chantry

and one that's powerful enough to inflict serious damage

upon your own. (5 points) Deadly hatred from a Chantry that could level

yours if they really wanted to… and they probably do.

From the three-point version onward, it's pretty unlikely that the rivalry can be resolved without a shared enemy or some significant interference from an even more powerful third party. It might not be resolvable even then. This Flaw requires the Background: Chantry /Construct, but any character with such associations can take it – the Flaw is not restricted to mages from the Traditions and Technocracy. Your rivalry might cross factions, too; a Hermetic House might hold a longstanding enmity with a Progenitor lab. It can also exist within a single group (two rival Etherite collectives), or between two related groups that do not belong to the same faction; alchemist sects, for example, have been arguing over the name Solificati for centuries, with no end in sight!]==],
				},
				["Rival House (3)"] = {
					en = [==[Book of Secrets, p. 63


Rival House (3)


You belong to a Chantry (or Construct, or whatever) that has a longstanding animosity with another such organization. This could be a rival Hermetic Chantry, a temple whose members consider you to be heretics, a hostile street gang, an opposing martial arts order, a coven that has declared a witch- war against your group, a Construct that has marked you all for death, and so on. This antagonism is mutual, too, and you're expected to act accordingly. Mediation remains unlikely, and things could get worse before they get better… if improved relations are even possible.

