				},
				["Rival Sires"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 491


Rival Sires


The flip side of Escaped Target, two vampires want- ed to gift you with the Embrace. One succeeded, one failed — and she's not happy about that failure. You, VAMPIRE THE MASQUERADE 20th ANNIVERSARY EDITION 491 your actual sire, or both of you have become the target of the failed suitor's ire. Regardless, your persecutor is at +2 difficulty to refrain from frenzy in your presence. In addition, she may well be working actively to dis- credit or destroy you.]==],
				},
				["Rivalry (1)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 424


Rivalry (1)


Someone hates you so much that they cannot bear to leave you alone. The scale of this Flaw is similar to that of the Enemy Flaw (see above), but your Rival is not interested in seeing you dead. Rather, a Rival desires only to make your unlife as troublesome and hellish as possible. At lower point value, the Rival may also be a friend who arrives at precisely the worst moment to steal your thunder or make you embarrassed. At higher levels, your Rival loses sleep planning how to make your life miserable.]==],
				},
				["Rivalry (2)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 424


Rivalry (2)


Someone hates you so much that they cannot bear to leave you alone. The scale of this Flaw is similar to that of the Enemy Flaw (see above), but your Rival is not interested in seeing you dead. Rather, a Rival desires only to make your unlife as troublesome and hellish as possible. At lower point value, the Rival may also be a friend who arrives at precisely the worst moment to steal your thunder or make you embarrassed. At higher levels, your Rival loses sleep planning how to make your life miserable.]==],
