				},
				["Rivalry (5)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 424


Rivalry (5)


Someone hates you so much that they cannot bear to leave you alone. The scale of this Flaw is similar to that of the Enemy Flaw (see above), but your Rival is not interested in seeing you dead. Rather, a Rival desires only to make your unlife as troublesome and hellish as possible. At lower point value, the Rival may also be a friend who arrives at precisely the worst moment to steal your thunder or make you embarrassed. At higher levels, your Rival loses sleep planning how to make your life miserable.]==],
				},
				["Rogue"] = {
					en = [==[Book of Secrets, p. 68


Rogue


The loosest of cannons, you're gonna do whatever you damn well please, and to hell with any and all consequences! You might still belong to a group, but your membership is more a matter of habit or convenience than of loyalty. Alternately, you may have gone your way and now exist in a nebulous state between fondly remembered comrade and total outlaw. Certain Backgrounds (Requisitions and Secret Weapon) are forbidden to you now, and others (Allies, Backup, Chantry, Resources, and potentially many more) are hard to access – perhaps even impossible to access – if their connection to you depends upon your allegiance to a group. Former peers consider you a liability, and the main reason no one has taken you out yet is because nobody's gotten around to doing so successfully.

For Technocratic operatives, this Flaw is a slow-motion death sentence; for other mages, it could involve similar threats to longevity, although many Crafts (aside from the Templars, Wu Lung, and Hippolytoi) and most Traditions (aside from the Chakravanti, Akashayana, and Order of Hermes) take a more liberal approach to rogue members. Either way, your relationships with former allies are strained at best (+3 to the difficulty of most social rolls involving their goodwill), and you're on rather hostile terms with your so-called (or former) superiors. Some mages manage to live for quite a while in this state of mutual antagonism. Most, however, do not.]==],
				},
				["Romantic Notions"] = {
					en = [==[Ghouls & Revenants, p. 138


Romantic Notions


You believe your entire existence as a ghoul is a marked improvement over your previous life, and you are convinced you owe it all to your domitor. You feel your domitor needs you, you'd die without her, and that every feeding is an act of pure love.

When your domitor attempts to use either Dominate or Presence on your character, your Willpower is at 2. This Flaw is in effect regardless of how you react to the blood bond, and while under its influence you may feel an even stronger sense of artificial love toward your domitor.

This Flaw does not affect revenants, who were born with their condition, in the same way as it does ghouls. At the Storyteller's discretion, only a revenant who feels romantically inclined toward a specific vampire who has the use of Dominate and Presence may take this Flaw. Independent ghouls may not purchase this Flaw, as it does not make sense narratively for them to be romantically inclined toward a specific vampire.

Used by: All ghouls, except for independent ghouls, and revenants in rare cases.]==],
				},
				["Rose-Colored Glasses"] = {
					en = [==[Book of Secrets, p. 50


Rose-Colored Glasses


Known sardonically as Rose-Colored Mirrorshades among Technocracy operatives, this Flaw reflects a rather delusional loyalty to your faction of choice. Essentially, your team can do no wrong as far as you're concerned. Their cause is just, their paradigm unshakable, their deeds necessary under the circumstances, no matter how extreme those deeds might be. Your character views almost anything the group does in its most favorable light… which, considering how awful Awakened groups can be, means that you're choosing to overlook a great deal. Confronted with inconvenient truths, you can get downright irrational, abusive, or even fanatical. If you're ever confronted with truths you cannot deny, avoid, or slander away, the shock could devastate you for years to come – very possibly driving you into the arms of a diametrically opposed faction for which you'll hold a similar sort of loyalty. (See Changing Focus and Allegiance in Mage 20, p. 339.)]==],
				},
				["Rotten Liar"] = {
					en = [==[Book of Secrets, p. 66


Rotten Liar


Man, you suck at lying! You could not tell a credible un- truth if your life depended on it… which it might, so this can be sort of a problem for you. It may be that you're just too honest for your own good, or cursed to speak the truth as you know it, regardless of the cost or your intentions; then again, you might just stammer your way through attempted deceptions, telegraphing your lies through body language and vocal tone. Whatever the reason, add +2 to the difficulty of any die roll you make when you're trying to deceive another character. Yes, this penalty extends to magickal deceptions too, like illusions or mind control. Honesty might not always be the best policy among the Awakened, but for you it's generally the best option.]==],
				},
				["Scales (1)"] = {
					en = [==[Lore of the Clans, p. 67


Scales (1)


Set blessed you upon your Embrace, and you bear his mark. A portion of your skin is covered in scales. As a one-point Flaw, a small, easily hidden area of skin is covered. As a two-point Flaw, a whole limb is covered, while having a scaled, lipless LORE OF THE CLANS face is a three-point Flaw. Kine are frightened and disturbed by the obviously unnatural scales, and Kindred have their own prejudices against the Setites. All social rolls receive a +2 difficulty when the scales are visible. This penalty does not apply to social interactions with other Setites.]==],
				},
				["Scales (2)"] = {
					en = [==[Lore of the Clans, p. 67


Scales (2)


Set blessed you upon your Embrace, and you bear his mark. A portion of your skin is covered in scales. As a one-point Flaw, a small, easily hidden area of skin is covered. As a two-point Flaw, a whole limb is covered, while having a scaled, lipless LORE OF THE CLANS face is a three-point Flaw. Kine are frightened and disturbed by the obviously unnatural scales, and Kindred have their own prejudices against the Setites. All social rolls receive a +2 difficulty when the scales are visible. This penalty does not apply to social interactions with other Setites.]==],
				},
				["Scales (3)"] = {
					en = [==[Lore of the Clans, p. 67


Scales (3)


Set blessed you upon your Embrace, and you bear his mark. A portion of your skin is covered in scales. As a one-point Flaw, a small, easily hidden area of skin is covered. As a two-point Flaw, a whole limb is covered, while having a scaled, lipless LORE OF THE CLANS face is a three-point Flaw. Kine are frightened and disturbed by the obviously unnatural scales, and Kindred have their own prejudices against the Setites. All social rolls receive a +2 difficulty when the scales are visible. This penalty does not apply to social interactions with other Setites.]==],
				},
				["Sect Enmity"] = {
					en = [==[Book of Secrets, p. 64


Sect Enmity


Mage groups tend to have issues with each other by their very nature. You, however, have managed to piss off an entire sect of mages within your larger group. You could be a Verbena witch who hacked off the Hermetic House Flambeau (yipe), a Black Suit on the wrong side of the Friends of Courage, or a Red Spear who trash-talked the Ghost Wheel Society and lived to regret it. Although your enemies won't try to kill you – you are theoretically on the same side, after all – they really don't like your face, or much else about you.

Generally, the members of the sect in question will have as little to do with you as they can, and won't be terribly coop- erative if they must deal with you at all. Social dice rolls you make while dealing with members from this group add +2 to the difficulty. You cannot, obviously belong to this sect when you first take this Flaw, although you could conceivably smooth things over, buy off the Flaw, and join that group later. A player may buy this Flaw multiple times to reflect poor relationships with several different sects. Storytellers are advised to create several reoccurring characters from the rival sect, in order to give this Flaw some teeth. For a more severe version of this Flaw, see Hit List, below.]==],
				},
				["Seizures"] = {
					en = [==[Ghouls & Revenants, p. 136


Seizures


Seizures tend to occur during moments of duress, and few mortals have a more stressful or terrifying existence than ghouls. The affliction of the Seizures Flaw can also be more pronounced in revenant families whose members suffer from a limited genetic pool. Many types of seizures can be controlled or mitigated with medication following thorough medical tests or examinations. However, some ghouls and revenants aren't willing to risk their lives by seeking the advice of a doctor, and these Seizures are often not related to a diagnosed illness. This Flaw is a side effect of the many horrors ghouls and revenants witness over the course of their lives.

Seizures can potentially be disastrous, especially if they occur in the presence of a vampire or at an inopportune moment. Under any stressful circumstances related to combat, physical or verbal threats, or witnessing a terrifying, bloody sight the character with this Flaw will need to make a Frenzy roll. A success means a seizure was not triggered, and you've managed to regain control.

Failure indicates your body was not able to cope with the stress and something has happened. If you roll a critical failure, your character suffers a full-blown grand mal seizure. You will have fallen to the ground and will thrash uncontrollably for a number of minutes equal to the number of 1s rolled on the Frenzy check. Your actions may wind up getting yourself, or others, hurt as your finger might accidentally pull the trigger, or you may slip and fall. A less than critical failure may likely result in your character blacking out until the next round. Depending on the needs of your story, your ghoul may pass out and drop to the ground, your vision might turn black for a few seconds, or your arm might tremble and you cannot regain control.

Used by: All ghouls and revenants Supernatural]==],
				},
				["Self-Preservation"] = {
					en = [==[Ghouls & Revenants, p. 132


Self-Preservation


For whatever reason, your character refuses to carry out orders that you feel will threaten your safety and put your life at risk. For ghouls, the Self-Preservation Flaw defeats the purpose of serving a vampire. If you cannot defend your domitor, then your worth decreases considerably. However, a Bound ghoul who can refuse to carry out an order bears close watching. This Flaw is also one of the most common reasons why a ghoul leaves his master's service to operate as an independent.

Revenants who have a sense of Self-Preservation may feel the effects of this Flaw in a different way. Your loyalty to your family may be questioned, for you might sacrifice another family member or ally when the time is right. Should you, too, be subjected to the blood bond, your inability to fully “commit” to a vampire's orders may result in unforeseen consequences ranging from experimentation to further scrutiny.

Mechanically-speaking, any time your domitor or master gives you an order that threatens your life, your character gets a check against Willpower at +2 difficulty. If successful, your ghoul or revenant may refuse to carry out the order. Should you refuse to carry out such a command in front of your master, you may expect to be punished severely.

Clever ghouls and revenants will attempt to manipulate this Flaw to their advantage. They might attempt to carry out a life-threatening command while ensuring they do not come to harm, though this isn't always possible.

Used by: All ghouls and revenants]==],
				},
				["Shadow Scarred"] = {
					en = [==[Lore of the Bloodlines, p. 48


Shadow Scarred


Since escaping the Shadowlands, you've struggled to reacclimatize to the world of the living. You see ravenous Spectres in every shadow. You must roll your Courage (difficulty 7) or spend a point of Willpower whenever using Necromancy, as you fear the repercussions of touching the Underworld.]==],
				},
				["Shadow Walker"] = {
					en = [==[Lore of the Clans, p. 107


Shadow Walker


The Giovanni Clan is by its nature inexorably tied to the realm beyond the sudario. Giovanni suffering from this Flaw are so tied to the Shadowlands that even in the lands of the living they must interact with the world of the dead on a nightly basis. To shadow walkers, objects in the Underworld are as real as anything found in the physical world. Such vampires find that the ghosts of walls may impeded their flight, ghostly objects may strike them, and wraiths' powers work as if the Kindred were on the far side of the Shroud. This Flaw is similar to the Ash Path power Dead Hand (V20, p. 163), except that Shadow Walker is always on and it in no way allows the character possessing it to perceive beyond the Shroud.

The Storyteller may determine that certain Shadowlands topography interferes with you. Unless you have some ability to do so, you can't see into the Shadowlands, so you have to be careful in feeling your way about — essentially, a blind man subject to the Underworld landscape. At the Storyteller's discretion, immaterial walls or environmental effects may restrict you.]==],
				},
				["Short"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Short


You are well below average height — four and a half feet (1.5 meters) tall or less. You have difficulty reach- ing or manipulating objects designed for normal adult size, and your running speed is one-half that of an aver- age human.]==],
				},
				["Short Fuse"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Short Fuse


You are easily angered. Difficulties to avoid frenzy are two greater. Brujah vampires cannot take this Flaw, as they already suffer from a similar weakness.]==],
				},
				["Shy"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Shy


You are distinctly ill at ease when dealing with peo- ple and try to avoid social situations whenever possi- ble. Difficulties for all rolls involving social interaction with strangers are increased by two. If the character becomes the center of attention in a large group, dif- ficulties are increased by three.]==],
				},
				["Siege Mentality"] = {
					en = [==[The Hunters Hunted II, p. 132


Siege Mentality


The agency is your family and your only friends. You don't trust civilians and amateurs to do what you see as your job, and politicians and lawmakers just get in your agency's way. You'd trust other intelligence agencies if they'd just once prove that they could find their collective asses with a mirror and a flashlight.

Your attitude has a number of cascading effects. First, you're brash and domineering with “civilians,” whether that's an FBI agent talking with local police, or a CIA operative dealing with a private intelligence company. Subtract two dice from all Empathy and Investigation dice pools when dealing with amateurs in your field. Second, you're on edge around other members of the intelligence community, even though you're supposed to be on the same side. Add one to the difficulty of all social interaction rolls with them. Finally, if the law gets in the way of your duty, you won't think twice about breaking it. The Storyteller is encouraged to have your superiors rake you over the coals for your blatant disregard for procedure.]==],
				},
				["Sire's Resentment"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Sire's Resentment


Your sire dislikes you and wishes you ill. Given the smallest opportunity, she will actively seek to do you harm. Your sire's allies also work against you, and many elders may resent you.]==],
				},
				["Sleeping With the Enemy"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Sleeping With the Enemy


You have some sort of intimate connection with a member of an opposing Sect or inimical Clan. You may have a lover, a childe, a friend, or a contact working the other side of the fence, but regardless of politics you retain a friendly (or more than friendly) relation- ship with your putative foe. Your close ties to someone on the other side would be regarded as treason by your superiors within the Sect, and if you are discovered, the penalty will surely be death.]==],
				},
				["Slow Healing"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 483


Slow Healing


You have difficulty healing wounds. It requires two blood points to heal one health level of bashing or le- thal damage, and you heal one health level of aggra- vated damage every five days (plus the usual five blood points and Willpower expenditure).]==],
				},
				["Smell of the Grave"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Smell of the Grave


You exude an odor of dampness and newly turned earth, which no amount of scents or perfumes will cover. Mortals in your immediate presence become uncomfortable, so the difficulties of all Social rolls to affect mortals increase by one.]==],
				},
				["Soft-Hearted"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Soft-Hearted


You cannot stand to watch others suffer. You avoid any situation that involves causing someone physical or emotional pain, unless you make a Willpower roll (difficulty 8). You must have a Humanity rating of 7 or above to take this Flaw — vampires on Paths of En- lightenment can only take this Flaw with Storyteller approval.]==],
				},
				["Special Responsibility"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Special Responsibility


Shortly after your Embrace, you volunteered for some task in order to gain respect and approval from the vampires around you. Now, you wish you had nev- er opened your damn mouth! While you are not given any special credit for performing this duty, you would lose a lot of respect if you were to stop. The nature and the details of your duty should be worked out with the Storyteller in advance. Ideas can range from lend- ing money to other Kindred to acting as a messenger or possibly gathering victims for ritae (such as Blood Feasts).]==],
				},
				["Speech Impediment"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Speech Impediment


You have a stammer or other speech impediment that hampers verbal communication. The difficulties of all die rolls involving verbal communication are in- creased by two. This Flaw must be roleplayed when- ever possible.]==],
				},
				["Sphere Inept"] = {
					en = [==[Book of Secrets, p. 94


Sphere Inept


A particular element of Reality eludes you. No matter how devoted you might be to mastering its complexities, this field of magick remains a challenge. Essentially, this is the reverse of the Merit: Sphere Natural, described above; one Sphere costs 130% more (rounded up) to learn than the other Spheres cost. Rank Cost /Affinity Sphere Cost New Sphere 13 pts 2 11 /9 pts. 3 21 /19 pts. 4 32 /28 pts. 5 42 /37 pts.

Again, this Flaw can apply to only one Sphere (fortunately!), and comes through in your practice and backstory. Someone who's inept at understanding, say, Time will have a very wonky relationship with schedules and timing.]==],
				},
				["Squeamish (1)"] = {
					en = [==[Ghouls & Revenants, p. 130


Squeamish (1)


Your ghoul or revenant might talk a good game, but you've never been around real violence before. When you're confronted with the sight of blood, you probably won't respond well, and may faint, panic, or run away.

In situations that involve gunfire, bloody combat, or an aggressive use of Disciplines, roll Willpower (difficulty 7). If this roll fails, your character either freezes in place (if her Courage is higher than her Self-Control) or flees the area (if her Self-Control is higher than her Courage).

At your Storyteller's discretion, you may be forced to make a Willpower check once per relevant scene. Your character does not need to be directly involved in the fight; she may simply be a witness to a stabbing. When you accumulate five successes in a single session, no further rolls need be made for that night of game time. A gory show of violence might necessitate another roll, however, at your Storyteller's discretion.

Should you botch a Willpower check, your ghoul is so unnerved by the gruesomeness you've encountered you cannot act for the rest of that scene. Your ghoul is frozen from shock, and may soil herself or puke in response to your fear or revulsion.

Used by: All ghouls and revenants]==],
				},
				["Squeamish (3)"] = {
					en = [==[Ghouls & Revenants, p. 130


Squeamish (3)


Your ghoul or revenant might talk a good game, but you've never been around real violence before. When you're confronted with the sight of blood, you probably won't respond well, and may faint, panic, or run away.

