Used by: All ghouls and revenants]==],
				},
				["Stench"] = {
					en = [==[Lore of the Clans, p. 161


Stench


Most Nosferatu pick up a certain odor, but you stink so bad even your Clan-mates find you hard to be close to. Your presence is preceded by your stench, removing two die from all Stealth rolls.]==],
				},
				["Stereotype"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Stereotype


You buy heavily into all of the vampire stories you've read and heard. You wear a cape or body glitter, speak with an accent, and otherwise act in a cartoonish fash- ion. Such behavior is embarrassing in the extreme to other Kindred, who are likely to ostracize or mock you (+2 difficulty to Social rolls with other vampires who don't share your habits). You also stand out to hunters.]==],
				},
				["Stigmata (2)"] = {
					en = [==[Lore of the Clans, p. 142


Stigmata (2)


Oracles are often marked as messengers of the gods. Your markings come in the forms of phantom wounds that seep blood. The bleeding is slight but incessant, costing you an extra blood point every day just before you wake at dusk.

The 2-point version of this Flaw means wounds that can be easily hidden from prying eyes, such as on the hands or the side. You gain a +1 difficulty to all Social rolls when dealing with someone aware of your condition.

The 4-point version can't be easily hidden, like bleeding eyes. The Social penalty increases to +2, and one of your Attributes also gains a +1 difficulty to all rolls because of the constant seeping blood.]==],
				},
				["Stigmata (4)"] = {
					en = [==[Lore of the Clans, p. 142


Stigmata (4)


Oracles are often marked as messengers of the gods. Your markings come in the forms of phantom wounds that seep blood. The bleeding is slight but incessant, costing you an extra blood point every day just before you wake at dusk.

The 2-point version of this Flaw means wounds that can be easily hidden from prying eyes, such as on the hands or the side. You gain a +1 difficulty to all Social rolls when dealing with someone aware of your condition.

The 4-point version can't be easily hidden, like bleeding eyes. The Social penalty increases to +2, and one of your Attributes also gains a +1 difficulty to all rolls because of the constant seeping blood.]==],
				},
				["Stone Tongue"] = {
					en = [==[Lore of the Bloodlines, p. 37


Stone Tongue


The transformation of the Embrace didn't just affect your appearance. It made it physically difficult for you to speak properly and clearly. It may be because of a clumsy tongue, some nasty looking tusks, or a raptor-type beak. No matter the cause, you suffer a +2 difficulty to any Social rolls requiring you to speak.]==],
				},
				["Strangeness"] = {
					en = [==[Book of Secrets, p. 85


Strangeness


Your metaphysical prowess occasionally warps reality in your presence, even when you don't want it to do so. Weird stuff happens when you're not expecting such phenomena, and those quirks of strangeness seem to be rooted in the sort of magick you pursue. A specialist in Entropy could suffer twists of probability and decay; a Life-attuned healer discovers odd growths and mutations in the life-forms around him, while a Forces-gifted mage bends the physics in his general vicinity. These phenomena ebb and flow without your guidance or control. Perversely, the more skilled you become in magick, the stronger these tides of weirdness become.

System-wise, the Storyteller determines, once or twice per game session, to roll your Arete against difficulty 6. If the roll succeeds, the Storyteller throws in some random occurrence that's based on a Sphere you possess – most often, on your Affinity Sphere. Grass could grow suddenly, mirrors could crack, psychic impressions could inform you of the sexual habits of the person standing next to you in the elevator – that sort of thing.

If the roll fails, then nothing unusual occurs. If the roll botches, however, then a Paradox backlash expels one point of Paradox in your current pool for each dot you have in your Affinity Sphere; or all of your current Paradox, if you have fewer points than that in your Paradox pool. (If, as an example, Jinx has three dots in Entropy but only one point of Paradox, the backlash dispels that one point in a backlash.) These small backlashes won't be terribly damaging, but given the unpredictable nature of this Flaw, they could come at very inconvenient times.]==],
				},
				["Stress Atavism"] = {
					en = [==[Book of Secrets, p. 53


Stress Atavism


See Mage 20, p. 644, and the Merit: Berserker.]==],
				},
				["Sympathizer"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 490


Sympathizer


You have publicly expressed sympathy for some of the goals and policies of the enemies of your Sect. Your outspoken views on the subject have made you suspect in the eyes of the city's hierarchy, and you may be sus- pected of (or arrested for) treason.]==],
				},
				["Taint of Corruption"] = {
					en = [==[Book of Secrets, p. 96


Taint of Corruption


Evil has an intimate hold on you. Your spirit has been corrupted – possibly since birth, as with the reborn Nephandi known as widderslainte – and you are, as the werewolves put it, “of the Wyrm” whether you wish to be or not. This doesn't necessarily mean you behave in an evil manner – you can]==],
				},
				["Territorial"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Territorial


You are extremely territorial, staking out a particular area as your hunting ground and reacting aggressively to trespassers. If another vampire enters your territory uninvited, you must make a frenzy roll. If you fail, you immediately attack the interloper and continue at- tacking until the intruder is dead or has left your hunt- ing grounds. You are reluctant to leave your territory except in desperate circumstances.]==],
				},
				["Thaumaturgically Inept"] = {
					en = [==[Lore of the Clans, p. 219


Thaumaturgically Inept


Something about you refuses to respond to Thaumaturgy. Magic just doesn't work for you. You cannot take any ability in the Thaumaturgy Discipline or any of its paths or rituals. For a Tremere this is doubly difficult, as skill in Thaumaturgy is often the key to position within the Clan. While some willingly choose to ignore their thaumaturgical studies and serve in other ways, ineptitude is never excused. Only Tremere can take this Flaw.

219]==],
				},
				["The Bard's Tongue"] = {
					en = [==[Book of Secrets, p. 82


The Bard's Tongue


A curse has rendered you unable to lie. It may even compel you to speak the truth when you struggle to remain silent. Worse still, you tend to say things that later turn out to be true even if you hadn't known anything about them at the time. (“Don't try and score food from that guy over there – he's got a gun and is having a really bad day.”) You often get a certain “look” when the urge to speak truth comes up, and folks who know you have begun to recognize the signs of a forthcoming “honesty blast” before you even open your mouth.

Life and Mage chronicles are both filled with times when it's best to keep a lid on the truth. And so, in order to avoid saying speaking the proverbial inconvenient truth (or worse), you need to spend a Willpower point to keep your mouth shut about it. Repressing that truth may also cost you one health level in bashing damage if the truth you're clamping down on is one of those “things that really must be said” which isn't a smart thing to say under the circumstances. (“Yeah, Agent Courage, everybody knows you work every angle with every group – that's not exactly a 'secret,' now is it?”) Cast No Shadow or Reflection]==],
				},
				["The Eighth"] = {
					en = [==[Lore of the Bloodlines, p. 5


The Eighth


Your sire is one of the Seven, the diablerist Golconda- seekers, trying to ensure the spiritual wealth of salvation would never be lost with their Final Death. They sought you as a successor, and proudly prepared you for your sacred duty. You, on the other hand, smiled at their lies, listened to their bullshit, and ran for the hills the first chance you got. You're constantly hunted, not only by the Tremere, but by your sire, the other Seven, and their various hangers-on. You must be at least Ninth Generation to take this Flaw. Permanent Third Eye (2 or 4pt. Flaw; Salubri and Tremere only)

While most sealed third eyes are visible as a slight scar, yours remains permanently open on your forehead. For 2 points, the eye is merely open, and may be closed for a scene on a successful Willpower roll (difficulty 6). For 4 points, the eye sheds light, increasing all Stealth difficulties by 2.]==],
				},
				["The Largest Maw"] = {
					en = [==[Lore of the Bloodlines, p. 70


The Largest Maw


Due to the size of the Nagaraja's shark-like rows of teeth, they find it hard to communicate verbally. Instead, she speaks through pools of spit and sometimes bites her own teeth in the process. This makes them quieter than other Nagaraja, but can also affect situations where clear speech is mandatory, such as when giving speeches or reciting delicate rituals. All difficulties for rolls where speech is a factor are raised by +2.]==],
				},
				["Thin Blood"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 483


Thin Blood


Your blood is thin, weak, and does not sustain you well. All blood point costs are doubled (e.g., using blood-related Disciplines or healing damage), although you only lose one blood upon rising in the evening. Furthermore, you are unable to create a blood bond, and efforts to sire other vampires succeed only one in five times.]==],
				},
				["Thirst for Innocence"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Thirst for Innocence


The sight of innocence — of any sort — arouses in you a terrible bloodlust. Roll Self-Control or Instincts, or else frenzy and attack the source of your hunger.]==],
				},
				["Thirteenth Generation"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Thirteenth Generation


By some strange twist of the supernatural, you were Embraced by a member of the Twelfth Generation. Your sire may not have even expected this to come to pass, and it certainly worries the powers-that-be, for you are something that should surely not exist. The difficulty of any rolls to activate your Disciplines is increased by one. At Storyteller discretion, you may also face other increased difficulties when you brush up against those who are frightened or suspicious of what you are. Strongly consider taking the Cannot Embrace or the Weak Blood Flaws as well.]==],
				},
				["Throwback (1)"] = {
					en = [==[Book of Secrets, p. 85


Throwback (1)


Haunted by a past life (often as per the Background Trait of that name, described above), you suffer from awful memories and act out in ways that are, shall we say, not pro- ductive to your current incarnation. Perhaps you still loathe the clergymen who tortured a former “you” for witchcraft 400 years ago; the smell of cooking meat still sends you into panic attacks. Or you'll get vertigo and acrophobic surges from that time a previous incarnation fell off a castle wall. You may slip into archaic accents, foreign languages, or terminology that is not exactly au courant (or socially acceptable) in today's world. Flashbacks, time segues, inappropriate behavior – it's all part of the package in this life you lead today.

For each point in this Flaw, up to a maximum of five points (and dice), the Storyteller will roll one die against difficulty 8 when the potential arises for a past life to affect your present life. The more successes he rolls, the more that past life affects you. The symptoms of this “throwback syndrome” generally depend upon the Storyteller's whim, but you could collabo- rate with him to hash out a backstory (or several backstories) for the previous incarnations your character recalls, and then roleplay symptoms that seem appropriate to those histories. For especially strong flashbacks (three successes or more), you may need to roll your Willpower (again, difficulty 8) to suppress the reaction to what your character recalls.

Described in Guide to the Traditions as an adversarial Background of Past Life, this Flaw makes a fitting companion to that Background, the Dream Background, and to other Merits and Flaws related to reincarnation (Twin Souls, Shat- tered Avatar, and similar Traits described within this section). With a few appropriate changes to the symptoms, you could also describe the Throwback Flaw as manifestations of a Leg- end Background, or as memories from a life that goes back several centuries. You'd rather forget the things you did, and endured, back during the Conquest of the Americas, but you never really can.]==],
				},
				["Throwback (2)"] = {
					en = [==[Book of Secrets, p. 85


