				},
				["Tic/Twitch"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 481


Tic/Twitch


You have some sort of repetitive motion that you make in times of stress, and it's a dead giveaway as to your identity. Examples include a nervous cough, con- stantly wringing your hands, cracking your knuckles, and so on. It costs one Willpower to refrain from en- gaging in your tic.]==],
				},
				["Tortured Artist"] = {
					en = [==[Lore of the Clans, p. 200


Tortured Artist


Nothing is ever good enough for your work. No matter how much praise is lavished upon you, you can only see the flaws and mistakes. This leads to long periods of ennui, which makes your artistic work irregular at best. Further, you throw yourself into business arrangements and social situations with intensity, which often leads to heartbreak, which leads to the pain and passion that fuels your next work. You are at +1 difficulty on Social rolls in which you are being praised, complimented, or treated with respect.]==],
				},
				["Touch of Frost"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Touch of Frost


Plants wither as you approach and die at your touch. Your touch leeches heat from living beings, as though you were made of ice.]==],
				},
				["Troublemaker"] = {
					en = [==[Book of Secrets, p. 65


Troublemaker


Pretty much the inverse of the Merit: Sanctity (p. 57); you project an impression of guilt even when you haven't done anything wrong. Folks blame you for pretty much everything, and the authorities go harder on you than they might if you didn't seem like such a noxious little turd! You come across like a natural-born sinner regardless of how you behave. Gee, if you're gonna get punished no matter what you do, maybe you ought to at least have some fun before the whip comes down.]==],
				},
				["Turncoat"] = {
					en = [==[Ghouls & Revenants, p. 132


Turncoat


The Turncoat is more than just a traitor. Revenants that take the Turncoat Flaw have betrayed more than the bonds of friendship, but also those of their familial connection and duty. Typically, a revenant that takes this Flaw has decided he is more interested in serving her family's enemies, and has taken the requisite steps to do so.

Most revenants with the Turncoat Flaw understand the ramifications of their actions. They understand that this Flaw requires them to protect themselves and hide from her former colleagues; they might even expect their families to hunt them down for their treachery. Depending on the nature and depth of the betrayal, allied vampires may decide to render their assistance to the hunt as well.

A Turncoat revenant will have likely earned the trust of her new friends by killing a former ally, friend, or relative, or by turning over sensitive information, such as the haven of a (formerly) allied vampire or the passwords to access her family's finances or accounts.

Despite being protected by a powerful vampire, Clan, members of a local Sect, or revenant family, characters who take this Flaw know their problems are far from over. The Turncoat's new allies will probably be skeptical of this character, and may not divulge anything other than minor details. After all, if the Turncoat betrayed her own family or a master while under the influence of the blood bond, she could do so again.

In general, this Flaw is best used by characters who are embroiled in the politics of a larger organization. The ramifications of a revenant's betrayal, such as a Grimaldi revenant divulging secrets pertaining to his family's desire to leave the Sabbat, are often far-reaching and significant. Thus, independent ghouls may also select this Flaw when and if it makes sense for them to do so. However, an independent ghoul might struggle to find the allies required to help ensure their survival, since most vampires may seek a blood bond with the traitor.

Used by: Revenants, some independent ghouls]==],
				},
				["Twisted Apprenticeship"] = {
					en = [==[Book of Secrets, p. 64


Twisted Apprenticeship


Someone taught you all the wrong things. For whatever reason, the mentor who introduced you to the Awakened realm did a terrible job, and now you reap the benefits. They may have told you lies about other groups, filled your head with nonsense about the nature of magick (though in all honesty, pretty much everyone does that), or simply behaved like a raging shmuck and left you with the payoff. Now folks blame you for things you did not do (or you did out of ignorance), and the mentor's bad rep and worse teachings hang about you like a god-slaying stink. You'll probably recover eventually, but your Awakened career got off to a wretched start.]==],
				},
				["Unblinking"] = {
					en = [==[Lore of the Clans, p. 239


Unblinking


Your eyes do not close. Ever. Perhaps you have left your humanity too far behind to upkeep such habits, or perhaps you fleshcrafted some form of transparent eye-scale or nictitating membrane. Your quirk probably makes astute observers uncomfortable, adding +1 to the difficulty of friendly social interactions with humans, Kindred on Humanity, and others with mortal sensibilities.]==],
				},
				["Uncanny (1)"] = {
					en = [==[Book of Secrets, p. 86


Uncanny (1)


No matter how unobtrusive you try to be, you remain re- markably memorable to anyone who encounters you. You're the very opposite of “arcane,” which is why this Flaw was originally described as an adversarial Background for the Trait of that name; rather than moving through life with near-invisibility, you stand out like a HIT Mark at a Verbena barbeque.

Why are you memorable, exactly? Is it an inhuman glow behind your eyes? An unsettling tone in your voice? A meta- physical miasma that hangs about you despite your apparently mundane appearance? Does grass grow or die in your shadow? Maybe dogs cower when they sense your approach. There could be a low buzzing in your presence, like a chorus of flies, or a disconcerting crackle of electricity that radiates from your skin, disrupting electrical systems in small but noticeable ways. Whatever it is that causes people to remember you, that facet of your presence is a constant reminder that you are not like other folk.

Once again, the point-value of this Flaw depends upon the extent to which it interferes with your life: (1 point) You stand out in a crowd. (2 points) It's pretty hard to conceal your oddities. (3 points) People remember you long after you're gone. (4 points) You creep people out simply by existing. (5 points) You scare people simply by existing.

By its nature, this Flaw represents an unmistakable impres- sion. Each point in this Flaw adds one die to the dice pool of anyone who's trying to notice you, recognize you, or penetrate your attempts at stealth or concealment. (You didn't really think those wailing damned souls were gonna shut up just because you were trying to get past the guards, now did you?) You may, however, attempt to cover up your uncanny presence with a roll of Intelligence + Subterfuge, assuming you have a method of doing so – it's easier to conceal your glowing red eyes with sunglasses than to get those wailing damned souls to piss off for a few minutes! The difficulty of such attempts is generally 5 + the value of your Uncanny Flaw; if, for instance, the clever bioconstruct Victoria Carliotti gets two points in Uncanny for her too-perfect skin, rippling muscles, and impossibly green eyes, her concealment difficulty would be 7. That said, this Flaw does not increase the difficulty of social rolls and may, depending on what you're trying to do, decrease such difficulties instead (Storyteller's option).

Despite the potentially grotesque nature of this Flaw, your uncanniness doesn't necessarily have to mean that your physical features are fearsome in themselves. An inhumanly gorgeous or disturbingly ordinary person can be Uncanny in their own ways. This Flaw makes an excellent companion to a variety of Physical Merits and Flaws – Enchanting Feature, Hyperflexible, Hideous, and so forth – and fits in with Back- grounds like Legend, Past Life or Totem quite well too. (See the appropriate entries for details.)

Although the Flaw: Echoes can manifest similar odd phenomena, this Flaw reflects a constant and recognizable distinction. While it probably embodies certain elements of your metaphysical practices, it's not tied to your Resonance or activities – it's an innate part of who you are. Your uncanniness could represent physical features (hulking physique, metallic skin, eyes that reflect eternity, and so forth); metaphysical quirks (an unearthly aura, echoing disembodied voices, a chilling radius around you, etc.); weird companions (a parade of pink-winged kittens, smoldering butterflies, howling coyote spirits, or similar inexplicable critters). Essentially, any sort of localized kink in normalcy's tail could be considered a sign of your Uncanny nature. By “uncanny,” incidentally, we don't necessarily mean “supernatural.” The unnatural stillness of a Black Suit, the flawless skin of a Victor, the predatory charisma of a Syndicate “magic man” – they're all examples of uncannily Enlightened technology.]==],
				},
				["Uncanny (2)"] = {
					en = [==[Book of Secrets, p. 86


Uncanny (2)


No matter how unobtrusive you try to be, you remain re- markably memorable to anyone who encounters you. You're the very opposite of “arcane,” which is why this Flaw was originally described as an adversarial Background for the Trait of that name; rather than moving through life with near-invisibility, you stand out like a HIT Mark at a Verbena barbeque.

Why are you memorable, exactly? Is it an inhuman glow behind your eyes? An unsettling tone in your voice? A meta- physical miasma that hangs about you despite your apparently mundane appearance? Does grass grow or die in your shadow? Maybe dogs cower when they sense your approach. There could be a low buzzing in your presence, like a chorus of flies, or a disconcerting crackle of electricity that radiates from your skin, disrupting electrical systems in small but noticeable ways. Whatever it is that causes people to remember you, that facet of your presence is a constant reminder that you are not like other folk.

Once again, the point-value of this Flaw depends upon the extent to which it interferes with your life: (1 point) You stand out in a crowd. (2 points) It's pretty hard to conceal your oddities. (3 points) People remember you long after you're gone. (4 points) You creep people out simply by existing. (5 points) You scare people simply by existing.

By its nature, this Flaw represents an unmistakable impres- sion. Each point in this Flaw adds one die to the dice pool of anyone who's trying to notice you, recognize you, or penetrate your attempts at stealth or concealment. (You didn't really think those wailing damned souls were gonna shut up just because you were trying to get past the guards, now did you?) You may, however, attempt to cover up your uncanny presence with a roll of Intelligence + Subterfuge, assuming you have a method of doing so – it's easier to conceal your glowing red eyes with sunglasses than to get those wailing damned souls to piss off for a few minutes! The difficulty of such attempts is generally 5 + the value of your Uncanny Flaw; if, for instance, the clever bioconstruct Victoria Carliotti gets two points in Uncanny for her too-perfect skin, rippling muscles, and impossibly green eyes, her concealment difficulty would be 7. That said, this Flaw does not increase the difficulty of social rolls and may, depending on what you're trying to do, decrease such difficulties instead (Storyteller's option).

Despite the potentially grotesque nature of this Flaw, your uncanniness doesn't necessarily have to mean that your physical features are fearsome in themselves. An inhumanly gorgeous or disturbingly ordinary person can be Uncanny in their own ways. This Flaw makes an excellent companion to a variety of Physical Merits and Flaws – Enchanting Feature, Hyperflexible, Hideous, and so forth – and fits in with Back- grounds like Legend, Past Life or Totem quite well too. (See the appropriate entries for details.)

Although the Flaw: Echoes can manifest similar odd phenomena, this Flaw reflects a constant and recognizable distinction. While it probably embodies certain elements of your metaphysical practices, it's not tied to your Resonance or activities – it's an innate part of who you are. Your uncanniness could represent physical features (hulking physique, metallic skin, eyes that reflect eternity, and so forth); metaphysical quirks (an unearthly aura, echoing disembodied voices, a chilling radius around you, etc.); weird companions (a parade of pink-winged kittens, smoldering butterflies, howling coyote spirits, or similar inexplicable critters). Essentially, any sort of localized kink in normalcy's tail could be considered a sign of your Uncanny nature. By “uncanny,” incidentally, we don't necessarily mean “supernatural.” The unnatural stillness of a Black Suit, the flawless skin of a Victor, the predatory charisma of a Syndicate “magic man” – they're all examples of uncannily Enlightened technology.]==],
