				},
				["Unclean (2)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 421


Unclean (2)


Whether a lingering trait

from your mortal life or an unfortunate side effect of

your Embrace, your skin is marred in such a way that

most casual observers assume you are a leper (or at least

carrying some kind of plague). You may be barred entry

to major cities, thrown out of most establishments, or

subject to misguided attempts at healing or mercy. At 3

points, you carry leprosy (or some other contagious and

visible disease). Nosferatu who take this Flaw receive

only 1 point for it and must take its full effects (3 points).]==],
				},
				["Unclean (3)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 421


Unclean (3)


Whether a lingering trait

from your mortal life or an unfortunate side effect of

your Embrace, your skin is marred in such a way that

most casual observers assume you are a leper (or at least

carrying some kind of plague). You may be barred entry

to major cities, thrown out of most establishments, or

subject to misguided attempts at healing or mercy. At 3

points, you carry leprosy (or some other contagious and

visible disease). Nosferatu who take this Flaw receive

only 1 point for it and must take its full effects (3 points).]==],
				},
				["Uncommon Vitae Preference"] = {
					en = [==[Lore of the Clans, p. 261


Uncommon Vitae Preference


Your preferred source for vitae is rarified even by the standards of your Clan, such as “only Korean War vets,” “only Federal Court Judges,” or “only virgins over the age of 40.” The difficulty of all hunting rolls for your character is increased by +2, to a maximum of 9. 261]==],
				},
				["Uncontrollable Night Sight"] = {
					en = [==[Lore of the Clans, p. 123


Uncontrollable Night Sight


Your night vision is good, but you can't turn it off. While you can see easily into the deepest shadows, any light is almost blinding to you. You suffer penalties the brighter the area you are in is lit, inversely proportional to the standard penalties for darkness. Even just standing in a well-lit room is uncomfortable to you.]==],
				},
				["Unconvinced"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Unconvinced


You fail to see the need for the core ideologies of your Sect or Clan, and have gone on record as saying so. Taking your stand has made you suspect in the eyes of your superiors, and may have attracted the attention of your enemies as well. 485]==],
				},
				["Unholy Stain"] = {
					en = [==[Dark Ages Tome of Secrets, p. 108


Unholy Stain


Your soul is stained with sacrilege. Some are born or Embraced this way; more earn the stain through wicked oaths and foul deeds. When interacting with any mortal, your Social difficulties increase by one, as people feel unnaturally ill at ease in your presence. Additionally, people of faith feel compelled to hostility when in your proximity. Their initial stance toward you is always aggressive, and it takes little to provoke them to violence. Mortals with True Faith will recognize you on sight, and often attack.]==],
				},
				["Unlucky (1)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Unlucky (1)


You are spectacularly unfor- tunate. Disaster follows in your wake. You are magnetically attracted to misfortune. At 1 point, it rains whenever you forget your coat. At 3 points, it's rare for you to recover from any failure gracefully. At 5 points, nearly everything you attempt ends catastrophically. A number of times per day equal to the point you have in this Flaw, the Storyteller may force you to reroll a successful roll and take the second result. Lucky and Unlucky are not mutually exclusive, but for simplicity's sake, the same roll cannot be modified by both at once. That is, if a Lucky reroll is used, the Storyteller cannot force you to reroll the reroll.]==],
				},
				["Unlucky (2)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Unlucky (2)


You are spectacularly unfor- tunate. Disaster follows in your wake. You are magnetically attracted to misfortune. At 1 point, it rains whenever you forget your coat. At 3 points, it's rare for you to recover from any failure gracefully. At 5 points, nearly everything you attempt ends catastrophically. A number of times per day equal to the point you have in this Flaw, the Storyteller may force you to reroll a successful roll and take the second result. Lucky and Unlucky are not mutually exclusive, but for simplicity's sake, the same roll cannot be modified by both at once. That is, if a Lucky reroll is used, the Storyteller cannot force you to reroll the reroll.]==],
				},
				["Unlucky (3)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Unlucky (3)


You are spectacularly unfor- tunate. Disaster follows in your wake. You are magnetically attracted to misfortune. At 1 point, it rains whenever you forget your coat. At 3 points, it's rare for you to recover from any failure gracefully. At 5 points, nearly everything you attempt ends catastrophically. A number of times per day equal to the point you have in this Flaw, the Storyteller may force you to reroll a successful roll and take the second result. Lucky and Unlucky are not mutually exclusive, but for simplicity's sake, the same roll cannot be modified by both at once. That is, if a Lucky reroll is used, the Storyteller cannot force you to reroll the reroll.]==],
				},
				["Unlucky (4)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Unlucky (4)


You are spectacularly unfor- tunate. Disaster follows in your wake. You are magnetically attracted to misfortune. At 1 point, it rains whenever you forget your coat. At 3 points, it's rare for you to recover from any failure gracefully. At 5 points, nearly everything you attempt ends catastrophically. A number of times per day equal to the point you have in this Flaw, the Storyteller may force you to reroll a successful roll and take the second result. Lucky and Unlucky are not mutually exclusive, but for simplicity's sake, the same roll cannot be modified by both at once. That is, if a Lucky reroll is used, the Storyteller cannot force you to reroll the reroll.]==],
				},
				["Unlucky (5)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 427


Unlucky (5)


You are spectacularly unfor- tunate. Disaster follows in your wake. You are magnetically attracted to misfortune. At 1 point, it rains whenever you forget your coat. At 3 points, it's rare for you to recover from any failure gracefully. At 5 points, nearly everything you attempt ends catastrophically. A number of times per day equal to the point you have in this Flaw, the Storyteller may force you to reroll a successful roll and take the second result. Lucky and Unlucky are not mutually exclusive, but for simplicity's sake, the same roll cannot be modified by both at once. That is, if a Lucky reroll is used, the Storyteller cannot force you to reroll the reroll.]==],
				},
				["Unproven"] = {
					en = [==[Lore of the Clans, p. 123


Unproven


Somehow, you have failed to prove yourself worthy of the name Lasombra. Maybe your sire did not test you well enough, or an opportunity to prove yourself has not come up. Whatever the reason, you are not truly considered part of the Clan. All social dealings with other Lasombra suffer a -3 dice penalty. You may also not be chosen to sit in judgment in the Courts of Blood.]==],
				},
				["Unsanctioned Embrace"] = {
					en = [==[Lore of the Bloodlines, p. 4


Unsanctioned Embrace


Lazarus decreed no Harbingers should Embrace, but your sire failed to listen. You're hopelessly green and unworthy of the vitae in your veins. Until you perform acts befitting the nobility of your blood, your existence is shunned as a bad omen. Increase difficulties of all Social actions involving your bloodline by two.]==],
				},
				["Uppity"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 492


Uppity


You are proud of your new status in the Sect — so proud that you've shot your mouth off to other Kindred and made some enemies. Wiser vampires laugh at you and chalk your rudeness up to youth, but others find you arrogant and insulting. These enemies will take ac- tion to embarrass or harm you. Furthermore, you are at +2 difficulty on all Social rolls against any vampires you have alienated through your yammering — and you may not know who they are.

At Storyteller discretion, you may also be required to make a Willpower roll (difficulty 6) to keep your mouth shut any time the opportunity presents itself for you to brag about your pack, your Clan, or your status.]==],
				},
				["Vanilla"] = {
					en = [==[Book of Secrets, p. 48


Vanilla


Oh my gods, you're such an innocent! In a world filled with sex magick and power plays, you're the little lamb who's strayed far away from home. Jokes get past you, clues escape you, and references to anything rawer than a Disney flick go straight over your head. Maybe you grew up in a secluded place with overprotective parents; or you could be in denial about the things you see all around you because life can't possibly be that twisted… can it? Regardless, hold firm to your innocence. Once it's gone, it ain't never coming back again!]==],
				},
				["Vassal of the Clan"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 179


Vassal of the Clan


Through natural predisposition or a curse, you bear a permanent one-point blood bond to those one Generation lower, a two-point blood bond with those two Generations lower, and a three-point blood bond to those three or more Generations lower than you within your own Clan. These blood bonds override any other blood bonds you may earn during play. This can be a great risk for Hand members, as the blood forces allegiances to potentially risky vampires, or worse, to heretical ideologies. 179]==],
				},
				["Vengeful"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Vengeful


You have a score to settle, incurred either during your mortal days or after the Embrace. You are obsessed with taking your revenge on an individual or group, and it is your overriding priority in any situation where you encounter the object of your revenge. You may temporarily resist your need for vengeance by spending a Willpower point.]==],
				},
				["Venomous Bite"] = {
					en = [==[Lore of the Clans, p. 67


Venomous Bite


You have developed venom glands in the roof of your mouth. The venom is a virulent neurotoxin, fatal to mortals, although Kindred and other supernatural creatures are unaffected by it. You, of course, are immune. The problem is you have no control over your poison glands. When you bite, you always inject this venom, usually killing your human victims. You must learn to feed in other ways, perhaps drawing the blood you need with a syringe or razor, if you do not wish to kill every time you feed.]==],
				},
				["Victim of the Masquerade"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Victim of the Masquerade


The Camarilla's propaganda machine did too good a job on you. Even after your Embrace you refused to be- lieve you were a vampire. You remain convinced that there is some logical explanation for your condition, and spend as much time as you can searching for it. You also have problems feeding, and may insist on try- ing to eat regular food. None of these habits makes you particularly pleasant company for other Kindred. This Flaw must be roleplayed at all times, and is generally taken by Camarilla vampires.]==],
				},
				["Vitae Sink"] = {
					en = [==[Ghouls & Revenants, p. 139


Vitae Sink


For whatever reason, your ghoul or revenant metabolizes vitae more quickly than others do. You must be fed every two weeks, rather than once every month, or risk losing all supernatural Traits and will revert to your natural state. Few ghouls with this Flaw last beyond their natural life spans, unless their domitors are especially devoted to them. At this increased rate, however, it is likely that missed feedings might happen, which is why this Flaw is deadly to independent ghouls.

Revenants who suffer from Vitae Sink replenish their natural vitae at half the rate they normally might.

Used by: Most ghouls and revenants Asset]==],
				},
				["Vulgar"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 178


Vulgar


Tact is a foreign concept to you, and you're famous for being abrasive and generally unpleasant. Rolls involving social graces or delicate situations suffer +1 difficulty.]==],
				},
				["Vulnerability (1)"] = {
					en = [==[Book of Secrets, p. 86


Vulnerability (1)


Some perilous substance may spell your doom. Thanks to a paranormal weakness – a curse, a Paradox Flaw, a quirk of belief or cultural legends – you suffer extraordinary harm from that malignant material. Perhaps you shrivel up in sunlight, flee from the scent of roses, or melt when obnoxious farm girls throw water in your face. This substance isn't generally fatal to most folks (Awakened or otherwise), but it's potential death for you.

Your vulnerability to this substance in question has two potential levels: Weakening, which inflicts one aggravated health level

on your character every turn she's in contact with the

substance; and… Mortal peril, which inflicts three aggravated health levels

for each turn she's in contact with the substance.

The value of this Flaw is based upon two factors: How common the fatal substance is, and how badly it affects you: (2 points) You can be mortally wounded by contact

with something that's almost impossible to acquire (the

sound of Pan's pipes, a splinter from the True Cross),

or weakened by a very rare substance (a chunk of moon

rock, the tooth from an aged lion). (3 points) Mortal injury from a very rare substance, or

weakness caused by something that's relatively scarce

and not obviously harmful (saffron, grave dirt, a raven's

feathers). (4 points) Mortal injury from something that's relatively

scarce, or weakness from a common substance (rainwater,

silver, a baby's cry). (5 points) A common substance inflicts mortal injury

on you. (+1 point) You die instantly upon contact with the

substance in question. (+1 point) The mere presence of the substance means

instant death to you. (-1 point) The substance must first inflict damage on

you through a typical injury (a stab wound, ingested

poison, a silver bullet) before it can harm you.

Damage from this Flaw cannot be soaked unless you're wearing an appropriate type of armor to prevent exposure to that substance. (Being aggravated damage, it shouldn't normally be soaked anyhow, but mages have ways of getting around such trivialities.) Your backstory should feature the reason for your potentially fatal vulnerability to this substance. That vulnerability ought to be tied into your magickal focus, too – an Alpha Male tycoon isn't likely to burn upon contact with holy water, although it might be fun to fling a few dashes of the stuff around Wall Street and find out for sure! (That would certainly explain a few things.)]==],
				},
				["Vulnerability (2)"] = {
					en = [==[Book of Secrets, p. 86


Vulnerability (2)


Some perilous substance may spell your doom. Thanks to a paranormal weakness – a curse, a Paradox Flaw, a quirk of belief or cultural legends – you suffer extraordinary harm from that malignant material. Perhaps you shrivel up in sunlight, flee from the scent of roses, or melt when obnoxious farm girls throw water in your face. This substance isn't generally fatal to most folks (Awakened or otherwise), but it's potential death for you.

Your vulnerability to this substance in question has two potential levels: Weakening, which inflicts one aggravated health level

on your character every turn she's in contact with the

substance; and… Mortal peril, which inflicts three aggravated health levels

for each turn she's in contact with the substance.

The value of this Flaw is based upon two factors: How common the fatal substance is, and how badly it affects you: (2 points) You can be mortally wounded by contact

with something that's almost impossible to acquire (the

sound of Pan's pipes, a splinter from the True Cross),

or weakened by a very rare substance (a chunk of moon

rock, the tooth from an aged lion). (3 points) Mortal injury from a very rare substance, or

weakness caused by something that's relatively scarce

and not obviously harmful (saffron, grave dirt, a raven's

feathers). (4 points) Mortal injury from something that's relatively

scarce, or weakness from a common substance (rainwater,

silver, a baby's cry). (5 points) A common substance inflicts mortal injury

on you. (+1 point) You die instantly upon contact with the

substance in question. (+1 point) The mere presence of the substance means

instant death to you. (-1 point) The substance must first inflict damage on

you through a typical injury (a stab wound, ingested

poison, a silver bullet) before it can harm you.

Damage from this Flaw cannot be soaked unless you're wearing an appropriate type of armor to prevent exposure to that substance. (Being aggravated damage, it shouldn't normally be soaked anyhow, but mages have ways of getting around such trivialities.) Your backstory should feature the reason for your potentially fatal vulnerability to this substance. That vulnerability ought to be tied into your magickal focus, too – an Alpha Male tycoon isn't likely to burn upon contact with holy water, although it might be fun to fling a few dashes of the stuff around Wall Street and find out for sure! (That would certainly explain a few things.)]==],
