				},
				["Vulnerability to Silver"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 482


Vulnerability to Silver


To you, silver is as painful and as deadly as the rays of the sun. You suffer aggravated wounds from any silver weapons (bullets, knives, etc.), and the mere touch of silver objects discomfits you.]==],
				},
				["Ward"] = {
					en = [==[Book of Secrets, p. 66


Ward


Mages rarely move through life alone. And when certain companions – lovers, children, partners, parents, close friends, even employers – depend upon you, that lack of loneliness can become a liability. This Flaw represents a character, or a group of characters, who require constant attention on your part. Your life is a hazard to them, and their needs often provide hazards for you as well. Wards tend to get in trouble, require rescuing, and go digging into aspects of your life you'd prefer they left alone. Is it love that binds you to your ward? Duty? An oath? Family obligations? A job like bodyguarding, teaching or medicine? Regardless of the reason, each ward is an essential part of your life. Their life is your priority.

Although Ward characters may have a useful skill or two, such folks are unAwakened people, not mages, Night-Folk, familiars, or other powerful entities. That said, you could take a Ward Flaw to reflect a special bond with a Retainer, a Cult member, or one of your Spies. Merits like Supportive Family or True Love (and Flaws like Family Issues) go well with the Ward Trait. Wards don't have to be human, either – your dog, your cat, your horse… an animal who depends upon you could be a ward as well. You can take this Flaw more than once, to reflect several dependent characters. Yeah, there are reasons that mages tend to avoid having big families!

Obviously, each ward is a Storyteller character, with all the agendas and complications that situation entails. This person might not count as a Sleeper witness with regards to your magick… but if you've been keeping that person in the dark with regards to your true life and nature, they could still count as a witness for at least their first experience with your sort of “reality.”]==],
				},
				["Weak Blood"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 428


Weak Blood


Something has diminished your supernatural vigor and lessened your abilities as a vampire. Where others effortlessly command the gifts of Lilith, you struggle. No Discipline you have knowledge of may be higher than 4. It costs you twice the normal amount of blood points to control any vampiric abilities. You must feed a person six drinks of your feeble blood before they can become your thrall, and you do not possess the potency to create a ghoul or sire a childe. This effect also covers the drawbacks of the Cannot Embrace Flaw (page 427), therefore the two are mutually exclusive.

Weak Aura (2 point Merit or Flaw): The aura of your Road clings weakly to you, manifesting only when you perform acts of faith or when your fervor is at its most intense. This is a Merit if your Road rating is 4 or less, and a Flaw if it's 5 or more. Follow the chart below for the mechanical effects on the application of your aura.]==],
				},
				["Weak-Willed"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 486


Weak-Willed


You are highly susceptible to Dominate and intimida- tion by others; Dominate attempts automatically affect you unless the Discipline wielder is of higher Genera- tion, and your difficulties to resist Social abilities such as Intimidation or Leadership, as well as mind-altering spells or magic, are increased by two. Your Willpower Trait may never rise above 4.]==],
				},
				["Whimsy"] = {
					en = [==[Book of Secrets, p. 48


Whimsy


You get silly under stress. It's an avoidance tactic, and while such behavior can be endearing in small doses, your whimsical streak can get kinda annoying after a while, especially for folks who have to deal with you pulling out hand puppets in the middle of an argument or tossing grapes down your covenmate's cleavage when she's trying to have a serious conversation with you. In especially stressful situations, you might need to make a Willpower roll (difficulty 6) to not clown around. Hey, you can't help it, right, if you're trying to lighten the mood? Jeeze, why does magick have to be so damned serious…?]==],
				},
				["Witch-Hunted"] = {
					en = [==[Book of Secrets, p. 68


Witch-Hunted


The Masses want you dead. You've been exposed for what you are and can do, and so various unAwakened parties have decided to take you out like the abomination you've become. These hunters could be law-enforcement authorities, religious groups, fanatical sects, furious mobs, imbued hunters, pawns of the Night-Folk… whoever they might be, these people offer a significant threat to your existence, possessing the power to end you and the dedication to back it up. Your Arts alone cannot stop them, and a painful showdown (or three) is sadly inevitable.]==],
				},
				["Acute Sense"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 479


Acute Sense


One of your senses is exceptionally sharp, be it sight, hearing, smell, touch, or taste. The difficulties for all

479 tasks involving the use of this particular sense are re- duced by two. This Merit can be combined with the Discipline of Auspex to produce superhuman sensory acuity.]==],
				},
				["Acute Senses (1)"] = {
					en = [==[Book of Secrets, p. 35


Acute Senses (1)


See Mage 20, pp. 642-643.]==],
				},
				["Acute Senses (3)"] = {
					en = [==[Book of Secrets, p. 35


Acute Senses (3)


See Mage 20, pp. 642-643.]==],
				},
				["Addictive Blood"] = {
					en = [==[Lore of the Clans, p. 67


Addictive Blood


You don't just peddle narcotics; through the blessings of the Dark God, you are the perfect drug. Your blood is especially delicious to others, Kindred or kine. Whoever tastes your blood must, during any subsequent scenes that they meet you, drink again or spend a Willpower point to avoid the pangs of craving. These cravings add +2 difficulty to any Mental or Social rolls. Setites with this Merit find it much easier to blood bond an opponent, as once they have tasted the tainted vitae, they will do almost anything to drink it again.]==],
				},
				["Additional Discipline"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Additional Discipline


You can take one additional Discipline (Storyteller discretion) as if it were a Clan Discipline. All costs to learn that Discipline are paid out as if it were na- tive to your Clan. A character cannot take this Merit more than once, and Caitiff vampires cannot take this Merit.]==],
				},
				["Advanced Tech (1)"] = {
					en = [==[Lore of the Bloodlines, p. 99


Advanced Tech (1)


You have a device (or possibly a few) of an advanced design. While the True Brujah are not especially good at innovation, they are good at making improvements. So this device has no special functions unavailable to its contemporaries, but it does work a lot better. It reduces the chance of a mechanical fault (such as a jam) by half and all uses of the device are made with a -1 to the difficulty. The Storyteller should decide on the cost of the Merit, depending on how many items the character has, and how powerful they are.]==],
				},
				["Advanced Tech (2)"] = {
					en = [==[Lore of the Bloodlines, p. 99


