				},
				["Advanced Tech (5)"] = {
					en = [==[Lore of the Bloodlines, p. 99


Advanced Tech (5)


You have a device (or possibly a few) of an advanced design. While the True Brujah are not especially good at innovation, they are good at making improvements. So this device has no special functions unavailable to its contemporaries, but it does work a lot better. It reduces the chance of a mechanical fault (such as a jam) by half and all uses of the device are made with a -1 to the difficulty. The Storyteller should decide on the cost of the Merit, depending on how many items the character has, and how powerful they are.]==],
				},
				["Alcohol /Drug Tolerance (1)"] = {
					en = [==[Book of Secrets, p. 35


Alcohol /Drug Tolerance (1)


You can drink folks under the table or otherwise party till everybody else drops. System-wise, this Merit lets you make a Stamina roll (difficulty 7) to shake off the effects of intoxication – a useful talent for hard-pounding Ecstatics and tough-as-leather Black Suits!

In its one-point form, this Merit functions only for “natural” drugs (booze, pot, cocaine, etc.), not for lab-synthesized concoctions (LSD, meth, krokodil, etc.). For two points, however, the Merit can neutralize the psychoactive effects of any drug unless that drug has been created as the vector for a Sphere-based magickal Effect. (That is, say, a pill that delivers a Life 3 /Mind 3 Effect to the person who takes it, as opposed to an “ordinary” pill that a mage takes as part of the focus instruments Drugs and Poisons or Brews, Potions, and so forth, as detailed in Mage 20, pp. 588-600.) In the latter case, the character needs to use countermagick; this Merit will not help to counteract such drugs. “Awakened” substances, however (as per Mage 20, p. 443) are treated as “synthesized concoctions” even if they are, in all other forms, “natural.

For a more comprehensive resistance to toxins, see Poison Resistance, below.]==],
				},
				["Alcohol /Drug Tolerance (2)"] = {
					en = [==[Book of Secrets, p. 35


Alcohol /Drug Tolerance (2)


You can drink folks under the table or otherwise party till everybody else drops. System-wise, this Merit lets you make a Stamina roll (difficulty 7) to shake off the effects of intoxication – a useful talent for hard-pounding Ecstatics and tough-as-leather Black Suits!

In its one-point form, this Merit functions only for “natural” drugs (booze, pot, cocaine, etc.), not for lab-synthesized concoctions (LSD, meth, krokodil, etc.). For two points, however, the Merit can neutralize the psychoactive effects of any drug unless that drug has been created as the vector for a Sphere-based magickal Effect. (That is, say, a pill that delivers a Life 3 /Mind 3 Effect to the person who takes it, as opposed to an “ordinary” pill that a mage takes as part of the focus instruments Drugs and Poisons or Brews, Potions, and so forth, as detailed in Mage 20, pp. 588-600.) In the latter case, the character needs to use countermagick; this Merit will not help to counteract such drugs. “Awakened” substances, however (as per Mage 20, p. 443) are treated as “synthesized concoctions” even if they are, in all other forms, “natural.

For a more comprehensive resistance to toxins, see Poison Resistance, below.]==],
				},
				["Alien Perfection"] = {
					en = [==[Lore of the Bloodlines, p. 59


Alien Perfection


You possess beauty unsettling in its perfection. People stand in awe of your flawless form, while inexplicable nausea LORE OF THE BLOODLINES 59

The Necromancy Lie

At the Storyteller's discretion, Kiasyd may

take the Discipline of Necromancy instead

of Dominate, but in so doing earn the Clan

Enmity Flaw (V20, p. 492) twice, both for the

Giovanni and Harbingers of Skulls. Freebie

points aren't gained for taking these Flaws. subconsciously creeps up. The difficulty of any Appearance roll is reduced by three. A Stamina roll is required by anyone in your presence for longer than one scene, if this is the first time they've encountered you. Failure drives them away from you with a sickness wracking their body.]==],
				},
				["Ambidextrous"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Ambidextrous


You have a high degree of off-hand dexterity and can perform tasks with the “wrong” hand at no pen- alty. The rules for taking multiple actions still apply, but you do not suffer a difficulty penalty if you use two weapons or are forced to use your off hand.]==],
				},
				["Animal Magnetism"] = {
					en = [==[Book of Secrets, p. 54


Animal Magnetism


Though it might not involve conventionally good looks, you possess a primal sort of attractiveness. Your social rolls subtract 2 from their difficulty when you're trying to charm, seduce, or otherwise impress folks by appealing to their carnal natures. This benefit doesn't usually apply to threats or intimidation attempts, although clever applications of raw sex appeal can be rather unnerving, which could facilitate rather effective threats…]==],
				},
				["Antitoxin Blood"] = {
					en = [==[Lore of the Clans, p. 181


Antitoxin Blood


Although vampires are typically immune to mortal drugs and poisons, there are supernatural venoms that can affect Kindred physiology. A Ravnos with this Merit is immune to all forms of drugs and poisons, including the venoms and toxins of supernatural creatures or those created by supernatural powers. LORE OF THE CLANS 181]==],
				},
				["Apostate (Modern)"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 178


Apostate (Modern)


Since their inception, Nergali Baali have subverted members of other Clans into their own ranks. Known as Apostates, initiates are first drained completely by a Baali nest-master, who then extracts the still-beating heart from a mortal victim, fills it with his own blood, and buries it in a pool of gore within a Well of Sacrifice. The initiate swims through the dismembered bodies and viscous re- mains to find and consume the heart. In this way, Nergali do not make a victim of those they Embrace; prospective members must claim it through strength of will.

Apostates replace any one in-Clan Discipline with Daimoinon, but in turn gain the Baali Clan weakness on top of their standard Clan weakness. Apostates can still pass with relative ease for members of their former Clans, but any childe they Embrace is indistinguishable from a standard Baali. Further, such a childe shares none of the Clan Disciplines or weaknesses of their sire's for- mer Clan, save those Disciplines that are innate to the Baali. Apostates do not lose levels in the Discipline they choose to exchange for Daimoinon, but further levels in that Discipline are purchased at out-of-Clan costs. Baali may not take this Merit.]==],
				},
				["Arcane (1)"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 177


Arcane (1)


Some vampires have a strange ability to slip from no- tice, which manifests as an aura of forgetfulness. Those trying to remember the vampire experience a sensation of jamais-vu. The ability may be deliberately developed, or the Kindred could simply be too ordinary to pay attention to. Though not similar to Obfuscate, Arcane doesn't help in combat situations — the vampire can't literally vanish. However, someone searching for them may well fail, as no one remembers the vampire or can give a reliable description.

Each point taken subtracts one die from any dice pools used to actively locate the vampire or recall her from memory. Those with this Merit can choose to “turn off” Arcane if they wish. As a passive trait, it doesn't help on Stealth rolls or other overt attempts to hide. If you have 177 any dots in Status or Fame, Arcane ceases to function while you possess them.]==],
				},
				["Arcane (2)"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 177


