				},
				["Artistically Gifted"] = {
					en = [==[Book of Secrets, p. 43


Artistically Gifted


The Muses work their will through you, or so it appears. Whenever you employ your artistic talent (as in, the Talent: Art in Mage 20, p. 275), reduce the difficulty of those rolls by -2. As with other Merits of this kind, this Merit does not reduce the difficulty of magick-casting rolls, but may reduce the difficulty of Attribute + Ability rolls that are involved with magickal acts. (For more details, see Abilities Enhancing Magick, Mage 20, pp. 533.)]==],
				},
				["Aura of Command"] = {
					en = [==[Lore of the Clans, p. 122


Aura of Command


Whether you are good at barking orders or simply have a commanding tone, people tend to do what you tell them to do. You are not so much a natural leader as a born commander. When using the Leadership skill to get others to obey you, the difficulty is reduced by two.]==],
				},
				["Avatar Companion"] = {
					en = [==[Book of Secrets, p. 79


Avatar Companion


From lifetime to lifetime, you share a bit of your Avatar with a companion who follows you through incarnations, recalling more about their details than you do. Although he's not as powerful as you are, and lacks the metaphysical prowess of the Merits: Twin Soul or Shattered Avatar (above), this companion knows a great deal about your reincarnated self… quite a bit more about it than you do. This loyal (if not always agreeable) character literally follows you for life, typically ending his life when you do; in the meantime, he provides insights, advice, information about previous life- times, and whatever other forms of aid he can possibly offer. Like the Merit: Guardian Angel, the Avatar Companion is essentially a walking boost from your Storyteller, subject to her whims but acting in your best interests… for the most part, anyway.

Unless it's purchased in addition to the Background: Allies, your companion isn't anything special; he could be a person or animal, but not a vampire, a werebeast, or some other Night-Folk entity. Your Avatar Companion could also be a Ward, the focus of True Love, or perhaps an embodiment of a Manifest Avatar. Treat him badly enough, and he might become an Enemy. (See all appropriate entries for details.) As with all other character-based Traits, this companion has his own personality, desires, and so on. He may be loyal, but he's not suicidal, and isn't likely to be thrilled if the mage decides to abuse his loyalty!]==],
				},
				["Backup Identity"] = {
					en = [==[The Hunters Hunted II, p. 133


Backup Identity


Most agents build up one or two cover identities, replete with backgrounds and supporting documents. You've gone one further, and got a cover identity that your agency doesn't know about. Your backup identity has a full set of documents, including a social security card and a passport, a bank account, and even owns a small apartment. Unlike most cover identities, nothing links you and your backup identity, meaning it can come in very handy when you need to work off the record, and as a get-out card when things get hairy.

This Merit just provides documentation and a guarantee that intelligence agencies don't know about your alter ego. You still need the Alternate Identity Background if you want to play the part effectively.]==],
				},
				["Bardic Gift"] = {
					en = [==[Book of Secrets, p. 69


Bardic Gift


Blessed with uncanny inspiration, you create profoundly evocative artwork. Truth echoes through your words, blazes from your canvas, resonates in song, speaks silently in dance. Although artistic skill is, of course, important, this gift runs deeper than mere technique. Art is your passion, your spirit, your Truth. And that Truth manifests itself in whatever arts you pursue, up to and including the Magickal Arts.

When making a roll with the Art Talent, reduce the difficulty by -2. Even when the attempt itself falls short of your expectations (that is, when you fail a roll), your creations feature an unmistak- able gleam of brilliance and a preternatural expression of Truth. Although you're not required (as a player) to employ artwork as part of your magickal focus, chances are good that your approach to magick does feature elements of painting, dance, music, and other manifestations of artistic expression.]==],
				},
				["Benevolent Domitor"] = {
					en = [==[Ghouls & Revenants, p. 129


Benevolent Domitor


For reasons unbeknownst to you, your domitor is fond of you. Perhaps your service has been exemplary, or you simply remind your master of a past love. Given the alien nature of a vampire's mind, you may never know for sure, but you do not begrudge the benefits you've gained from your master's feelings toward you.

You feel safe in your master's care, and do not dread spending night after night fulfilling your duties. Your domitor treats you with a measure of faux compassion, and does not casually endanger your life. Unlike the relationship between other masters and their ghouls, this Merit does not represent a temporary phase. You have already proven yourself to your master. Thus, your relationship is akin to a friendship between a great boss and his employee.

Though this Merit shapes how your domitor treats you, it does not guarantee that you will never run afoul of your master. You may, at your Storyteller's discretion, lose the right to keep this Merit should your actions necessitate such a decision over time.

Prerequisite: Domitor Background Used by: Camarilla ghouls, some Sabbat ghouls]==],
				},
				["Berserker (Mage)"] = {
					en = [==[Book of Secrets, p. 46


Berserker (Mage)


See Mage 20, p. 644, and the Flaw: Stress Atavism.]==],
				},
				["Berserker (Vampire)"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 177


Berserker (Vampire)


You possess the ability to willingly enter a berserker state for a scene. While berserking, you ignore wound penalties and reduce the difficulty of all combat rolls except for dodges by -3. You also can take no complex actions other than combat, dodging, or running. Social]==],
				},
				["Bigger Boys Came"] = {
					en = [==[Lore of the Clans, p. 121


Bigger Boys Came


When someone uses their contacts to their advantage, you can try to use yours to overrule them. You might get an editor to quash a reporter's story, or get a gang boss to stop his thugs taking down a rival. To do this you must make a roll using Manipulation + Contacts (difficulty 8). If you can get more successes than the Contacts rating of your opponent, their contacts fail to come through for them. 121]==],
				},
				["Bioluminescence"] = {
					en = [==[Lore of the Clans, p. 238


Bioluminescence


Perhaps through biological expertise, or perhaps by unlocking something primordial within, you have accessed the secrets of bioluminescence. Using Vicissitude, you may grant yourself (through Malleable Visage) or others (via Fleshcraft — both as per V20, p. 241) the ability to emit a soft glow. With muscle control and practice, you can control the color and pattern of the illumination. This can light a soft glow in the dark, create beautiful displays, or even act as a primal form of communication. Some Fiends grant their ghouls or childer bioluminescence, developing an eerily nuanced and wordless language with their thralls and broods. Only characters with at least one dot of Vicissitude may purchase this Merit.]==],
				},
				["Blasphemous Pact"] = {
					en = [==[Dark Ages Tome of Secrets, p. 108


Blasphemous Pact


In your recent past or long ago, you knowingly made a pact with a being of unadulterated wickedness. Whether the being was a demon of immense power, a reaper wishing to claim your soul, or some greater monster seeking knowledge in exchange for its foul blessing, your pact resulted in your receipt of a gift. This gift allows you to stave off the Curse of Caine, to a degree. Perhaps your gift allows you the ability to walk in daytime while under cover. Maybe you can eat uncooked meat, still running with blood. The gift may allow you to breed. The dark nature of the pact means all this comes at a price. The entity with whom you consort will one night take everything you own, and bring it to ruin. It will destroy all relationships, any reputation, and any good you may achieve. It will claim your soul, and likely the souls of those close to you. Speak to the Storyteller about the nature of your gift. The Storyteller will decide on the price you must pay.]==],
				},
				["Blessed by St. Gustav"] = {
					en = [==[Lore of the Clans, p. 261


Blessed by St. Gustav


Many Ventrue antitribu replace their traditional affinity for Presence with an aptitude for Auspex by means of the ignobilis LORE OF THE CLANS

Prayer to St. Gustav

To the Ventrue antitribu, the Presence

discipline (while useful) is often viewed as

decadent and unworthy of the martial heritage

they imagine for themselves. In contrast, the

Auspex discipline is prized for its power to

grant insights and to see through deceptions.

This ignobilis ritus allows a Ventrue antitribu

to replace Presence with Auspex as a Clan

Discipline. The ritus requires a group consisting

solely of Ventrue antitribu to participate in a

Vaulderie while wearing ceremonial armor and

singing the praises of St. Gustav Mallenhaus, the

founder of the Sabbat Inquisition. The player of

any crusader present who has not yet acquired

any dots in Presence may roll Intelligence +

Occult (difficulty 7), and if the roll succeeds,

she may replace Presence with Auspex as a Clan

Discipline. With five or more successes, the

Storyteller may decide to award the Blessed by

St. Gustav Merit. A character who has already

started learning Presence may attempt this ritus,

but may not swap out his Presence for Auspex

— instead his Presence immediately becomes out-

of-Clan, and the player must pay the difference in

experience points between what the Presence cost

before and what it costs now. ritus known as the Prayer to St. Gustav (see sidebar). For your piety and devotion to the Sabbat cause, you have been especially blessed and have an affinity for both Disciplines.

System: This Merit is identical to Additional Discipline Merit found on V20, p. 494, except that it can only be used to add Auspex as a fourth in-Clan discipline. Only Ventrue antitribu can take this Merit.]==],
				},
				["Blood Flaw Immunity"] = {
					en = [==[Ghouls & Revenants, p. 137


Blood Flaw Immunity


You have discovered that you are resistant to the Clan or bloodline flaws present in the blood you drink. Your domitor might be a lower Generation Nosferatu, who lives in the sewers because her appearance is so hideous, and yet your appearance will not change. Should members of the Tremere or Tzimisce Clans learn of your Blood Flaw Immunity, you may be sought after for further study. After all, if a ghoul's biology is such that you do not suffer as much as your domitor, surely there's a “cure” for the flaws present in every Clan's or bloodline's blood.

This Merit no longer applies if your ghoul or revenant is Embraced.

Used by: All ghouls and revenants]==],
				},
				["Blooded by the Code"] = {
					en = [==[Dark Ages Companion, p. 100


Blooded by the Code


Inducted by a true Salubri Warrior, rather than a mere member

of the bloodline, the young Cyclops possesses supernatural might

far in excess of what she might otherwise wield. She is allowed

to purchase and use the Discipline power Song of the Blooded

at normal cost (40 experience points), irrespective of Generation.

No other Valeren Discipline power may be purchased unless

the Salubri otherwise qualifies for it. Additionally, her Status is

accounted as two higher when interacting with other Salubri.

charitable, they disrupt the social order wherever they do not

define it. They exist according to their own codes, and worse,

they rarely betray one another. The loyalty of the Clan to other

members is yet another reason to distrust the Clan of Seekers.

More so than other Clans, the Ravnos are family, and you betray family at your own peril. Alone among the Clans of India, the Seekers Embrace their childer across caste lines, deferring not to mortal castes but to a structure of bloodlines already extant within their own Clan. Clan Ravnos refers to these lineages as jati, a term encompassing both caste division and family group.

Most jati travel together, roving bands of sires and childer bound together by common ancestry and caste origin. Sometimes, they will form semi-permanent enclaves within Cainite society, ensconcing themselves within cities along trade routes so that traveling Clanmates will be able to find a kindred bloodline.]==],
				},
				["Blush of Health"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Blush of Health


You look more hale and healthy in appearance than other vampires, allowing you to blend with human so- ciety much more easily. You still retain the color of a living mortal, and your skin feels only slightly cool to the touch.]==],
				},
				["Boon (1)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Boon (1)


Someone owes you a favor. The vampire in your debt might be the lowliest neonate in the city or might be the Prince herself; it all depends on how many points the Merit costs. You only have that single favor owed you (unless you take the Merit multiple times), so us- ing it properly is of paramount importance. Depending on status and other factors, the vampire who owes you a favor may well resent his debt, and might go out of his way to “settle” it early — even going so far as to create situations from which he must “rescue” you and thus clear the slate.]==],
				},
				["Boon (2)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Boon (2)


Someone owes you a favor. The vampire in your debt might be the lowliest neonate in the city or might be the Prince herself; it all depends on how many points the Merit costs. You only have that single favor owed you (unless you take the Merit multiple times), so us- ing it properly is of paramount importance. Depending on status and other factors, the vampire who owes you a favor may well resent his debt, and might go out of his way to “settle” it early — even going so far as to create situations from which he must “rescue” you and thus clear the slate.]==],
				},
				["Boon (3)"] = {
