Boon (4)


Someone owes you a favor. The vampire in your debt might be the lowliest neonate in the city or might be the Prince herself; it all depends on how many points the Merit costs. You only have that single favor owed you (unless you take the Merit multiple times), so us- ing it properly is of paramount importance. Depending on status and other factors, the vampire who owes you a favor may well resent his debt, and might go out of his way to “settle” it early — even going so far as to create situations from which he must “rescue” you and thus clear the slate.]==],
				},
				["Boon (5)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Boon (5)


Someone owes you a favor. The vampire in your debt might be the lowliest neonate in the city or might be the Prince herself; it all depends on how many points the Merit costs. You only have that single favor owed you (unless you take the Merit multiple times), so us- ing it properly is of paramount importance. Depending on status and other factors, the vampire who owes you a favor may well resent his debt, and might go out of his way to “settle” it early — even going so far as to create situations from which he must “rescue” you and thus clear the slate.]==],
				},
				["Boon (6)"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Boon (6)


Someone owes you a favor. The vampire in your debt might be the lowliest neonate in the city or might be the Prince herself; it all depends on how many points the Merit costs. You only have that single favor owed you (unless you take the Merit multiple times), so us- ing it properly is of paramount importance. Depending on status and other factors, the vampire who owes you a favor may well resent his debt, and might go out of his way to “settle” it early — even going so far as to create situations from which he must “rescue” you and thus clear the slate.]==],
				},
				["Brahmin"] = {
					en = [==[Lore of the Clans, p. 182


Brahmin


As a member of the Brahmin jati, you are a priest, artist, teacher, or other pillar of society. Perhaps you keep the lore of the Clan, or perhaps you act as an advisor to other Ravnos in need of wisdom. Once per session, if you fail an Academics or Expression roll, you may immediately reroll it.

You do not have to purchase this Merit to be a member of the Brahmin jati, but only members of the Brahmin jati may have this Merit.]==],
				},
				["Broken Bond"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Broken Bond


You were once blood-bound but have secretly slipped the leash, and you are free to act as you will once more. Your regnant has no idea that you are not in fact bound, VAMPIRE THE MASQUERADE 20th ANNIVERSARY EDITION and continues to treat you as if you were. At Storyteller discretion, the experience of having been bound once may render you immune to ever being enthralled again. Sabbat vampires cannot take this Merit.]==],
				},
				["Bruiser"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Bruiser


Your appearance is sufficiently thug-like to inspire fear (or at least disquiet) in those who see you. While you're not necessarily ugly, you do radiate a quiet men- ace, to the point where people cross the street to avoid passing near you. All Intimidation rolls against those who have not demonstrated their physical superiority to you are at -1 difficulty.]==],
				},
				["Bullyboy"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Bullyboy


You're part of the brute squad the local Sheriff or Bishop calls on when he needs some muscle. As a result, you get in on action that others miss entirely, score points with those in power, and occasionally get a chance to act outside of the law. How far outside the law you can go depends on circumstance and how much the vampire you report to likes you.]==],
				},
				["Burning Aura"] = {
					en = [==[Book of Secrets, p. 68


Burning Aura


To those who can sense it, your aura burns with amazing brilliance and clarity. Even folks who can't actually perceive this bright corona of energy realize that you're “different.” Entities that can read your aura react accordingly; some will treat you with uncommon respect, while others will view you as a nice meal. The nature of your aura cannot be hidden easily (+2 to the difficulty of any attempt to do so), and while this is a dreadful disadvantage for, say, a Nephandus, people who prize forthright integrity may reduce their difficulties by 2 when they're trying to make an impression that's in accord with that vivid aura and affecting characters who can sense it.

Assuming that you employ these optional Traits, your Resonance and Synergy each get a vivid, one-dot boost from this Merit – see Chapter Three, pp. 133-134, for details. For aura colors and tones, see Mage 20, p. 507.]==],
				},
				["Call of the Sea"] = {
					en = [==[Lore of the Clans, p. 122


Call of the Sea


There is something about the sea that makes you feel at home. You are in tune with the tides and rhythm of the ocean. When on a boat in the ocean or on a river, you may add a die to all your dice pools except for Disciplines.]==],
				},
				["Calm Heart"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Calm Heart


You are naturally calm and do not easily fly off the handle. You receive two extra dice when attempting to resist a frenzy. Brujah may not take this Merit.]==],
				},
				["merit|Cannibal"] = {
					en = [==[Lore of the Clans, p. 106


Cannibal


Most vampires can't eat food, and even those who can force it down, don't gain sustenance from it. Like them, you still can't stomach the crap most mortals eat. Human meat, on the other hand, brings you great joy. It can be baked, fried, or even raw, and you can tuck right in, and even gain sustenance. Even other vampires look askance at Kindred who devour their prey, though the Dunsirn applaud your respect for tradition.

In addition to the blood points every human can provide, you can cannibalize a mortal and gain even more. An average human can provide up to seven helpings of meat (one per health level). Each helping provides you with one blood point.]==],
				},
				["Cast-Iron Stomach"] = {
					en = [==[Book of Secrets, p. 36


Cast-Iron Stomach


You can eat more or less anything without gagging. Squirming bugs, synthetic goop, a freshly-gutted carcass with the innards still hanging out… hey, it's all food, so chow down! Anything you can physically devour and digest is yours for the eating. This Merit does not in any way protect you from the effects of said substances (rotted meat can still poison you), but you can keep down a meal that would make the average person puke from its mere proximity… an especially useful gift if you have the supernatural Flaw: Bizarre Hunger (see p. 87).]==],
				},
				["Catlike Balance"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Catlike Balance


You possess an innately perfect sense of balance. Characters with this Merit reduce difficulties of all bal- ance-related rolls (e.g., Dexterity + Athletics to walk along a narrow ledge) by two.]==],
				},
				["Celestial Affinity"] = {
					en = [==[Book of Secrets, p. 70


Celestial Affinity


You get along especially well with a certain type of spirit entity. Depending upon your practice, you might relate well with nature spirits, High Umbral Courtiers, Digital Web en- tities, the Restless Dead, the Loa, angelic or demonic beings, and so forth.

When you're dealing with entities within a single selected category, you reduce the difficulty of your summoning and negotiation rolls by -2. (See the section that deals with Sum- moning, Binding, Bargaining, and Warding in How Do You DO That?, pp. 90-95.) This bonus does not apply to attempts to bind or ward against such beings, as it's based upon goodwill, not force. It does, however, apply to the Arete rolls when casting the summoning Effect (within the normal modifier limits, as usual), because the entities in question are more inclined to show up when you call upon them.

For three additional points per category, you may add another category of spirits, assuming that your practice favors an affinity for such spirits. (A BCD Void Engineer “ghost-buster,” for example, could not purchase an Affinity for ghosts, though a necromancer could certainly do so.) If you abuse this goodwill, as one might imagine, this bonus, and the Merit, both go away – and might wind up being replaced by a Flaw like Immortal Enemy (p. 93) if your mage behaves in an especially foolish manner.]==],
				},
				["Celestial Attunement"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 422


Celestial Attunement


You innately

know what time of day it is and are able to accurately

guess the hour of sunrise and sunset within a few min-

utes. With a moment's concentration, you may also

estimate the position of the stars, even without the

aid of a star chart.]==],
				},
				["Chorus Trained (3)"] = {
					en = [==[Lore of the Bloodlines, p. 3


Chorus Trained (3)


The character has learned how to use the Fugue to tune in to her sisters and work together with far more efficiency. For 3 points, this Merit grants the character 2 extra dice to any Melpominee dice pool when using the power with another character with this Merit. For 5 points, the bonus 2 dice can be added for any action being performed by a partner with this Merit, such as making art or even fighting together.]==],
				},
				["Chorus Trained (5)"] = {
					en = [==[Lore of the Bloodlines, p. 3


Chorus Trained (5)


The character has learned how to use the Fugue to tune in to her sisters and work together with far more efficiency. For 3 points, this Merit grants the character 2 extra dice to any Melpominee dice pool when using the power with another character with this Merit. For 5 points, the bonus 2 dice can be added for any action being performed by a partner with this Merit, such as making art or even fighting together.]==],
				},
				["Circumspect Avatar"] = {
					en = [==[Book of Secrets, p. 69


Circumspect Avatar


You've never seen your Avatar, and probably doubt that such a thing exists. Sure, you have a shadow, and a reflection, or maybe a little dog who's followed you around since you were a kid and seems no older even though he should have died of old age years ago, but an Avatar? Nah – that's a buncha New Age hippie crap! You have yet to encounter any such thing, you don't go on “seekings” or whatever they're called, and you get your metaphysical insights the same way any normal person does: through everyday events in the everyday world.

Essentially, this Merit grants a “silent” Avatar – one that, for whatever reason, does not hound or guide your character but merely drops hints, cues, and clues that the mage either figures out or doesn't figure out on her own. Seekings and Epiphanies take place in the physical realm, typically as puzzles and dilemmas that happen to be related to issues that the mage needs to sort through in order to advance to the next level of understanding. During such situations, the Avatar may indeed appear (possibly even manifest – see the Merit: Manifest Avatar, p. 71), but only as some apparently mundane person, creature or thing, not as an obviously paranormal entity. You could, for instance, get a call from your mother that sends you into an introspective mood which, in turn, leads you to figure out an important riddle from your past; Mom, of course, denies even having called you. Huh. So who could that call have been from, anyway? Or did you, perhaps, just imagine it after all?]==],
				},
				["Clan Apostate"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 425


Clan Apostate


Having undergone the Baali Rite of Apostasy, you now belong to a brood. Re- place any one in-clan Discipline with Daimoinon but also gain the Baali clan weakness in addition to your default clan weakness. You still pass for a member of your former clan with relative ease, and anyone you Embrace will also belong to your original clan. You do not lose levels in the Discipline you chose in exchange for Daimoinon, but further levels in that Discipline are purchased at out-of-clan cost.]==],
				},
				["Clan Friendship"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Clan Friendship


One particular Clan (not your own) has a special lik- ing for you. You might have done the Clan as a whole a favor at some point, or perhaps you're just a loud voice in support of their aims. Whatever the case, you're at 2 difficulty on all friendly Social rolls involving mem- bers of the Clan in question. Of course, the reaction your cozy relationship with another Clan is likely to draw from your own Clan leaders is an entirely differ- ent can of worms. Primogen/Bishop Friendship]==],
				},
				["Clear Sighted (Hunter)"] = {
					en = [==[The Hunters Hunted II, p. 141


Clear Sighted (Hunter)


You can see through all levels of Kindred Obfuscate, Chimerstry, and other related Disciplines or supernatural power, with a Perception + Alertness roll against the opposing power's level + 3.]==],
				},
				["Clear Sighted (Mage)"] = {
					en = [==[Book of Secrets, p. 75


Clear Sighted (Mage)


Even without employing your Arts, you have a preternatural gift for seeing things as they are, not as they appear to be. Illusions, disguises, cloaking spells, and other forms of trickery rarely deceive your eyes.

In game terms, you can make a Perception + Awareness roll to see through metaphysical deception powers: vampiric Disciplines, faerie cantrips, werecreature Gifts, Sphere-based illusions, and other powers that are based on deceiving a witnesses' perceptions. This roll works only against powers that deceive the target's perceptions, not against any other form of Gift, Discipline, cantrip, and so forth. (Vampiric Obfuscate, for example, but not Presence or Dominate.)

The difficulty for that roll is generally 5 + the highest Sphere Rank or other level involved in that power; a Forces 2 /Prime 2 illusion, then, would be difficulty 7, while a vampire's Mask of a Thousand Faces (Obfuscate 3) would be difficulty 8. If a character could normally get a roll to see through the illusion (as shown in How Do You DO That?, pp. 129-132), then your character subtracts -3 from her difficulty when trying to do so.

Your clear sight also reduces your difficulty by -3 when you try to see through a disguise, a cloaking spell or device, or other attempts to conceal the truth from an onlooker. It does not, however, allow you to see through darkness, notice stealthing or invisible characters, or otherwise perceive something that you would not be able to see without this Merit; combining this Merit with the physical Merit: Acute Senses, however, could make you a formidably perceptive character.]==],
				},
				["Clear-Sighted"] = {
					en = [==[The Hunters Hunted II, p. 44


Clear-Sighted


Your character is not easily fooled by illusions. When faced with a supernatural illusion, such as those created by Obfuscate, Chimerstry, and the like, you may make a Perception + Alertness roll (difficulty equal to the opposing power's level +3) for your character to see through the effect.]==],
				},
				["Cloak of the Seasons"] = {
					en = [==[Book of Secrets, p. 70


Cloak of the Seasons


Adverse weather does not bother you. Regardless of your clothing or lack thereof, you're essentially immune to the effects of exposure to harsh climates, as described in Mage 20, p. 435. You still need to eat, drink, and breathe – this Merit won't save you from starvation or suffocation – and climate-based obsta- cles (fog, high winds, snowdrifts, ice, etc.) hinder you as badly as they'll hinder anybody else. Aside from outright attacks by the elements, however, you remain untouched by extremes of temperature and climate. You might not always be comfortable, but you'll survive. Cyclic Magick (3 pt. Merit /Flaw)

The strength or weakness of your Arts is tied to some periodic cycle – the phases of the moon, night or day, your menstrual periods, the rise and fall of the stock market, and so forth. At the peak of your cycle, your magick flows most easily; at its nadir, you find it challenging to work with your magick at all.

System-wise, this Trait is both a Merit and a Flaw, granting bonuses at one point in the cycle and penalties on its opposite point. At the highest point, you reduce your casting difficulties by -3 for one hour, while at the lowest point you increase them by +3 for one hour. On either end of that cycle, you subtract or add -1 /+1 to your casting difficulties for each hour on both sides – the surge and the ebb – of that cycle: -2 or + 2 for the two hours on each side of the peak or nadir, -1 or +1 on the two hours on the side of those two hours, and no modifiers during the rest of the time in between. If, for example, Victoria Ashley-Croft bani Flambeau has a peak at midnight and a low at noon, her player would receive a peak modifier of -3 difficulty at midnight, 2 difficulty at 11:00 PM and 1:00 AM, a -1 difficulty at 10:00 PM and 2:00 AM, and no modifiers otherwise, aside from the reverse modifiers (+3 at noon, +2 at 11:00 AM and 1:00 PM, and +1 at 10:00 AM and 2:00 PM) at the opposite end of that cycle.

Naturally, you'll need to decide just what this cycle is when you select this Trait, and then determine what the highest and lowest points of that cycle would be. This Merit must also be tied into your focus – intrinsically connected to the beliefs you hold and the practices you follow. Your choice of instruments is often tied to such cycles too; cycle-bound instruments include celestial alignments, crossroads and crossing-days, formulae and mathematics, group rites, money and wealth, music (peaks and lulls in a song, movements in a symphony, etc.), numbers and numerology, and offerings and sacrifices (“when the stars are right”). A stockbroker will be watching the peaks and ebbs on Wall Street, while a witch pays attention to the cycles of the moon or her blood. By observing your cycles, you'll have a good idea about the best and worst times to use your Arts. And by observing you, your allies and enemies may be able to figure those things out too.]==],
				},
				["Code of Honor"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Code of Honor


You have a personal code of ethics to which you ad- here. The specifics of this code must be worked out with the Storyteller prior to play, and the character must follow it strictly. Characters with this Merit gain two additional dice to all Willpower or Virtue rolls when acting in accordance with their code (e.g., defending the helpless) or when attempting to avoid situations that might force them to violate their code.]==],
				},
				["Cold Read"] = {
					en = [==[Lore of the Clans, p. 142


Cold Read


Whenever you meet someone for the first time, you may spend a number of points of Willpower equal to your Perception. For each point spent, you may ask the Storyteller one question about the character. The Storyteller must either answer truthfully or let you take the Willpower point back to you to avoid answering the question.]==],
				},
				["Coldly Logical"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Coldly Logical


While some might refer to you as a “cold fish,” you have a knack for separating factual reporting from emo- tional or hysterical coloration. You may or may not be emotional yourself, but you can see clearly when others are clouding the facts with their feelings (-1 difficulty on all related rolls).]==],
				},
				["Common Sense"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Common Sense


You have a significant amount of practical, every- day wisdom. Whenever you are about to act in a way contrary to common sense, the Storyteller can make suggestions or warnings about the implications of said action. This is a very useful Merit for beginning players unfamiliar with the game.]==],
				},
				["Computer Aptitude"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Computer Aptitude


You are familiar with and talented in the uses of computer equipment. Other Kindred may not under- stand computers, but to you they are intuitive. All rolls involving computers are at -2 difficulty for you.]==],
				},
				["Concentration"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Concentration


You have the ability to focus your mind and shut out any distractions or annoyances. Characters with this Merit are unaffected by any penalties stemming from distracting circumstances (e.g., loud noises, strobe lights, or hanging upside down).]==],
				},
				["Confidence"] = {
					en = [==[Book of Secrets, p. 55


Confidence


You exude an aura of unshakable authority. Nothing seems to rattle you. Folks defer to you by default, and you expect nothing less. Even when you're making things up off the top of your head, or lying your ass off about your true feelings or intentions, your self-confidence inspires an unusual degree of trust. Cool is your middle name, and the few people who try to get one over on you have a very hard time doing so.

When dice start falling, subtract -2 from the difficulty of all social rolls based upon impressing other characters with your capabilities. Other players, however – the Storyteller included – add +2 to the difficulty of social rolls for characters who try to shake your confidence or shatter your calm.]==],
				},
				["Connoisseur"] = {
					en = [==[Lore of the Clans, p. 261


Connoisseur


Your study of the Auspex Discipline, combined with your rarified tastes, allows you an uncanny empathy and connection to a victim, giving you powerful insights into the character of any whose blood you taste.

System: The character tastes another's blood (potentially risking a blood bond), and player rolls Perception + Empathy (difficulty 6 for mortals or 8 for Kindred). If the blood came from a mortal, each success allows him to learn one of the following: the mortal's Nature, her Demeanor, any Derangements she may possess, whether she is blood bonded, and whether she carries any blood-borne diseases. If the vitae came from a vampire, he can learn all of the previous information, plus anything discoverable with the first level of the Path of Blood (see V20, p. 213). The Ventrue may taste the blood of a mortal who does not fit within his feeding restriction long enough to use this ability, but he must immediately spit it out afterward.

Vampires that do not have Auspex •• cannot take this Merit.]==],
				},
				["Consanguineous Resistance"] = {
					en = [==[Lore of the Clans, p. 106


Consanguineous Resistance


Your character cannot be blood bound by anyone who shares his mortal bloodline. That is, if you were born into the Giovanni family, you cannot be bound by anyone else who was born a Giovanni, though you can still be bound by, say, a Pisanob of the Giovanni Clan, or by Kindred of any other Clan. Similarly, a Dunsirn with Consanguineous Resistance could not be bound by others who were born into the mortal Dunsirn family, but could be bound by a Milliner of the Giovanni Clan.

The Giovanni are extremely suspicious of anyone known to manifest this quirk. Although this blood-borne aberration hasn't been documented, a few savvy Giovanni have a rough idea of what it is and does. It's generally associated with being a rebellious young smartass who needs to be put down. This is not as unfair as it sounds; by the time a bond resistance is really obvious, it's likely because a punishment isn't working. A character who is discovered to have this trait probably earns her sire's hostility at the very least.]==],
				},
				["Controllable Night Sight"] = {
					en = [==[Lore of the Clans, p. 122


Controllable Night Sight


Your night vision is extraordinarily good, even for a vampire. The deepest shadows are like looking into a well-lit room for you. However, in normal light or bright conditions, you have to switch back to less-sensitive vision, or the weakest light quickly blinds you. While your night sight is active, you suffer no penalties for the dark and can see perfectly well. Should you use it in well-lit conditions; you suffer a penalty inversely proportional to the usual penalties for darkness.]==],
				},
				["Court Favorite (1)"] = {
					en = [==[Lore of the Clans, p. 121


Court Favorite (1)


While the Courts of Blood are usually difficult to sway, you have become very good at shifting the balance. A mixture of experience and political empathy allow you to know just the right way to nudge the decision in your direction, or perhaps for that of your client. Any roll made that will affect the decision in a Court of Blood is granted a bonus or penalty (whichever is in your favor) in dice equal to the level you have of this Merit.]==],
				},
				["Court Favorite (2)"] = {
					en = [==[Lore of the Clans, p. 121


Court Favorite (2)


While the Courts of Blood are usually difficult to sway, you have become very good at shifting the balance. A mixture of experience and political empathy allow you to know just the right way to nudge the decision in your direction, or perhaps for that of your client. Any roll made that will affect the decision in a Court of Blood is granted a bonus or penalty (whichever is in your favor) in dice equal to the level you have of this Merit.]==],
				},
				["Court Favorite (3)"] = {
					en = [==[Lore of the Clans, p. 121


Court Favorite (3)


While the Courts of Blood are usually difficult to sway, you have become very good at shifting the balance. A mixture of experience and political empathy allow you to know just the right way to nudge the decision in your direction, or perhaps for that of your client. Any roll made that will affect the decision in a Court of Blood is granted a bonus or penalty (whichever is in your favor) in dice equal to the level you have of this Merit.]==],
				},
				["Court Favorite (4)"] = {
					en = [==[Lore of the Clans, p. 121


Court Favorite (4)


While the Courts of Blood are usually difficult to sway, you have become very good at shifting the balance. A mixture of experience and political empathy allow you to know just the right way to nudge the decision in your direction, or perhaps for that of your client. Any roll made that will affect the decision in a Court of Blood is granted a bonus or penalty (whichever is in your favor) in dice equal to the level you have of this Merit.]==],
				},
				["Court Favorite (5)"] = {
					en = [==[Lore of the Clans, p. 121


Court Favorite (5)


While the Courts of Blood are usually difficult to sway, you have become very good at shifting the balance. A mixture of experience and political empathy allow you to know just the right way to nudge the decision in your direction, or perhaps for that of your client. Any roll made that will affect the decision in a Court of Blood is granted a bonus or penalty (whichever is in your favor) in dice equal to the level you have of this Merit.]==],
				},
				["Critters"] = {
					en = [==[Lore of the Clans, p. 182


Critters


You're excellent with animals — so much so that they constantly seek to befriend you. Wherever you go, the animals are happy to see you, and more often than not, happy to help you when you ask for their aid. You receive a bonus die on Social rolls to affect small animals. Further, animal companions who have had continual interaction with you see you as something of a pet, and occasionally bring you small useful things. Once per game session, animals will bring you a useful piece of information or a small item relevant to events. This item might occasionally play into the individual Ravnos' particular vice, as the animals quickly pick up on what pleases their friend.]==],
				},
				["Cultural Chameleon"] = {
					en = [==[The Hunters Hunted II, p. 141


Cultural Chameleon


You're able to quickly pick up on social cues, local customs, phrases, modes of dress, and other little things particular about a place. If you're able to address those (can change your clothes, able to speak the language, etc.), anyone attempting to discern if you don't belong there suffer a two die penalty. Either way, you receive two extra dice for any action to find others who don't belong somewhere. Isolated Upbringing

Similar to the Inquisition Flaw, p. 123. Social]==],
				},
				["Danger Sense"] = {
					en = [==[Book of Secrets, p. 70


Danger Sense


A heightened state of awareness allows you to sense impend- ing harm. This gift could originate from primal perceptiveness, intense conditioning, spirit voices that warn you of danger, nanotech sensors, or other methods of refined cognizance. Whatever the source of this Merit might be, your Storyteller must make a secret Perception + Alertness roll for you when some otherwise hidden threat is heading toward your character.

The difficulty for this roll depends upon the immediacy of the danger; a distant, abstract sort of danger (like a plot to kill you) is far harder to sense than an onrushing disaster (like a sniper's bullet), and would thus have a higher difficulty (say, difficulty 10 for the plot, difficulty 6 for the bullet). A simple success would tell you that something's wrong, while a large number of successes could pinpoint the nature and location of the threat.

Your Storyteller, of course, is under no obligation to give you objective details about that threat. She could be as vague as “A chill tightens across your scalp,” with perhaps a hint of the direction and nature of the danger's source (“A sudden metallic clicking sound echoes in from behind your right side. What do you do?”).]==],
				},
				["Daredevil"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Daredevil


You are good at taking risks, and even better at sur- viving them. When attempting exceptionally risky non-combat actions (such as leaping from one moving car to another), characters with this Merit add an ad- ditional three dice to their rolls, and negate a single botch die that may result from such a roll. Generally, such actions must be at least difficulty 8 and have the potential to inflict at least three health levels of dam- age if failed.]==],
				},
				["Dark Triad"] = {
					en = [==[Book of Secrets, p. 58


Dark Triad


See Mage 20, p. 643.]==],
				},
				["Darksight"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 425


Darksight


Your character sees in the darkness the way others see in light. Even in the complete absence of light, she sees perfectly. She suffers no penalties for darkness. Additionally, she catches glimpses of the otherworldly. She sees ghosts as if they were material, but only while in the dark. More than a candle's light negates this ability.]==],
				},
				["Dead Zone"] = {
					en = [==[The Hunters Hunted II, p. 151


Dead Zone


Your exposure to death on a regular basis makes it difficult for ghosts to notice that you exist. You are considered to have one dot of Obfuscate (which works in the lands of the dead as well) against wraiths, spectres, and other such beings.]==],
				},
				["Death Grip"] = {
					en = [==[Lore of the Bloodlines, p. 91


Death Grip


Thanks to your connection with death, you have a keen insight few other Kindred possess. When in contact with a dead body, you make a Wits + Alertness roll (difficulty 7). On a success, you intuitively know how the body died. On a failure, you suffer an illusory version of the wound that saps a point of Willpower. On a botch, your body mirrors the wound and hurts itself in the same manner, causing lethal damage equal to the final blow. LORE OF THE BLOODLINES]==],
				},
				["Deathwalker"] = {
					en = [==[Book of Secrets, p. 74


Deathwalker


The Underworld welcomes you. While most Umbral travelers are more or less barred from the Shadowlands and Low Umbra unless they possess special magicks (or have died), you can step sideways into the Dead Lands with a simple ap- plication of Spirit 3. When you do so, your aura assumes the pale tone of death, and you become essentially indistinguish- able from a ghost unless some knowledgeable entity makes a successful Perception + Occult roll (difficulty 7) to see you for what you really are. If the Avatar Storm is still raging in your chronicle, you can pass into the Low Umbra without suffering the Storm's effects.

This sort of “gift” often leaves macabre traces on the mortals it favors. Hence, this Merit is well-suited for the Flaws: Echoes, Uncanny, and Primal Marks. Thanks to their innate ties to the Dead Lands, Deathwalkers, as a rule, view the Otherworlds through the Vidare Mortem, suffer from Morbidity Quiets, and tend to have a rather fatalistic view of life.]==],
				},
				["Debt of Gratitude (1)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 423


Debt of Gratitude (1)


Though he may

grudgingly admit it, an elder is in your debt. At 1 point, the

elder owes you a favor. Work together with the Storyteller

to determine what type of favor is owed and what you

did to earn such a thing. At 3 points, the indebted elder

owes you his unlife. Such an incident is extraordinarily

unusual, so the elder likely despises being beholden to

you. Work with the Storyteller to detail how (and why)

this happened.]==],
				},
				["Debt of Gratitude (3)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 423


Debt of Gratitude (3)


Though he may

grudgingly admit it, an elder is in your debt. At 1 point, the

elder owes you a favor. Work together with the Storyteller

to determine what type of favor is owed and what you

did to earn such a thing. At 3 points, the indebted elder

owes you his unlife. Such an incident is extraordinarily

unusual, so the elder likely despises being beholden to

you. Work with the Storyteller to detail how (and why)

this happened.]==],
				},
				["Deceptive Aura"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Deceptive Aura


Your aura is unnaturally bright and colorful for a vampire. You register as a mortal on all attempts to read your aura.]==],
				},
				["Deceptive Eating"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 420


Deceptive Eating


By some fortune, you

are able to consume and enjoy mortal cuisine, thereby

adding another layer to your guise of mortality. When

applicable, the Storyteller may rule a lower difficulty or

reduced penalties to rolls to convince others that you are

human. You cannot digest or derive nourishment from

normal food, however, and eventually must find a time

and a place to heave it back up.]==],
				},
				["Demonic Patron"] = {
					en = [==[Dark Ages Tome of Secrets, p. 108


Demonic Patron


Your actions drew the attention of a demonic entity. Maybe you deliberately sought it as a means to gain power, or perhaps it wheedled its way into your existence and now won't let go. The entity became a patron of yours, offering guidance when sought and assistance against your foes. One night it will turn on you and demand something. You will be unable to refuse its request. Until that time, your patron counts as three dots in Mentor and two dots in Allies. Profane Trappings]==],
				},
				["Detached"] = {
					en = [==[The Hunters Hunted II, p. 42


Detached


Your hunter has the rare ability to view his psychic abilities as separate from his physical existence and can maintain this distance even under adverse conditions. Wound penalties don't affect the use of Psychic Numina until your character reaches Incapacitated. If he's Incapacitated, then you may spend a Willpower point to use a Psychic Numina power at half the normal dice pool (rounded down). This action may be performed only once per scene, after which the character falls unconscious, so choose last-ditch efforts carefully. Note: This Merit may be used in conjunction only with Psychic Numina.]==],
				},
				["Discerning Palate"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 177


Discerning Palate


Your naturally selective palate allows you to discern specific traits inherent to a sample of blood. With but a taste, you can determine potency, freshness, species, or whether a blood sample is contaminated, as well as attempt to identify the Generation, age, and even Clan of other vampires. If you sample even a single drop of blood, roll Perception + Awareness (difficulty 8).

One success allows you to identify the relative potency and freshness of the blood, a species whose blood you have previously tasted and know to be of a specific kind, the Generation of another vampire within two steps of your own, if the blood is either under one hundred or over one hundred years old, and if it is of your same Clan.

Two successes identifies whether the blood is contaminated by disease or poison, the Generations of vampires within four steps of your own, the approximate age within fifty years (if less than three hundred years old), and any Clan whose blood you've previously tasted.

With three or more successes, you identify specific contaminates you've sampled before, Generations within six steps of your own, the vintage of blood within twenty-five years (if less than six hundred years old), and any Clan as well as family of vampires whose blood you've tasted previously.]==],
				},
				["Disciple of Lazarus / Japheth"] = {
					en = [==[Lore of the Bloodlines, p. 48


Disciple of Lazarus / Japheth


You speak for the powers-that-be within your bloodline, and bear the clean, white death mask of a respected Harbinger lost to one of the historic purges suffered by your people. Most Harbingers of Skulls will listen to what you say, and take your words at face value. This Merit adds two dice to any Social roll when you invoke the name of Lazarus or Japheth.]==],
				},
				["Distracting Aura"] = {
					en = [==[Lore of the Clans, p. 142


Distracting Aura


Reading an aura using Auspex requires the viewer to focus on recurring patterns and colors to detect a target's emotional state. Because of the unique state of your psyche, your aura is even harder to read than most. All uses of Aura Perception are at a +2 difficulty against you.]==],
				},
				["Dracon's Temperament"] = {
					en = [==[Lore of the Clans, p. 238


Dracon's Temperament


You emulate the ideal of Azi Dahaka within and without, to levels visceral and abstract. Your psyche flows with the permutable nature of change. Like the protean Dracon, you are a whirlwind of temperaments. This is not multiple personalities. You are one identity shown through the prism of ever-shifting Natures. No anchor fetters your sense of self. You can be any you.

At the start of each story, you may choose one Personality Archetype to function as your Nature, spending the rest of the story perceiving the world through that perspective. You also regain Willpower according to your new Nature and may be affected by other effects or Discipline powers as per your new Nature as well.]==],
				},
				["Drug Resistance"] = {
					en = [==[Lore of the Clans, p. 67


Drug Resistance


The Setite religion is one fraught with vices, both to compromise enemies and to enlighten initiates. Cultists tend to build up a tolerance to the substances they take directly (if human or ghoul) or through the blood of prey (if Kindred). You are unusually resistant to alcohol, narcotics, and similar addictive substances. You can pretend to be far more under the influence than you are in order to take advantage of an opponent. All rolls to resist the effects of such substances are at -2 difficulty.]==],
				},
				["Dual Affiliation"] = {
					en = [==[Book of Secrets, p. 79


Dual Affiliation


You've been initiated and trained in two different Awakened groups. Perhaps you were a Verbena who gravitated toward the Virtual Adepts, or a Man in Black who sought refuge among the Templars. Whatever your history and affiliations might be, you're intimately familiar with both groups, have connections (not nec- essarily friends) in both groups, and may use and understand the practices, tools and beliefs (in short, the focus) of either group.

Rules-wise, your mage enjoys the benefits of each affilia- tion. If he's a former Technocrat who went over to the mystic side, he can still use technomagick while transcending the usual Technocratic bans regarding Arete and focus. When raising a Sphere, your character gets to use the Affinity Sphere rate for one Sphere per group. His former associates probably don't view him very favorably, though, unless he “cross-trained” within friendly groups, like a Dreamspeaker who went Ecstatic or a Hermetic who joined the Children of Knowledge.

For additional details about this subject, see Chapter Three's Focus FAQ, p. 174.]==],
				},
				["Dynamic Personality"] = {
					en = [==[Lore of the Clans, p. 48


Dynamic Personality


Your natural charisma draws mortals to you like groupies to a rock star. Consequently, it is easier for you to acquire certain Backgrounds related to mortals.

System: In addition to any Backgrounds acquired at character creation or through roleplay, you can purchase new Backgrounds with experience points at the end of each story. The available Backgrounds are Allies, Contacts, Herd, Retainers, and each new dot costs the current rating in experience points.]==],
				},
				["Early Riser"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Early Riser


No one can explain it, but you seem to have the abil- ity to work on less rest than your fellow vampires. You always seem to be the first to rise and the last to go to bed even if you're been out until dawn. Your Human- ity or Path score is considered to be 10 for purposes of deciding when you rise each evening. Vampires with this Merit cannot take the Deep Sleeper Flaw.]==],
				},
				["Eat Food"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Eat Food


You have the capacity to eat food and even savor its taste. While you cannot derive any nourishment from eating regular foods, this ability will serve you well in pretending to be human. Of course, you can't digest what you eat, and there will be some point during the evening when you have to heave it back up.]==],
				},
				["Ecclesial Rank (1)"] = {
					en = [==[The Hunters Hunted II, p. 123


Ecclesial Rank (1)


Though your status as an Inquisitor is a secret outside of the Society of Leopold, you are also an official member of the Roman Catholic Hierarchy. This Merit determines your standing, each point widening the scope of your service and influence. The one-point version grants you the rank of priest, presiding over one parish (and its deacons and laity). The two- point version grants you the rank of Bishop, presiding over one diocese, consisting of many parishes (and their priests). The three-point version grants you the rank of Archbishop, presiding over several dioceses (and their bishops).]==],
				},
				["Ecclesial Rank (2)"] = {
					en = [==[The Hunters Hunted II, p. 123


Ecclesial Rank (2)


Though your status as an Inquisitor is a secret outside of the Society of Leopold, you are also an official member of the Roman Catholic Hierarchy. This Merit determines your standing, each point widening the scope of your service and influence. The one-point version grants you the rank of priest, presiding over one parish (and its deacons and laity). The two- point version grants you the rank of Bishop, presiding over one diocese, consisting of many parishes (and their priests). The three-point version grants you the rank of Archbishop, presiding over several dioceses (and their bishops).]==],
				},
				["Ecclesial Rank (3)"] = {
					en = [==[The Hunters Hunted II, p. 123


Ecclesial Rank (3)


Though your status as an Inquisitor is a secret outside of the Society of Leopold, you are also an official member of the Roman Catholic Hierarchy. This Merit determines your standing, each point widening the scope of your service and influence. The one-point version grants you the rank of priest, presiding over one parish (and its deacons and laity). The two- point version grants you the rank of Bishop, presiding over one diocese, consisting of many parishes (and their priests). The three-point version grants you the rank of Archbishop, presiding over several dioceses (and their bishops).]==],
				},
				["Ecstatic"] = {
					en = [==[The Hunters Hunted II, p. 124


Ecstatic


You are prone to fits of religious ecstasy — stigmata, glossalia (speaking in tongues), visions, and trances. This is a Merit of dubious benefit. While some may distrust you as a religious hysteric, you find high regard among others of the faith as one “touched by God.” Add one die to any Social dice pools when interacting with the Society (and possibly others with similar spiritual beliefs).]==],
				},
				["Ecumenist"] = {
					en = [==[The Hunters Hunted II, p. 124


Ecumenist


The Holy Spirit “bloweth where it listeth.” You understand this. You see the fractal reflections of your God in other religions, and you remain humble in knowing how little of the divine you can know. Where others must brandish the holy symbols of their tradition when using True Faith, you see the supernal spark at the core of beliefs beyond your own, and you are able to use their religious icons and holy ground when confronting the supernatural. Likewise, in your presence, a group of individuals from different religions may pool their True Faith for greater effect. Such a communal pool requires only one person with this Merit. You can be the bridge that connects all faiths as brothers and sisters in the long, dark night of the soul.]==],
				},
				["Efficient Digestion"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Efficient Digestion


You are able to draw more than the usual amount of nourishment from blood. When feeding, you gain an additional point to your blood pool for every two points of blood you consume. This does not allow you to exceed your blood pool maximum.]==],
				},
				["Eidetic Memory"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Eidetic Memory


You remember, with perfect detail, things you see and hear. Documents, photographs, conversations, etc., can be committed to memory with only minor concen- tration. Under stressful conditions involving numerous distractions, you must make a Perception + Alertness roll (difficulty 6) to summon enough concentration to absorb what your senses detect.]==],
				},
				["Elysium Regular"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 487


Elysium Regular


You spend an unusual amount of time in Elysium. You see and are seen to such an extent that all of the movers and shakers of Elysium at least know who you are. Extended time spent in Elysium also gives you ex- tended opportunities to interact with the Harpies and other Kindred of that stature — and they'll know your name when you approach them. This Merit is gener- ally taken by vampires that respect and attend Elysium on a regular basis.]==],
				},
				["Embedded Agent"] = {
					en = [==[The Hunters Hunted II, p. 133


Embedded Agent


You're an accepted member of your intelligence agency, despite any weird side-project you work on. You might be an FBI agent with a sterling record who happens to moonlight for SAD, or an NSA intelligence analyst who just happens to spend a couple of weeks each quarter monitoring chaoscope reports. Because you spend more time around “normal” agents, they accept you as one of their own. Add a bonus die to any Empathy, Leadership, or Investigation rolls when dealing with other members of your agency. You're also the last person anyone would think to name as a “monster hunter,” which keeps you under the radar of otherwise well-informed supernatural creatures.]==],
				},
				["Embraced without the Cup"] = {
					en = [==[Lore of the Clans, p. 218


Embraced without the Cup


For some reason you did not drink the blood of the elders when you were inducted into Clan Tremere. More dangerously, it may have had no effect on you. As a result, you are not bound to the Clan the way most Tremere are. Should it be discovered, it will usually be corrected, but one might almost believe there was some purpose to this lapse, as the Tremere don't make mistakes. Perhaps the Clan has a special task in mind for you, one where you might be forced to act against the Clan to maintain a cover….]==],
				},
				["Enchanting Feature"] = {
					en = [==[Book of Secrets, p. 37


Enchanting Feature


Blessed with magnificent eyes, sleek hair, mighty biceps, preternatural grace, ripped abs, a dazzling smile, or some other standout physical feature, you can enchant people with the raw perfection of that feature. The feature in question doesn't need to be visually obvious, either; maybe you smell good, possess a seductive voice, move with animalistic allure, or enjoy some likewise wondrous physical asset. (Please be tasteful here, folks.)

This Merit takes the place of related Physical Merits such as Enchanting Gaze, Soothing Voice, Graceful, and other potentially similar attributes. Story-wise, this Enchanting Fea- ture becomes a standout part of your character's description. System-wise, you reduce the difficulty by -2 when your character deploys the feature in question as part of some social feat.

If your mage employs his Enchanting Feature Merit as part of his magickal focus (see the Instruments entries for Eye Con- tact, Dance and Movement, Ordeals and Exertions, Sex and Sensuality, Social Domination, and Voice and Vocalizations in Mage 20, Chapter Ten), then you could count this Merit as a personalized unique /specialized instrument (as detailed in Mage 20, pp. 503 and 588). On the plus side, this allows you to reduce certain casting difficulties by -2 when the feature in question is specifically employed in the casting of an Effect. On the not-so-good side, this might get your mage's eyes gouged out, his face marred, his vocal cords cut, or… well, you get the picture… if a particularly ruthless enemy considers that feature to be “the focus of his power.”]==],
				},
				["Enchanting Voice"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Enchanting Voice


There is something about your voice that others cannot ignore. When you command, they are cowed. When you seduce, they swoon. Whether thundering, soothing, persuading, or simply talking, your voice com- mands attention. The difficulties of all rolls involving the use of the voice to persuade, charm, or command are reduced by two.]==],
				},
				["Entrepreneur"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 178


Entrepreneur


Making money comes naturally to you, and you know what it takes to succeed. All rolls involving acquiring money through business dealings have their difficulty reduced by 2.]==],
				},
				["Expert Driver"] = {
					en = [==[Book of Secrets, p. 44


Expert Driver


You were born to drive like a demon wherever the road takes you. All of your driving-roll difficulties are reduced by -2.]==],
				},
				["Extra Sharp"] = {
					en = [==[Lore of the Bloodlines, p. 70


Extra Sharp


All Nagaraja already have sharpened fangs for the purposes of cutting into flesh with ease. A character with this Merit, however, has additional rows of fangs, similar to a shark, each one poised to inflict the most pain possible. Instead of dealing 1 unsoakable lethal damage per bite, they deal 2 lethal instead. Some Nagaraja like this gift since it makes their victims stop squirming much quicker. Others fear it creates a connection to the painful bite of the Giovanni, and may see Nagaraja with this Merit almost as outsiders. Speed Eater (2pt. or 4pt. Merit)

The vampire's jaws have been strengthened to allow for faster devouring of one's prey. For 2 points, he can devour 2 blood points worth of flesh per minute, or he may devour 3 blood points worth for 4 points. Must have at least Stamina 3 in order to gain this Merit. Otherwise, his undead form cannot support the influx of blood and viscera at such a fast pace.]==],
				},
				["Eyes of Shadow (1)"] = {
					en = [==[Lore of the Clans, p. 121


Eyes of Shadow (1)


There is something about your eyes that makes you look dark and dangerous. Making eye contact with you is like staring into the Abyss. It may not be obvious why, but anyone you talk to gets a chill when they meet your gaze. The difficulty for any Intimidation roll is reduced by the number of points in this Merit (to a minimum of 2).]==],
				},
				["Eyes of Shadow (2)"] = {
					en = [==[Lore of the Clans, p. 121


Eyes of Shadow (2)


There is something about your eyes that makes you look dark and dangerous. Making eye contact with you is like staring into the Abyss. It may not be obvious why, but anyone you talk to gets a chill when they meet your gaze. The difficulty for any Intimidation roll is reduced by the number of points in this Merit (to a minimum of 2).]==],
				},
				["Eyes of Shadow (3)"] = {
					en = [==[Lore of the Clans, p. 121


Eyes of Shadow (3)


There is something about your eyes that makes you look dark and dangerous. Making eye contact with you is like staring into the Abyss. It may not be obvious why, but anyone you talk to gets a chill when they meet your gaze. The difficulty for any Intimidation roll is reduced by the number of points in this Merit (to a minimum of 2).]==],
				},
				["Eyes of Shadow (4)"] = {
					en = [==[Lore of the Clans, p. 121


Eyes of Shadow (4)


There is something about your eyes that makes you look dark and dangerous. Making eye contact with you is like staring into the Abyss. It may not be obvious why, but anyone you talk to gets a chill when they meet your gaze. The difficulty for any Intimidation roll is reduced by the number of points in this Merit (to a minimum of 2).]==],
				},
				["Fae Blood"] = {
					en = [==[Book of Secrets, p. 74


Fae Blood


Your veins pulse with the enigmatic blood of the fae. Although not a full changeling, you possess a distant tie to the Dreaming by way of your strange heritage. In Changeling: The Dreaming terms, you're kinain: a mortal human related to their kind. Your Banality rating is low (no higher than 4, and often lower than that), and you remain permanently enchanted in the sense that you perceive, and are affected by, the changeling world. As a default member of that eldritch fellowship, you also tend to get swept up in their odd intrigues, and know an uncomfortable amount about their hidden world.

As with the Merit: Faerie Affinity, this Merit is forbidden to technomancers of all kinds. Their Banality is too high to sustain this gift of the blood.]==],
				},
				["Faerie Affinity"] = {
					en = [==[Book of Secrets, p. 69


Faerie Affinity


Fae beings like you. Drawn by an ineffable appeal, they seek you out and share secrets with you that few mortals even comprehend. System-wise, you lower the difficulty of your social rolls by -2 when you're dealing with changelings and related entities; in return, changelings reduce their difficulty by -2 when they attempt – through whatever method – to obtain Glamour from you, or to enchant you so as to bring you into their ephemeral realm. Story-wise, the Fae tend to favor you over other mortals, even when your temperaments would seem to be at odds with one another. A gruff Nocker, for example, normally has no use for frivolity… but in your case, you silly Cultist, he'll make this one exception!

Technomancers, being considered “banal” in the eyes of the Fae, may not purchase this Merit. Even if they don't be- long to the Technocratic Union, the presence of such mages is metaphysical poison to the Dreaming Ones. (See Changeling: The Dreaming for details about the effects of Glamour and Banality on changelings.)]==],
				},
				["False Reflection"] = {
					en = [==[Lore of the Clans, p. 161


False Reflection


Even when using their Obfuscate abilities, Nosferatu still show up in their true form when noticed by machines, such as cameras or video surveillance. With this ability, the Nosferatu can extend their power to recorded images and media. However, as with Mask of the Thousand Faces, the original image isn't actually changed; it is just that people see it the way the Nosferatu wants it seen. Unfortunately, computers are not so easily fooled: if the image is used for facial recognition software (for instance), the computer will see the Nosferatu's real face and fail to find a match. The Nosferatu has best take care how this power is used, as it may wear off in time. Some archived photos have given librarians a nasty surprise, years after going into storage.]==],
				},
				["Family Support (1)"] = {
					en = [==[Book of Secrets, p. 53


Family Support (1)


Your family knows about your Awakened life – and for the most part, they approve of it. You might belong to an ancestral “fam trad” (a family tradition of magical /occult pursuits), a supportive New Ager-type of clan, an appropriately religious family (that is, relatives who follow the same creed as you do), a wealthy dynasty that backs your current life-choices, and so on. This family could be your proverbial “family of origin” (your blood relations), an adopted “family of choice” (people who are not your genetic kin but who function as your family now), or both. Either way, your family stands behind you. This Merit doesn't extend to major economic help unless you also purchase the appropriate Backgrounds too (Resources, Retain- ers, and so on). Still, it's good to have someplace to call home, and someone to be there when you need them.

The more influential your family, and the more supportive of you they are, the more this Merit costs: (1 point) You've got a “typical” family for your culture,

and their support is mostly emotional although you can

get a few bucks, a favor, and a place to crash when you

need it. (2 points) Your family has status, wealth, and influence.

While they expect you to stand on your own for the most

part, you can still get help if and when you need some. (3 points) A scion of wealth, power, and privilege, you

can call upon favors and influence when need be. Your

clan pulls strings on your behalf even when you don't

ask for help, and people defer to you because of your

heritage.

As anyone who's been born into a wealthy yet dysfunc- tional clan can attest, you can have both Family Support and Family Issues (as the Flaw described below). Your rich dad could be an abusive prick, your loving uncle might be creepily possessive, and Mom's support comes with more strings than a puppeteer's convention. Both Traits could also represent a character whose family of origin is a mess, but whose family of choice supports her.

For the purposes of coincidental magick, a family reflected in this Merit does not count as Sleeper witnesses when their beloved mage casts Effects. That benefit doesn't usually extend to your companions, however, unless they employ the same sort of focus as you do, use magick that fits into your family's world-view, or purchase this Merit to reflect being “adopted” into your family as a childhood friend, a spouse, or an otherwise beloved part of the clan.]==],
				},
				["Family Support (2)"] = {
					en = [==[Book of Secrets, p. 53


Family Support (2)


Your family knows about your Awakened life – and for the most part, they approve of it. You might belong to an ancestral “fam trad” (a family tradition of magical /occult pursuits), a supportive New Ager-type of clan, an appropriately religious family (that is, relatives who follow the same creed as you do), a wealthy dynasty that backs your current life-choices, and so on. This family could be your proverbial “family of origin” (your blood relations), an adopted “family of choice” (people who are not your genetic kin but who function as your family now), or both. Either way, your family stands behind you. This Merit doesn't extend to major economic help unless you also purchase the appropriate Backgrounds too (Resources, Retain- ers, and so on). Still, it's good to have someplace to call home, and someone to be there when you need them.

