For the purposes of coincidental magick, a family reflected in this Merit does not count as Sleeper witnesses when their beloved mage casts Effects. That benefit doesn't usually extend to your companions, however, unless they employ the same sort of focus as you do, use magick that fits into your family's world-view, or purchase this Merit to reflect being “adopted” into your family as a childhood friend, a spouse, or an otherwise beloved part of the clan.]==],
				},
				["Family Support (3)"] = {
					en = [==[Book of Secrets, p. 53


Family Support (3)


Your family knows about your Awakened life – and for the most part, they approve of it. You might belong to an ancestral “fam trad” (a family tradition of magical /occult pursuits), a supportive New Ager-type of clan, an appropriately religious family (that is, relatives who follow the same creed as you do), a wealthy dynasty that backs your current life-choices, and so on. This family could be your proverbial “family of origin” (your blood relations), an adopted “family of choice” (people who are not your genetic kin but who function as your family now), or both. Either way, your family stands behind you. This Merit doesn't extend to major economic help unless you also purchase the appropriate Backgrounds too (Resources, Retain- ers, and so on). Still, it's good to have someplace to call home, and someone to be there when you need them.

