ask for help, and people defer to you because of your

heritage.

As anyone who's been born into a wealthy yet dysfunc- tional clan can attest, you can have both Family Support and Family Issues (as the Flaw described below). Your rich dad could be an abusive prick, your loving uncle might be creepily possessive, and Mom's support comes with more strings than a puppeteer's convention. Both Traits could also represent a character whose family of origin is a mess, but whose family of choice supports her.

For the purposes of coincidental magick, a family reflected in this Merit does not count as Sleeper witnesses when their beloved mage casts Effects. That benefit doesn't usually extend to your companions, however, unless they employ the same sort of focus as you do, use magick that fits into your family's world-view, or purchase this Merit to reflect being “adopted” into your family as a childhood friend, a spouse, or an otherwise beloved part of the clan.]==],
				},
				["Fatalist"] = {
					en = [==[Lore of the Bloodlines, p. 5


Fatalist


The character's study of time has led them to believe that what is done is simply done. Destiny is a fixed path and therefore we are all the slaves of our own futures. As such, nothing can truly be our fault, for nothing is entirely under our control. It therefore becomes a lot easier to excuse themselves from their worst excesses. The character subtracts 2 from the difficulty of all degeneration rolls against losses of Humanity or Path of Enlightenment.]==],
				},
				["Favor (1)"] = {
					en = [==[Book of Secrets, p. 54


Favor (1)


Also known as a Boon, this Merit means that some- body owes you, big-time. You scratched their back, and will eventually call in some scratching of your own in due time. Maybe you aided a Master-level mage… or helped a vampire prince… or did a solid for a wealthy Sleeper, a spirit, a faerie, or a ranking member of the Changing Breeds. Regardless of their identity, this party is more powerful than you are, and can get things done on your behalf that you could not get done yourself.

The value of this Merit depends upon the value of that favor. Minor acts of benevolence cost one point, significant boons are worth two, and a life-debt is worth three. You may purchase several Favors, either from a single party or from several different folks who owe you. A Storyteller may grant this Merit in place of experience points if your character has helped a supporting character and requested, earned or demanded a Favor in return. Once that favor has been performed, however, the Merit is spent. Long-lasting assistance would be counted as a Background like Mentor or Patron, or as one of the allies described in the section about Supernatural Merits.]==],
				},
				["Favor (2)"] = {
					en = [==[Book of Secrets, p. 54


Favor (2)


Also known as a Boon, this Merit means that some- body owes you, big-time. You scratched their back, and will eventually call in some scratching of your own in due time. Maybe you aided a Master-level mage… or helped a vampire prince… or did a solid for a wealthy Sleeper, a spirit, a faerie, or a ranking member of the Changing Breeds. Regardless of their identity, this party is more powerful than you are, and can get things done on your behalf that you could not get done yourself.

The value of this Merit depends upon the value of that favor. Minor acts of benevolence cost one point, significant boons are worth two, and a life-debt is worth three. You may purchase several Favors, either from a single party or from several different folks who owe you. A Storyteller may grant this Merit in place of experience points if your character has helped a supporting character and requested, earned or demanded a Favor in return. Once that favor has been performed, however, the Merit is spent. Long-lasting assistance would be counted as a Background like Mentor or Patron, or as one of the allies described in the section about Supernatural Merits.]==],
				},
				["Favor (3)"] = {
					en = [==[Book of Secrets, p. 54


Favor (3)


Also known as a Boon, this Merit means that some- body owes you, big-time. You scratched their back, and will eventually call in some scratching of your own in due time. Maybe you aided a Master-level mage… or helped a vampire prince… or did a solid for a wealthy Sleeper, a spirit, a faerie, or a ranking member of the Changing Breeds. Regardless of their identity, this party is more powerful than you are, and can get things done on your behalf that you could not get done yourself.

The value of this Merit depends upon the value of that favor. Minor acts of benevolence cost one point, significant boons are worth two, and a life-debt is worth three. You may purchase several Favors, either from a single party or from several different folks who owe you. A Storyteller may grant this Merit in place of experience points if your character has helped a supporting character and requested, earned or demanded a Favor in return. Once that favor has been performed, however, the Merit is spent. Long-lasting assistance would be counted as a Background like Mentor or Patron, or as one of the allies described in the section about Supernatural Merits.]==],
				},
				["Fist of God"] = {
					en = [==[The Hunters Hunted II, p. 124


Fist of God


Some call you “Witch-Hammer,” for your naked hands do grievous hurt to the children of the elder night. All your Brawling damage is considered aggravated against supernaturals. Work with the Storyteller to create a good reason for this rare effect, and how it developed. Only mortals with Humanity of seven or higher may purchase (or keep) this Merit.]==],
				},
				["Force of Spirit"] = {
					en = [==[M20 Sorcerer, p. 107


Force of Spirit


The light of your soul is evident to those around you. You may physically glow, appear divinely beautiful, or perhaps your voice resonates with the music of the spheres. You may spend Quintessence points to reduce the difficulty of a social roll on a one-for-one basis. No difficulty may be lower than two, and none may be lowered by more than three. You must be able to store Quintessence in your own pattern to be eligible for this Merit.]==],
				},
				["Former Ghoul"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 487


Former Ghoul


You were introduced to the Blood long before you were made Kindred. Your long experience as a ghoul gives you insight into and comfort with vampiric soci- ety. You are at -1 difficulty on all Social rolls when in the presence of other neonates (particularly those who haven't been educated by their sires), and have a -1 difficulty on all rolls relating to vampiric knowledge.]==],
				},
				["Foul Blood"] = {
					en = [==[Lore of the Clans, p. 160


Foul Blood


Your blood is vile; in fact, it tastes so disgusting it requires a Willpower roll (difficulty 6) just to avoid gagging and retching after tasting it. If someone is foolish enough to attempt diablerie on you, they need to succeed in three (difficulty 9) Willpower rolls to go through with it. The blood is so disgusting that no one can keep it down long enough to use it to become a ghoul, either.]==],
				},
				["Friend of the Underground"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Friend of the Underground


While you're not a Nosferatu, you know your way around the sewers, tunnels, ducts, subway tubes, and other subterranean passages of your hometown. The lo- cal Nosferatu (and any other creatures dwelling down in the muck) may not actually like you, but they're not inclined to kill you on sight when they see you in their territory. You are at -1 difficulty on any rolls involving the subterranean world (sneaking from place to place underground, finding routes into sub-basements, and so on). Nosferatu cannot purchase this Merit.]==],
				},
				["Friendly Face"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Friendly Face


You have a face that reminds everyone of someone, to the point where strangers are inclined to be well- inclined toward you because of it. The effect doesn't fade even if you explain the “mistake,” leaving you at 1 difficulty on all appropriate Social-based rolls (yes for Seduction, no for Intimidation, for example) when a stranger is involved. This Merit only functions on a first meeting.]==],
				},
				["Fugue Instinct"] = {
					en = [==[Lore of the Bloodlines, p. 26


Fugue Instinct


You can hear warnings and gain insight by listening to the Fugue more deeply. You must forego one of your actions to listen properly to the Fugue within. During this time, you may defend yourself but take no active actions. If you do, then you gain an insight for your next action that grants you +2 dice to whatever dice pool you use.]==],
				},
				["Ghoul"] = {
					en = [==[Book of Secrets, p. 75


Ghoul


The blood of vampiric Kindred has made you something more than human. Willingly or otherwise, you have supped on a vampire's blood, and although you're probably not blood- bound to her service any longer (unless you are), that creature's unnatural vitality has become your own. Trouble is, you need more vitae to sustain your uncanny abilities… and, as many mages have discovered, such blood is exceedingly addictive.

A ghouled character ages very slowly, gets one automatic success on any Strength-based roll, and inflicts one extra die of damage with all hand-to-hand, non-magickal attacks. If your chronicle employs Vampire: The Masquerade rules, your character also has a blood pool, one dot in Potence, and the potential to buy and employ Fortitude, Potence, and an ability from the initiating vampire's clan.

That's the good part; the bad parts involve the constant craving for more vitae, the loss of those supernatural bonuses after roughly a month without vampire blood, several dots in Resonance (or the Echoes Flaw, detailed in Mage 20, pp. 646-647) that reflect the corrupt nature of the undead, and the obvious drawbacks of hanging around with vampires just so you can drink their blood.]==],
				},
				["Green Thumb"] = {
					en = [==[Book of Secrets, p. 69


Green Thumb


Plants flourish from your touch. Although they don't bloom and grow on contact (a wildly paranormal effect which was part of this Merit's original form), they do attain a healthy boost when you work with them. Reduce the difficulty of all non-Arete rolls by -2, and reduce the difficulty of Arete rolls by 1, when you work with plants, trees, and other forms of vege- tation –algae, mold, fungus, seaweed, and the like. Story-wise, your aura pulsates with green vitality, plant matter grows fast and robust in your presence, and your Resonance and Synergy reflect a powerful connection to the green world. A common Merit among Verbena, Bata'a, and other primal mystics, this could also represent a strange acumen for vegetative biomass that certain technomancers enjoy.]==],
				},
				["Groomed for Embrace"] = {
					en = [==[Ghouls & Revenants, p. 129


Groomed for Embrace


Your character has been deemed worthy of the Embrace, and is being prepared for the eventuality through careful, directed training by your future sire. While this Merit does not guarantee when you will be Embraced, your character is aware that you will become a vampire, and you know the identity of your future sire.

The benefits of being Groomed for Embrace are related to your current role as a ghoul, and your future position as a vampire within a specific Clan or bloodline. As such, your role among the ghouls of your domitor's house will be elevated to that of a valued apprentice as opposed to a disposable servant. Some Clans, like the Tremere or the Tzimisce, might track your progress through your academic study of lore, Disciplines, or thaumaturgical rituals. You might not be able GHOULS & REVENANTS to use Vicissitude, for example, but you may be permitted to assist your domitor at her laboratory table. Other vampires might be more careful, and may prepare you to be evaluated by the local prince before proceeding further.

There may be a few drawbacks that your character might encounter over the course of your chronicle. Because you have achieved the dream of many ghouls, you may be subjected to fits of jealous rage or harm by other ghouls. Your domitor might even be aware of this fact, and may have encouraged these feelings to test you to see if you're worthy of becoming a vampire.

Additionally, should this fact become known, you may garner unwanted attention from your future sire's enemies. Since it is most likely your future sire will also be your domitor, you may be kidnapped, spied upon, or pumped for information about your domitor's haven, holdings, and schemes. However, many vampires do not reveal that their ghouls and revenants are being Groomed for Embrace, and keep their intentions secret.

Should you decide to purchase the Groomed for Embrace Merit, you may purchase Benevolent Domitor at a cost of one point, provided you have taken the prerequisite Domitor Background. In this circumstance, you are signaling your Storyteller that your domitor has pledged to become your future sire. You may also, at your Storyteller's discretion, learn one dot in a third Discipline known to your future sire or follow a Path after abandoning your Humanity.

Used by: Camarilla and Sabbat ghouls, as well as some revenants. Independent ghouls may be Embraced, but they would not be Groomed for Embrace due to their status as a pariah among ghouls.]==],
				},
				["Guardian Angel"] = {
					en = [==[Book of Secrets, p. 78


Guardian Angel


A powerful entity is watching over

you, providing advice, assistance, and

occasional protection when things get ugly.

Such aid is beyond your control (perhaps

even beyond your comprehension) and while

this “angel” has certainly supported your best

interests thus far, there could be a terrible price-

tag attached to all this help. You think your

angel is of the better sort, but seriously – have

you read the lore about angels? Sweetness and light are not among their more noted characteristics. From a Merit perspective, this Trait provides occasional rather ironic – an actual angel, for example, watching over an Infernalist mage, or a nature spirit protecting an avowed Technocrat. The helpful party may be waiting for the mage to “see the light,” honoring an ancient vow to the mage's ancestors, leading the protected party toward a new and unexpected Path, or perhaps setting him up for a final revelation that could be more terrible than the things the angel has been driving away.

From a Storyteller standpoint, we recommend playing up the mysterious and potentially frightening nature of this guardian “angel.” Legendary angels tend to be notoriously bloody in their work, and can scare the living hell of mortals even when their intentions are technically righteous. As a Storyteller, determine who is helping the mage out, and why; that information, of course, can be for you to know and your players to wonder about. Whenever the angel manifests, play up the implacable weirdness of such entities, couching their appearances in eerie symbolism and elemental phenomena (winds, fires, earthquakes, and so forth) whenever they appear. (For suggestions, see Mage 20, pp. 356-359 and 363-367.)

Conversely, the angel could be an apparently mundane person or animal who just happens to unleash hell on the mage's behalf. The animal spirits, minions, and elementals described in Mage 20, Appendix I, represent the more sedate end of the guardian angel spectrum; stranger beings could in- clude protoplasmic globs, shimmering energies, horrific beasts, and unnamable things that serve powers best undreamed of. Even if the angel is exactly that – a messenger from the Biblical God – such messengers can be pretty frightening. Check out Ezekiel 1-10, Genesis 3, Revelations 4, and other awe-inspiring manifestations. If the Powers That Be behind this guardian angel are more along the lines of Pagan gods or cosmic horrors, this unearthly Merit could unleash some rather scary things…]==],
				},
				["Half-Life"] = {
					en = [==[Lore of the Bloodlines, p. 4


Half-Life


You're more than just a vampire; you're a wraith in vampire form. Your awareness of the realities of death enables you to spend half the regular experience points cost for increasing Necromancy Paths after the first point, and permits you to move between Shadowlands and Skinlands through the expenditure of a Willpower point. You cannot be controlled as a normal spirit through use of Necromancy, but should other vampires discover what you are, you can expect to be hunted mercilessly. You suffer the same weaknesses and have the same strengths as a vampire, but if viewed with a power such as Aura Perception (V20, p. 135) the aura appears as a double-exposure, with a wavering, translucent humanoid shape merging in and out of yours.]==],
				},
				["Hands of Daedalus"] = {
					en = [==[Book of Secrets, p. 71


Hands of Daedalus


You've got an innate gift for crafting machines and tech- nology. Such devices seem to come to life in your hands, fitting easily into place and functioning with incredible precision once you've worked with 'em. Although this gift does not extend to the ins and outs of software technology, you can work on computer hardware (assuming that you know what you're doing) as naturally as you can tune a '58 Ford.

From a systems standpoint, any rolls you make to craft, repair, invent, or otherwise modify mechanical technologies are at -2 difficulty when you've got the opportunity to put those Hands of Daedalus to work. Tech-based magickal instruments (see the Mage 20 entries for Armor, Devices and Machines, and other hardware-based technologies) and practices (see Craftwork and Hypertech in the Focus and the Arts section of Mage 20, Chap- ter Ten) function, in your hands, as Personalized Instruments (Mage 20, pp. 503 and 587-588) once you've had a chance to get familiar with them… and to have them get familiar with you.]==],
				},
				["Harmless"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 487


Harmless


Everyone in the city knows you, and knows that you're no threat to their plans. While that sort of es- timation may seem insulting, it's also what's kept you from being killed. No one considers you worth their time to deal with, and that low opinion keeps you safe. If you start acting in a way that demonstrates that you are no longer harmless, others' reactions to you will likely change as a result.]==],
				},
				["Haven Affinity"] = {
					en = [==[Lore of the Clans, p. 238


Haven Affinity


You are the land. The land is you. The home soil calls to you. You give to it, and it gives to you. Your connection to the earth of your prime haven grants you an extra die to all dice pools when operating there. It also acts as a mystic beacon, allowing you to home in on its location with a standard Perception + Survival roll (difficulty 6), +1 difficulty when a state or country separates you; +2 if you're halfway across the globe. This applies only to your primary haven.]==],
				},
				["Healing Touch"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Healing Touch


Normally vampires can only seal the wounds they inflict from feeding by licking them. With but a touch, you can achieve the same effect, closing the puncture wounds left by drinking blood.]==],
				},
				["Heart of Needles"] = {
					en = [==[Lore of the Clans, p. 182


Heart of Needles


Your natural abilities with illusions have rendered you particularly jaded and unimpressible. How can anything be as perfect as your own imagination? Because of this, your heart is harder than most, and you have a significant resistance to emotion control. All powers and Social challenges that attempt to manipulate you emotionally are made at a +2 difficulty.]==],
				},
				["Heavy Hands"] = {
					en = [==[Lore of the Bloodlines, p. 37


Heavy Hands


One of the effects of becoming a vampire is strange changes happening to your body. The obvious alterations to your hands have made them tougher, harder, and more impervious to pain. All difficulties for damage rolls using unarmed attacks go down by 1.]==],
				},
				["Heretical Sympathizer"] = {
					en = [==[Dark Ages Tome of Secrets, p. 4


Heretical Sympathizer


You are the protector of a Witch of Echidna, or you possess a trove of their knowledge. Whether you do this with altruistic or selfish aims, you stand to benefit from the cult's permanent support and earn the Orthodoxy's enduring distrust. Depending on the situation leading to your taking this trait, you may be able to court favor with the opposing side by selling out your Gorgon ward and gaining the en- dorsement of the Egyptian Followers of Set. Hunted by the Hierophants]==],
				},
				["Hidden Diablerie"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Hidden Diablerie


The tell-tale black streaks of diablerie do not mani- fest in your aura.]==],
				},
				["Hideaway /Safehouse (2)"] = {
					en = [==[Book of Secrets, p. 55


Hideaway /Safehouse (2)


When you need time to yourself, there's a place you can go to that no one knows about except you. It's small, yeah, and remote enough that your friends and enemies can't find you there. Chances are, it's a secret apartment or condo, a distant cottage, a mobile home, or a literal cave or grove or camping spot where you go to escape the stress of your usual life. It could even be a pocket Realm, accessible only to you and whomever you choose to share it with, should you be foolish enough to trust anyone else with this secret hideaway. Unless you give its location away, however, or wind up getting tracked to it by a dedicated stalker, this little getaway is your personal escape hatch. Use it wisely, and be careful when you come and go!

Unlike the Merit: Property (see below), or the Backgrounds: Chantry, Node, and Sanctum, this discrete hidey-hole isn't expan- sive, elaborate, or innately magickal. That said, it's hidden from most forms of casual detection. You could combine this Merit with Property, Node or Sanctum, although those Traits would need to be purchased in addition to your Hideaway, and their existence must remain secret from other characters. Chantries are social by default, and so cannot also become a Hideaway. This place is stocked up with whatever you would need for a roughly two-week stay, and may, of course, be stocked up for longer periods if you bring in additional supplies. Although you might be traced to your hideaway with magick or other tracking methods, your little retreat is not linked to you by any searchable official channels: bills, lease, mail, Internet services, etc.

Once per story – if events occur which could lead other people to your hideaway, if you do something that could reveal its location, or if someone dedicates time and effort trying to track you down – the Storyteller may roll two dice against difficulty 6. (Yes, this roll is done in secret, so you won't know the results.) If that roll gets at least one success, then your secret remains hidden; one failure means that someone has gotten a clue but not your exact whereabouts; four successive failures reveal the location of your hideaway, and a botch on that roll exposes its location immediately. So long as you continue to cover your tracks, however, this place remains yours and yours alone.

For four points, this Merit could also be purchased un- der the name Safehouse. In this case, it's a secured getaway that features better facilities and protections than a typical Hideaway. Its store of supplies can provide for a dozen or so people for roughly two months, and the Merit includes a small dedicated staff (in game terms, two dots in Retain- ers or four dots in Backup) to maintain that site. Unlike a Hideaway, this area can withstand a minor-league assault, and features up to three offices /work areas, reinforced walls, bulletproof glass, and a vault-like panic room. This safehouse also includes a shielded communications array (-2 to attempts to hack or trace that system), and a simple but effective alarm and security camera system (again, -2 to subversion attempts). The downside is that the Merit is not your property; it belongs to your superiors, and can be taken away from you if you fall out with the folks who foot the bill for it. Generally, a Technocrat in good standing with her superiors can get a Safehouse Merit (or, for especially good service, be awarded with one), but other mages could obtain a similar facility as well.

For six points, your refuge can be both a Safehouse and a Hideaway; in this case, the property belongs entirely to you. Enjoy your Batcave, Mr. Wayne!]==],
				},
				["Hideaway /Safehouse (4)"] = {
					en = [==[Book of Secrets, p. 55


