For six points, your refuge can be both a Safehouse and a Hideaway; in this case, the property belongs entirely to you. Enjoy your Batcave, Mr. Wayne!]==],
				},
				["Hive-Minded (1)"] = {
					en = [==[Lore of the Clans, p. 86


Hive-Minded (1)


Your Animalism works on insects and other

creepy-crawlies in addition to animals. If you

select the two-point version of this merit, your Protean forms may take the form of an insectoid swarm rather than a single creature (though the swarm must be of a size and mechanical equivalent to a wolf or a bat, as appropriate).]==],
				},
				["Hive-Minded (2)"] = {
					en = [==[Lore of the Clans, p. 86


Hive-Minded (2)


Your Animalism works on insects and other

creepy-crawlies in addition to animals. If you

select the two-point version of this merit, your Protean forms may take the form of an insectoid swarm rather than a single creature (though the swarm must be of a size and mechanical equivalent to a wolf or a bat, as appropriate).]==],
				},
				["Holy Aura"] = {
					en = [==[The Hunters Hunted II, p. 124


Holy Aura


No matter the color, your aura burns as a brilliant beacon of religious devotion. Even mortals who cannot see auras are drawn to your presence. Subtract one from the difficulty of all social interaction rolls. Some supernaturals will find this a positive aspect; others, particularly the Kindred, may likely be hostile toward you. Many will believe you possess great power (regardless of the truth).]==],
				},
				["Huge Size"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 480


Huge Size


You are abnormally large in size, at least 6'10” and 300 pounds in weight (well over two meters tall and over 130 kgs). Aside from making you extremely no- ticeable in public, this extra mass bestows an addition- al Bruised health level. Characters with this Merit may also gain bonuses to push objects, open barred doors, avoid being knocked down, etc.]==],
				},
				["Hyperflexible"] = {
					en = [==[Book of Secrets, p. 36


Hyperflexible


You are what's commonly but erroneously known as “double-jointed” (as per the old Merit of that name). In reality, your joints are exceedingly flexible, perhaps due to intense training, magickal augmentation, or the medical condition known as Ehlers-Danlos Syndrome (EDS – see above, as well as the Impediment Flaw, below). Whatever the reason, you can stretch and flex in ways most people cannot.

In game terms, this Merit allows you a -2 reduction in difficulty for rolls that involve physical flexibility – escape attempts, contortions, etc. Your character can also perform uncanny acts of hyperflexibility, as seen in Cirque Du Soleil, butoh dance, and extreme yoga postures.]==],
				},
				["Hyperfocus"] = {
					en = [==[Book of Secrets, p. 45


Hyperfocus


Given time and a lack of distractions, you can focus your mind to an uncanny extent. For every hour spent focusing without distractions on a mundane task (not on a magick-casting roll), you may add one die to your dice pool for each roll made during an extended action (as described in Mage 20, p. 389). This bonus has a limit of three dice, total. So if, for example, Nix has Hyperfocus and spends two hours on a task, zir player adds two extra dice to Nix's dice pool; three hours' focus provide three dice, but four hours of focus keeps those three dice. All two or three dice, however, get used every time Nix's player makes a roll to complete that extended action.

As noted above, this Merit does not assist magickal cast- ing rolls. Due to the time required to focus – and the lack of distractions involved – Hyperfocus doesn't help in combat situations either, although a strategy-minded character could hyperfocus on planning for a battle, but not on fighting it once the combat began. On a similar note, a mage could use Hyperfocus to aid in the mundane elements of a ritual – see Rituals and Mundane Abilities, Mage 20, p. 541.

Extreme hyperfocus is often (though not exclusively) as- sociated with people on the autistic spectrum, although some authorities claim that perseveration (see the Flaw: Mental Lock) is more a more accurate way of looking at that intense form of focus. With or without autism, this Merit comes in handy for Hermetics, technomancers, shamans, and other mages whose practices depend upon extreme dedication to certain tasks.]==],
				},
				["Hypersensitivity"] = {
					en = [==[Book of Secrets, p. 38


Hypersensitivity


Extraordinarily open to physical sensations, you possess a depth of sensitivity most folks cannot conceive of having. A mere sip of wine can reveal its vintage to you; a whiff of smoke betrays the quality (or lack thereof) and origins of its burnt tobacco; a faint touch can conjure up orgasmic ecstasies.

Story-wise, you can easily “fall into” an enjoyable sen- sation, relishing it to a degree far beyond typical human sensitivity. System-wise, you reduce the difficulty by -2 if you're trying to use a Perception + Alertness roll to identify details about a sensation. Assuming that you employ instruments like Bodywork, Drugs, Energy, Eye Contact, Food and Drink, or Sex and Sensuality (and you probably use most or all of them), you can get more “bang for your buck” from such sen- sations, which allows you to employ those instruments faster, and perhaps (Storyteller's option) gives you a -2 reduction to the difficulty of associated Ability rolls. The normal modifier limits still apply.

On the flipside, however, painful sensations and over- stimulation can trigger paralyzing agonies and intense panic. Whenever you experience a painful sensation without your consent (that is, being flogged against your will, subjected to loud music that you didn't wish to hear, or injured by something you didn't want to be hurt by), you must make a Willpower roll to avoid being “dragged under” and stunned by the pain for a turn or two. (See Stunning in Mage 20, p. 417.) That roll's difficulty depends upon the intensity of the pain – from difficulty 4 for a minor annoyance, to difficulty 10 for screaming agony. As any Cultist can tell you, ecstasy is indeed a two-way street!

Although this Merit goes well with Acute Senses, it cannot be taken by a character who's also Insensate to Pain (detailed below).]==],
				},
				["Impressive Restraint"] = {
					en = [==[Lore of the Clans, p. 200


Impressive Restraint


When you haven't fed, it can be torturous to be near mortals. The pounding thrum of blood through their veins does not leave you nearly as tempted as it might other Kindred. When opportunity presents itself, the difficulty of all Self-Control rolls to resist hunger are made against a -2 difficulty. Characters on Paths of Enlightenment that require Instinct cannot take this Merit.]==],
				},
				["Incantation"] = {
					en = [==[Dark Ages Tome of Secrets, p. 4


Incantation


Your character learns a single Incantation. This Merit may be purchased during play several times, each for a new Incantation. This costs six experience points.]==],
				},
				["Indelible (1)"] = {
					en = [==[Lore of the Clans, p. 200


Indelible (1)


Whereas other vampires' bodies return to the state they were in at the Embrace each evening, any body modifications you get after the Embrace remain as they are until you actively spend a Willpower point to return your body to its tabula rasa state. This Merit applies to changes as simple as dyeing or cutting your hair to modifications as complicated as tattoos, piercings, or even small implants.

If the Merit only allows for cosmetic alterations, it is worth 1 point. If it allows for more utilitarian alterations, such as RFID implants that activate certain electronic devices, then it is worth 2 points.]==],
				},
				["Indelible (2)"] = {
					en = [==[Lore of the Clans, p. 200


Indelible (2)


Whereas other vampires' bodies return to the state they were in at the Embrace each evening, any body modifications you get after the Embrace remain as they are until you actively spend a Willpower point to return your body to its tabula rasa state. This Merit applies to changes as simple as dyeing or cutting your hair to modifications as complicated as tattoos, piercings, or even small implants.

If the Merit only allows for cosmetic alterations, it is worth 1 point. If it allows for more utilitarian alterations, such as RFID implants that activate certain electronic devices, then it is worth 2 points.]==],
				},
				["Inner Knight"] = {
					en = [==[Book of Secrets, p. 77


Inner Knight


In your heart of hearts, you're a hero. While your com- panions work toward their own selfish ends, you embody a higher purpose. This purpose guides you in uncanny ways that feel, at times, as if you're being moved by a force greater than yourself – a noble force, naturally, but one that transcends even your personal Enlightenment. In dreams, you see yourself as a Warrior of Reason, a Champion of Truth. A paladin. A genius. A knight of everything that is worth defending.

Intended more for Technocratic operatives and skeptical technomancers than for mages who accept reincarnation as a metaphysical truth, this Merit grants you special gifts when it seems like all hope has been lost. These gifts allow you to… access Traits you don't possess, as per the Background:

Dream (at a rating of 5) but without entering a trance; add five temporary points to your Willpower Trait, to

use during that “hope is lost” crisis; …and perhaps recall things from a previous life that the

character could not possibly have known – a language

she does not know, an escape route in a place he's never

visited, a person they've never met before, and so forth.

These boosts last only through the current scene, but include a burst of vitalizing energy and a sense of your inner hero coming through to save the day again.

This isn't the sort of thing you talk about, of course, especially not if you're an agent of the Technocratic Union. The benefits, though, cannot be denied, even if their source is clearly… well, improbable, at best. And while this Merit was originally created for the sourcebook Guide to the Technocracy, any mage with a sense of higher purpose can take it. Just remember that the biggest difference between a knight and a murderer is the side of his sword you happen to be on at the time.]==],
				},
				["Inner Strength"] = {
					en = [==[Book of Secrets, p. 45


Inner Strength


Faced with adversity, you prevail. System-wise, this Merit reduces the difficulty of Willpower rolls by -2 when you struggle against apparently overwhelming odds.]==],
				},
				["Innocent"] = {
					en = [==[The Hunters Hunted II, p. 142


Innocent


You are always thought of in the most positive light, unless evidence exists to prove otherwise. If you do something wrong and the act is not easily attributed to you, it will most likely be blamed on someone else. This does not mean that you are “an innocent” — it just means everyone thinks you are.]==],
				},
				["Inoffensive to Animals"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Inoffensive to Animals


With rare exceptions, animals usually despise the Kindred. Some flee, others attack, but all dislike being in the presence of a vampire. You have no such prob- lem. Animals may not enjoy being in your company, but they don't actively flee from you. VAMPIRE THE MASQUERADE 20th ANNIVERSARY EDITION]==],
				},
				["Insensate to Pain"] = {
					en = [==[Book of Secrets, p. 38


Insensate to Pain


Nothing hurts until it kills you. Okay, it probably does hurt, but not enough to slow you down. Wound penalties do not affect your character at all; until she dies, she usually functions with her full dice pools intact. This Merit does not in any way change the way in which she takes damage – for that Merit, see below – but it radically changes the way said damage affects her ability to get things done.

There is, of course, a downside to all this: Pain tells us that we're not functioning properly and should probably stop while we're ahead. And so, you'll also do stuff like burn yourself by accident, try to walk on broken legs, and notice cuts only when the blood is seeping through your shirt. Although pain won't slow you down, shattered bones and organs will. Injuries that inflict significant physical im- pairment (crushed legs, broken skull, gouged-out eyes, etc.) supersede your usual immunity to dice-pool penalties due to wounds, and you might inflict further lethal injury upon yourself (Storyteller's option) if you keep going after your body tries to tell you to stop.]==],
				},
				["Instrument of God"] = {
					en = [==[Lore of the Clans, p. 123


Instrument of God


Your self-confidence comes not from a belief in your own abilities, but due to a direct manifesto from the Lord. You have a divine purpose and He works through you, even though your goals may seem anything but holy. Whether it is because of you powerful will or an actual connection to the divine, you gain three additional dice to resist the powers of True Faith when they are used against you, including soaking damage from True Faith abilities. Uncontrollable Night Sight]==],
				},
				["Inter-Agency Liaison"] = {
					en = [==[The Hunters Hunted II, p. 133


Inter-Agency Liaison


You work for two agencies at the same time. Either you're a liaison officer between the two agencies — Homeland Security provides a handy cover for the CIA or NSA to poke their noses into the FBI and vice versa — or your current employers don't know who you really work for. Either way, you can draw on the intelligence and resources of both agencies when you need to. You must purchase the Rank Background for each agency separately, and your Rank at your “home” agency must be equal to or greater than your Rank at your new agency.]==],
				},
				["Introspection"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Introspection


You have keen insight into the ulterior motives of all your actions. Through this nightly exercise, you also have incredible insight into the underlying motives of others' actions. Add two dice to your Perception dice pool when you must take an action against someone with the same Nature or Demeanor as you.]==],
				},
				["Iron Will"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Iron Will


When you are determined and your mind is set, noth- ing can thwart you from your goals. Characters using Dementation, Dominate, or any other mind-altering magic, spell, or Thaumaturgy path against your charac- ter are at +3 difficulty.

Elder levels of powers like Dementation and Domi- nate may overwhelm even this resistance. Against Level Six powers, the expenditure of a Willpower point through Iron Will only raises the difficulty of the Disci- pline roll by two. Against Level Seven powers, the dif- ficulty is increased by only one. Level Eight and higher powers cannot be resisted with Iron Will.

This Merit does not affect Presence or other powers dealing with the emotions. Characters will Willpower scores below 8 cannot take this Merit.]==],
				},
				["Jack-of-All-Trades"] = {
					en = [==[Book of Secrets, p. 45


Jack-of-All-Trades


You know a little about a lot. When attempting to make a roll using a Skill (not a Talent) that your character does not possess, you don't suffer the usual penalty. (See Skills, Mage 20, p. 279.) If you're trying to use a Knowledge your character does not possess, you can still make the roll but with an addition of +2 to the normal difficulty. (See Knowledges, Mage 20, p. 283.)

Because Talent Traits represent innate gifts honed by practice, this Merit does not grant access to Talents that your character does not possess.]==],
				},
				["Judge's Wisdom"] = {
					en = [==[Book of Secrets, p. 46


Judge's Wisdom


Through firm self-discipline, you have mastered your emotions to Vulcan perfection. No passion-based assault can rattle your judgment, and the base attacks of heart-twisting fiends have little hold on you. Rules-wise, you remain immune to Mind- or Life- based Effects that influence emotions (as detailed in How Do You DO That?, pp. 60 and 120-122), and can shrug off the vampiric Discipline of Presence unless that bloodsucker has at least six dots in that Discipline. Emotion-based powers from werecreatures, faeries, and other such creatures cannot affect you, although you can still be possessed, mind-controlled, enchanted, and otherwise bent or broken so long as the assault is not based on wrangling an emotional response from your perfect serene command.]==],
				},
				["Kashaph"] = {
					en = [==[Rites of Blood, p. 100


Kashaph


The term kashaph is of ambiguous meaning, based on a Hebrew root word for “mutter,” and implying spoken sorcery and incantations. The term is used in the Old Testament to condemn the practitioners of witchcraft. True kashaph has long been extinct — save among the Inconnu. Kashaph is an enchanted language, and cannot be “decoded” by modern linguistics or cryptography. The Inconnu use kashaph to communicate secretly, and also as a method of identifying one another.

New members of the Inconnu are not taught kashaph by normal means. It cannot be studied, nor learned like a conventional language. Instead, members are indoctrinated into the society through an elaborate ritual during which the language of kashaph is inscribed upon their soul. Once “learned” in this way, the language may be spoken, not written (there is no written form, and the sounds cannot be accurately captured by phonetic scribblings), and only another individual with this merit has the capacity to understand the words said in the language of kashaph.]==],
				},
				["Keys to the Library (1)"] = {
					en = [==[Lore of the Clans, p. 218


Keys to the Library (1)


You have one of the most sought after positions in the chantry: a librarian. It is one of your duties to catalogue and maintain the magical lore kept in your chantry. This means you have complete access to it, and get to decide who can see it and who can't. A vast array of rituals and Thaumaturgical knowledge resides here, making it simple to learn many of the secrets of magic. No matter how restrictive your chantry, you have complete access to the library for research. The cost of this merit is the same as the chantry's Library rating (see pp. 221-222).]==],
				},
				["Keys to the Library (2)"] = {
					en = [==[Lore of the Clans, p. 218


Keys to the Library (2)


You have one of the most sought after positions in the chantry: a librarian. It is one of your duties to catalogue and maintain the magical lore kept in your chantry. This means you have complete access to it, and get to decide who can see it and who can't. A vast array of rituals and Thaumaturgical knowledge resides here, making it simple to learn many of the secrets of magic. No matter how restrictive your chantry, you have complete access to the library for research. The cost of this merit is the same as the chantry's Library rating (see pp. 221-222).]==],
				},
				["Keys to the Library (3)"] = {
					en = [==[Lore of the Clans, p. 218


Keys to the Library (3)


You have one of the most sought after positions in the chantry: a librarian. It is one of your duties to catalogue and maintain the magical lore kept in your chantry. This means you have complete access to it, and get to decide who can see it and who can't. A vast array of rituals and Thaumaturgical knowledge resides here, making it simple to learn many of the secrets of magic. No matter how restrictive your chantry, you have complete access to the library for research. The cost of this merit is the same as the chantry's Library rating (see pp. 221-222).]==],
				},
				["Keys to the Library (4)"] = {
					en = [==[Lore of the Clans, p. 218


Keys to the Library (4)


You have one of the most sought after positions in the chantry: a librarian. It is one of your duties to catalogue and maintain the magical lore kept in your chantry. This means you have complete access to it, and get to decide who can see it and who can't. A vast array of rituals and Thaumaturgical knowledge resides here, making it simple to learn many of the secrets of magic. No matter how restrictive your chantry, you have complete access to the library for research. The cost of this merit is the same as the chantry's Library rating (see pp. 221-222).]==],
				},
				["Keys to the Library (5)"] = {
					en = [==[Lore of the Clans, p. 218


Keys to the Library (5)


You have one of the most sought after positions in the chantry: a librarian. It is one of your duties to catalogue and maintain the magical lore kept in your chantry. This means you have complete access to it, and get to decide who can see it and who can't. A vast array of rituals and Thaumaturgical knowledge resides here, making it simple to learn many of the secrets of magic. No matter how restrictive your chantry, you have complete access to the library for research. The cost of this merit is the same as the chantry's Library rating (see pp. 221-222).]==],
				},
				["King or Queen of Shadow"] = {
					en = [==[Lore of the Clans, p. 122


King or Queen of Shadow


It is hard to hold onto your Humanity within the Sabbat, or even simply as a vampire. However, you draw strength from your ability to empathize with the kine. Any degeneration checks you make while on Path of Humanity reduce their difficulty by two.]==],
				},
				["Kshatriya"] = {
					en = [==[Lore of the Clans, p. 182


Kshatriya


You are a member of the Kshatriya jati; perhaps you are a warrior, a descendant of rulers, or a member of the military. Your role is to protect the Ravnos in war, and govern in peace. Once per session, you regain a Willpower when you successfully use a combat maneuver (see V20, pp. 274-278).

You do not have to purchase this Merit to be a member of the Kshatriya jati, but only members of the Kshatriya jati may have this Merit.]==],
				},
				["Language"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Language


You know a language in addition to your native one. You can take this Merit multiple times, each reflecting a different language.]==],
				},
				["Lawman's Friend"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Lawman's Friend


For whatever reason (maybe your winning smile or perhaps just your superb groveling technique), the lo- cal Sheriff or Bishop in charge of discipline likes you. He's inclined to overlook your minor trespasses and let you in on things you're not supposed to know about. He even gives you warnings about occasional crack- downs and times when the higher-ups aren't feeling generous. Of course, abusing this connection might well turn a friendly vampire into an enemy — and the change might not be apparent until it's too late.]==],
				},
				["Legacy"] = {
					en = [==[The Hunters Hunted II, p. 151


Legacy


Your character comes from a lineage of hunters; either a family responsibility has been passed down, or your character is considered a “successor” to a particularly famous or successful hunter of the past. When you purchase the Contacts Background, you may double the number of specific contacts you receive for each dot. Alternatively, you can purchase the Artifact or Reliquary Background to reflect a powerful heirloom. Supernatural]==],
				},
				["Legendary Attributes"] = {
					en = [==[Book of Secrets, p. 77


Legendary Attributes


Gifted with the strength of Shango or the beauty of Lucifer, you may exceed the human capacity for one Attribute Trait. That Trait is not automatically higher than usual (you still need to spend points to raise the favored Attribute), but you may purchase up to six dots in a given Attribute for your character, exceeding the usual limit of five dots.

Beyond that higher maximum, you also get one heroic capability that's linked to that Attribute. The Shango-strength mage might always inflict at least one health level of damage with hand-to-hand blows, while the Luciferian seducer could score an automatic success whenever he tries to charm someone who ought to know better. These bonuses are always subject to Storyteller approval, however, and they don't kick in until you reach six dots in the given Trait. Not even Lucifer, after all, possessed his full charm when he was just a little devil…]==],
				},
				["Legerdemain"] = {
					en = [==[Lore of the Clans, p. 182


Legerdemain


You're extremely good at sleight of hand and other physical tricks. Difficulties when using Subterfuge for physical trickery, shell games, card tricks, and so forth, are decreased by two.]==],
				},
				["Lesser Mark of the Beast"] = {
					en = [==[Lore of the Clans, p. 87


Lesser Mark of the Beast


Common to the Gangrel known as the Knights of Avalon, you are able to control how your Beast manifests more than others do. Whenever you would gain an animalistic feature (V20, p. 55), roll your current Willpower (difficulty 12 - Humanity rating, maximum 9). If successful, you manage to channel your humanity to avoid gaining an animalistic feature. However, your Beast is further from you, making you at +2 difficulty to rolls involving Animalism or Protean (or combo Disciplines involving those powers) for the rest of the evening. Vampires on a Path of Enlightenment lose all access to this Merit.]==],
				},
				["Light Sleeper"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Light Sleeper


You can awaken instantly at any sign of trouble or danger, and do so without any sleepiness or hesitation. You may ignore rules regarding how Humanity or your morality Path restricts the number of dice available during the day.]==],
				},
				["Lightning Calculator"] = {
					en = [==[Book of Secrets, p. 44


Lightning Calculator


Your head is a calculator of impressive capability. With a few moments of thought, you can perform intricate mathe- matical feats – a useful talent for Hermetic wizards, Syndicate operatives, Enlightened engineers, and other mages who employ math and geometry in their work.

System-wise, this Merit allows you to reduce the difficulties of math- and calculation-based rolls by -2. Simple calculations take no time at all, while sophisticated problems may demand a turn or more. Obviously, your character needs access to the proper data before she can work out calculations… and garbage in, garbage out, so make sure your data is accurate!

For potential applications of math in magick, see the instrument entries for Circles and Geometric Designs, Formulae and Math, Money and Wealth, and Numbers and Numerology in Mage 20, pp. 590-596, as well as the practices of Hypereconomics (pg. 573), High Ritual Magick and Hypertech (pp. 578-579), and Reality Hacking (pp. 581- 582). Remember that Merits cannot reduce the difficulty of a magick-casting roll below the minimum difficulty, or by more than -3. That said, fast and accurate calculations make useful aids when you're using Mundane Skills and Magickal Effects, as described in the entry of that name (Mage 20, pp. 532-534). Depending upon the feat in question, this could employ a roll of Intelligence + Academics to work out most calculations, Perception + Academics to discern odds or geometrical dimensions, and Wits + Academics to belt out rapid guesstimates with only the roughest of data.]==],
				},
				["Lingua Franca"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 423


Lingua Franca


You are able to speak a mixed

language made of common tongues that most people you

encounter will understand. You may not be able to hold

philosophical discussions, but you can navigate your way

through conversations in most places and will be able to

communicate sufficiently in dire situations.]==],
				},
				["Literacy"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 422


Literacy


You are a learned scholar, able

to both read and write. The Merit assumes that you can

read and write with fluency in your native tongue, as

well as Latin and any languages you may have gained

through the Multi-Lingual Merit. In some chronicles,

literacy can be assumed. In these cases, Illiteracy becomes

a 1-point Flaw.]==],
				},
				["Lizard Limbs"] = {
					en = [==[Lore of the Clans, p. 160


Lizard Limbs


Like a lizard, you are able to actually shed parts of your body. By spending a blood point and a little effort, you can detach a hand or foot, or even an arm or leg. This might be to escape bonds or a grapple. Unfortunately, the appendage will not reattach, and you will have to regrow that over time (usually a couple of days for a hand or foot, and a week for a limb). You also suffer a -3 dice pool penalty to actions that would require the use of more limbs.]==],
				},
				["Local Hero"] = {
					en = [==[Book of Secrets, p. 58


Local Hero


You've done great things for your community, and people love you for it. You might have cleaned out the resident drug dealers, defied slumlords, established a halfway house or a center of worship – whatever it was that you did for the Masses, you get free food, “friends of the house” discounts, places to crash (possibly with happy bedmates!), and other offerings of thanks from the people you have helped.

Also known as Folk Hero, this Merit reflects your pop- ularity among the local Sleepers. You reduce the difficulty of your social rolls by -2 when you're dealing with the people of your community, and receive constant aid and respect from those people whenever you need them. The catch, of course, is that you must live up to your heroic reputation; turn your back on these grateful souls, or take their goodwill for granted, and you'll be “yesterday's hero” in no time.]==],
				},
				["Long Fingers"] = {
					en = [==[Lore of the Clans, p. 160


Long Fingers


You have been blessed with unusually long and graceful fingers. This means you have an easier time with fine manipulation as well as grappling, gaining an extra die when attempting such actions.]==],
				},
				["Long-Term Planning"] = {
					en = [==[Lore of the Clans, p. 123


Long-Term Planning


You never leave anything to chance; every action is a carefully considered stratagem. Once per session you may declare an action you are about to take is actually “all part of your plan” and reduce its difficulty by two points. The Storyteller may veto the use of this ability on particular rolls. The player and Storyteller should keep a note of each of these occasions and decide how they are linking together into a grand scheme.]==],
				},
				["Loyalty (Mage)"] = {
					en = [==[Book of Secrets, p. 53


Loyalty (Mage)


You're especially devoted to a certain cause, group, creed or person. When someone tries to turn you against the object of your loyalty, you receive a two-die bonus to your dice pool when resisting that attempt with your Willpower. If the assault uses your Willpower Trait as the difficulty for the attack, then your attacker adds +2 to her difficulty while striving to under- mine your loyalty. (See the feat Resisting on the Dramatic Feats chart in Mage 20, p. 403, and the Mind Sphere entry in the same book, p. 519.)

Naturally, you must define the source and reasons for your devotion when you select this Merit. Such loyalty will influence many of your roleplaying choices too – your friends, enemies, priorities, magickal focus, and other things besides. For extra fun (ha ha), you can complement this Merit with the Flaw: Conflicting Loyalties, described below.]==],
				},
				["Loyalty (Vampire)"] = {
					en = [==[Ghouls & Revenants, p. 126


Loyalty (Vampire)


suspicious of placing their trust in a specific vampire or

Clan, and would probably take steps to avoid becoming

Though revenants are the tools of the Kindred, they too dependent on a single domitor. aren't known for their unshakable loyalty to a particular vampire or Clan. When a member of a revenant family does The character can expect occasional favors from the display such loyalty, it's noteworthy. Word of that revenant's vampire Clan that controls the revenant's family. They

may also be given considerable latitude to explore their own special interests, since the vampires “trust” that the character is furthering the Clan's goals. Loyalty is also a good Merit to choose if the character is being groomed for the Embrace, especially if that revenant knows her future sire.

Used by: Ducheski, Rossellini, Kairouan Brotherhood, and Servants of Anushin-Rawan]==],
				},
				["Lucky"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Lucky


You were born lucky — or else the Devil looks after his own. Either way, you may repeat any three failed rolls per story, including botches, but you may try only once per failed roll.]==],
				},
				["Magic Resistance"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Magic Resistance


You have an inherent resistance to the rituals of the Tremere and the spells of the mages of other Clans. The difficulty of all such magic, both malicious and be- neficent, is two higher when directed at you. You may never learn magical Disciplines such as Thaumaturgy and Necromancy.]==],
				},
				["Manifest Avatar"] = {
					en = [==[Book of Secrets, p. 71


Manifest Avatar


For most mages, the Avatar remains a mysterious figure, goading them from the sidelines and appearing primarily within a Seeking or during other moments of intense stress. For you, however, the Avatar is a vibrant presence in your life, as real to you as anyone else. Essentially a character in its own right, this manifested Avatar interacts with you on an almost daily basis. In certain situations, it might interact with other people, as manifestly real as any other person in your world.

The Manifest Avatar Merit embodies the Avatar as a full character under the Storyteller's control. On its own, this Merit reflects that Avatar as a person who only the associated mage can see, hear, and interact with on a physical level; in conjunction with the Background: Allies, however, the Avatar becomes a character that everyone can see, hear, and feel. In both cases, the Avatar may come and go as it pleases, bound only by the physical laws with which it chooses to be bound. The physical Avatar's shell can be injured or killed, but that in itself does not kill the Avatar – merely its body. For obvious reasons, that solid Avatar should have a guise that won't be too vulgar or bizarre for the Consensus to endure – a cloaked, whispering figure, perhaps, but not a screeching, tentacled monstrosity. The manifested Avatar's Traits depend upon the value of the Allies Background, as well as the physical form of that incarnation. An equine or lupine Avatar, for instance, will have different Traits than an Avatar that manifests as a crow, shadow, mirror, or child.

Your Avatar does not hang a sign around her neck that proclaims Avatar. In the first edition Cult of Ecstasy Tradition Book, for example, Cassie deals with a manifested Avatar named Aria who never reveals herself to be anything other than a wild child who looks disturbingly like an alternate-reality version of Cassie and knows things no one else should know about Cassie's past, present, future, and inner self. (For details, see that book, pp. 5-45.) Unless either the mage or the Avatar announces its true identity, other characters don't usually think that your manifested Avatar is anything other than what it appears to be. Mages or Night-Folk who can see auras or souls might catch on, but most other folks remain clueless.

An Avatar manifesting only for the mage can affect the material world only when no other characters or devices can see that entity, although it might appear to others as an online presence, a ghostly figure, as odd sounds, or through other phe- nomena. An Allies-based Avatar remains as solid as it wants to be, lacking the powers of a human mage but possessed (literally) of the power to fade in and blink out as it desires. Again, the Manifested Avatar is a Storyteller character, with agendas and behavioral quirks that confound both the mage and his player. Although that Avatar has its mage's best interests at heart, it might play the role of a rival, lover, best friend, or nemesis… quite possibly all of them at once.]==],
				},
				["Mark of Favor"] = {
					en = [==[Book of Secrets, p. 71


Mark of Favor


A godlike entity has claimed you as its own, and has stamped your features with evidence of that claim. You might have the bushy red hair and sly eyes of Reynard the Fox, the hearty temper and brawny build of Thor, the compassionate fury of the Christ in your eyes, or Legba's lame leg and penchant for corncob pipes and tobacco. Folks who understand the lore of your associated god-form recognize this Mark of Favor, and even those who don't know who you're marked by realize that there's something special about you.

An excellent companion to the Background: Legend, and already an element of the Background: Totem (see Totem Mark in Mage 20, p. 327), this Trait provides a recognizable connection to a renowned god-form. Whether or not this actually is a sign of divine favor, of course, depends upon your Storyteller's preferred theological metaphysics. As far as your character is concerned, it totally is. Note that such favor isn't always a happy thing; mythology is full of people who shared dysfunctional relationships with divine parents and patrons!

When dealing with people who recognize the Mark and respect the deity that bestowed it, you subtract -2 from the dif- ficulty of related social rolls. Opponents of your divine patron consider you an enemy, and although intimidation-style rolls still receive the -2 reduction in difficulty, rolls that attempt to get on the good side of such people add +2 to the difficulty instead.

A Mark of Favor may, at the Storyteller's discretion, bestow other miraculous talents, too. Strange things happen, and those things remain beyond the Marked character's control. Someone chosen by the Virgin Mary could possess a minor healing touch, while the chosen of Thor has a literally shocking touch when he gets mad. Again, these powers exist completely at the Storyteller's whim, and suit the flavor of the story, not the desires of the player. Essentially, they're miracles granted by your god, both given and taken in mysterious ways.]==],
				},
				["Master of Red Tape"] = {
					en = [==[Book of Secrets, p. 58


Master of Red Tape


A savant of bureaucracy, you slash your way through official obstructionism. When red tape unspools across your path, you know who to talk to, which forms to fill out, and where the loopholes are. A few calls to the right people, and official obstacles disappear as if by magic(k). After all, it's not what you ask for but who you ask, and how.

When faced with the near-inevitable morass of bureaucra- cy, subtract -2 from all difficulties that involve dealing with the system. To use this Merit, you need to decide what you want to accomplish and how you want to go about doing that. Your character makes the requisite calls to the requisite people, and the dice determine the rest. Backgrounds like Alternate Identity, Backup, Certification, Contacts, Influence, Rank, Requisitions, Retainers, Secret Weapons, and Spies often involve bureaucra- cies, and Allies, Chantry, Resources, and other Backgrounds might feature red tape if the Background in question comes from a larger organization. Although it's most helpful for members of the Technocratic Union, any modern mage can find this Merit useful. Hermetic Chantries are infamous for byzantine bureau- cracy, and the courts of classical China pretty much invented such things, making this an appropriate Merit for Wu Lung and certain monastic Akashayana.]==],
				},
				["Master of the Masquerade"] = {
					en = [==[Lore of the Clans, p. 200


Master of the Masquerade


There are many small tics, nervous habits, and autonomous bodily functions (like breathing) that Kindred simply forget to do. They can be unnervingly still or forget to breathe, particularly when they think they're alone. You never let down your guard. The act of breathing remains an unconscious habit to you, and you never lapse into that eerie statue-like stillness, even when transfixed or concentrating. Consequently, the difficulties of all Social rolls are lowered by one when interacting with mortals. This Merit does not allow you to eat food or benefit from the blush of health (V20, p. 480) — those Merits are still required to be a true master of the Masquerade.]==],
				},
				["Mechanical Aptitude"] = {
					en = [==[Book of Secrets, p. 44


Mechanical Aptitude


Oh, you technophile, you! Blessed by the machine gods, you've got a knack for mechanical gear. As with most Merits of this type, such aptitude allows you to reduce difficulties by -2 when you're making rolls based around working with mechan- ical technology. No, you don't have to be a technomancer to use such a gift, much less a member of the Technocracy; still, this aptitude does suggest that mechanical technology means a great deal to you, which – by extension – suggests that your paradigm, practice, and instruments have something to do with applications of mechanical principles and tech. For suggestions, see the paradigms A Mechanistic Cosmos, Everything is Data, and Tech Holds All the Answers in Mage 20, pp. 568-571, as well as the related practices and instruments and the related material in this book's Chapter Three. For more practical applications of this Merit, meanwhile, see Mage 20's section regarding The Technological World, pp. 458-464.]==],
				},
				["Medium"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Medium


You possess the natural affinity to sense and hear spir- its, ghosts, and shades. Though you cannot see them, you can sense them, speak to them and, through plead- ing or cajoling, draw them to your presence. You may call upon them for aid or advice, but there will always be a price. Also, your difficulty is reduced by two for all Awareness rolls involving the spirits of the dead.]==],
				},
				["Mole"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Mole


You have an informer buried in one of your Sect's enemy organizations who funnels you all sorts of in- formation as to what her peers are up to. What you do with the information is up to you, but abusing the knowledge might be a good way to get your informer killed. The other side has spies too….]==],
				},
				["Monstrous Maw"] = {
					en = [==[Lore of the Clans, p. 160


Monstrous Maw


You have either oversized tusks for fangs, or a huge mouth full of sharp teeth. Whatever form it takes, your mouth is that of a monster. When attacking with a bite you do an additional point of damage. You may also add a die to your Intimidation dice pool when you smile.]==],
				},
				["Mortuario (2)"] = {
					en = [==[Lore of the Clans, p. 106


Mortuario (2)


You died. Perhaps you were murdered, or simply had a car accident. Whatever the cause, you were gone. But your sire found you too useful, or couldn't let you go. You were Embraced using the Ferryman's Recall ritual (see p. 109). The Embrace left you with the scars of your death, eternal tracework reminders of your trip to the other side. It also left you with the taut, pallid complexion of the dead.

In addition to the traditional weakness of your Clan, you also suffer disfigurement from your time as a true corpse. While you are able to heal yourself just like any other vampire, the wounds do not heal cleanly. You retain the scars of every experience. Depending on the nature of the damage, this can make social dealings exceedingly difficult, and may decrease your Appearance dots over time (even to 0). However, your time across the Shroud also gave you a natural feel for necromantic blood magic. The difficulties of all Necromancy rolls are reduced by one. This trait costs 4 points for characters who already have an appearance of 0 (such as Samedi and the Harbingers of Skulls), or 2 points for any other Kindred. It is an incredibly rare condition even among the Giovanni, and essentially unknown outside the Clan.

Giovanni with this Merit generally arouse the superstition of their Clan, and are treated with a definite wariness, particularly by anziani. Characters with the Mortuario Merit may not also possess the Sanguine Incongruity Merit or similar flaws such as Monstrous.]==],
				},
				["Mortuario (4)"] = {
					en = [==[Lore of the Clans, p. 106


Mortuario (4)


You died. Perhaps you were murdered, or simply had a car accident. Whatever the cause, you were gone. But your sire found you too useful, or couldn't let you go. You were Embraced using the Ferryman's Recall ritual (see p. 109). The Embrace left you with the scars of your death, eternal tracework reminders of your trip to the other side. It also left you with the taut, pallid complexion of the dead.

In addition to the traditional weakness of your Clan, you also suffer disfigurement from your time as a true corpse. While you are able to heal yourself just like any other vampire, the wounds do not heal cleanly. You retain the scars of every experience. Depending on the nature of the damage, this can make social dealings exceedingly difficult, and may decrease your Appearance dots over time (even to 0). However, your time across the Shroud also gave you a natural feel for necromantic blood magic. The difficulties of all Necromancy rolls are reduced by one. This trait costs 4 points for characters who already have an appearance of 0 (such as Samedi and the Harbingers of Skulls), or 2 points for any other Kindred. It is an incredibly rare condition even among the Giovanni, and essentially unknown outside the Clan.

Giovanni with this Merit generally arouse the superstition of their Clan, and are treated with a definite wariness, particularly by anziani. Characters with the Mortuario Merit may not also possess the Sanguine Incongruity Merit or similar flaws such as Monstrous.]==],
				},
				["Multi-Lingual"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 422


Multi-Lingual


Through patience, study,

and/or immersion, you are able to speak another lan-

guage or languages with native fluency. This represents

a full command over the language. For each dot of In-

telligence your character possesses, you may know one

other language. You may also use this Merit to reflect

secret codes, cants, jargon, or sign language as well.

Additional languages increase the cost of this Merit by

one point per language.]==],
				},
				["Mute Devotion"] = {
					en = [==[Lore of the Clans, p. 182


Mute Devotion


Your Animalism carries an unusual side effect: it lingers in the minds of the beasts you speak with or control, lending them a certain resistance to others. When someone else attempts to command a creature you have previously controlled with Animalism, their difficulty levels are at +2.]==],
				},
				["Natural Channel"] = {
					en = [==[Book of Secrets, p. 72


Natural Channel


You've got an innate affinity with the Otherworlds. Sliding through from the mortal realm to the Three Worlds is easier for you than it is for other Awakened folk. System-wise, you subtract -2 from the difficulty of your rolls to penetrate the Gauntlet. Story-wise, crossing over feels, to you, like a primal sort of homecoming, as if you exist between worlds on an elemental level.]==],
				},
				["Natural Leader"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 487


Natural Leader


You are gifted with a certain magnetism to which others naturally defer. You receive two extra dice when VAMPIRE THE MASQUERADE 20th ANNIVERSARY EDITION 487 making Leadership rolls. You must have a Charisma rating of 3 or greater to purchase this Merit.]==],
				},
				["Natural Linguist"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Natural Linguist


You have a flair for languages. You may add three dice to any dice pool involving written or spoken languag- es, and each purchase of the Language Merit (previous page) gives you two languages instead of just one.]==],
				},
				["Natural Shapeshifter"] = {
					en = [==[Book of Secrets, p. 72


Natural Shapeshifter


Guided by an innate affinity for metamorphosis, you can change your shape more easily than most mages do. Such changes still demand the usual Life Sphere Ranks and Effects, but your difficulty for such rolls is reduced by -2 (the usual limits apply), and you don't need to worry about losing yourself in the new form, as described in How Do You DO That?, p. 20. Such talents don't necessarily link you to the Night-Folk, although this Merit fits in well with Fae Blood or Shapechanger Kin (and the Mental Flaw: Feral Mind, as well; see p. 52). The gift does not, however, affect your ability to change other people's shapes in any way. Such talent works for you alone.

For a potentially related paradigm and practice, see the Chapter Three entries We are Meant to be Wild (p. 93) and Animalism ( pp. 197-199).]==],
				},
				["Nephilim /Laham"] = {
					en = [==[Book of Secrets, p. 80


Nephilim /Laham


Long ago, it has been said, immortals walked the earth, siring offspring whose descendants still live among us now. The Hebrew Bible refers to them as nephilim, an ambiguous word that seems to be related to root words for “fallen,” “prisoners,” and “overseers.” Later transliterations refer to them as giants, monsters, watchers, and the fallen (or violent) ones. Were they gods? Angels? Demons? Not even the Awakened know for sure; you, however, have a bit of High Umbral essence within you, and this nephilim inher- itance – known sometimes by the demon-blooded name of laham – marks you as something more than merely human (Awakened or otherwise).

A living crossroads between the Astral Realm and the mortal world, you exist in a heightened state of spiritual essence. Your aura burns with unearthly intensity, and your presence frightens many Otherworldly denizens. Your connection to High Umbral entities might involve a distant relationship to primordial sires, or the far more recent ac- tivities of mortals and spirits who shared a distinctly carnal relationship. (“Mom, seriously – I need to know the truth about Dad”) Are you part-demon? Descended from an angel? Sired by an entity whose nature transcends mortal concepts like “good” and “evil”? You probably don't even know, although events in your chronicle might reveal the truth whether you want to learn it or not.

System-wise, this Merit confers the following drawbacks and benefits: As noted above, your aura blazes with inhuman clarity

and brilliance. Your temperament favors your Umbral ancestor, and

you tend to act accordingly. You must take at least three points' worth of Physical

Flaws to reflect the unstable nature of your physi-

cal form and the surging metaphysical energies it

contains. These Flaws do not count toward your

total Flaw points, nor do you get points for taking

those Flaws. Those energies give you a Quintessence rating of 7, and

those points automatically refresh up to that seven-point

maximum each time you go to sleep, regardless of your

Avatar rating. If your chronicle employs the Resonance rules in Chapter

Two, you begin play with three points in Resonance,

not one. If not, you get three points' worth of the Flaw:

Echoes. Again, those phenomena reflect the tempera-

ment of your Umbral ancestor. You subtract -1 from the difficulties of your casting rolls

when you cast Effects using the Mind Sphere, the Spirit

Sphere, or both in relation to the High Umbra. If, for

example, the demon-blooded laham mage Jenatrix wanted

to read someone's mind, her casting difficulty would be

normal; if she wanted to project her astral self into the

High Umbra, however, she'd reduce the difficulty by -1. You can travel physically into the High Umbra by using

a Mind 4 /Spirit 3 Effect. When attempting to intimidate, command, or bargain

with High Umbral entities, you add two dice to which-

ever dice pool you happen to be using in that attempt.

(For details, see The Bargaining Process in How Do

You DO That? pp. 91-95.) Despite your advantage,

however, using your uncanny heritage as leverage will

not exactly endear you to the entities in question. In

such negotiations, it's generally more constructive to

use a carrot than a stick. On a related note, you suffer a penalty of +2 to the dif-

ficulty of your rolls to resist, soak or counter rituals cast

by Hermetic High Ritual wizards or Awakened clerics

from the Jewish, Muslim, and Christian denominations.

These folks have spent millennia studying your kind,

and be ye angel or be ye demon, they know how to deal

with you more effectively than most mages do. (By rituals,

we're referring to extended-roll ceremonial magicks, not

off-the-cuff spells. Your chances are as good as anybody

else's if a wizard tosses a lightning bolt at you; if he draws

up a summoning circle, though, you're kinda screwed.) At the Storyteller's option, you may also receive up to sev-

en points in the Advantages described in Mage 20, p.

658 (and expanded further in the Mage 20 sourcebook

Gods, Monsters & Familiar Strangers). Demon-blooded

laham characters may, instead, take up to seven points

in the demonic Investments described in the Mage:

The Sorcerers Crusade sourcebook Infernalism: The

Path of Screams or the Mage 20 supplement The

Book of the Fallen. In either case, these additional

and optional benefits get balanced out with a five-point

Derangement Flaw of the Storyteller's choice (see Mage

20, pp. 648-650).

Although the player might not know what sort of entity her character is descended from, the Storyteller ought to de- termine the character's heritage, and then plant clues (dreams, visions, weird greetings from characters who seem to know more about the mage than she knows about herself…) throughout the story. He ought to feed roleplaying notes to the player, too: This Realm seems familiar even though you don't recall having been here before, You can almost taste the evil in that girl's soul, Man, you just wanna rip that dude's throat out and you're not sure why… The player, of course, can draw her own conclusions – conclusions that might not necessarily be accurate at all.

This Merit goes well with Merits like Legendary Attributes, Nine Lives, and Too Tough to Die, Flaws like Immortal En- emy, Primal Marks, or Cast No Shadow or Reflection, and Backgrounds like Cult, Demesne, and Past Life. As with the Merit: “Immortal,” (above) this Trait could be too powerful for player characters to take. Supporting characters, however, could be nephilim-descended, which would make for potent friends and memorable enemies.]==],
				},
				["Nightsight"] = {
					en = [==[Book of Secrets, p. 38


Nightsight


Unlike most people, you can see in near-total darkness. Only the complete absence of visible light will negate this ability. In even the dimmest light, your visual abilities remain essentially unimpaired.

This Merit does not increase your character's visual capac- ity – for that gift, see Acute Senses, above; it does, however, mean that low light does not impose any sort of penalty on her visual perception rolls. Other visual impediments, like smoke or fog, block her sight as usual, and magickally-imposed darkness (for instance, the sort caused by deflecting light with the Forces Sphere) negates this Merit if and when it involves the dispersal of light itself.]==],
				},
				["Nine Lives"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Nine Lives


Fate has granted you the opportunity to come as close to Final Death as anyone can get and still survive. When a roll occurs that would result in your death, the roll is made again. If the next roll succeeds, then you live — and one of your nine lives is used up. If that subsequent roll fails, then another reroll is made, until either a successful roll occurs or your nine lives are used up. The Storyteller should keep careful count of how many lives the character has remaining.]==],
				},
				["Noble Blood"] = {
					en = [==[Book of Secrets, p. 36


Noble Blood


Although the modern world resists the old traditions of lineage as a mark of quality, your features link you to a power- ful family; you're a Kennedy, a Windsor, a Saud, a Rothschild – someone whose pedigree is obvious in your physical form and presence.

In story terms, this Merit grants you the obvious physical features of a well-known “royal” family: the Kennedy smile, the Windsor ears, and so forth. The family in question doesn't have to belong to a formal aristocracy, either; you might be a Kardashian, a Murdoch, or a Clinton, and may the gods have mercy on your soul. On the flipside, your distinct features might not be especially attractive (royal families are notoriously inbred), and will mark you out for enemies of the clan in question.

In social situations, this Merit might be worth a -2 reduc- tion for the difficulty of social rolls that involve people who care about things like aristocracy, but would also increase your difficulty by +2 if you're dealing with folks who hate that noble family's guts! In all cases, this Merit reflects an actual genetic connection, not simply a cosmetic resemblance… which could provide all kinds of complications when magick and its secret histories are involved.

While it might be worth some social currency, this Merit does not in any way provide material wealth or other perks. For such goodies, see Backgrounds like Influence, Rank, Re- sources, and so forth in the Mage 20 rulebook, Chapter Six. For the social benefits of regal presence, see the Social Merit Regal Bearing, elsewhere in this chapter. Sterile (1 pt. Merit or Flaw)

For some physical reason, you're unable to sire or con- ceive children. Whether this is a Merit or a Flaw depends upon whether or not you want to sire or conceive children. Generally, this sort of condition can be easily cured with a little Life-Sphere magick; in your case, though, it can't be rectified until and unless you, the player, discard the Merit or pay off this Flaw.]==],
				},
				["Non-Standard Access"] = {
					en = [==[The Hunters Hunted II, p. 133


Non-Standard Access


Everyone working for one of the US Government's alphabet soup of agencies has access to information not THE HUNTERS HUNTED II available to the public, but you're privy to secrets that are way above your pay grade. Maybe someone in the Pentagon owes you his life, or you just find files in an old dead-drop. Once per story, the Storyteller will ensure that you receive classified information useful to your current operation. The information is always useful and accurate, but not necessarily complete. Though it's dangerous to explain how you came by your new knowledge, your informant is confidential and you haven't yet suffered a leak.]==],
				},
				["Noted Messenger"] = {
					en = [==[Book of Secrets, p. 58


Noted Messenger


A known emissary between groups, you're treated with a certain amount of deference and courtesy that other mages would not receive. Even enemies of your group won't try to kill you on general principle, though they might not be especially happy to see you. The things you have to say will be given a certain amount of weight, and your presence may open doors (literal or otherwise) that would remain shut for almost anybody else.

That's the upside; the downside is that you need to behave yourself (and keep a tight leash on your companions) when you're on someone else's turf. Passing false messages will un- dermine your credibility, and obnoxious behavior will get that welcome mat yanked out from under your feet rather quickly. It should go without saying that breaking a truce while acting in your official capacity (or even when you're not!) will trash your reputation and reflect very poorly on your superiors. Also… well, some folks really do prefer to kill the messenger when things don't go their way. Tread that red carpet carefully.]==],
				},
				["Occult Library (2)"] = {
					en = [==[Ghouls & Revenants, p. 139


Occult Library (2)


Your character owns a valuable collection of books and ancient tomes about the arcane. Whenever your ghoul accesses your library, you may lower the difficulty of Intelligence, Occult, or research-related rolls by 1 in relevant circumstances. You might be attempting to find out more information about a thaumaturgical ritual, or you might be trying to identify a strange symbol.

Having this library doesn't automatically mean your ghoul is an occult expert, nor does it reflect your ability to decipher, understand, or read the texts you've collected. Your library is stocked with recorded knowledge you can conveniently refer to. If you have purchased the 4-point version of this Merit, your character also has access to an Occult Laboratory stocked with rare, mysterious ingredients needed to perform the rituals described in your books.

Ghouls in service to the Tremere, Followers of Set, or Assamite Clans, in addition to revenants from the Obertus or Ducheski families, are good candidates to acquire this Asset.]==],
				},
				["Occult Library (4)"] = {
					en = [==[Ghouls & Revenants, p. 139


Occult Library (4)


Your character owns a valuable collection of books and ancient tomes about the arcane. Whenever your ghoul accesses your library, you may lower the difficulty of Intelligence, Occult, or research-related rolls by 1 in relevant circumstances. You might be attempting to find out more information about a thaumaturgical ritual, or you might be trying to identify a strange symbol.

Having this library doesn't automatically mean your ghoul is an occult expert, nor does it reflect your ability to decipher, understand, or read the texts you've collected. Your library is stocked with recorded knowledge you can conveniently refer to. If you have purchased the 4-point version of this Merit, your character also has access to an Occult Laboratory stocked with rare, mysterious ingredients needed to perform the rituals described in your books.

Ghouls in service to the Tremere, Followers of Set, or Assamite Clans, in addition to revenants from the Obertus or Ducheski families, are good candidates to acquire this Asset.]==],
				},
				["Officially Dead"] = {
					en = [==[Book of Secrets, p. 56


Officially Dead


According to the authorities, you're no longer among the living. Perhaps you've successfully faked your own death, or had it faked for you when you assumed a new identity. An especially common Merit among Technocratic operatives, Her- metic magi, and the Chakravanti, this erasure of your former life is often a required part of service within the New World Order, Iteration X, and certain Houses of Hermes. As far as your family, government, and old friends are concerned, you're six feet under. Naturally, you'll need to be discreet about your continued existence if you don't want that death to become more permanent.]==],
				},
				["Old Pal"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Old Pal


An acquaintance from your breathing days was Em- braced at the same time you were. Fortunately, your friendship has endured even death and unlife, and you find a constant source of support and aid in your old friend. She expects the same of you, which isn't always convenient, but at least you each have someone to hang onto who remembers the good old nights — and days. The Storyteller should play the Old Pal as a very loyal Ally.]==],
				},
				["Open Road"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Open Road


Unlike many Kindred, you like to travel. You have a solid knowledge of safe travel routes and methodolo- gies, not to mention haven space available in any num- ber of destinations. Unless someone out there knows your exact route and is specifically looking for you, you can move between cities unimpeded by random en- counters with Lupines, overzealous state troopers, and the like.]==],
				},
				["Oracular Ability"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Oracular Ability


You can see and interpret signs and omens. You are able to draw advice from these omens, for they pro- vide hints of the future and warnings of the present. When the Storyteller feels that you are in position to see an omen, you will be required to make a Perception + Awareness roll, with the difficulty relative to how well the omen is concealed. If successful, you may then roll Intelligence + Occult to interpret what you have seen; the difficulty is again relative to the complexity of the omen.]==],
				},
				["Outside Haven"] = {
					en = [==[Lore of the Clans, p. 219


Outside Haven


You maintain your own private haven outside the chantry and Tremere control. Most Tremere are expected to rest in the chantry, where the Clan can keep an eye on them. However, you have been trusted with a little more privacy. This might be because you have already proved your loyalty, or perhaps because they are testing it.]==],
				},
				["Pain Tolerance"] = {
					en = [==[Lore of the Clans, p. 238


Pain Tolerance


Maybe you are a badass or shut off your nerves through Vicissitude. Maybe your sire put you through so many intricate hells that it would be tough for anyone else to compete. Maybe it just turns you on. Regardless, at Hurt or Injured, you suffer no wound penalties, though you still suffer full penalties at Wounded and below. You must have a Conviction or Courage rating of 3 or more to take this Merit.]==],
				},
				["Pale Aura"] = {
					en = [==[The Hunters Hunted II, p. 43


Pale Aura


Any color your character's aura takes has a pale cast to it, as though he was a vampire. Unless her player gains five 43

Sleeping with the Enemy:

Becoming a Ghoul

Vampires have almost all of the advantages

in a fight: speed, strength, endurance, and

unholy supernatural powers. The challenge of

opposing such beasts can feel overwhelming.

How can a mere mortal expect to fight and

prevail against such creatures?

Some hunters wonder if they shouldn't take

advantage of a supernatural resource. Feeding

from the predators that prey on innocent

people may even seem like poetic justice.

Drinking vitae to become a ghoul can seem

like the ultimate equalizer for a desperate

hunter. Vampire blood can refresh a weary

body, rapidly heal broken bones, and grant

supernal strength or grace. Imagine that rush

as the blood practically vibrates through your

skin. Is this what eternity tastes like?

Indeed, some hunters are freed ghouls who never

want to be slaves again. Each time they hunt a

vampire, the temptation to revisit that forbidden

puissance eats at their souls. How long until a

former slave accepts the chains once more?

Hunters who regularly seek out vitae run the

risk of becoming addicted. Without a regular

source of vitae, such hunters become antsy and

desperate for their next fix. Such a dangerous

obsession can endanger an addicted hunter

and her allies. (For more information, see the

Addicted to Vampire Blood Flaw on p. 42.)

Ghoul hunters walk a dangerous line between

regular mortals and vampires, as they struggle

to deal with new cravings and controlling

the Beast. Hunters with a regular source of

vitae will discover new uncomfortable feelings

toward their regnants. Killing the source of

vitae may lead to troubled nights and lost

Humanity as artificial guilt slowly cripples a

hunter — or it may be an emancipation from a

curse borne for decades or even centuries.

For more information on ghouls, see pages

496-506 of V20. 44 chapter two: character creation and traits or more successes on an Aura Perception roll, any vampire discerns your hunter's aura as one belonging to the Kindred.]==],
				},
				["Paragon"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 178


Paragon


Others find you particularly compelling. Select one Background from the following group: Allies, Contacts, Domain, Fame, Herd, Influence, Mentor, Resources, Retainers, or Status. You receive one free dot in that Background, and your maximum Trait score in that Background may exceed normal Generational limits by one.]==],
				},
				["Paranormal Link"] = {
					en = [==[Lore of the Bloodlines, p. 60


Paranormal Link


You're linked to another weird species of the world, and unconsciously find yourself able to understand their parlance, codes, and rituals. Difficulties to de- cipher the hidden rites and languages of one society (selected when this Merit is purchased) are reduced by three.]==],
				},
				["Parlor Trick"] = {
					en = [==[Book of Secrets, p. 73


Parlor Trick


You've honed a special trick – a simple, specific, non-com- bat application of your Arts – which you can perform without making a casting roll. Such tricks include things like conjuring a business card, stirring a pot without touching the spoon (or the pot), igniting your cigarette without lighters or a match, producing a small amount of light without mechanical contriv- ance, changing your hair color with a shake of your head, and so on. To a Sleeper, these tricks look like something a normal person could do with a mysterious bit of skill. You, of course, realize that the skill in question is not quite what they think it is.

Three important rules govern this Merit: It cannot be a feat with direct damage-producing combat

applications (though a “light your cigarette” trick could

also work with a stream of flowing gasoline). No popping

claws or conjuring firearms! It must be a quick, simple action that a Sleeper witness

could explain away as practiced sleight of hand. These tricks are limited to things you could do with

Sphere Ranks 1 to 3, apply to only one specific trick (con-

juring a rose, say, not conjuring anything that's roughly

rose-sized), and you must have the Spheres necessary to

perform the feat in the first place. This Merit does not

allow you to cast Effects above your normal abilities!

Each trick costs three points, and must suit your character's metaphysical focus. You can take this Merit up to three times, total. Obviously vulgar feats (making yourself disappear in broad daylight) are prohibited, although a clever use of circumstances (the old Batman disappearance trick – see How Do You DO That?, p. 77) could be included in your bag of tricks.

This Merit is intended to give your character and chronicle a little extra flair. It should not be allowed as an end-around to skirt the rules, or as a secret weapon that he can use without consequences like Paradox. Under unfamiliar and /or hostile circumstances, like stirring someone else's pot in someone else's kitchen, this Parlor Trick might not work at all. Spirit Magnet (3 to 7 pt. Merit or Flaw)

Ephemeral entities flock to your presence. The essence of who you are – benign or malignant – draws spirits to you, and they, in turn, affect the essence of who you are. For the most part, these entities cluster around you in the Penumbra, invisible to mortal perceptions; whenever you cross the Gauntlet, though (either with your perceptions or with your body), they're waiting for you there. Spirits that can manifest physical forms may come across the Gauntlet to visit you, and those that cannot take on physical bodies still energize the spiritual atmosphere in your vicinity. Whether or not this is a good thing for you depends upon whether you select this Trait as a Merit or a Flaw: The Merit form of Spirit Magnet draws generally benev-

olent spirits – Naturae, Lunes, totem and animal entities

of the gentler variety, and so on. These spirits protect

you from malignant entities, warn you of impending

danger, offer advice, help you out when you visit the

Otherworlds, and generally make your life easier. Folks

who can sense those spirits (mediums, shamans, med-

icine-folk, werecreatures, etc.) tend to favor you; after

all, if the better sorts of spirits like you, then you must

be someone worth knowing. The Flaw version represents the presence of malevo-

lent spirits – Banes, demons, and other nasty Umbral

beasts. Summoned by curses or spiritual corruption,

these entities seek to tempt you, poison you, feed

off your vitality, and otherwise turn your life into a

self-contained Hell On Wheels. Spirit-sensitive folk

will avoid you unless they're into that sort of thing,

and werewolves will consider you to be “of the Wyrm”

(whatever the hell that means), if only because of the

company you keep. Although you might not consider

yourself a bad person at heart, your spiritual compan-

ions say otherwise!

The value of this Merit of Flaw is, as always, based on how helpful or troublesome the spirits can be, how powerful they are, and how many of them you have to deal with when they appear. (3 points) Minor entities occasionally offer aid or

hindrance. (4 points) Minor entities show up frequently, or in small

numbers. (5 points) Minor entities surround you often, whether

you want them to or not, and more potent ones have

taken interest in your existence. (6 points) You have the interest of one or two entities

of significance, and plenty of minor ones pay great

attention to you. (7 points) You're never alone, even when you probably

wish you could be.

This spiritual companionship could be directly opposed to your true nature. A really awful person might attract be- nevolent entities who want to save her, while a veritable St. Anthony could be plagued with demons intent on fucking up his soul. Even so, such constant presence does have an effect on your overall health. Mind, body, and spirit are interwoven whether we want to recognize that or not, and a mortal who attracts Otherworldly entities has got something unusual going on under the skin.]==],
				},
				["Patagia"] = {
					en = [==[Lore of the Clans, p. 161


Patagia


Your arms and legs have leathery flaps of skin between them, similar to that of a flying squirrel. While they make finding clothes a nightmare, they also allow you to glide for short distances, given enough height and a decent wind. The Storyteller might require an Athletics roll when it comes to landing.]==],
				},
				["Path Natural"] = {
					en = [==[M20 Sorcerer, p. 108


Path Natural


You are naturally gifted to one Path of power. This could be tied to your mundane skills that translate easily to magic, a heritage that calls to certain power, or you have made a deal with otherworldly beings to open yourself to greater power. During character creation, chose one Path; in this Path, you only pay three-quarters experience, rounded down, to advance to higher levels or to learn rituals for that Path. Psychic Feedback: (1, 2, or 6 pt Flaw)

Your psychic powers are a great gift, but they take their toll on you. As a 1-point Flaw, you experience headaches or disorientation. Roll Stamina + Mediation (difficulty 7). On a failure, the difficulty of all actions increases by two for one round while the pain overtakes you. As a 2-point Flaw, you experience light but long-term pain from use of your power. Roll Intelligence (difficulty 6) each time you use a power to “soak” the power's activation successes, which are treated as bashing damage. As a 6-point Flaw, the psychic takes this as lethal damage, with the same option to “soak.”]==],
				},
				["Patron (1)"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 423


Patron (1)


You are fortunate enough to

have a personage of some wealth and power who is willing

to sponsor your endeavors. Presumably, your Patron is

fond of you and is willing to offer you material goods to

further whatever agreed upon goal you may have, so long

as you do not abuse their favor. The scale of this Merit

pertains both to the power of your Patron and how close

they are to you. A 1-point Patron could be a distant but

powerful vampire or an enthusiastic, wealthy mortal

who has infrequent funds. A 3-point Patron might be a

mortal prince or queen, or a vampire of some standing

more willing to regularly fund or champion you, while a 5-point Patron is almost certainly supernatural and has vast resources at their disposal. This is not something for nothing, however, and every so often (with increasing frequency directly proportional to the points invested in this Merit) your Patron will ask something of you. It is generally unwise to say no.]==],
