				},
				["Peacemaker"] = {
					en = [==[Anarchs Unbound, p. 102


Peacemaker


You have a reputation for having a good head on your shoulders and the honor to keep your word no matter what. As a result, your allies and sectmates ask you to mediate their disputes, even with other sects. This Merit allows your character to use her reputation as leverage to keep the peace during tense situations. Reduce the difficulty of all social rolls to keep the peace or to mediate honestly between factions (even other sects) by 2.]==],
				},
				["Perfect Liar"] = {
					en = [==[Book of Secrets, p. 56


Perfect Liar


Oh gods, you're good at lying! Falsehoods slide from your tongue like water off a vine leaf, and even the folks who know you well tend to be taken in when you start talking. You also lack the usual “tells” that betray a liar: your vital signs remain stable, your eyes don't twitch, and your voice never falters. Unless someone is outright reading your mind (as in, using Mind-Sphere magick or some other paranormal power), you still often appear to be telling the truth; even then, the mind-reader might assume that you at least believe you're telling the truth!

Story-wise, people usually believe what you say when you're lying about small, casual things that are not immediately, obvi- ously false. With regards to the dice, reduce the difficulty by -2 when you're trying to lie about something important. Again, this Merit will not alter auras or change the thoughts in your head, although those folks who can't actively monitor your soul will be inclined to give you the benefit of the doubt. (Suckers…)]==],
				},
				["Personal Masquerade"] = {
					en = [==[Lore of the Clans, p. 269


Personal Masquerade


Thorough charm, manipulation, or just plain luck, you have managed to convince other vampires that you are a member of one of the Clans. Any social interactions with vampires ignorant of your true nature ignore your usual penalty for being Caitiff. However, you must constantly 269

be vigilant of your ruse. Should anyone come to realize

you have been playing them for fools, their vengeance

will be swift. The higher you climb in Kindred politics,

the more likely this becomes. The Clan Weakness Flaw

can actually prove to be a boon in supporting your

Masquerade. Others, however, must be that much

more careful.]==],
				},
				["Physically Impressive"] = {
					en = [==[Book of Secrets, p. 37


Physically Impressive


You are one imposing sumbitch, not so much large as apparently dangerous no matter what mood you might be in at the time. This could be as obvious as scarring or an intimi- dating build, or as intangible as the proverbial “air of menace.” System-wise, the Merit adds two dice to all Social-Trait rolls that involve intimidating someone; story-wise, people find you unnerving – and quite possibly attractive in a dangerous way – even when you're not trying to be impressive.]==],
				},
				["Piscine"] = {
					en = [==[Lore of the Clans, p. 161


Piscine


Water is a far more comfortable environment for you, be it the sea or sewer effluent. Rolls involving swimming or underwater movement have their difficulty reduced by 1.]==],
				},
				["Pitiable"] = {
					en = [==[Book of Secrets, p. 54


Pitiable


Oh, you poor thing! People want to help you, and you're willing to let them do so. Although this Merit lowers the difficulty of your social rolls by -2 when you're trying to get someone to take care of you, it adds +2 to the difficulty of rolls that attempt to intimidate people or otherwise impress folks into taking you seriously.]==],
				},
				["Poison Resistance"] = {
					en = [==[Book of Secrets, p. 37


Poison Resistance


Toxins may sicken you, but probably won't kill you. Although magickal poisons may be the exception to this rule, your body shakes off the worst effects of natural and synthesized poisons.

When attacked by such substances, add two dice to your character's Stamina roll when resisting their effects; a successful roll reduces the intensity of powerful toxins, and eliminates the deadlier effects of lesser ones altogether. Sure, she might feel a little woozy and could get seriously ill, but even if you fail that roll your character probably won't die.

Although it works against toxic bacteria, this Merit does not protect against diseases spread from viruses, genetic conditions, and so forth. For details, see Drugs, Poisons, and Disease in Mage 20, pp. 441-444 and 456. And because intoxicants are toxins too, this Merit helps you survive overdoses of booze or drugs – see Alcohol /Drug Tolerance, above.]==],
				},
				["Poisonous Blood"] = {
					en = [==[The Hunters Hunted II, p. 44


Poisonous Blood


Due to mysterious circumstances, your character's blood is poisonous to vampires. Should a vampire drink from him, every blood point imbibed causes one health level of bashing damage to her. Vampires naturally resent mortals known to possess this blessing and may well seek their destruction. Storytellers are encouraged to have an explanation for this aberration in their chronicles, though the player (and likely character) may not be immediately privy to such knowledge. Some examples include holy protection from a higher power, a rare ritual of protection, or even a genetic abnormality.]==],
				},
				["Poker Face"] = {
					en = [==[Book of Secrets, p. 38


Poker Face


Nothing rattles you. Nothing. The emergence of a titanic elder thing from the depths of space might warrant a concerned twitch of your mouth, but that's really about it. Oh, this doesn't mean you don't feel anything – that's the Mental Flaw: Icy, below. Your deadpan expression, blank eyes, and flat tone of voice, however, reveal nothing about your thoughts or intentions… which, for folks on the receiving end of you, can be quite disconcerting; reduce the difficulty of intimidation, subterfuge, and resistance-to-in- timidation rolls by -2, while adding +2 to the difficulties of anyone who tries to rattle your cage or get under your skin, including attempts to read, seduce, torture, or otherwise get past that poker face.]==],
				},
				["Postulant of Echidna"] = {
					en = [==[Dark Ages Tome of Secrets, p. 4


Postulant of Echidna


You receive the tutelage of one of the Witches of Echid- na. This Merit allows you to take Setite Sorcery as a Clan Discipline in place of one of your others. If you're outside the Setite Orthodoxy you may find yourself hunted for integration or destruction by others of your blood. Most Postulants of Echidna have several points in the Mentor Background to account for the Gorgon tutor, though the lack of a Mentor may imply the Witch met destruction. This Merit is pre- dominantly held by Setites, but rumors hold of Witches of Echidna passing knowledge to vampires of other clans.]==],
				},
				["Powerful Ally (5)"] = {
					en = [==[Book of Secrets, p. 77


Powerful Ally (5)


You've got seriously badass friends – a vampire lord, a faerie noble, a werewolf pack, Umbrood courtiers, or other similarly magnificent entities. In most respects, this is the Supernatural Companion Merit but with a much higher power-level… a level which might be beyond the capacity of mages below the Master rank. And while the Storyteller determines who your friends are, what they can do, and what they want out of their relationship with you, the value of this Merit depends upon their relative benefit to you: (5 points) One buddy of considerable power and in-

fluence within his community – a Prince of the City, a

Garou elder, and so forth. (6 points) A small group of Supernatural Companions

(five or so), or an especially powerful representative of

his kind. (7 points) A larger group of Companions (around a

dozen), or two or three powerful friends. (8 points) Over a dozen Companions, a handful of

powerful friends, or one ally of near-godlike power.

Again, the Storyteller decides who these allies are, why they're interested in your goodwill, and what the cost of their aid might be. You get nothing for nothing, after all, especially not when such beings are involved! For a commensurate level of enemies, see the Flaw: Immortal Enemy, p. 93.]==],
				},
				["Powerful Ally (6)"] = {
					en = [==[Book of Secrets, p. 77


