				},
				["Precocious"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 485


Precocious


You learn quickly. The time for you to pick up a par- ticular Ability (or Abilities, at Storyteller discretion) is cut in half, as is the experience cost.]==],
				},
				["Prestige"] = {
					en = [==[Book of Secrets, p. 56


Prestige


Also known as Reputation, this Merit reveals you as an honored personage within your Tradition, Convention, Craft, or another sort of sect. Among your peers, you add three extra dice to all social rolls used to influence folks within that group. Story-wise, allies of your group will tend to like you, and rivals or enemies will tend to… not.

When you first select this Merit, decide upon the source of this prestige. Perhaps you earned it through deeds before the chronicle began, or won the Merit in place of experience points. It might represent an honored lineage to which you belong, or reflect a glorious mentor whose rep rubs off on you. Either way, folks expect great things of you, and usually defer to you so long as you live up to the reputation you currently enjoy.

For the flipside of this Merit, see the Social Flaw: Infamy, pp. 62-63.]==],
				},
				["Prestigious Mentor"] = {
					en = [==[Book of Secrets, p. 54


Prestigious Mentor


Your Mentor (as in the Background Trait of that name) has a reputation that benefits you as well. When you're mak- ing social rolls to invoke your influential teacher, reduce the difficulty by -2. Of course, some folks will be somewhat less than impressed; for rolls that involve rivals or enemies of your mentor, add +2 to the difficulty unless that mentor scares the shit out of them… in which case, you had damned well better be able to live up to the fear his name invokes!]==],
				},
				["Prestigious Sire"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Prestigious Sire


Your sire has or had great status in her Sect or Clan, and this has accorded you a certain amount of pres- tige. Though your sire may no longer have any dealings with you, the simple fact of your ancestry has marked you forever. This prestige might aid you greatly in deal- ings with other vampires, or it might engender jealousy or contempt. Protégé (1pt. Merit)

Your sire watched you for some time before Embrac- ing you, and spoke glowingly of you to acquaintances. These vampires may be inclined to look favorably on you by dint of your sire's recommendation; you are at 1 difficulty on Social rolls with all those who've heard good things about you.]==],
				},
				["Primogen/Bishop Friendship"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Primogen/Bishop Friendship


The ruling vampires of the city value you and your opinions. You are called in to consult on decisions, and your recommendations carry great weight. Your posi- tion may not be an official one, but it's powerful none- theless.]==],
				},
				["Prized Collection (1)"] = {
					en = [==[Lore of the Bloodlines, p. 59


Prized Collection (1)


Kiasyd have appreciation for compilations of books, records, vintages of blood, and other collectable items among Cainites. You possess a collection that may not be worth much (1pt.) or could be worth a lot to the right buyer (2pt.). Importantly, it's a point of interest for any visiting Kiasyd or expert in the field, and they're likely to treat you well just to get access to it.]==],
				},
				["Prized Collection (2)"] = {
					en = [==[Lore of the Bloodlines, p. 59


Prized Collection (2)


Kiasyd have appreciation for compilations of books, records, vintages of blood, and other collectable items among Cainites. You possess a collection that may not be worth much (1pt.) or could be worth a lot to the right buyer (2pt.). Importantly, it's a point of interest for any visiting Kiasyd or expert in the field, and they're likely to treat you well just to get access to it.]==],
				},
				["Prized Patch"] = {
					en = [==[Anarchs Unbound, p. 102


Prized Patch


You belong to an Anarch gang with a violent, effective, or otherwise impressive reputation. The history of the gang might extend a hundred years before you were born, but so long as you hold membership and wear the colors of your crew, other Anarchs naturally tend to respect you. Some may even occasionally perform minor tasks for you to try to curry favor with the others. When your membership is known, reduce the difficulty of all Manipulation rolls with other Anarchs by 2 unless a given Anarch has a historical animosity with your gang.]==],
				},
				["Profane Trappings"] = {
					en = [==[Dark Ages Tome of Secrets, p. 108


Profane Trappings


You befoul everything you touch. Whether through intent or unfortunate happenstance, your Domain, Retainers, Herd, and trappings are all tainted with the unholy. While this pollutes your surroundings with a constant aura of nausea and unease, it does make any infernal acts easier to perform in their presence. By taking this Merit, any Disciplines you use are considered infernal; at the Storyteller's discretion, using your Disciplines on land you hold, on servants in your employ, or with objects you possess, reduces the difficulty of the roll by –2. Unholy Stain]==],
				},
				["Promethean Clay"] = {
					en = [==[Lore of the Clans, p. 238


Promethean Clay


Your flesh ripples and molds itself to your preternatural will, almost before you consciously invoke the change. The difficulty to use any Vicissitude power on yourself is two less than normal, and you may activate Vicissitude powers reflexively at your full dice pool while taking other actions. Powers that require multiple turns to activate still require the usual duration. The change simply occurs without conscious direction. As a final benefit, you need no physical sculpting to use the first three levels of Vicissitude on yourself, as your flesh undulates and extrudes to its desired shape. Only characters with at least one dot of Vicissitude may purchase this Merit.]==],
				},
				["Property (2)"] = {
					en = [==[Book of Secrets, p. 56


Property (2)


You've got a decent-sized piece of property that, while non-magickal, is certainly useful: a manor house, a farm, a nightclub, bookstore, restaurant, grove, and so forth. The larger and more prosperous the property, the more points this Merit costs. Elsewhere known as the Merits: Nightclub and Mansion, this Merit demands a minimum rating in the Background: Resources, as noted below. (2 points) A relatively small property of roughly 3000

square feet /900 meters, with perhaps – if it's a business

– a trickle of income that slightly exceeds its expenses.

Examples: a nice house, a comic store, a coffee shop, a

penthouse apartment, etc. Minimum Resources: 3 (3 points) A rather sweet place with dedicated servants

/staffers, all necessary facilities (sewer, trash, Internet

connection, etc.), and – if it's a business – an income

that contributes to your Resources Background. Examples:

A nightclub, a mansion, a small farm, a radio station, a

large store, and so forth. Minimum Resources: 4 (4 points) A substantial location, staffed with skilled

(though mundane) employees and connected to an acre

or two of associated land. Examples: A small office build-

ing, a family manor, an arena, a school, a medium-sized

farm, a vineyard, a small laboratory, a library, and the

like. At this level, it could also represent several smaller,

two-point Properties as well. Minimum Resources: 5 (5 points) An impressive holding that features an exten-

sive staff and a fair amount of property. Examples: An

office complex, a stadium, a college, a major laboratory,

a shopping center, an archive, and so forth. This level

could reflect a number of two-point or three-point

Properties, too. Minimum Resources: 6

Although this Merit, by itself, is in no way magickal or hyper- tech-equipped, your Property could provide the base of operations for the Backgrounds: Allies, Backup, Chantry, Cult, Library, Node, Resources, Retainers, Sanctum, and even Spies. (Baris- tas overhear a lot of crazy stuff…) Unless you've got a dedicated manager for the Property, it also demands a certain amount of time and attention, and quickly falls into disrepair and /or bankruptcy if you leave it alone for a week or more while jaunting off on various adventures. Property also tends to attract interest from parties both mundane and otherwise, especially if there's an ongoing rivalry with competing businesses, family enemies, an archnemesis, and so on. Cops take a dim view of wild stuff going down on your property, and the insurance costs can be murder if (read: when) your place gets trashed by extradimensional entities, HIT Marks, or raging Ascension Warriors.

Unless they're part of the Backgrounds: Allies, Backup, Cult, or Retainers, employees of your Property Merit do count as Sleeper witnesses with regards to magickal deeds on and around such properties.]==],
				},
				["Property (3)"] = {
