Unless they're part of the Backgrounds: Allies, Backup, Cult, or Retainers, employees of your Property Merit do count as Sleeper witnesses with regards to magickal deeds on and around such properties.]==],
				},
				["Prophetic Dreams"] = {
					en = [==[Lore of the Clans, p. 142


Prophetic Dreams


You have dreams during your daylight sleep. Dreams you remember. Sometimes, they even come true. By spending a Willpower point upon rising for the evening, you may have the Storyteller give your character a lucid dream featuring foreshadowing about upcoming events, characters, and situations.]==],
				},
				["Psychic Awareness"] = {
					en = [==[M20 Sorcerer, p. 106


Psychic Awareness


Even if you have no psychic powers of your own, you can sense the presence of recent psychic energies within a nearby area (about a 10-foot radius) with a Perception + Occult (difficulty 8) roll. How much information you glean and how detailed it is depends on your successes. A single success might merely confirm that a psychic talent was at work recently, while five or more might allow you to pick up the lingering sensation of a talented psychic who had been here, her strength, mood, and plans at the moment she had passed by.]==],
				},
				["Psychic Leech"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 179


Psychic Leech


At the cost of one Willpower point, you may feed on the Willpower of your victims from a distance. The con- sumed Willpower strengthens the potency of your own blood, effectively transforming it into temporary blood that dissipates at the end of the night. These temporary blood points may be spent just like regular blood points, but cannot be lost due to damage or blood drain, do not affect hunger rolls for frenzy, and may not be used to create or sustain blood bonds or ghouls. To activate this ability, the target must have at least one of your blood points in their system, and must be engaged in eye contact with you.]==],
				},
				["Quartermaster"] = {
					en = [==[Lore of the Clans, p. 219


Quartermaster


You are one of the Kindred responsible for maintaining and organizing the chantry's mundane supplies. You may take anything from the chantry's stores as defined by the chantry's Stores rating. While you will have to return or replace anything you borrow, you have access the whole range of equipment appropriate to the size of the chantry. This might range from assault weapons and explosives to advanced medical and scientific equipment.]==],
				},
				["Ravnos Jati"] = {
					en = [==[Dark Ages Companion, p. 101


Ravnos Jati


You belong to a widely-recognized Ravnos jati, affording you some measure of status with your Clan members. When- ever you interact with another Vagabond, treat your Status as one level higher; if they also belong to your jati, treat your Background as two levels higher and your Allies, Contacts, or Mentor as one higher where your jati is concerned. Once per session, if you're in a city with a significant Ravnos pop- ulation, you can find one member of your jati with no issue, who will likely help you out with no questions asked. Once per chapter, a member of your jati will seek you out for help with a troublesome and dangerous task.]==],
				},
				["Regal Bearing"] = {
					en = [==[Book of Secrets, p. 54


Regal Bearing


Aristocratic charisma is your birthright. Although you might not actually hail from a noble family, your presence radi- ates dignity. Posture, features, tone of voice, aura of dominion – you're got them all. People defer to you as a reflex; subtract 2 from the difficulty of your Social-Trait rolls whenever you're trying to make an impression, and while certain folks will want to take you down a few pegs on general principle, most people are inclined to respect you even if they don't necessarily like you.]==],
				},
				["Rep"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Rep


Your fame has exceeded the bounds of your Sect. Ev- eryone knows who you are, what you've done and what you're supposed to have done (which might not be the same thing). The publicity can be good or bad; what matters is that everybody knows your name. Wheth- er individuals outside of your immediate social circle know enough to match your face to your name is a dif- ferent matter.]==],
				},
				["Research Grant"] = {
					en = [==[The Hunters Hunted II, p. 141


Research Grant


You have a prestigious research grant from some university or research center. This frees you from the burden of needing a regular job. The grant provides a minimal stipend (from $1500 to $2000 a month in most cases), as well as credentials which grant access to exclusive libraries and research centers around the world. Supernatural]==],
				},
				["Revenant Disciplines"] = {
					en = [==[Lore of the Clans, p. 238


Revenant Disciplines


The blood of your revenant family runs deep, deeper than the Embrace. The Disciplines that were innate to you as a ghoul have remained so as a Cainite. At character creation, select the ghoul family from which you hail (V20, pp. 503-506). Instead of the Tzimisce's standard complement of Animalism, Auspex, and Vicissitude, you draw from your three family Disciplines for your starting allocation (though you may buy other Disciplines with freebies, as normal). You trade in the entire set of Tzimisce Clan Disciplines for the set of revenant family Disciplines, for the purposes of in-Clan Experience cost.]==],
				},
				["Rising Star"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Rising Star


You're one of the up-and-comers in the city, a rising star in your Sect. Everyone wants to know you and be your friend, even as those in power groom you for posi- tions of greater responsibility. You are at -1 difficulty on all Social rolls against any vampires in your Sect who aren't actively opposing your ascent.]==],
				},
				["Rugged Bad Looks"] = {
					en = [==[Lore of the Clans, p. 161


Rugged Bad Looks


While you are still hideous, you are not quite as ugly as most Nosferatu. You still have an appearance of 0, but you might pass for human in the right light. It is a still a good idea to cover up and stay in the shadows, but the sight of you (or even the smell of you) is not cause for someone to immediately think of you as a freak or a trauma victim.. Having said that, you are still ugly enough to unnerve the crap out of most people.]==],
				},
				["Sabbat Survivor"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Sabbat Survivor


You've lived through at least one Sabbat attack or attempted recruitment. Your experience helps you anticipate situations where you might potentially be endangered by the Sabbat once again. You are at 1 difficulty on all Perception rolls when it comes to Sabbat-based matters. This Merit is generally taken by groups in conflict with the Sabbat, and comes into play most frequently as a means of avoiding ambushes.]==],
				},
				["Sanction"] = {
					en = [==[The Hunters Hunted II, p. 133


Sanction


Your agency has given you a limited sanction to deploy lethal force against specific named targets. They will hold you responsible for any additional deaths, and won't hesitate to revoke your sanction if you're too sloppy. This authority is extremely rare — the CIA authorizes some killings in foreign territories, and a shadowy group high up in the FBI uses it to eliminate potential domestic terrorists. As long as you do as they tell you, your agency provides weapons and equipment (within reason) and will cover your tracks once the job is done. Despite popular perception, this isn't a “license to kill” — murdering people is still illegal even with the backing of an intelligence agency, and you could be prosecuted for murder if caught.]==],
				},
				["Sanctioned Witch"] = {
					en = [==[The Hunters Hunted II, p. 123


Sanctioned Witch


You are known as a “Judas Witch,” having received the Sanctuary of the Disciplina Arcani from the Inquisitor- General herself. You cannot be punished or detained for occult study or the use of Numina (though the sanction can be revoked for misconduct). A tattoo of the Seal of Solomon, on the palm of your left hand, marks your credentials. This does not mean everyone in the Society trusts your expertise, as many despise the magic arts.]==],
				},
				["Sanctity"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 488


Sanctity


This Merit is sometimes called the halo effect; ev- eryone considers you pure and innocent, though not necessarily naïve. You have a saint-like quality that is hard to pinpoint but cannot be denied. You are trust- ed, even if you are not trustworthy. At the Storyteller's discretion, you tend to receive lesser punishments for wrongdoing, and you are liked by most.]==],
				},
				["Sanctuary"] = {
					en = [==[The Hunters Hunted II, p. 44


Sanctuary


Your character has a safe house that is a true sanctuary. Supernatural creatures require a successful Willpower check (difficulty 9) in order to enter her home without an invitation. It might be due some strange mystical occurrence, luck, a forgotten ritual, or perhaps your character's house stands on consecrated ground. This Merit must be assigned to a single building in which the character has a permanent residence. Good examples of a sanctuary might be a house, a small apartment building, or a church.]==],
				},
				["Sanguine Incongruity"] = {
					en = [==[Lore of the Clans, p. 106


Sanguine Incongruity


Giovanni with this atavism are few and far between. Kindred possessing it do not bear the traditional Giovanni Clan weakness, the so-called Curse of Lamia; their Kiss causes no more damage than the blood loss itself. These vampires acquire a peculiar pallor upon their Embrace, however — they look like corpses, and no amount of blood ingestion can flush their features (as other vampires are able to do). Indeed, the bearer of this Merit more closely resembles the Clan's Cappadocian ancestors, and they have a slightly unnerving air about them. As a result, all rolls involving a Social attribute (Charisma, Manipulation, or Appearance) are at +1 difficulty.

Giovanni with this Merit are afforded wide berth, as the Giovanni tend to be quite superstitious about it. Characters with the Sanguine Incongruity Merit may not also possess the Mortuario Merit.]==],
				},
				["Scent of the Other"] = {
					en = [==[Lore of the Bloodlines, p. 80


Scent of the Other


“You don't seem like a soul-sucker…” For whatever reason, your third eye shuts tightly when you choose to hide it, and your blood and aura don't give away your Clan. You might be regarded as a Caitiff, or as a member of another Clan. In any case, Tremere or other Salubri hunters are thrown off your trail, unless you do something to reveal yourself again.]==],
				},
				["Scholar of Enemies"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Scholar of Enemies


You have taken the time to learn about and special- ize in one particular enemy of your Sect. You are aware of at least some of the group's customs, strategies, abili- ties, and long-term goals, and can put that knowledge to good use. This Merit is worth a -2 difficulty for all non-combat rolls pertaining specifically to the subject of your specialization. On the other hand, you are at a +1 difficulty when it comes to dealing with other en- emies, simply because you're so thoroughly focused on your field.]==],
				},
				["Scholar of Others"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 489


Scholar of Others


This Merit functions identically to Scholar of Ene- mies, except that it applies to a group that is not neces- sarily inimical to your Sect. Friend of the Underground]==],
				},
				["Science Laboratory"] = {
					en = [==[The Hunters Hunted II, p. 43


Science Laboratory


Your character has access to a fully stocked laboratory with functional scientific apparatuses and research equipment. When she has access to her laboratory, your character can perform experiments, run tests, and collect data, and you may lower your difficulty by 2 for relevant Investigation or Science rolls, or lower the difficulty by 1 for other appropriate rolls (as determined by the Storyteller) while she uses the equipment. Supernatural Merits and Flaws]==],
				},
				["Scientific Mystic /Techgnosi"] = {
					en = [==[Book of Secrets, p. 45


Scientific Mystic /Techgnosi


Certain unorthodox technomancers understand that “mysticism” is just another form of science whose principles may be understood by a properly Enlightened mind. Although you pursue a technological practice and employ tech-based instruments, you can employ instruments that are traditionally considered to be “magic” once you've had an opportunity to study them and fit those tools into your scientific paradigm.

The Scientific Mystic Merit lets a dedicated technomancer – that is, a member of the Society of Ether, the Virtual Adepts, a tech-based “orphan,” or perhaps even a rogue Technocrat like the Disparates of Navalon – study metaphysical princi- ples from mystic-paradigm mages for no extra point-cost if that technomancer has the focus practice Weird Science. (For details, see Can a Mage Who Uses One Type of Focus Learn Magick from a Mage Who Uses a Different Kind of Focus?, Chapter Three, p. 174, and the Weird Science entry in Mage 20, p. 584.) That technomancer can also choose tradi- tionally “mystic” tools as up to half of her required instruments (as detailed under Arete, Focus, and Instruments in Mage 20, p. 329), and can discard those instruments as a mystic instead of as a technomancer (again, see Mage 20, p. 329). Essentially, this means that your approach to Enlightened science is flexible enough to embrace bizarre approaches to your metaphysical pursuits. Other scientists might consider such things impos- sible, but you realize that “possibility” is what you make of it.

On the other side of that metaphysical coin, the Techgnosi Merit allows a dedicated mystic to do the exact same things, but with technological instruments and no extra cost involved in studying magick from technomancer peers, regardless of your practices. (See the Chapter Three entry cited above.) Yes, your soul belongs to the Mysteries, but you've recognized that technology has a place in those Mysteries as well.]==],
				},
				["Secret Code Language"] = {
					en = [==[Book of Secrets, p. 57


Secret Code Language


Language itself is a series of codes; folks who've been initiated into it (that is, folks who've learned the language) are considered members of the society in question. Some languages, however, are more exclusive and secretive than others. This Merit reflects your knowledge of a particular code known to only the “right people.”

Mages are secretive by nature, and so mage society is full of secret codes. Even Sleepers, though, have their own initiatory languages: military jargon, the Language of Flowers, various hand-signals, ciphers, and passwords employed by people who need to communicate with each other in ways no one outside their group can understand… except, perhaps, for those who've learned those codes through some “unauthorized” source.

As with the Merit: Language (p. 44), this Merit confers knowledge of a particular communication mode, which might not be in any way verbal. It could involve hand-signals, body postures, artwork, flags, symbolism, numbers, and so on. To uninitiated observers, that language appears to be gibberish (a word, incidentally, that refers to the coded writings of the alchemist Abu Musa Jabir ibn Hayyan); in many cases, a coded method of communication appears completely mundane unless you know what to look for, as with the encrypted artwork in The DaVinci Code.

One vital caveat: A character must have a very good in-game reason for knowing the things she knows. Learning a Secret Code Language requires some story-based foundation for that knowledge: elite military training, mind-reading, time among the group in question, etc. Fortunately, code languages tend to be utilitarian, revealing essential things in a general manner. (“I'm hungry,” “Kill him,” “This area's forbidden,” etc.) Even so, codes may have subtleties that aren't readily apparent; a single gesture or stressed syllable might mark the difference between Knock him out and move on quickly and Torture him to his least breath, no matter how long it takes.]==],
				},
				["Secret Society Member"] = {
					en = [==[Lore of the Clans, p. 218


Secret Society Member


You have found and joined one of the many secret societies in Clan Tremere. Your character must be suitable to join, such as having Necromancy to join the Covenant. You might pick one of the societies listed here or create one of your own. In most cases, your society membership should be kept secret, but your allegiance to it is not considered a crime. While your society expects you to uphold its tenets and agenda, they can also be counted upon to back you up and help you increase your power within the pyramid.]==],
				},
				["Secret Stash (2)"] = {
					en = [==[Lore of the Clans, p. 122


Secret Stash (2)


You have several resources, sleeper agents, or followers hidden away for a rainy day. For each level of this Merit you have one unassigned Background point “sitting in storage” (2 gives you one point, 3 gives you two points, and so on). At any time, you may spend as many of them as you like to increase your level in Allies, Contacts, Herd, Influence, Mentor, Resources, or Retainers. Once spent, the points remain assigned permanently, but until then they cannot be affected by anything. This allows the vampire to create a new resource in an instant, without requiring the expenditure of experience points or awaiting a downtime. The vampire is not really gaining new levels, but revealing levels he has had all along.]==],
				},
				["Secret Stash (3)"] = {
					en = [==[Lore of the Clans, p. 122


Secret Stash (3)


You have several resources, sleeper agents, or followers hidden away for a rainy day. For each level of this Merit you have one unassigned Background point “sitting in storage” (2 gives you one point, 3 gives you two points, and so on). At any time, you may spend as many of them as you like to increase your level in Allies, Contacts, Herd, Influence, Mentor, Resources, or Retainers. Once spent, the points remain assigned permanently, but until then they cannot be affected by anything. This allows the vampire to create a new resource in an instant, without requiring the expenditure of experience points or awaiting a downtime. The vampire is not really gaining new levels, but revealing levels he has had all along.]==],
				},
				["Secret Stash (4)"] = {
					en = [==[Lore of the Clans, p. 122


Secret Stash (4)


You have several resources, sleeper agents, or followers hidden away for a rainy day. For each level of this Merit you have one unassigned Background point “sitting in storage” (2 gives you one point, 3 gives you two points, and so on). At any time, you may spend as many of them as you like to increase your level in Allies, Contacts, Herd, Influence, Mentor, Resources, or Retainers. Once spent, the points remain assigned permanently, but until then they cannot be affected by anything. This allows the vampire to create a new resource in an instant, without requiring the expenditure of experience points or awaiting a downtime. The vampire is not really gaining new levels, but revealing levels he has had all along.]==],
				},
				["Secret Stash (5)"] = {
					en = [==[Lore of the Clans, p. 122


Secret Stash (5)


You have several resources, sleeper agents, or followers hidden away for a rainy day. For each level of this Merit you have one unassigned Background point “sitting in storage” (2 gives you one point, 3 gives you two points, and so on). At any time, you may spend as many of them as you like to increase your level in Allies, Contacts, Herd, Influence, Mentor, Resources, or Retainers. Once spent, the points remain assigned permanently, but until then they cannot be affected by anything. This allows the vampire to create a new resource in an instant, without requiring the expenditure of experience points or awaiting a downtime. The vampire is not really gaining new levels, but revealing levels he has had all along.]==],
				},
				["Sectarian Ally"] = {
					en = [==[Lore of the Clans, p. 26


Sectarian Ally


You have a close friend in one of the Kindred sects. Perhaps you are a warrior who is in touch with one of the antitribu, a vizier who shares common business interests with some Camarilla Ventrue, or a sorcerer who corresponds with one of the rare blood magicians of the Anarch Movement. Your ally can help you navigate the currents of their sect, but they might want something in exchange from time to time.]==],
				},
				["Self-Confident"] = {
					en = [==[Book of Secrets, p. 46


Self-Confident


Mages are confident; you're even more so. When spending Willpower to gain an automatic success, you don't even need to lose that point of Willpower unless:

1) The Willpower-gained success is the only success you get for that action; or…

2) the difficulty for that action is 5 or less. This Merit kicks in only in challenging circumstances, and tasks with a difficulty of 5 or lower are just too easy to demand help from your character's self-confidence.]==],
				},
				["Sense Influence"] = {
					en = [==[The Hunters Hunted II, p. 151


Sense Influence


Through training and working with other experienced hunters, you have the ability to buy the Awareness Skill. Further, you can get a sense that someone is controlled by some supernatural influence or ghostly presence with a Perception + Awareness roll, difficulty 8. Social]==],
				},
				["Setite Initiate"] = {
					en = [==[Lore of the Clans, p. 67


Setite Initiate


You were Embraced into a Clan other than the Followers of Set. However, you have accepted the Setite religion, undergone the vetting process and rites, and have been formally inducted into the cult. You have access to Serpentis and Setite Blood Sorcery (though you pay out-of-Clan costs to learn them). You may even study one of their Paths of Enlightenment.

It is important to note that “Setites” from other Clans or bloodlines are not treated as second-class citizens. You are no longer a dupe they can string along. Once you are in, you are a sibling of faith, which is a much more important distinction than blood. An outsider accepting the Dark God is a joyous event, even to the most conservative elder. There are even rumors of non-Kindred supernatural beings joining the cult.]==],
				},
				["Shapechanger Kin"] = {
					en = [==[Book of Secrets, p. 74


Shapechanger Kin


Through a distant but noticeable quirk of lineage, you share a touch of the Changing Blood. In plain English, you're related to one of the were-breeds: werewolves, werecats, were- crows, and so forth. This gift does not grant you their powers or Gnosis, but you probably know a few secrets (in game terms, Lore Knowledge) about your kin. You remain immune to the primal-fear Delirium that affects most people in a werecreature's presence (not that mages suffer from it anyway); can travel in the Otherworlds longer than most mortals manage, without suffering the Disconnection and Acclimation side-effects of such travel (detailed in Mage 20, pp. 482-483); and possibly enjoy some goodwill from your feral family, so long as you haven't done anything to piss them off. Their enemies, however, are your enemies, which makes this an extremely double-edged Merit.]==],
				},
				["Shattered Avatar"] = {
					en = [==[Book of Secrets, p. 77


Shattered Avatar


Your Avatar has been broken into pieces by some past-life trauma. As a result, the part within you is incomplete… but that situation can be rectified. If and when you locate the missing pieces of your Avatar, you could make that inner spirit stronger. In gamespeak, this Merit allows you to increase your Avatar Background after character creation – a thing that cannot, ordinarily, be done. (See Mage 20, p. 336.)

As with Twin Souls, above, this Merit provides plenty of dramatic story hooks. The missing pieces of your Avatar might be incarnated in other people; trapped in spiritual prisons (Paradox Realms, demonic hells, soul- snares, enchanted gems, and so forth); embedded in a tree in a garden that's warded by five dragons, and so on. The quest for your soul-fragments can be an epic part of your chron- icle, with puzzles, twists, reversals, betrayals, and battles for which your soul is literally the prize. This sort of thing might be hard to reconcile with your beliefs if, for example, you happen to be a Technocrat. Still, until you unite the missing bits of your Avatar, there'll be an essential part of you that feels incomplete.

The Storyteller should determine exactly what it was that shattered your Avatar, and what you need to do in order to reunite the various bits into one spirit again. Whether or not she shares that information with you is up to her – it might be something you'll discover over the course of the game. With each piece restored, you add one dot to your Avatar Background rating, unless that Avatar was embodied in another mage; in that case, his Avatar rating gets added to your own if you manage to kill him… and if he kills you first, then your Avatar gets added to his own. (There can, apparently, be only one.)

No matter how many pieces are involved, however, the Avatar Background maxes out at 5 dots. Although this Merit allows you to raise your Trait's rating, it does not allow you to raise it above that level. Spark of Life]==],
				},
				["Sight Beyond Sight"] = {
					en = [==[Lore of the Bloodlines, p. 80


Sight Beyond Sight


Your third eye occasionally experiences visions and pierces illusions. When your eye is open (via use of Auspex or Obeah), you occasionally pierce Obfuscate or Chimerstry. Some past Salubri have seen through faerie miens or glimpsed the dead lands of ghosts. You have no control over what your eye sees, though it'll sometimes open involuntarily in response to the above phenomena.]==],
				},
				["Simply Waiting"] = {
					en = [==[Lore of the Bloodlines, p. 16


Simply Waiting


The Baali knows their place within the order of the universe, and where they stand against other vampires or those of their own bloodline. They also know the end of the world is coming, sooner rather than later. They appear apathetic to the world around them, but in truth, they are simply resigned to their fate and remain unmoved if others try to get them to stray from their path. All Social rolls against them are increased by +2 difficulty, as the Baali knows the true end of it all.]==],
				},
				["Skald"] = {
					en = [==[Lore of the Clans, p. 87


Skald


Anytime you make an Occult roll to know a fact about vampiric history, you may add a die to your dice pool. Further, you have exceptional memory for oral histories, and you are a quick study when it comes to memorizing large amounts of rote information. This is not true eidetic memory, but constitutes the ability to memorize poetic eddas, codes, or complex messages with only a few hours of study.]==],
				},
				["Skin of Porcelain"] = {
					en = [==[Lore of the Bloodlines, p. 60


Skin of Porcelain


Through concoctions imbibed or by a fluke of your Embrace, you possess a ceramic-like coating to your skin. In order for this to have any effect beyond looking strange, a Stamina roll is required (difficulty 8). Success allows you to convert up to three points of aggravated damage from a fire source to lethal damage before attempts to soak. The hardening dissipates for the remainder of the current story.]==],
				},
				["Sleep Unseen"] = {
					en = [==[Lore of the Clans, p. 161


Sleep Unseen


The power of Obfuscate usually requires you to concentrate at least a little. However, you are able to lock the power on, allowing you to sleep while remaining hidden. To do so requires the expenditure of blood point, but it will last throughout the day's rest. Those with Auspex can still attempt LORE OF THE CLANS to detect you, but mortals will be unaware of your sanctuary. This can be a useful trick for Kindred who like to travel.]==],
				},
				["Slimy"] = {
					en = [==[Lore of the Clans, p. 161


Slimy


You secrete an ooze, which is as disgusting as it sounds. The ooze covers your entire body and soaks into your clothes. It makes you slippery and difficult to hold, requiring opponents to gain two more successes to grapple you. The dampness also makes you a little fire resistant, reducing your difficulty to soak fire damage by 1.]==],
				},
				["Slowed Degeneration"] = {
					en = [==[Lore of the Clans, p. 200


Slowed Degeneration


Your Humanity is strong and can more easily withstand the Beast's assaults. You gain two additional dice on any Conscience roll. This degree of moral resilience allows a well-behaved vampire to lose Humanity at a much slower rate than would otherwise be possible. Only vampires following Humanity may take this Merit, and the Merit is lost forever in the event that the vampire takes up another Path of Enlightenment.]==],
				},
				["Soapbox"] = {
					en = [==[Anarchs Unbound, p. 4


Soapbox


You have some sort of special forum (a zine, a secure blog, a well-known podcast, or a social media account with a lot of followers) that allows your Anarch to express an opinion and have said opinion spread widely. The Soapbox Merit represents a social delivery mechanism that can influence Kindred outside of your character's normal social circle or class. Reduce the difficulty of Expression and Subterfuge rolls by 2 difficulty when dealing with vampires who read the Soapbox.]==],
				},
				["Socially Networked"] = {
					en = [==[Book of Secrets, p. 57


Socially Networked


Well-Connected on the Internet (as in the Virtual Adept Merit of that name), you enjoy a high online profile – a web- site, at least one blog, more Twitter followers and Facebook friends than you could possibly meet in Meatspace, and so on. When you post, folks read, share, and take it seriously. While this might or might not translate into folks you know in the Digital Web (and really – would you want it to?), you command global influence via the World Wide Web. As a result, you've got the sort of influence and resources that most folks cannot imagine: crowdfunding backers, instant information, places to crash all over the world if and when you want them… the details depend upon the sort of presence you maintain and the people you attract, but they go beyond anything you could accomplish without the Internet.

Of course, you could fuck things up on a grand scale if you're not careful – such attention can backfire on you if you post the wrong thing at the wrong time – and certain haters despise you on general principle. Considering that the Internet is a prime front in twenty-first century reality wars, though, this sort of network can provide a major edge for your side.]==],
				},
				["Spark of Life"] = {
					en = [==[Book of Secrets, p. 78


Spark of Life


Blessed with great vitality, you heal injuries with heroic speed and ease. Your own injuries from lethal damage heal as if they were bashing damage (see the Healing Damage chart in Mage help from the Storyteller. The nature of said help is entirely up 20, p. 406), and aggravated damage heals as if it to the Storyteller, although it should be beneficial in at least the were one level higher than it is. (Wounded-level short term. The help in question should also suit the nature of

the mage and her paradigm, although that suitability might turn 78 The Book of Secrets out to be

damage, for instance, would heal

at the Injured-level rate.) Bashing

damage, regardless of its extent,

heals within an hour.

If you're trying to heal someone

else, you subtract -2 from the difficul-

ty of the roll, even if that roll involves

casting a Life Sphere healing Effect.

(The usual +3 maximum modifier

and minimum difficulty of 3 still

apply – see Mage 20, p. 503.) As long

as you remain in physical touch

with the injured party, that

character uses your healing

rate as her own. Your touch

also soothes minor pains –

muscle spasms, headaches,

and so forth – within a

minute or two.

Beyond its healing pow-

ers, this rush of life-energy

simply feels good, too. Your

aura shines with bright

vitality, and your Reso-

nance reflects your strong

connection to the primal

life-force. On the inevita-

ble downside, vampires

find your blood delicious

– twice as potent as normal

human vitae (worth double the

usual blood points, for players of

Vampire: The Masquerade) – and

unspeakably refreshing.

Guardian Angel]==],
				},
				["Spawning Pool (1)"] = {
					en = [==[Lore of the Clans, p. 161


Spawning Pool (1)


You have a spawning pool of your own (or possibly donate heavily to the Clan's main pool). Creating such a pool takes time, and requires regular infusions of blood, at least six blood points a week for a year.

The Merit grants its level as a dice pool bonus to the Nosferatu's use of Animalism in their home city, but only with animals considered vermin, such as rats and cockroaches. Essentially the bonus is only available for creatures that might conceivably drink regularly from the tainted blood.

Once established, the spawning pool requires twice its level in blood points each week to it. Without proper maintenance, its level will drop by one. It can be rebuilt by maintaining it at the new level and adding four additional blood points each week for six months.

The Merit cannot be improved above its initial level, as this also represents the convenience of its location and the variety of creatures that might find it.]==],
				},
				["Spawning Pool (2)"] = {
					en = [==[Lore of the Clans, p. 161


Spawning Pool (2)


You have a spawning pool of your own (or possibly donate heavily to the Clan's main pool). Creating such a pool takes time, and requires regular infusions of blood, at least six blood points a week for a year.

The Merit grants its level as a dice pool bonus to the Nosferatu's use of Animalism in their home city, but only with animals considered vermin, such as rats and cockroaches. Essentially the bonus is only available for creatures that might conceivably drink regularly from the tainted blood.

Once established, the spawning pool requires twice its level in blood points each week to it. Without proper maintenance, its level will drop by one. It can be rebuilt by maintaining it at the new level and adding four additional blood points each week for six months.

The Merit cannot be improved above its initial level, as this also represents the convenience of its location and the variety of creatures that might find it.]==],
				},
				["Spawning Pool (3)"] = {
					en = [==[Lore of the Clans, p. 161


Spawning Pool (3)


You have a spawning pool of your own (or possibly donate heavily to the Clan's main pool). Creating such a pool takes time, and requires regular infusions of blood, at least six blood points a week for a year.

The Merit grants its level as a dice pool bonus to the Nosferatu's use of Animalism in their home city, but only with animals considered vermin, such as rats and cockroaches. Essentially the bonus is only available for creatures that might conceivably drink regularly from the tainted blood.

Once established, the spawning pool requires twice its level in blood points each week to it. Without proper maintenance, its level will drop by one. It can be rebuilt by maintaining it at the new level and adding four additional blood points each week for six months.

The Merit cannot be improved above its initial level, as this also represents the convenience of its location and the variety of creatures that might find it.]==],
				},
				["Sphere Natural"] = {
					en = [==[Book of Secrets, p. 79


Sphere Natural


For a single element of magick – the Sphere of your choice – you enjoy an innate proficiency. The powers of that Sphere come to you more easily than usual, and you advance faster in that field of knowledge than you do in other Spheres. System-wise, you pay 70% of the usual experience cost, rounded up, when advancing in that Sphere. Naturally, such advancement costs even less when you're raising your Affinity Sphere. Rank Cost /Affinity Sphere Cost New Sphere: 7 pts. 2 6 /5 pts. 3 11 /10 pts. 4 17 /15 pts. 5 23 /20 pts.

The Mage 20 version of this Merit costs more than the ver- sion presented in previous editions because the cost of improving Spheres with experience has gone down, and so the benefits involved in this Merit have gone up. You may select this Merit only once, for a single Sphere, and that Sphere should have some intrinsic connection to your mage's concept, backstory, and magickal focus. This is, after all, an Art that comes naturally to you, and so that predisposition should come through in many different aspects of your character's personality.]==],
				},
				["Spirit Mentor"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


Spirit Mentor


You have a ghostly companion and guide. The iden- tity and exact powers of this spirit are up to the Story- teller, but it can be called upon in difficult situations for help and guidance.]==],
				},
				["Stillness of Death"] = {
					en = [==[Lore of the Bloodlines, p. 37


Stillness of Death


Gargoyles often hide themselves as statuary. The difficulty for any searches to find you are increased by 2 when you stay perfectly still.]==],
				},
				["Stitcher"] = {
					en = [==[Lore of the Bloodlines, p. 5


Stitcher


Getting blown apart isn't a big deal. When parts of your body are cut off or otherwise removed due to damage, you may make a Dexterity + Medicine (difficulty 7) to sew the part back in place properly. If successful, the cost of healing the wound is reduced by one blood point.]==],
				},
				["Stormwarden"] = {
					en = [==[M20 Victorian Age, p. 122


Stormwarden


Given the time in

which these stories take place, this Merit is an irrelevant

concept.]==],
				},
				["Stormwarden /Quantum Voyager (3)"] = {
					en = [==[Book of Secrets, p. 74


Stormwarden /Quantum Voyager (3)


See Mage 20, p. 643.]==],
				},
				["Stormwarden /Quantum Voyager (5)"] = {
					en = [==[Book of Secrets, p. 74


Stormwarden /Quantum Voyager (5)


See Mage 20, p. 643.]==],
				},
				["Strength of Psyche"] = {
					en = [==[M20 Sorcerer, p. 107


Strength of Psyche


You have developed a talent to draw on arcane energies to supercharge your mind. You can sharpen your senses, speed your thoughts, and connect the dots between disparate clues. You may spend Quintessence points to reduce the difficulty of any die pool for a men- tal action. The difficulty may not be reduced below two, nor be reduced by more than three. You must be able to store Quintessence in your own pattern to be eligible for this Merit.]==],
				},
				["Sturdy"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 420


Sturdy


Training, hardships, or natural ability have inured your body to pain and damage. While you are not necessarily a hulking brute, anyone who has seen you in action knows that you can take more dam-

age than the average individual. You gain an additional

Bruised health level and the Storyteller may award you

with any appropriate bonuses when your innate toughness

comes into play.]==],
				},
				["Style Sleeper"] = {
					en = [==[M20 Sorcerer, p. 107


Style Sleeper


Your character knows that magic is real, they practice magic themselves, but these other pretenders are clearly fakes. Anytime you see magic that fits your Paradigm, things proceed as they should, but when you are a witness to magic outside of that style, you are treated as a Sleeper. This is not a Flaw because it more often disrupts the magic of your op- ponents and not your own. There may be some unintended consequences when another sorcerer of a different Paradigm tries to heal you, but your disbelief counters their magic.]==],
				},
				["Styx Baptism"] = {
					en = [==[Lore of the Bloodlines, p. 48


Styx Baptism


You pledged fealty to the Harbingers of Skulls and swore to work against the machinations of Ashur, despite not being Embraced into the bloodline. You were escorted to the Shadowlands, where you were baptized head-first in the churning waters of the Styx. The flesh upon your head sloughed off with contact over the coming month, leaving just rotten patches or bare bone, reducing your Appearance Rating to 0 permanently. You're now held in esteem by Lazarenes, gaining any one of the bloodline's Disciplines as a Clan Discipline in place of one of your own.]==],
				},
				["Subculture Insider"] = {
					en = [==[Book of Secrets, p. 58


Subculture Insider


You're innately familiar with a social environment that most folks never visit, much less understand. They know you there, and so even when you haven't met a given person (human or otherwise) in that environment, they consider you to be an insider. Thanks to your familiarity, you can navigate certain elements of the physical environment there too – the security apparatuses, the “secret handshakes,” the hidden corners that an insider would know about and an outsider would never think to look for, and other obstacles that a subculture puts into place to make certain that only the “right” people can get around. When moving through your subculture of choice, subtract -2 from the difficulties of rolls that grant social or physical access to that subculture's established turf.

The subculture in question can be any kind of exclusive social environment that also includes the physical surroundings employed by that particular group: country clubs, drug cartels, the international mercenary network, the global espionage un- derworld, high-level finance executives, the fetish community, homeless transient communities, clannish rural communities, hip-hop networks, the jet set, rave festival culture, fantasy fans, the touring road-dog musical community, world financial leaders, “gypsy” Travelers, and so on. Although it can include mages and other Night-Folk, the community must be essentially “mortal” in terms of the majority of insiders. You can buy this Merit several times to reflect membership in several different communities. That insider status, however, takes time to acquire and a lot of attention to maintain. If you neglect your community, you'll soon find those familiar doors slammed in your face.]==],
				},
				["Sugar Daddy"] = {
					en = [==[Anarchs Unbound, p. 102


Sugar Daddy


You have a personal relationship with a high-ranking member of a different sect. You may invoke your Sugar Daddy's name to lower the difficulty of Manipulation rolls by 2 against members of that sect when attempting to smooth out problems or acquire minor favors. Of course, the Sugar Daddy may expect similar treatment in kind, and is unlikely to look favorably on any behavior that impugns whatever status he may have.]==],
				},
				["Supernatural Companion"] = {
					en = [==[Book of Secrets, p. 74


Supernatural Companion


You've got a friend among the Night-Folk: a vampire, a changeling, a werebeast, a ghost, or some other entity who exists outside the Sleeping Masses. This friend isn't quite as reliable as an Ally Background character, but can aid you if need be. That door swings both ways, of course; your companion will also call on you from time to time, and not always on the most convenient occasions!

Folks (and Night-Folks) probably frown upon this friend- ship. Werewolves, for example, aren't fond of you Caern-robbing mage-types! That's especially true if you're a Technocrat who's buddy-buddy with one of those damned Reality Deviants, or a Tradition mage who pals around with a bloodsucking fiend. Yeah, this friendship is worth the trouble, but it can really be a hassle at times. Whoever and whatever this friend might be, the Storyteller creates and controls the character in question… with all the strange priorities, conflicting needs, and secret agendas that situation suggests. Stormwarden /Quantum Voyager]==],
				},
				["The Company of Saints and Heroes"] = {
					en = [==[Vampire: The Dark Ages 20th Anniversary Edition, p. 423


The Company of Saints and Heroes


Life

(and possibly unlife) experiences have brought you close

to august religious figures, political entities, and legendary

heroes. They do truly know you and think well of you, but

you are not necessarily close. Use the Allies background

to represent a tighter relationship. This Merit allows you

to name-drop your famous connection and reduce the

difficulty to applicable Social rolls by one.]==],
				},
				["The Flow of Ki"] = {
					en = [==[M20 Sorcerer, p. 106


The Flow of Ki


You understand the natural flow of energy through the human body, taught through a form of martial arts. This energy is represented as Quintessence but may be called a variety of things: chi, ki, and others, depending on your martial arts style. You may spend Quintessence from your internal reserves to reduce the difficulty of any die pool for physical actions. You cannot lower the difficulty below two, nor may you reduce it by more than three. You must be able to store Quintessence in your own pattern to be eligible for this Merit.]==],
				},
				["The High Price"] = {
					en = [==[Lore of the Bloodlines, p. 16


The High Price


The burden of acquiring truth or power always comes at a high price. None know that more than these Baali, who sacrifice a part of their own soul in aspiration of greatness. Their physical body is wracked with weakness and pain, capping any Physical Attributes at four dots and costing 1 Willpower point every evening when they rise. In exchange for this tribute, the Baali receive +2 dice to any Discipline-related checks.]==],
				},
				["Thousand Meter Killer"] = {
					en = [==[Lore of the Clans, p. 26


Thousand Meter Killer


You have proven yourself worthy to join the Thousand Meter Club through your remarkable skill with the sniper rifle. The difficulty of all rolls associated with sniping is reduced by -1. You also double the normal range when using a sniper rifle as a weapon.]==],
				},
				["Thugs"] = {
					en = [==[The Hunters Hunted II, p. 151


Thugs


When you purchase the Allies Background, you are acquiring hard-core members of the underworld rather than ordinary members of lawful society. Your Allies may be gang members, mafiosos, or members of your organized crime syndicate. Unlike normal Allies, these individuals are willing to pick fights with other mortals, murder innocents, intimidate locals, temporarily lock down an area of the city, or even commit crimes on your behalf.]==],
				},
				["Ties"] = {
					en = [==[Book of Secrets, p. 58


Ties


See Mage 20, pp. 643-644.]==],
				},
				["Time Sense"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Time Sense


You have an innate sense of time and are able to es- timate the passage of time accurately without using a watch or other mechanical device.]==],
				},
				["Too Tough to Die"] = {
					en = [==[Book of Secrets, p. 39


Too Tough to Die


See Mage 20, p. 644.]==],
				},
				["Totemic Change"] = {
					en = [==[Lore of the Clans, p. 87


Totemic Change


Your Protean forms are flexible; you may choose a different animal form each time you change shape. The form you choose each time must follow all the conventions and rules of standard Protean animal shapes (see p. 91); you simply may choose to appear as a different animal each time you take Beast Form.]==],
				},
				["Tough Hide"] = {
					en = [==[Lore of the Clans, p. 161


Tough Hide


Your skin is much tougher than usual, possibly like that of a rhino or a lizard. This hide protects you against most damage, granting you an extra die when making a soak roll. However, this bonus does not apply against fire and sunlight.]==],
				},
				["Tracker's Mark"] = {
					en = [==[Dark Ages Companion, p. 100


Tracker's Mark


Well attuned to the soul of her quarry, the Salubri's third eye

sees the influence of her opponent in the world, rather than mere

V20 Dark Ages, page 337), the Salubri's player rolls at -2 difficulty.

Ephemeral signs of a quarry are considered valid evidence to follow,

even if a Salubri cannot normally detect them; for example, if an

irate Brujah disturbed a market's peace, the Warrior can discern

his presence from the still-irritated traders hours later, making the

intuitive leap to relate the event to her quarry's passing.]==],
				},
				["True Celerity"] = {
					en = [==[Lore of the Bloodlines, p. 99


True Celerity


The True Brujah have an odd relationship with Celerity. It often comes easily to them, but a few refuse to learn it, as it has become a symbol of the traitor Brujah. However, many find it a useful skill for masquerading as Brujah within the Camarilla or Sabbat, and so a few True Brujah have developed a slightly different form of the Discipline.

A character with this Merit has the ability to learn True Celerity. While it works exactly the same as Celerity, it feels very different. Instead of the character moving quickly, they slow time down all around them. This Merit confers no Discipline points for the character, but does allow it to be bought with experience as if Celerity was a Clan discipline. While this power functions the same as Celerity, it cannot be taught to anyone who does not have any levels of the Temporis Discipline.]==],
				},
				["True Faith"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


True Faith


You have a deep-seated faith in and love for God, or whatever name you choose to call the Almighty. You begin the game with one point of True Faith (see the sidebar on p. 372); this Trait adds one die per point to all Willpower and Virtue rolls. You must have a Hu- manity of 9 or higher to choose this Merit, and if you lose even a single point, all your Faith points are lost and may be regained only when the lost Humanity is recovered. Individuals with True Faith are capable of performing magical acts akin to miracles, but the exact nature of those acts are up to the Storyteller.]==],
				},
				["True Love"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 493


True Love


You have discovered, perhaps too late, a true love. He or she is mortal, but is the center of your existence, and inspires you to keep going in a world of darkness and despair. Whenever you suffer, the thought of your true love gives you the strength to persevere. This Mer- 493 it grants you one automatic success on all Willpower rolls, which can be negated only by a botch die. This can be a great gift but also a hindrance, for your true love may require protection and occasionally rescue.]==],
				},
				["Tunnel Rat (1)"] = {
					en = [==[Lore of the Clans, p. 161


Tunnel Rat (1)


You are remarkably adept at moving through the underground tunnels that you call your home. When attempting to navigate, escape, or track through sewers and underground places you know, you gain an additional die for every point you have in this Merit.]==],
				},
				["Tunnel Rat (2)"] = {
					en = [==[Lore of the Clans, p. 161


Tunnel Rat (2)


You are remarkably adept at moving through the underground tunnels that you call your home. When attempting to navigate, escape, or track through sewers and underground places you know, you gain an additional die for every point you have in this Merit.]==],
				},
				["Tunnel Rat (3)"] = {
