Tunnel Rat (3)


You are remarkably adept at moving through the underground tunnels that you call your home. When attempting to navigate, escape, or track through sewers and underground places you know, you gain an additional die for every point you have in this Merit.]==],
				},
				["Tunnel Rat (4)"] = {
					en = [==[Lore of the Clans, p. 161


Tunnel Rat (4)


You are remarkably adept at moving through the underground tunnels that you call your home. When attempting to navigate, escape, or track through sewers and underground places you know, you gain an additional die for every point you have in this Merit.]==],
				},
				["Tunnel Rat (5)"] = {
					en = [==[Lore of the Clans, p. 161


Tunnel Rat (5)


You are remarkably adept at moving through the underground tunnels that you call your home. When attempting to navigate, escape, or track through sewers and underground places you know, you gain an additional die for every point you have in this Merit.]==],
				},
				["Twin Link (4)"] = {
					en = [==[M20 Sorcerer, p. 107


Twin Link (4)


Your psychic character shares a permanent psychic connection to another person. This duplicates the ben- efit of the Level Two Synergy effect. The linked psychics gain +2 to their Empathy score to determine the other party's feelings. As a 6pt Merit, the bonded characters can purchase the Synergy power, in addition to other psychic powers they may have at a lower cost — 7 freebie points per dot, 3 experience points per dot to increase. This Synergy power only works on their bonded partner. Wild Talent: (4 pt Merit to 4 pt Flaw)

While many psychics never receive proper training to develop their gifts, you lack even basic control of your powers. However, without burdensome control over your talents comes greater power. Use the following table to determine the costs and effect of this Merit (or Flaw) which cannot exceed 4 points: +1 For every extra die you have when using the power. –1 You must make a Willpower roll (Difficulty 7) to

use the power. –2 You can only consciously use the power defensively.

(Your precognitive powers warn you of an attack

using Danger Sense, or your telekinesis can stop

an oncoming car.) –3 You have no conscious control of the power, but

it works more often to your benefit than not.

(Your clairvoyancy manifests in useful prophetic

dreams.) –4 Your powers activate randomly (a minimum of

once per session) and often when you least expect

or desire it. (Telekinetically flinging books around

a library while attempting to do research.)]==],
				},
				["Twin Link (6)"] = {
					en = [==[M20 Sorcerer, p. 107


Twin Link (6)


Your psychic character shares a permanent psychic connection to another person. This duplicates the ben- efit of the Level Two Synergy effect. The linked psychics gain +2 to their Empathy score to determine the other party's feelings. As a 6pt Merit, the bonded characters can purchase the Synergy power, in addition to other psychic powers they may have at a lower cost — 7 freebie points per dot, 3 experience points per dot to increase. This Synergy power only works on their bonded partner. Wild Talent: (4 pt Merit to 4 pt Flaw)

While many psychics never receive proper training to develop their gifts, you lack even basic control of your powers. However, without burdensome control over your talents comes greater power. Use the following table to determine the costs and effect of this Merit (or Flaw) which cannot exceed 4 points: +1 For every extra die you have when using the power. –1 You must make a Willpower roll (Difficulty 7) to

use the power. –2 You can only consciously use the power defensively.

(Your precognitive powers warn you of an attack

using Danger Sense, or your telekinesis can stop

an oncoming car.) –3 You have no conscious control of the power, but

it works more often to your benefit than not.

(Your clairvoyancy manifests in useful prophetic

dreams.) –4 Your powers activate randomly (a minimum of

once per session) and often when you least expect

or desire it. (Telekinetically flinging books around

a library while attempting to do research.)]==],
				},
				["Twin Souls"] = {
					en = [==[Book of Secrets, p. 75


Twin Souls


To you, the term soulmate is literally true. Your Avatar has a twin that has been embodied within another mortal body. That other person (typically a human being, but potentially an animal) shares your Nature and Essence, and possibly your Demeanor as well. Even so, your “twin” can be a very different person – different gender, different ethnicity, different culture, and again possibly even a “higher” animal like a wolf, bear, hawk, bison, and so forth. That person might live on the other side of the world, and may not even know that you exist. If soul-twins meet in person, though, both feel an unmistakable connection to one another. This connection, however, might not necessarily translate to goodwill. Blood-siblings often clash, and soulmates can clash as well.

If that twin is also a mage (many twin Avatars are not yet Awakened), then both mages have the same Avatar rating. You can both share Quintessence and cast spells together if you happen to be physically touching (or, in the Umbra, ephemerally touching). In this case, the character with the highest Arete rating and Sphere Ranks is the one whose Traits get used to cast those Effects. Both mages, when they're within arm's reach, also get an amount of bonus Quintessence points that's equal to their Avatar rating; if Ryan Summers and his twin Sylvia Jane have three dots in Avatar, they each get an additional three points of Quintessence when they're close enough to touch one another. For details about collaborative spellcasting, see Acting in Concert in Mage 20, pp. 542-543. Shared souls, however, also share equally in any Paradox gathered by their magicks, with each twin separately getting the full amount of Paradox. If Ryan or Sylvia casts an Effect that earns 10 points of Paradox, then both Ryan and Sylvia get 10 Paradox points each.

Whether or not your twin is a mage, you can use magick to keep track of them once you've met your twin. A single dot of Correspondence will let you know where your soulmate is, a single dot in Life will let you know their current state of health, and a single dot in Mind allows you to share thoughts with one another. A twin's death, however, is a shattering event; if your twin dies, you must make a Willpower roll (difficulty 8) or else suffer the psychic shock of Things Man Was Not Meant to Know. Until that twin's Avatar reincarnates (which might not happen in your own lifetime), and is met in person once again, you cannot use the shared powers you had once enjoyed.

As with other character-based Traits, your twin is not a walking Merit but a character in their own right. Both twins could be roleplayed by different players in the same group, and probably should not be played by the same player. The quest to find a soulmate, a bitter dispute between soulmates, two soul- mates on opposing factions of the Ascension War – such stories could provide the foundation for pivotal events and themes in your chronicle. This Merit goes well with the Background: Allies, the Merit: True Love, and the Flaws: Enemy, Sleeping with the Enemy, and Ward. Because of the already-Awakened natures of the Night-Folk, however, a soul-twin cannot be a vampire, werecreature, changeling, or other paranormal entity.]==],
				},
				["Umbral Affinity"] = {
					en = [==[Book of Secrets, p. 75


Umbral Affinity


See Mage 20, p. 644.]==],
				},
				["Unaging"] = {
					en = [==[Book of Secrets, p. 69


Unaging


The years seem to pass you by. Time moves on, but you remain essentially the same physical age as you were when this Merit stopped your aging process. Maybe you discovered the Fountain of Youth, upgraded yourself to perpetual stability, assumed an odd relationship with the time stream, or entered an uncanny bargain that preserved your current age. And so, although you continue to accumulate the scars, experience, and perspective of age, your body maintains a consistent state of chronological development. Note that this is not the same thing as immortality – injuries and sickness can kill you just as surely as they'll kill any other person. Age-based decrepitude, however, is not something you'll have to worry about.]==],
				},
				["Unbondable"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 494


Unbondable


You are immune to being blood bound. Tremere can- not take this Merit.]==],
				},
				["Unmarked Antitribu (2)"] = {
					en = [==[Lore of the Clans, p. 219


Unmarked Antitribu (2)


While you are part of the Sabbat and a traitor to House and Clan Tremere, somehow you remain unmarked by the antitribu curse. You are not easily recognized as a renegade Tremere, and the magic that burned so many of your brethren cannot target you. Further, other Sabbat members cannot judge you at a glance. Those of the Telyavelic bloodline can purchase this Merit at 2 points, while other Tremere pay 5 points.]==],
				},
				["Unmarked Antitribu (5)"] = {
					en = [==[Lore of the Clans, p. 219


Unmarked Antitribu (5)


While you are part of the Sabbat and a traitor to House and Clan Tremere, somehow you remain unmarked by the antitribu curse. You are not easily recognized as a renegade Tremere, and the magic that burned so many of your brethren cannot target you. Further, other Sabbat members cannot judge you at a glance. Those of the Telyavelic bloodline can purchase this Merit at 2 points, while other Tremere pay 5 points.]==],
				},
				["Unobtrusive"] = {
					en = [==[Book of Secrets, p. 54


Unobtrusive


You can pass without notice in most social situations. This is less about the uncanny Background: Arcane (although it can complement that Background) than it is a matter of simply seeming unremarkable. Unless you make a fuss of some kind, folks just don't remember you. You're… um, that dude… or that girl… or, well, damn, I don't even remember exactly what sort of person you are, actually. And in some lines of work or walks of life, this is a very useful talent to have.

Although it does not in any way render you invisible or untraceable, this Merit lets you blend in and slip from memory. Folks need to make a Perception roll (difficulty 6) in order to recall your features or name. On the flipside, you add +2 to the difficulty of any social rolls you need to make, because folks just don't notice you under most circumstances. For obvious reasons, you can't take any socially distinctive Merits, Flaws or Backgrounds – such Traits would make you memorable – or have especially distinctive features or clothing. Granted, “distinctive” depends upon who and where you are; the proverbial gray flannel suit, for example, stands out at places like Burning Man! Under most circumstances, though, you blend in wherever you go.]==],
				},
				["Useful Knowledge"] = {
					en = [==[Vampire: The Masquerade 20th Anniversary Edition, p. 484


Useful Knowledge


You have expertise in a specific field that makes your conversation intriguing to an older Kindred. So long as your knowledge holds the other vampire's attention, he has a vested interest in keeping you around. Then again, once he's pumped you for every iota of informa- tion you possess, that patronage may suddenly vanish. (Note: This Merit should be played like a 1-dot Men- tor with a specific interest. However, unlike a Mentor, Useful Knowledge does not imply a permanent rela- tionship.)]==],
				},
				["Vaishya"] = {
					en = [==[Lore of the Clans, p. 182


Vaishya


The Vaishya jati are tasked with utilizing influence, maintaining the human herds, and keeping finances. They are often seen as traders and merchants, but to the Ravnos, they are also a critical part of maintaining the Masquerade that hides vampires from mortal hunters. Once per session, you may call on one of your Backgrounds as if you had an extra dot in that Background (up to the normal maximum of 5).

You do not have to purchase this Merit to be a member of the Vaishya jati, but only members of the Vaishya jati may have this Merit.]==],
				},
				["Vicissitude Modifications (1)"] = {
					en = [==[Ghouls & Revenants, p. 134


Vicissitude Modifications (1)


You are a ghoul or revenant whose body has been hideously modified through the use of the Vicissitude Discipline. You, yourself, might not be gifted in this area, but your flesh and bones have been reshaped into a nightmare designed to be useful in war. Thus, while your Modifications may provide you with a mechanical benefit, you are considered a monster even though, technically, you are still mortal.

The alterations made to your body are permanent unless shaped by further uses of Vicissitude. Although your Vicissitude Modifications can be dangerous, your body still sustains damage normally. Despite your horrid appearance, you are still flesh and bone.

Vicissitude Modifications requires you to take the Monstrous Flaw, which is found on page 482 of V20. Regardless of how many alterations you choose, you have an Appearance of 0. At your Storyteller's discretion, you may also be required to take a Mental Flaw, penalty to Social rolls, or a Derangement due to the horrors you're experiencing.

Generally speaking, this Merit may only be used by characters that are either Bound to, or are sponsored by, a vampire or Clan that has the use of Vicissitude. Revenants that are modified in this way are often subjected to the Blood Bond to ensure their loyalty. Circular Vision (1pt.): One of your eyes has been

moved to the back of your head, granting you the

ability to see at a wider angle. You may gain a bonus

to Perception, especially in cases when a character is

attempting to sneak up on you. Additionally, your

depth perception is poor at any angle, and you suffer

a two die penalty to any rolls that involve gauging

distance, including the use of projectile weapons. Fangs (1pt.): Your teeth have been lengthened and

sharpened; your smile may resemble a tiger's or a

shark's, or it may be unlike anything found in nature.

You may attack using Bite, which is found on page

276 of V20. Due to your monstrous appearance,

you will lose two dice in pools involving your

Manipulation Attribute, unless you are trying to

intimidate or scare your target. Iron Stomach (2pts.): You are able to digest any

organic material that you can break up, chew, and

swallow. On Stamina rolls, you gain a +2 when you

need to resist ingested poisons or other types of

stomach-based illnesses. This digestive modification

is often paired with Fangs. Spurs (2pts.): Sharp, pointed bone spurs protrude

from your forearms, spine, or calves. You may slash

with your Spurs for Str + 2 damage. However, Spurs

are hard to conceal and may limit your mobility in

some instances. Carapace (3pts.): You are covered with bony or

spiky plates that protect you from being attacked.

You may add two soak dice to your pool when you

are defending yourself from harm. Patagia (4pts.): Your bones have been hollowed

and flaps of foreign skin have been grafted onto

your arms and wrists to form membranes. While

you cannot fly, you may use these bat-like wings to

glide from one higher position to another, or to

the ground. Subtract one die from all soak pools

to resist strikes from fists and blunt weapons, or

any other forms of concussive damage that might

damage your bones.

Ghouls and revenants may never heal a damaged Vicissitude Modification, not even with the Blood. In this respect, both are as helpless as their unmodified counterparts. However, should a ghoul or revenant possess enough levels in Vicissitude, that character may heal themselves or remove the Vicissitude Modification altogether. To do so, the character must have a level of Vicissitude superior to that of the vampire who inflicted the mutilation in the first place.

Used by: Due to the complexity of this Merit, check with your Storyteller before spending points on Vicissitude Modifications.]==],
				},
