the ground. Subtract one die from all soak pools

to resist strikes from fists and blunt weapons, or

any other forms of concussive damage that might

damage your bones.

Ghouls and revenants may never heal a damaged Vicissitude Modification, not even with the Blood. In this respect, both are as helpless as their unmodified counterparts. However, should a ghoul or revenant possess enough levels in Vicissitude, that character may heal themselves or remove the Vicissitude Modification altogether. To do so, the character must have a level of Vicissitude superior to that of the vampire who inflicted the mutilation in the first place.

Used by: Due to the complexity of this Merit, check with your Storyteller before spending points on Vicissitude Modifications.]==],
				},
				["Vicissitude Modifications (7)"] = {
					en = [==[Ghouls & Revenants, p. 134


Vicissitude Modifications (7)


You are a ghoul or revenant whose body has been hideously modified through the use of the Vicissitude Discipline. You, yourself, might not be gifted in this area, but your flesh and bones have been reshaped into a nightmare designed to be useful in war. Thus, while your Modifications may provide you with a mechanical benefit, you are considered a monster even though, technically, you are still mortal.

The alterations made to your body are permanent unless shaped by further uses of Vicissitude. Although your Vicissitude Modifications can be dangerous, your body still sustains damage normally. Despite your horrid appearance, you are still flesh and bone.

Vicissitude Modifications requires you to take the Monstrous Flaw, which is found on page 482 of V20. Regardless of how many alterations you choose, you have an Appearance of 0. At your Storyteller's discretion, you may also be required to take a Mental Flaw, penalty to Social rolls, or a Derangement due to the horrors you're experiencing.

Generally speaking, this Merit may only be used by characters that are either Bound to, or are sponsored by, a vampire or Clan that has the use of Vicissitude. Revenants that are modified in this way are often subjected to the Blood Bond to ensure their loyalty. Circular Vision (1pt.): One of your eyes has been

moved to the back of your head, granting you the

ability to see at a wider angle. You may gain a bonus

to Perception, especially in cases when a character is

attempting to sneak up on you. Additionally, your

depth perception is poor at any angle, and you suffer

a two die penalty to any rolls that involve gauging

distance, including the use of projectile weapons. Fangs (1pt.): Your teeth have been lengthened and

sharpened; your smile may resemble a tiger's or a

shark's, or it may be unlike anything found in nature.

You may attack using Bite, which is found on page

276 of V20. Due to your monstrous appearance,

you will lose two dice in pools involving your

Manipulation Attribute, unless you are trying to

intimidate or scare your target. Iron Stomach (2pts.): You are able to digest any

organic material that you can break up, chew, and

swallow. On Stamina rolls, you gain a +2 when you

need to resist ingested poisons or other types of

stomach-based illnesses. This digestive modification

is often paired with Fangs. Spurs (2pts.): Sharp, pointed bone spurs protrude

from your forearms, spine, or calves. You may slash

with your Spurs for Str + 2 damage. However, Spurs

are hard to conceal and may limit your mobility in

some instances. Carapace (3pts.): You are covered with bony or

spiky plates that protect you from being attacked.

You may add two soak dice to your pool when you

are defending yourself from harm. Patagia (4pts.): Your bones have been hollowed

and flaps of foreign skin have been grafted onto

your arms and wrists to form membranes. While

you cannot fly, you may use these bat-like wings to

glide from one higher position to another, or to

the ground. Subtract one die from all soak pools

to resist strikes from fists and blunt weapons, or

any other forms of concussive damage that might

damage your bones.

Ghouls and revenants may never heal a damaged Vicissitude Modification, not even with the Blood. In this respect, both are as helpless as their unmodified counterparts. However, should a ghoul or revenant possess enough levels in Vicissitude, that character may heal themselves or remove the Vicissitude Modification altogether. To do so, the character must have a level of Vicissitude superior to that of the vampire who inflicted the mutilation in the first place.

Used by: Due to the complexity of this Merit, check with your Storyteller before spending points on Vicissitude Modifications.]==],
				},
				["Virulent Strike"] = {
					en = [==[Ghouls & Revenants, p. 138


Virulent Strike


Through strange thaumaturgical sorcery, unknown rituals, or even an odd quirk of your physiology, your blood has been imbued with the power of the supernatural. You can cause Aggravated Damage to supernatural creatures by striking them, biting them, or raking them with bonecrafted spurs. This is considered standard Brawl Damage against mortals, and should normally apply to only one attack form (bite, bone claws, etc.).

You should work with the Storyteller to find an explanation for this Merit, and the Storyteller may disallow this Merit entirely if she so chooses.

Used by: All ghouls and revenants]==],
				},
				["Vitae Mutation"] = {
					en = [==[Lore of the Bloodlines, p. 60


Vitae Mutation


You've drank the liquid essence of entities both strange and powerful. Whether the vitae of Methuselahs, the boiling blood of lupines, or bottled dreams of fae, the volume and combination of the brews you've consumed have forever altered you. Each night a Willpower roll is required (difficulty 7) for you to manifest a single point of Auspex, Chimerstry, or Dementation. This point can be added to an existing rating in the Discipline, but disappears the following night. 60 KIASYD]==],
				},
				["Warrior's Heart"] = {
					en = [==[Lore of the Bloodlines, p. 80


Warrior's Heart


Steel sits in the placid heart of the Salubri bloodline, and Adonai's resurrection has caused your own heart to flutter ever so slightly. Like the Healers of old, you may learn the Valeren powers of the antitribu at a cost of current rating x6; if you know the first two dots of Obeah and Valeren, you gain a 2-die bonus to using the first two Discipline dots. However, your warrior's heart suffers from the Precept of Samiel, the well-defined wanderlust that affects many Salubri — for every week you spend in the same location, you lose a point of Willpower, as your soul agitates without action. The antitribu might have a similar Merit allowing them to learn Obeah at a cost of always helping someone in need, at the Storyteller's discretion.]==],
				},
				["Well-Rounded"] = {
					en = [==[M20 Victorian Age, p. 119


Well-Rounded


You were trained or educated especially well in a generalized field. You can apply basic concepts to even distantly-related uses of your training. In time, your application of basic skills allows for marvelous flexibility in your chosen field of expertise.]==],
				},
				["Without a Trace"] = {
					en = [==[The Black Hand: A Guide to the Tal’Mahe’Ra, p. 179


Without a Trace


When in the wilderness, the earth fills in your footprints. You leave no noticeable traces, not even a scent. Normal attempts at tracking automatically fail. Supernatural attempts are done with a +2 difficulty.]==],
				},
				["Wolverine's Palate"] = {
					en = [==[Lore of the Bloodlines, p. 70


Wolverine's Palate


Though many do not know this, the dreaded wolverine is one of only a few creatures in the world that can eat their prey entirely, whether larger or smaller. The Nagaraja with this Merit has the ability to eat bone just as easily as flesh, sapping even more spiritual essence from her victim and converting it to blood points. With one bite, she can cut through flesh and bone and swallow it all at once with no ill effect. This also means she may gain up to 5 additional blood points from a body by consuming the bones.]==],
				},
				-- <<< MERIT_DESC_END
};
